def _bounded_utf8_length(value: Any, maximum: int) -> int:
    _require(
        type(value) is str and len(value) <= maximum,
        "text is not an exact bounded string",
        CaptureError,
    )
    total = 0
    for character in value:
        code_point = ord(character)
        _require(
            not 0xD800 <= code_point <= 0xDFFF,
            "text is not a Unicode scalar sequence",
            CaptureError,
        )
        total += (
            1
            if code_point <= 0x7F
            else 2
            if code_point <= 0x7FF
            else 3
            if code_point <= 0xFFFF
            else 4
        )
        _require(total <= maximum, "text exceeds its UTF-8 byte bound", CaptureError)
    return total


def _require(
    condition: bool,
    message: str,
    error_type: type[ProbeError] = ProbeError,
) -> None:
    if not condition:
        raise error_type(message)


def _u(index: int) -> str:
    return str(uuid.UUID(int=(4 << 76) | (2 << 62) | index))


def _u_for(value: Any) -> str:
    raw = bytearray(hashlib.sha256(_typed_canonical_bytes(value)).digest()[:16])
    raw[6] = (raw[6] & 0x0F) | 0x40
    raw[8] = (raw[8] & 0x3F) | 0x80
    return str(uuid.UUID(bytes=bytes(raw)))


def _is_uuid4(value: str) -> bool:
    if type(value) is not str:
        return False
    try:
        parsed = uuid.UUID(value)
    except (AttributeError, ValueError):
        return False
    return parsed.version == 4 and str(parsed) == value


def _safe_int(value: Any) -> bool:
    return type(value) is int and 0 <= value <= MAX_SAFE_INTEGER


_CAPTURE_ARTIFACT_TYPE_IDS: dict[type[Any], str] = {}


def _register_capture_artifact_type(
    value_type: type[Any],
    stable_type_id: str,
) -> None:
    _require(
        value_type not in _CAPTURE_ARTIFACT_TYPE_IDS,
        "capture artifact type registered twice",
    )
    _require(
        stable_type_id not in _CAPTURE_ARTIFACT_TYPE_IDS.values(),
        "capture artifact type ID reused",
    )
    _require(
        stable_type_id.startswith(("ncp.b01.capture-artifact.", "ncp.b01.bridge."))
        and stable_type_id.endswith("@1"),
        "capture artifact type ID is outside the explicit stable domain",
    )
    _CAPTURE_ARTIFACT_TYPE_IDS[value_type] = stable_type_id


_CAPTURE_CANONICAL_LIMITS = CanonicalLimits(
    max_output_bytes=MAX_CAPTURE_CANONICAL_BYTES,
    max_depth=MAX_CAPTURE_CANONICAL_DEPTH,
    max_nodes=MAX_CAPTURE_CANONICAL_NODES,
    max_collection_items=MAX_CAPTURE_CANONICAL_COLLECTION_ITEMS,
    max_artifact_fields=512,
    max_string_bytes=MAX_CAPTURE_CANONICAL_STRING_BYTES,
    max_payload_bytes=MAX_CONTENT_BYTES,
    max_aggregate_scalar_bytes=MAX_CAPTURE_CANONICAL_BYTES,
    min_integer=-MAX_SAFE_INTEGER,
    max_integer=MAX_SAFE_INTEGER,
    allow_float=True,
    allow_empty_payload=True,
)


def _owned_capture_value(value: Any) -> Any:
    return freeze_owned(
        value,
        limits=_CAPTURE_CANONICAL_LIMITS,
        error_type=CaptureError,
        allow_dataclasses=True,
        allowed_dataclass_types=_CAPTURE_ARTIFACT_TYPE_IDS,
        reject_shared_mutable=False,
    )


def _normalize(value: Any, *, typed_artifacts: bool = False) -> Any:
    encoded = (
        _typed_canonical_bytes(value) if typed_artifacts else _canonical_bytes(value)
    )
    normalized = json.loads(encoded)
    return normalized[1] if typed_artifacts else normalized


def _canonical_bytes(value: Any) -> bytes:
    return _bounded_canonical_bytes(
        _owned_capture_value(value),
        style="capture_plain",
        limits=_CAPTURE_CANONICAL_LIMITS,
        type_ids=_CAPTURE_ARTIFACT_TYPE_IDS,
        error_type=CaptureError,
    )


def _typed_canonical_bytes(value: Any) -> bytes:
    return _bounded_canonical_bytes(
        _owned_capture_value(value),
        style="capture_typed",
        limits=_CAPTURE_CANONICAL_LIMITS,
        type_ids=_CAPTURE_ARTIFACT_TYPE_IDS,
        error_type=CaptureError,
    )


def _digest(value: Any) -> str:
    return hashlib.sha256(_typed_canonical_bytes(value)).hexdigest()


def _actuation_authority_domain_key_body() -> dict[str, str]:
    """Return the one synthetic ActuationAuthorityDomainKey body."""

    return {
        "logical_session": SESSION,
        "plant_generation": GENERATION,
        "domain_id": "qualified-body-actuation-boundary",
        "domain_incarnation": _u(79_880),
        "plant_profile_digest": PLANT_PROFILE_DIGEST,
        "physical_actuation_jurisdiction_key": (PHYSICAL_ACTUATION_JURISDICTION_KEY),
        "physical_actuation_jurisdiction_incarnation": (
            PHYSICAL_ACTUATION_JURISDICTION_INCARNATION
        ),
        "physical_actuation_topology_digest": PHYSICAL_ACTUATION_TOPOLOGY_DIGEST,
        "boundary_contract_digest": hashlib.sha256(
            b"synthetic-qualified-atomic-actuation-boundary"
        ).hexdigest(),
    }


def _actuation_authority_domain_key_digest() -> str:
    return _digest(
        {
            "$type": "ActuationAuthorityDomainKey",
            "body": _actuation_authority_domain_key_body(),
        }
    )


def _validate_generation_actuation_domain_binding(
    *,
    generation: str,
    generation_domain_key_digests: tuple[str, ...],
    arbiter_mirror_domain_key_digest: str,
    actuator_domain_key_digests: tuple[str, ...],
    atomic_success_claimed: bool,
    qualified_atomic_boundary: bool,
) -> None:
    """Require one scalar domain/mirror and no cross-domain atomic claim."""

    expected_domain = _actuation_authority_domain_key_digest()
    _require(
        generation == GENERATION
        and len(generation_domain_key_digests) == 1
        and generation_domain_key_digests[0] == expected_domain
        and HEX64.fullmatch(generation_domain_key_digests[0]) is not None
        and arbiter_mirror_domain_key_digest == expected_domain
        and 1 <= len(actuator_domain_key_digests) <= MAX_REGISTRY_ENTRIES
        and all(
            domain_key_digest == expected_domain
            for domain_key_digest in actuator_domain_key_digests
        )
        and (
            len(actuator_domain_key_digests) == 1
            or qualified_atomic_boundary
            and atomic_success_claimed
        ),
        "plant generation must bind exactly one actuation authority domain and "
        "one scalar arbiter mirror; atomic success cannot span domains",
        CaptureError,
    )


def _capture_artifact_field_snapshot(
    value: Any,
) -> tuple[str, tuple[tuple[str, Any], ...]]:
    """Revalidate one registered artifact and read each field exactly once."""

    registry = _CAPTURE_ARTIFACT_TYPE_IDS
    _require(
        type(registry) is FrozenTypeRegistry,
        "capture artifact registry is not frozen",
        CaptureError,
    )
    try:
        return registry.snapshot_artifact_view(value)
    except ValueError as exc:
        raise CaptureError("capture artifact snapshot was rejected") from exc


def _capture_artifact_body_snapshot(
    value: Any,
    *excluded: str,
) -> tuple[str, dict[str, Any]]:
    blocked = set(excluded)
    type_id, field_snapshot = _capture_artifact_field_snapshot(value)
    return type_id, {
        field_name: field_value
        for field_name, field_value in field_snapshot
        if field_name not in blocked
    }


def _body(value: Any, *excluded: str) -> dict[str, Any]:
    _type_id, body = _capture_artifact_body_snapshot(value, *excluded)
    return body


def _capture_artifact_field_value(value: Any, field_name: str) -> Any:
    _type_id, field_snapshot = _capture_artifact_field_snapshot(value)
    for candidate_name, field_value in field_snapshot:
        if candidate_name == field_name:
            return field_value
    raise CaptureError("capture artifact does not contain the required pinned field")


def _capture_artifact_optional_field_value(
    value: Any,
    field_name: str,
    default: Any,
) -> Any:
    _type_id, field_snapshot = _capture_artifact_field_snapshot(value)
    for candidate_name, field_value in field_snapshot:
        if candidate_name == field_name:
            return field_value
    return default


def _capture_artifact_field_names(value_type: type[Any]) -> tuple[str, ...]:
    """Return one class's pinned field names after full registry revalidation."""

    registry = _CAPTURE_ARTIFACT_TYPE_IDS
    _require(
        type(value_type) is type and type(registry) is FrozenTypeRegistry,
        "capture artifact shape lookup is not exact",
        CaptureError,
    )
    try:
        shape_view = registry.revalidated_shape_view()
        type_id = registry[value_type]
    except (KeyError, ValueError) as exc:
        raise CaptureError("capture artifact shape lookup was rejected") from exc
    matches = tuple(
        field_names
        for candidate_type_id, field_names in shape_view
        if candidate_type_id == type_id
    )
    _require(
        len(matches) == 1,
        "capture artifact shape lookup is not one-to-one",
        CaptureError,
    )
    return matches[0]


def _body_digest(value: Any, *excluded: str) -> str:
    type_id, body = _capture_artifact_body_snapshot(value, *excluded)
    return hashlib.sha256(
        _typed_canonical_bytes(
            {
                "$artifact_type": type_id,
                "$fields": body,
            }
        )
    ).hexdigest()


def _unique_object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key, value in pairs:
        if key in result:
            raise CaptureError("JSON object has a duplicate member")
        result[key] = value
    return result


def _bounded_json_object(encoded: bytes) -> dict[str, Any]:
    """Reject lexical resource abuse before semantic object allocation."""

    _require(
        isinstance(encoded, bytes) and 1 <= len(encoded) <= MAX_JSON_BYTES,
        "JSON exceeds its byte budget",
        CaptureError,
    )

    try:
        text = encoded.decode("utf-8")
    except UnicodeDecodeError as error:
        raise CaptureError("JSON is not valid UTF-8") from error

    depth = 0
    nodes = 0
    index = 0
    while index < len(text):
        character = text[index]
        if character in "[{":
            depth += 1
            nodes += 1
            _require(
                depth <= MAX_JSON_DEPTH and nodes <= MAX_JSON_NODES,
                "JSON exceeds its structural budget",
                CaptureError,
            )
            index += 1
            continue
        if character in "]}":
            depth -= 1
            _require(depth >= 0, "JSON closes an absent container", CaptureError)
            index += 1
            continue
        if character == '"':
            index += 1
            decoded = 0
            while index < len(text) and text[index] != '"':
                if text[index] == "\\":
                    index += 1
                    _require(index < len(text), "incomplete JSON escape", CaptureError)
                    if text[index] == "u":
                        _require(
                            index + 4 < len(text),
                            "incomplete JSON Unicode escape",
                            CaptureError,
                        )
                        index += 4
                decoded += 1
                _require(
                    decoded <= MAX_JSON_STRING_CHARS,
                    "JSON string exceeds its character budget",
                    CaptureError,
                )
                index += 1
            _require(index < len(text), "unterminated JSON string", CaptureError)
            nodes += 1
            index += 1
            continue
        if character in "-0123456789":
            start = index
            while index < len(text) and text[index] in "0123456789+-.eE":
                index += 1
            _require(
                index - start <= MAX_JSON_NUMBER_CHARS,
                "JSON number exceeds its lexical budget",
                CaptureError,
            )
            nodes += 1
            continue
        literal = next(
            (
                token
                for token in ("true", "false", "null")
                if text.startswith(token, index)
            ),
            None,
        )
        if literal is not None:
            nodes += 1
            _require(
                nodes <= MAX_JSON_NODES,
                "JSON exceeds its structural budget",
                CaptureError,
            )
            index += len(literal)
            continue
        index += 1
    _require(depth == 0 and nodes <= MAX_JSON_NODES, "unbalanced JSON", CaptureError)

    def parse_int(token: str) -> int:
        _require(
            len(token) <= MAX_JSON_NUMBER_CHARS,
            "integer token exceeds its lexical budget",
            CaptureError,
        )
        value = int(token)
        _require(
            -MAX_SAFE_INTEGER <= value <= MAX_SAFE_INTEGER,
            "integer exceeds the exact JSON range",
            CaptureError,
        )
        return value

    def parse_float(token: str) -> float:
        _require(
            len(token) <= MAX_JSON_NUMBER_CHARS,
            "float token exceeds its lexical budget",
            CaptureError,
        )
        value = float(token)
        _require(math.isfinite(value), "non-finite number", CaptureError)
        return value

    try:
        value = json.loads(
            text,
            object_pairs_hook=_unique_object,
            parse_int=parse_int,
            parse_float=parse_float,
            parse_constant=lambda token: (_ for _ in ()).throw(
                CaptureError(f"non-finite constant {token}")
            ),
        )
    except CaptureError:
        raise
    except (
        json.JSONDecodeError,
        MemoryError,
        OverflowError,
        RecursionError,
        TypeError,
        ValueError,
    ) as error:
        raise CaptureError("JSON decode failed within its bounded domain") from error

    structural_nodes = 0
    stack: list[tuple[Any, int]] = [(value, 1)]
    while stack:
        member, member_depth = stack.pop()
        structural_nodes += 1
        _require(
            structural_nodes <= MAX_JSON_NODES and member_depth <= MAX_JSON_DEPTH,
            "decoded JSON exceeds its structural budget",
            CaptureError,
        )
        if isinstance(member, dict):
            _require(
                len(member) <= MAX_JSON_KEYS,
                "JSON object exceeds its member budget",
                CaptureError,
            )
            for key, item in member.items():
                structural_nodes += 1
                _require(
                    structural_nodes <= MAX_JSON_NODES
                    and len(key) <= MAX_JSON_STRING_CHARS,
                    "JSON key exceeds its structural or character budget",
                    CaptureError,
                )
                stack.append((item, member_depth + 1))
        elif isinstance(member, list):
            stack.extend((item, member_depth + 1) for item in member)
        elif isinstance(member, str):
            _require(
                len(member) <= MAX_JSON_STRING_CHARS,
                "JSON string exceeds its character budget",
                CaptureError,
            )
        elif isinstance(member, bool) or member is None:
            pass
        elif isinstance(member, int):
            _require(
                -MAX_SAFE_INTEGER <= member <= MAX_SAFE_INTEGER,
                "integer exceeds the exact JSON range",
                CaptureError,
            )
        elif isinstance(member, float):
            _require(math.isfinite(member), "non-finite number", CaptureError)
        else:
            raise CaptureError("decoded JSON has an unsupported member type")
    _require(
        isinstance(value, dict) and _canonical_bytes(value) == encoded,
        "JSON is not one exact canonical object",
        CaptureError,
    )
    return value


@dataclass(frozen=True, slots=True)
class CaptureExclusion:
    source_identity_digest: str
    reason: str
    count: int
    exclusion_digest: str


@dataclass(frozen=True, slots=True)
class ContentRef:
    sha256: str
    byte_length: int
    media_type: str


@dataclass(frozen=True, slots=True)
class StagedContentWrite:
    reference: ContentRef
    content: bytes


@dataclass(frozen=True, slots=True)
class _ContentStoreSnapshot:
    content: tuple[tuple[ContentRef, bytes], ...]
    atomic_visibility: tuple[tuple[str, tuple[ContentRef, ...]], ...]
    next_authority_receipt_sequence: int


class ContentStore:
    """Bounded same-process immutable-snapshot content-addressed fixture store.

    ``put_*`` installs unscoped CAS content. ``commit_atomic`` additionally
    publishes exactly its staged digest set in one namespace. This fixture does
    not model a filesystem journal, fsync, process restart, or storage durability.
    """

    def __init__(self) -> None:
        self._snapshot = _ContentStoreSnapshot((), (), 1)
        self._lock = threading.RLock()

    @staticmethod
    def _validate_media_type(media_type: Any) -> None:
        _require(
            type(media_type) is str
            and 0 < len(media_type) <= MAX_CONTENT_MEDIA_TYPE_BYTES
            and 1
            <= _bounded_utf8_length(media_type, MAX_CONTENT_MEDIA_TYPE_BYTES)
            <= MAX_CONTENT_MEDIA_TYPE_BYTES
            and MEDIA_TYPE.fullmatch(media_type) is not None,
            "content media type is not exact bounded Unicode media syntax",
            CaptureError,
        )

    @staticmethod
    def _validate_namespace(namespace: Any) -> None:
        _require(
            type(namespace) is str
            and 1
            <= _bounded_utf8_length(namespace, MAX_CONTENT_NAMESPACE_BYTES)
            <= MAX_CONTENT_NAMESPACE_BYTES
            and IDENTIFIER.fullmatch(namespace) is not None,
            "content visibility namespace is not an exact bounded identifier",
            CaptureError,
        )

    @classmethod
    def _validate_reference_shape(cls, reference: Any) -> None:
        _require(
            type(reference) is ContentRef
            and type(reference.sha256) is str
            and HEX64.fullmatch(reference.sha256) is not None
            and type(reference.byte_length) is int
            and 0 <= reference.byte_length <= MAX_CONTENT_BYTES
            and type(reference.media_type) is str,
            "content reference fields are not exact or bounded",
            CaptureError,
        )
        cls._validate_media_type(reference.media_type)

    @classmethod
    def _validate_reference_content(
        cls,
        reference: Any,
        value: Any,
    ) -> None:
        cls._validate_reference_shape(reference)
        _require(
            type(value) is bytes
            and len(value) <= MAX_CONTENT_BYTES
            and reference.sha256 == hashlib.sha256(value).hexdigest()
            and reference.byte_length == len(value),
            "content reference does not identify its exact bytes",
            CaptureError,
        )

    @staticmethod
    def _content_map(
        snapshot: _ContentStoreSnapshot,
    ) -> dict[ContentRef, bytes]:
        return dict(snapshot.content)

    @staticmethod
    def _visibility_map(
        snapshot: _ContentStoreSnapshot,
    ) -> dict[str, tuple[ContentRef, ...]]:
        return dict(snapshot.atomic_visibility)

    @staticmethod
    def _ordered_content(
        content: Mapping[ContentRef, bytes],
    ) -> tuple[tuple[ContentRef, bytes], ...]:
        return tuple(
            sorted(
                content.items(),
                key=lambda item: (
                    item[0].sha256,
                    item[0].media_type,
                    item[0].byte_length,
                ),
            )
        )

    @classmethod
    def _validate_candidate_content(
        cls,
        content: Mapping[ContentRef, bytes],
    ) -> None:
        _require(
            len(content) <= MAX_CONTENT_STORE_OBJECTS,
            "content store object capacity is exhausted",
            CaptureError,
        )
        aggregate = 0
        digest_bytes: dict[str, bytes] = {}
        for reference, value in content.items():
            cls._validate_reference_content(reference, value)
            prior = digest_bytes.get(reference.sha256)
            _require(
                prior in (None, value),
                "one content digest identifies conflicting bytes",
                CaptureError,
            )
            digest_bytes[reference.sha256] = value
            aggregate += len(value)
            _require(
                aggregate <= MAX_CONTENT_STORE_AGGREGATE_BYTES,
                "content store aggregate byte capacity is exhausted",
                CaptureError,
            )

    @staticmethod
    def stage_bytes(content: bytes, media_type: str) -> StagedContentWrite:
        _require(
            type(content) is bytes and len(content) <= MAX_CONTENT_BYTES,
            "content is absent or exceeds its bounded budget",
            CaptureError,
        )
        ContentStore._validate_media_type(media_type)
        reference = ContentRef(
            hashlib.sha256(content).hexdigest(),
            len(content),
            media_type,
        )
        return StagedContentWrite(reference, content)

    def put_bytes(self, content: bytes, media_type: str) -> ContentRef:
        staged = self.stage_bytes(content, media_type)
        with self._lock:
            base = self._snapshot
            candidate_content = self._content_map(base)
            prior = candidate_content.get(staged.reference)
            _require(
                prior in (None, staged.content),
                "content reference collision changed exact bytes",
                CaptureError,
            )
            candidate_content[staged.reference] = staged.content
            self._validate_candidate_content(candidate_content)
            self._snapshot = _ContentStoreSnapshot(
                self._ordered_content(candidate_content),
                base.atomic_visibility,
                base.next_authority_receipt_sequence,
            )
        return staged.reference

    def put_json(self, value: Any, media_type: str) -> ContentRef:
        return self.put_bytes(_canonical_bytes(value), media_type)

    def protect_body_atomic(
        self,
        body: dict[str, Any],
        *,
        media_type: str,
        domain: str,
        issuer: str,
        subject: str,
        event_time: int,
        clock_domain: str,
        clock_incarnation: str,
    ) -> ProtectedBody:
        """Seal and install one protected body under the same snapshot lock."""

        staged = self.stage_bytes(_canonical_bytes(body), media_type)
        with self._lock:
            base = self._snapshot
            sequence = base.next_authority_receipt_sequence
            _require(
                _safe_int(sequence) and 1 <= sequence < MAX_SAFE_INTEGER,
                "authority receipt identity allocator is exhausted or corrupt",
                CaptureError,
            )
            receipt = _seal_authority(
                receipt_id=_u(10_000 + sequence),
                domain=domain,
                subject_digest=staged.reference.sha256,
                issuer=issuer,
                subject=subject,
                clock_domain=clock_domain,
                clock_incarnation=clock_incarnation,
                event_time=event_time,
            )
            _validate_authority(
                receipt,
                domain=domain,
                subject_digest=staged.reference.sha256,
                issuer=issuer,
                subject=subject,
                expected_clock_domain=clock_domain,
                expected_clock_incarnation=clock_incarnation,
                latest_event_time=event_time,
            )
            candidate_content = self._content_map(base)
            prior = candidate_content.get(staged.reference)
            _require(
                prior in (None, staged.content),
                "protected body collides with existing exact content",
                CaptureError,
            )
            candidate_content[staged.reference] = staged.content
            self._validate_candidate_content(candidate_content)
            self._snapshot = _ContentStoreSnapshot(
                self._ordered_content(candidate_content),
                base.atomic_visibility,
                sequence + 1,
            )
            return ProtectedBody(
                staged.reference,
                staged.reference.sha256,
                receipt,
            )

    def get(self, reference: ContentRef) -> bytes:
        self._validate_reference_shape(reference)
        with self._lock:
            content = self._content_map(self._snapshot).get(reference)
        _require(content is not None, "content reference is absent", CaptureError)
        if content is None:
            raise CaptureError("validated content is absent")
        self._validate_reference_content(reference, content)
        return content

    def refs(self) -> tuple[ContentRef, ...]:
        with self._lock:
            return tuple(reference for reference, _value in self._snapshot.content)

    def atomic_visibility(self, namespace: str) -> tuple[ContentRef, ...]:
        self._validate_namespace(namespace)
        with self._lock:
            return self._visibility_map(self._snapshot).get(namespace, ())

    def _reset_for_fixture(self) -> None:
        """Erase only the process-local synthetic fixture between test builds."""

        with self._lock:
            self._snapshot = _ContentStoreSnapshot((), (), 1)

    def commit_atomic(
        self,
        *,
        namespace: str,
        staged_writes: tuple[StagedContentWrite, ...],
        visible_references: tuple[ContentRef, ...],
        allow_exact_retry: bool = False,
    ) -> None:
        self._validate_namespace(namespace)
        _require(
            type(allow_exact_retry) is bool
            and type(staged_writes) is tuple
            and 1 <= len(staged_writes) <= MAX_CONTENT_STORE_ATOMIC_WRITES
            and type(visible_references) is tuple
            and 1 <= len(visible_references) <= MAX_CONTENT_STORE_VISIBLE_DIGESTS,
            "atomic publication collections are malformed, empty, or unbounded",
            CaptureError,
        )
        for reference in visible_references:
            self._validate_reference_shape(reference)
        _require(
            tuple(
                sorted(
                    set(visible_references),
                    key=lambda reference: (
                        reference.sha256,
                        reference.media_type,
                        reference.byte_length,
                    ),
                )
            )
            == visible_references,
            "atomic visibility references are duplicate or unordered",
            CaptureError,
        )
        staged_references: set[ContentRef] = set()
        validated_writes: list[StagedContentWrite] = []
        for staged in staged_writes:
            _require(
                type(staged) is StagedContentWrite
                and type(staged.content) is bytes
                and type(staged.reference) is ContentRef,
                "staged content write changed before atomic publication",
                CaptureError,
            )
            self._validate_reference_content(staged.reference, staged.content)
            _require(
                staged.reference not in staged_references,
                "atomic publication contains a duplicate staged reference",
                CaptureError,
            )
            staged_references.add(staged.reference)
            validated_writes.append(staged)
        _require(
            staged_references == set(visible_references),
            "atomic publication visibility is not the exact staged reference set",
            CaptureError,
        )
        with self._lock:
            base = self._snapshot
            candidate_content = self._content_map(base)
            candidate_visibility = self._visibility_map(base)
            prior_visibility = candidate_visibility.get(namespace)
            if prior_visibility is not None:
                _require(
                    allow_exact_retry
                    and prior_visibility == visible_references
                    and all(
                        candidate_content.get(staged.reference) == staged.content
                        for staged in validated_writes
                    ),
                    "atomic content/state publication namespace already exists",
                    CaptureError,
                )
                return
            for staged in validated_writes:
                prior = candidate_content.get(staged.reference)
                _require(
                    prior in (None, staged.content),
                    "staged content collides with existing exact content",
                    CaptureError,
                )
                candidate_content[staged.reference] = staged.content
            self._validate_candidate_content(candidate_content)
            _require(
                all(reference in candidate_content for reference in visible_references),
                "atomic visibility names content that is not staged or stored",
                CaptureError,
            )
            _require(
                len(candidate_visibility) < MAX_CONTENT_STORE_NAMESPACES
                and sum(map(len, candidate_visibility.values()))
                + len(visible_references)
                <= MAX_CONTENT_STORE_TOTAL_VISIBLE_DIGESTS,
                "atomic visibility capacity is exhausted",
                CaptureError,
            )
            candidate_visibility[namespace] = visible_references
            self._snapshot = _ContentStoreSnapshot(
                self._ordered_content(candidate_content),
                tuple(sorted(candidate_visibility.items())),
                base.next_authority_receipt_sequence,
            )


@dataclass(frozen=True, slots=True)
class AuthorityReceipt:
    receipt_id: str
    domain: str
    subject_digest: str
    issuer_principal: str
    subject_principal: str
    issuer_key_id: str
    issuer_security_state_digest: str
    issuer_security_epoch: int
    clock_domain: str
    clock_incarnation: str
    event_time: int
    receipt_digest: str
    fixture_authentication_tag: str


def _authority_fixture_key_id(issuer: Any) -> str:
    _require(
        type(issuer) is str and IDENTIFIER.fullmatch(issuer) is not None,
        "authority receipt issuer is not an exact bounded principal",
        CaptureError,
    )
    return f"{issuer}:fixture-key:1"


def _authority_fixture_security_state_digest(issuer: str) -> str:
    return hashlib.sha256(
        b"NCP-B01-SYNTHETIC-AUTHORITY-SECURITY-STATE-V1\x00" + issuer.encode("utf-8")
    ).hexdigest()


def _authority_receipt_fixture_tag(receipt: AuthorityReceipt) -> str:
    _require(
        type(receipt) is AuthorityReceipt,
        "authority receipt authentication input type is not exact",
        CaptureError,
    )
    issuer_key = hmac.new(
        _AUTHORITY_RECEIPT_FIXTURE_ROOT_KEY,
        b"NCP-B01-SYNTHETIC-AUTHORITY-ISSUER-KEY-V1\x00"
        + receipt.issuer_principal.encode("utf-8"),
        hashlib.sha256,
    ).digest()
    _receipt_type_id, receipt_snapshot = _capture_artifact_field_snapshot(receipt)
    return hmac.new(
        issuer_key,
        b"NCP-B01-SYNTHETIC-AUTHORITY-RECEIPT-HMAC-V1\x00"
        + _typed_canonical_bytes(
            tuple(
                field_value
                for field_name, field_value in receipt_snapshot
                if field_name != "fixture_authentication_tag"
            )
        ),
        hashlib.sha256,
    ).hexdigest()


def _validate_authority_receipt_claim_fields(
    *,
    receipt_id: Any,
    domain: Any,
    subject_digest: Any,
    issuer: Any,
    subject: Any,
    clock_domain: Any,
    clock_incarnation: Any,
    event_time: Any,
) -> None:
    _require(
        _is_uuid4(receipt_id)
        and type(domain) is str
        and IDENTIFIER.fullmatch(domain) is not None
        and type(subject_digest) is str
        and HEX64.fullmatch(subject_digest) is not None
        and type(issuer) is str
        and IDENTIFIER.fullmatch(issuer) is not None
        and type(subject) is str
        and IDENTIFIER.fullmatch(subject) is not None
        and type(clock_domain) is str
        and IDENTIFIER.fullmatch(clock_domain) is not None
        and _is_uuid4(clock_incarnation)
        and _safe_int(event_time),
        "authority receipt claim fields are not exact, bounded, or canonical",
        CaptureError,
    )


def _seal_authority(
    *,
    receipt_id: str,
    domain: str,
    subject_digest: str,
    issuer: str,
    subject: str,
    clock_domain: str,
    clock_incarnation: str,
    event_time: int,
) -> AuthorityReceipt:
    _validate_authority_receipt_claim_fields(
        receipt_id=receipt_id,
        domain=domain,
        subject_digest=subject_digest,
        issuer=issuer,
        subject=subject,
        clock_domain=clock_domain,
        clock_incarnation=clock_incarnation,
        event_time=event_time,
    )
    receipt = AuthorityReceipt(
        receipt_id,
        domain,
        subject_digest,
        issuer,
        subject,
        _authority_fixture_key_id(issuer),
        _authority_fixture_security_state_digest(issuer),
        1,
        clock_domain,
        clock_incarnation,
        event_time,
        "",
        "",
    )
    receipt = replace(
        receipt,
        receipt_digest=_body_digest(
            receipt,
            "receipt_digest",
            "fixture_authentication_tag",
        ),
    )
    return replace(
        receipt,
        fixture_authentication_tag=_authority_receipt_fixture_tag(receipt),
    )


def _validate_authority(
    receipt: AuthorityReceipt,
    *,
    domain: str,
    subject_digest: str,
    issuer: str,
    subject: str,
    expected_clock_domain: str | None = None,
    expected_clock_incarnation: str | None = None,
    latest_event_time: int | None = None,
) -> None:
    _validate_authority_receipt_claim_fields(
        receipt_id=receipt.receipt_id,
        domain=receipt.domain,
        subject_digest=receipt.subject_digest,
        issuer=receipt.issuer_principal,
        subject=receipt.subject_principal,
        clock_domain=receipt.clock_domain,
        clock_incarnation=receipt.clock_incarnation,
        event_time=receipt.event_time,
    )
    _require(
        type(receipt) is AuthorityReceipt
        and _is_uuid4(receipt.receipt_id)
        and receipt.domain == domain
        and receipt.subject_digest == subject_digest
        and HEX64.fullmatch(receipt.subject_digest) is not None
        and receipt.issuer_principal == issuer
        and receipt.subject_principal == subject
        and (
            expected_clock_domain is None
            or receipt.clock_domain == expected_clock_domain
        )
        and (
            expected_clock_incarnation is None
            or receipt.clock_incarnation == expected_clock_incarnation
        )
        and (
            latest_event_time is None
            or _safe_int(latest_event_time)
            and receipt.event_time <= latest_event_time
        )
        and receipt.issuer_key_id == _authority_fixture_key_id(issuer)
        and receipt.issuer_security_state_digest
        == _authority_fixture_security_state_digest(issuer)
        and receipt.issuer_security_epoch == 1
        and IDENTIFIER.fullmatch(receipt.clock_domain) is not None
        and _is_uuid4(receipt.clock_incarnation)
        and _safe_int(receipt.event_time)
        and receipt.receipt_digest
        == _body_digest(
            receipt,
            "receipt_digest",
            "fixture_authentication_tag",
        )
        and hmac.compare_digest(
            receipt.fixture_authentication_tag,
            _authority_receipt_fixture_tag(receipt),
        ),
        f"{domain} authority receipt is malformed or from the wrong authority",
        CaptureError,
    )


@dataclass(frozen=True, slots=True)
class ProtectedBody:
    body: ContentRef
    body_digest: str
    authority_receipt: AuthorityReceipt


def _protect_body(
    body: dict[str, Any],
    *,
    store: ContentStore,
    media_type: str,
    domain: str,
    issuer: str,
    subject: str,
    event_time: int,
    clock_domain: str = "issuer-utc",
    clock_incarnation: str = GENERATION,
) -> ProtectedBody:
    return store.protect_body_atomic(
        body,
        media_type=media_type,
        domain=domain,
        issuer=issuer,
        subject=subject,
        event_time=event_time,
        clock_domain=clock_domain,
        clock_incarnation=clock_incarnation,
    )


def _validate_protected_body(
    protected: ProtectedBody,
    semantic_body: dict[str, Any],
    *,
    store: ContentStore,
    media_type: str,
    domain: str,
    issuer: str,
    subject: str,
) -> None:
    encoded = store.get(protected.body)
    decoded = _bounded_json_object(encoded)
    _require(
        decoded == _normalize(semantic_body)
        and protected.body.media_type == media_type
        and protected.body_digest == protected.body.sha256,
        "protected bytes or media type contradict the supplied semantic body",
        CaptureError,
    )
    _validate_authority(
        protected.authority_receipt,
        domain=domain,
        subject_digest=protected.body_digest,
        issuer=issuer,
        subject=subject,
    )


SOURCE_SESSION_KINDS = ("PLANT_CONTROL", "SIMULATION_SERVICE")
REQUIRED_SOURCE_GENERATION_CHILD_ROLES = {
    "PLANT_CONTROL": (
        "BODY_SESSION_CONTROL_STATE",
        "OBSERVER_AUTHORIZATION_STATE",
    ),
    "SIMULATION_SERVICE": (
        "OBSERVER_AUTHORIZATION_STATE",
        "SIMULATION_SESSION_STATE",
    ),
}
UNKNOWN_OBSERVER_TARGET_IDENTIFIERS = frozenset(
    {"DEFAULT", "NONE", "UNKNOWN", "UNSPECIFIED"}
)


def _closed_observer_target_identifier(value: object) -> bool:
    """Accept one bounded explicit identifier for observer target authority."""

    return (
        type(value) is str
        and IDENTIFIER.fullmatch(value) is not None
        and value.upper() not in UNKNOWN_OBSERVER_TARGET_IDENTIFIERS
    )


@dataclass(frozen=True, slots=True)
class ObserverDescriptor:
    descriptor_id: str
    source_session_kind: str
    source_logical_session_id: str
    source_generation: str
    security_state_digest: str
    stream_declaration_digests: tuple[str, ...]
    privacy_profile_digest: str
    descriptor_digest: str
    protected_body: ProtectedBody


def _descriptor_body(descriptor: ObserverDescriptor) -> dict[str, Any]:
    return _body(descriptor, "descriptor_digest", "protected_body")


def _seal_descriptor(
    descriptor: ObserverDescriptor,
    *,
    store: ContentStore,
) -> ObserverDescriptor:
    body = _descriptor_body(descriptor)
    protected = _protect_body(
        body,
        store=store,
        media_type="application/vnd.ncp.observer-descriptor+json",
        domain="observer-descriptor",
        issuer=DESCRIPTOR_AUTHORITY,
        subject="observer-class",
        event_time=1_700_000_000,
    )
    return replace(
        descriptor,
        descriptor_digest=protected.body_digest,
        protected_body=protected,
    )


def _validate_descriptor(
    descriptor: ObserverDescriptor,
    *,
    store: ContentStore,
) -> None:
    _require(
        _is_uuid4(descriptor.descriptor_id)
        and descriptor.source_session_kind in SOURCE_SESSION_KINDS
        and descriptor.source_logical_session_id == SESSION
        and descriptor.source_generation == GENERATION
        and HEX64.fullmatch(descriptor.security_state_digest) is not None
        and 1 <= len(descriptor.stream_declaration_digests) <= MAX_REGISTRY_ENTRIES
        and tuple(sorted(set(descriptor.stream_declaration_digests)))
        == descriptor.stream_declaration_digests
        and HEX64.fullmatch(descriptor.privacy_profile_digest) is not None
        and descriptor.descriptor_digest == descriptor.protected_body.body_digest,
        "observer descriptor identity is malformed",
        CaptureError,
    )
    _validate_protected_body(
        descriptor.protected_body,
        _descriptor_body(descriptor),
        store=store,
        media_type="application/vnd.ncp.observer-descriptor+json",
        domain="observer-descriptor",
        issuer=DESCRIPTOR_AUTHORITY,
        subject="observer-class",
    )


