OBSERVER_TARGET_HISTORY_PHASES = frozenset(
    {
        "CHECKPOINT_PUBLISHED",
        "GENERATION_FINALIZED_PENDING_CHECKPOINT_PUBLICATION",
        "GENERATION_LIVE",
    }
)
OBSERVER_HISTORY_MUTATIONS = frozenset(
    {
        "active_target_capacity_off_by_one",
        "drop_retirement_tombstone",
        "generation_chain_omits_target_key",
        "history_digest_substitution_accepted",
        "retirement_without_preparation",
        "tombstone_depends_on_future_retirement_receipt",
        "retirement_tombstone_digest_substitution_accepted",
        "retirement_tombstone_omits_source_key",
        "target_coordinate_omits_server_authority",
        "namespace_registry_reenrollment_recreates_empty",
    }
)
OBSERVER_GENERATION_CHAIN_GENESIS_DIGEST = hashlib.sha256(
    b"ncp-observer-target-generation-chain-genesis-v1"
).hexdigest()


def _seal_observer_history_capacity_manifest(
    manifest: ObserverAttachmentHistoryCapacityManifest,
) -> ObserverAttachmentHistoryCapacityManifest:
    return replace(
        manifest,
        manifest_digest=_body_digest(manifest, "manifest_digest"),
    )


def _default_observer_history_capacity_manifest(
    *,
    realm_authority: str,
    stable_realm_id: str = OBSERVER_STABLE_REALM_ID,
    **changes: Any,
) -> ObserverAttachmentHistoryCapacityManifest:
    baseline = ObserverAttachmentHistoryCapacityManifest(
        manifest_id=_u(81_900),
        authority_realm_key=ObserverAuthorityRealmKey(
            server_authority_principal=realm_authority,
            stable_realm_id=stable_realm_id,
        ),
        max_active_target_entries=8,
        max_active_target_key_bytes=4096,
        simulation_active_target_entry_reserve=4,
        plant_active_target_entry_reserve=4,
        simulation_active_target_key_byte_reserve=2048,
        plant_active_target_key_byte_reserve=2048,
        max_targets_per_source_generation=4,
        max_source_generation_count=MAX_SAFE_INTEGER,
        max_retired_source_tombstones=8,
        max_retired_source_key_bytes=8192,
        simulation_retired_source_tombstone_reserve=4,
        plant_retired_source_tombstone_reserve=4,
        simulation_retired_source_key_byte_reserve=4096,
        plant_retired_source_key_byte_reserve=4096,
        max_quarantined_target_entries=8,
        max_quarantined_target_key_bytes=4096,
        simulation_quarantined_target_entry_reserve=4,
        plant_quarantined_target_entry_reserve=4,
        simulation_quarantined_target_key_byte_reserve=2048,
        plant_quarantined_target_key_byte_reserve=2048,
        max_logical_session_namespace_entries=16,
        max_logical_session_namespace_key_bytes=16_384,
        simulation_logical_session_namespace_entry_reserve=8,
        plant_logical_session_namespace_entry_reserve=8,
        simulation_logical_session_namespace_key_byte_reserve=8192,
        plant_logical_session_namespace_key_byte_reserve=8192,
        manifest_digest="",
    )
    return _seal_observer_history_capacity_manifest(replace(baseline, **changes))


class ObserverAttachmentArchitectureModel:
    """Bound AttachObserver to a source child and realm-global target history."""

    def __init__(
        self,
        *,
        realm_authority: str,
        stable_realm_id: str = OBSERVER_STABLE_REALM_ID,
        capacity_manifest: ObserverAttachmentHistoryCapacityManifest | None = None,
        mutation: str | None = None,
    ) -> None:
        _require(
            _closed_observer_target_identifier(realm_authority),
            "observer realm authority is malformed",
            CaptureError,
        )
        _require(
            mutation is None or mutation in OBSERVER_HISTORY_MUTATIONS,
            "observer target-history mutation is unknown",
            CaptureError,
        )
        self.realm_authority = realm_authority
        _require(
            _closed_observer_target_identifier(stable_realm_id),
            "observer stable realm ID is malformed",
            CaptureError,
        )
        self.stable_realm_id = stable_realm_id
        self.authority_realm_key = ObserverAuthorityRealmKey(
            server_authority_principal=realm_authority,
            stable_realm_id=stable_realm_id,
        )
        self.transaction_store_incarnation = _u_for(
            (
                "observer-authority-transaction-store-incarnation",
                self.authority_realm_key,
            )
        )
        self.authority_transaction_domain_qualification_digest = _digest(
            {
                "domain": "observer-authority-transaction-domain-qualification-v1",
                "authority_transaction_domain_key": self.authority_realm_key,
                "transaction_store_incarnation": (self.transaction_store_incarnation),
                "semantics": (
                    "STRICT_SERIALIZABLE_MULTI_SELECTOR_CAS",
                    "ONE_LINEARIZATION_POINT",
                    "ATOMIC_CRASH_COMPLETE_PUBLICATION",
                ),
            }
        )
        self.mutation = mutation
        self.capacity_manifest = (
            _default_observer_history_capacity_manifest(
                realm_authority=realm_authority,
                stable_realm_id=stable_realm_id,
            )
            if capacity_manifest is None
            else capacity_manifest
        )
        self._validate_capacity_manifest(self.capacity_manifest)
        self.adr001_generations_allocated_by_attach = 0
        self.source_authorization_registries: dict[
            str,
            dict[ObserverAttachmentTargetKey, ObserverAuthorizationRegistryEntry],
        ] = {}
        self.registry_scopes: dict[str, tuple[str, str, str]] = {}
        self.target_history: dict[
            ObserverAttachmentTargetKey,
            ObserverAttachmentTargetHistoryEntry,
        ] = {}
        self.active_target_key_bytes = 0
        self.pending_target_roots: dict[
            tuple[str, str, str],
            ObserverPendingTargetRoot,
        ] = {}
        self.target_history_selector_id = _u_for(
            (
                "observer-attachment-target-history-selector",
                self.authority_realm_key,
            )
        )
        self.target_history_selector_version = 1
        self.target_history_head_digest = _digest(
            {
                "domain": "observer-attachment-target-history-head-genesis-v1",
                "authority_transaction_domain_key": self.authority_realm_key,
                "selector_id": self.target_history_selector_id,
                "selector_version": self.target_history_selector_version,
                "target_history_projection": (),
                "pending_target_root_projection": (),
            }
        )
        self.retired_source_tombstones: dict[
            ObserverSourceLogicalSessionKey,
            ObserverSourceLogicalSessionRetirementTombstone,
        ] = {}
        self.retired_source_key_bytes = 0
        self.source_parent_selectors: dict[
            ObserverSourceLogicalSessionKey,
            ObserverSourceParentSelectorHead,
        ] = {}
        self.source_retirement_preparations: dict[
            ObserverSourceLogicalSessionKey,
            ObserverSourceLogicalSessionRetirementPreparationReceipt,
        ] = {}
        self.source_retirement_receipts: dict[
            ObserverSourceLogicalSessionKey,
            ObserverSourceLogicalSessionRetirementReceipt,
        ] = {}
        self.source_retirement_branches: dict[
            ObserverSourceLogicalSessionKey,
            tuple[ObserverSourceTargetRetirementBranch, ...],
        ] = {}
        self.mutant_future_retirement_receipt_digest = _digest(
            "observer-mutant-future-retirement-receipt-a"
        )
        self.quarantined_targets: dict[
            tuple[ObserverSourceLogicalSessionKey, str],
            ObserverUnresolvedTargetQuarantineEntry,
        ] = {}
        self.quarantined_target_key_bytes = 0
        self.quarantine_shard_roots = {
            kind: _digest(
                {
                    "domain": "observer-unresolved-quarantine-shard-genesis-v1",
                    "source_session_kind": kind,
                }
            )
            for kind in SOURCE_SESSION_KINDS
        }
        self.quarantine_commitments: dict[
            ObserverSourceLogicalSessionKey,
            ObserverUnresolvedTargetQuarantineCommitment,
        ] = {}
        self.quarantine_late_closure_evidence: dict[
            str,
            ObserverQuarantineLateClosureEvidence,
        ] = {}
        self.logical_session_namespace_entries: dict[
            ObserverSourceLogicalSessionKey,
            ObserverLogicalSessionNamespaceRegistryEntry,
        ] = {}
        self.logical_session_namespace_key_bytes = 0
        self.logical_session_namespace_registry_head = (
            self._seal_namespace_registry_head(
                ObserverLogicalSessionNamespaceRegistryHead(
                    authority_realm_key=self.authority_realm_key,
                    transaction_store_incarnation=(self.transaction_store_incarnation),
                    authority_transaction_domain_qualification_digest=(
                        self.authority_transaction_domain_qualification_digest
                    ),
                    registry_incarnation=_u_for(
                        (
                            "observer-logical-session-namespace-registry",
                            self.authority_realm_key,
                        )
                    ),
                    selector_id=_u_for(
                        (
                            "observer-logical-session-namespace-selector",
                            self.authority_realm_key,
                        )
                    ),
                    selector_version=1,
                    security_state_digest=SECURITY_STATE_DIGEST,
                    entries=(),
                    prior_head_digest="0" * 64,
                    head_digest="",
                )
            )
        )

    def _validate_capacity_manifest(
        self,
        manifest: ObserverAttachmentHistoryCapacityManifest,
    ) -> None:
        active_entry_reserves = (
            manifest.simulation_active_target_entry_reserve,
            manifest.plant_active_target_entry_reserve,
        )
        active_key_byte_reserves = (
            manifest.simulation_active_target_key_byte_reserve,
            manifest.plant_active_target_key_byte_reserve,
        )
        retired_entry_reserves = (
            manifest.simulation_retired_source_tombstone_reserve,
            manifest.plant_retired_source_tombstone_reserve,
        )
        retired_key_byte_reserves = (
            manifest.simulation_retired_source_key_byte_reserve,
            manifest.plant_retired_source_key_byte_reserve,
        )
        quarantine_entry_reserves = (
            manifest.simulation_quarantined_target_entry_reserve,
            manifest.plant_quarantined_target_entry_reserve,
        )
        quarantine_key_byte_reserves = (
            manifest.simulation_quarantined_target_key_byte_reserve,
            manifest.plant_quarantined_target_key_byte_reserve,
        )
        namespace_entry_reserves = (
            manifest.simulation_logical_session_namespace_entry_reserve,
            manifest.plant_logical_session_namespace_entry_reserve,
        )
        namespace_key_byte_reserves = (
            manifest.simulation_logical_session_namespace_key_byte_reserve,
            manifest.plant_logical_session_namespace_key_byte_reserve,
        )
        _require(
            _is_uuid4(manifest.manifest_id)
            and manifest.authority_realm_key == self.authority_realm_key
            and _closed_observer_target_identifier(
                manifest.authority_realm_key.server_authority_principal
            )
            and _closed_observer_target_identifier(
                manifest.authority_realm_key.stable_realm_id
            )
            and _safe_int(manifest.max_active_target_entries)
            and 1 <= manifest.max_active_target_entries <= MAX_REGISTRY_ENTRIES
            and _safe_int(manifest.max_active_target_key_bytes)
            and 1 <= manifest.max_active_target_key_bytes <= MAX_JSON_BYTES
            and all(_safe_int(value) and value > 0 for value in active_entry_reserves)
            and sum(active_entry_reserves) == manifest.max_active_target_entries
            and all(
                _safe_int(value) and value > 0 for value in active_key_byte_reserves
            )
            and sum(active_key_byte_reserves) == manifest.max_active_target_key_bytes
            and _safe_int(manifest.max_targets_per_source_generation)
            and 1
            <= manifest.max_targets_per_source_generation
            <= min(active_entry_reserves)
            and _safe_int(manifest.max_source_generation_count)
            and 1 <= manifest.max_source_generation_count <= MAX_SAFE_INTEGER
            and _safe_int(manifest.max_retired_source_tombstones)
            and 1 <= manifest.max_retired_source_tombstones <= MAX_REGISTRY_ENTRIES
            and _safe_int(manifest.max_retired_source_key_bytes)
            and 1 <= manifest.max_retired_source_key_bytes <= MAX_JSON_BYTES
            and all(_safe_int(value) and value > 0 for value in retired_entry_reserves)
            and sum(retired_entry_reserves) == manifest.max_retired_source_tombstones
            and all(
                _safe_int(value) and value > 0 for value in retired_key_byte_reserves
            )
            and sum(retired_key_byte_reserves) == manifest.max_retired_source_key_bytes
            and _safe_int(manifest.max_quarantined_target_entries)
            and 1 <= manifest.max_quarantined_target_entries <= MAX_REGISTRY_ENTRIES
            and _safe_int(manifest.max_quarantined_target_key_bytes)
            and 1 <= manifest.max_quarantined_target_key_bytes <= MAX_JSON_BYTES
            and all(
                _safe_int(value) and value > 0 for value in quarantine_entry_reserves
            )
            and sum(quarantine_entry_reserves)
            == manifest.max_quarantined_target_entries
            and all(
                _safe_int(value) and value > 0 for value in quarantine_key_byte_reserves
            )
            and sum(quarantine_key_byte_reserves)
            == manifest.max_quarantined_target_key_bytes
            and _safe_int(manifest.max_logical_session_namespace_entries)
            and 1
            <= manifest.max_logical_session_namespace_entries
            <= MAX_REGISTRY_ENTRIES
            and _safe_int(manifest.max_logical_session_namespace_key_bytes)
            and 1 <= manifest.max_logical_session_namespace_key_bytes <= MAX_JSON_BYTES
            and all(
                _safe_int(value) and value > 0 for value in namespace_entry_reserves
            )
            and sum(namespace_entry_reserves)
            == manifest.max_logical_session_namespace_entries
            and all(
                _safe_int(value) and value > 0 for value in namespace_key_byte_reserves
            )
            and sum(namespace_key_byte_reserves)
            == manifest.max_logical_session_namespace_key_bytes
            and manifest.manifest_digest == _body_digest(manifest, "manifest_digest"),
            "observer target-history capacity manifest is malformed, "
            "unbounded, foreign, or digest-substituted",
            CaptureError,
        )

    def _kind_reserve(self, source_session_kind: str, resource: str) -> int:
        _require(
            source_session_kind in SOURCE_SESSION_KINDS,
            "observer quota source session kind is unknown",
            CaptureError,
        )
        prefix = (
            "simulation" if source_session_kind == "SIMULATION_SERVICE" else "plant"
        )
        field_name = f"{prefix}_{resource}_reserve"
        value = _capture_artifact_field_value(self.capacity_manifest, field_name)
        _require(
            _safe_int(value) and value > 0,
            "observer quota shard is malformed",
            CaptureError,
        )
        return value

    def _active_target_count_for_kind(self, source_session_kind: str) -> int:
        return sum(
            target_key.source_session_kind == source_session_kind
            for target_key in self.target_history
        )

    def _active_target_key_bytes_for_kind(
        self,
        source_session_kind: str,
    ) -> int:
        return sum(
            self._target_key_bytes(target_key)
            for target_key in self.target_history
            if target_key.source_session_kind == source_session_kind
        )

    def _retired_source_count_for_kind(self, source_session_kind: str) -> int:
        return sum(
            source_key.source_session_kind == source_session_kind
            for source_key in self.retired_source_tombstones
        )

    def _retired_source_key_bytes_for_kind(
        self,
        source_session_kind: str,
    ) -> int:
        return sum(
            self._source_key_bytes(source_key)
            for source_key in self.retired_source_tombstones
            if source_key.source_session_kind == source_session_kind
        )

    def _quarantined_target_count_for_kind(
        self,
        source_session_kind: str,
    ) -> int:
        return sum(
            source_key.source_session_kind == source_session_kind
            for source_key, _target_key_digest in self.quarantined_targets
        )

    def _quarantined_target_key_bytes_for_kind(
        self,
        source_session_kind: str,
    ) -> int:
        return sum(
            len(bytes.fromhex(target_key_digest))
            for source_key, target_key_digest in self.quarantined_targets
            if source_key.source_session_kind == source_session_kind
        )

    @staticmethod
    def _seal_namespace_registry_entry(
        entry: ObserverLogicalSessionNamespaceRegistryEntry,
    ) -> ObserverLogicalSessionNamespaceRegistryEntry:
        return replace(
            entry,
            entry_digest=_body_digest(entry, "entry_digest"),
        )

    def _validate_namespace_registry_entry(
        self,
        entry: ObserverLogicalSessionNamespaceRegistryEntry,
    ) -> None:
        source_key = entry.source_namespace_key
        _require(
            source_key.authority_realm_key == self.authority_realm_key
            and source_key.source_session_kind in SOURCE_SESSION_KINDS
            and _closed_observer_target_identifier(source_key.source_logical_session_id)
            and entry.state in {"LIVE_NAMESPACE", "PERMANENTLY_RETIRED"}
            and _is_uuid4(entry.latest_source_generation)
            and (
                entry.state == "LIVE_NAMESPACE"
                and entry.permanent_retirement_tombstone_digest is None
                or entry.state == "PERMANENTLY_RETIRED"
                and entry.permanent_retirement_tombstone_digest is not None
                and HEX64.fullmatch(entry.permanent_retirement_tombstone_digest)
                is not None
            )
            and entry.entry_digest == _body_digest(entry, "entry_digest"),
            "observer logical-session namespace registry entry is malformed "
            "or digest-substituted",
            CaptureError,
        )

    @staticmethod
    def _seal_namespace_registry_head(
        head: ObserverLogicalSessionNamespaceRegistryHead,
    ) -> ObserverLogicalSessionNamespaceRegistryHead:
        return replace(
            head,
            head_digest=_body_digest(head, "head_digest"),
        )

    def _validate_namespace_registry_head(
        self,
        head: ObserverLogicalSessionNamespaceRegistryHead,
    ) -> None:
        expected_entries = tuple(
            sorted(
                (_digest(source_key), entry.entry_digest)
                for source_key, entry in self.logical_session_namespace_entries.items()
            )
        )
        _require(
            head.authority_realm_key == self.authority_realm_key
            and head.transaction_store_incarnation == self.transaction_store_incarnation
            and head.authority_transaction_domain_qualification_digest
            == self.authority_transaction_domain_qualification_digest
            and _is_uuid4(head.registry_incarnation)
            and _is_uuid4(head.selector_id)
            and _safe_int(head.selector_version)
            and head.selector_version >= 1
            and HEX64.fullmatch(head.security_state_digest) is not None
            and head.entries == expected_entries
            and len(head.entries)
            <= self.capacity_manifest.max_logical_session_namespace_entries
            and HEX64.fullmatch(head.prior_head_digest) is not None
            and head.head_digest == _body_digest(head, "head_digest"),
            "observer authority-global logical-session namespace registry "
            "head is malformed, stale, incomplete, or digest-substituted",
            CaptureError,
        )
        for entry in self.logical_session_namespace_entries.values():
            self._validate_namespace_registry_entry(entry)

    def _namespace_entry_candidate(
        self,
        context: SourceGenerationObserverContext,
    ) -> tuple[
        ObserverSourceLogicalSessionKey,
        ObserverLogicalSessionNamespaceRegistryEntry | None,
        int,
    ]:
        source_key = self._source_namespace_key(
            source_session_kind=context.source_session_kind,
            source_logical_session_id=context.source_logical_session_id,
        )
        existing = self.logical_session_namespace_entries.get(source_key)
        if existing is not None:
            self._validate_namespace_registry_entry(existing)
            _require(
                existing.state == "LIVE_NAMESPACE",
                "observer source logical-session namespace is permanently "
                "retired in the authority-global registry",
                CaptureError,
            )
            if existing.latest_source_generation == context.source_generation:
                return source_key, None, 0
            candidate = self._seal_namespace_registry_entry(
                replace(
                    existing,
                    latest_source_generation=context.source_generation,
                    entry_digest="",
                )
            )
            return source_key, candidate, 0
        key_bytes = self._source_key_bytes(source_key)
        kind = source_key.source_session_kind
        kind_count = sum(
            candidate_key.source_session_kind == kind
            for candidate_key in self.logical_session_namespace_entries
        )
        kind_key_bytes = sum(
            self._source_key_bytes(candidate_key)
            for candidate_key in self.logical_session_namespace_entries
            if candidate_key.source_session_kind == kind
        )
        _require(
            len(self.logical_session_namespace_entries)
            < self.capacity_manifest.max_logical_session_namespace_entries
            and kind_count
            < self._kind_reserve(
                kind,
                "logical_session_namespace_entry",
            )
            and self.logical_session_namespace_key_bytes + key_bytes
            <= self.capacity_manifest.max_logical_session_namespace_key_bytes
            and kind_key_bytes + key_bytes
            <= self._kind_reserve(
                kind,
                "logical_session_namespace_key_byte",
            ),
            "observer authority-global logical-session namespace registry "
            "capacity is exhausted",
            CaptureError,
        )
        candidate = self._seal_namespace_registry_entry(
            ObserverLogicalSessionNamespaceRegistryEntry(
                source_namespace_key=source_key,
                state="LIVE_NAMESPACE",
                latest_source_generation=context.source_generation,
                permanent_retirement_tombstone_digest=None,
                entry_digest="",
            )
        )
        return source_key, candidate, key_bytes

    def _commit_namespace_entry(
        self,
        *,
        source_key: ObserverSourceLogicalSessionKey,
        entry: ObserverLogicalSessionNamespaceRegistryEntry,
        added_key_bytes: int,
    ) -> None:
        self._validate_namespace_registry_head(
            self.logical_session_namespace_registry_head
        )
        self._validate_namespace_registry_entry(entry)
        prior_head = self.logical_session_namespace_registry_head
        self.logical_session_namespace_entries[source_key] = entry
        self.logical_session_namespace_key_bytes += added_key_bytes
        installed = self._seal_namespace_registry_head(
            replace(
                prior_head,
                selector_version=prior_head.selector_version + 1,
                entries=tuple(
                    sorted(
                        (_digest(key), value.entry_digest)
                        for key, value in (
                            self.logical_session_namespace_entries.items()
                        )
                    )
                ),
                prior_head_digest=prior_head.head_digest,
                head_digest="",
            )
        )
        self.logical_session_namespace_registry_head = installed
        self._validate_namespace_registry_head(installed)

    def rotate_logical_session_namespace_registry(
        self,
        *,
        new_registry_incarnation: str,
        new_security_state_digest: str,
    ) -> ObserverLogicalSessionNamespaceRegistryHead:
        """Carry authoritative tombstones across registry/security rotation."""

        prior = self.logical_session_namespace_registry_head
        self._validate_namespace_registry_head(prior)
        _require(
            _is_uuid4(new_registry_incarnation)
            and new_registry_incarnation != prior.registry_incarnation
            and HEX64.fullmatch(new_security_state_digest) is not None
            and new_security_state_digest != prior.security_state_digest,
            "observer namespace registry rotation is malformed or reuses its "
            "incarnation/security state",
            CaptureError,
        )
        if self.mutation == "namespace_registry_reenrollment_recreates_empty":
            self.logical_session_namespace_entries.clear()
            self.logical_session_namespace_key_bytes = 0
            self.retired_source_tombstones.clear()
            self.retired_source_key_bytes = 0
            self.source_parent_selectors.clear()
            self.source_retirement_receipts.clear()
            self.source_retirement_branches.clear()
        installed = self._seal_namespace_registry_head(
            replace(
                prior,
                registry_incarnation=new_registry_incarnation,
                selector_version=prior.selector_version + 1,
                security_state_digest=new_security_state_digest,
                entries=tuple(
                    sorted(
                        (_digest(key), entry.entry_digest)
                        for key, entry in (
                            self.logical_session_namespace_entries.items()
                        )
                    )
                ),
                prior_head_digest=prior.head_digest,
                head_digest="",
            )
        )
        self.logical_session_namespace_registry_head = installed
        self._validate_namespace_registry_head(installed)
        return installed

    def reject_second_namespace_registry_selector(
        self,
        *,
        candidate_selector_id: str,
    ) -> None:
        _require(
            _is_uuid4(candidate_selector_id)
            and candidate_selector_id
            == self.logical_session_namespace_registry_head.selector_id,
            "a second live logical-session namespace registry selector would "
            "recreate NO_GENERATION outside the sole authority-global registry",
            CaptureError,
        )

    def _source_namespace_key(
        self,
        *,
        source_session_kind: str,
        source_logical_session_id: str,
    ) -> ObserverSourceLogicalSessionKey:
        key = ObserverSourceLogicalSessionKey(
            authority_realm_key=self.authority_realm_key,
            source_session_kind=source_session_kind,
            source_logical_session_id=source_logical_session_id,
        )
        _require(
            key.authority_realm_key == self.authority_realm_key
            and key.source_session_kind in SOURCE_SESSION_KINDS
            and _closed_observer_target_identifier(key.source_logical_session_id),
            "observer source logical-session namespace is malformed",
            CaptureError,
        )
        return key

    @staticmethod
    def _target_key_bytes(target_key: ObserverAttachmentTargetKey) -> int:
        return len(_typed_canonical_bytes(target_key))

    @staticmethod
    def _source_key_bytes(source_key: ObserverSourceLogicalSessionKey) -> int:
        return len(_typed_canonical_bytes(source_key))

    def _target_history_projection(self) -> dict[str, Any]:
        return {
            "target_history": tuple(
                sorted(
                    (_digest(target_key), history.history_entry_digest)
                    for target_key, history in self.target_history.items()
                )
            ),
            "pending_target_roots": tuple(
                sorted(
                    (_digest(scope), root.root_digest)
                    for scope, root in self.pending_target_roots.items()
                )
            ),
        }

    def _advance_target_history_selector(
        self,
        *,
        event_digest: str,
    ) -> None:
        _require(
            HEX64.fullmatch(event_digest) is not None,
            "observer target-history selector event digest is malformed",
            CaptureError,
        )
        prior_head_digest = self.target_history_head_digest
        self.target_history_selector_version += 1
        self.target_history_head_digest = _digest(
            {
                "domain": "observer-attachment-target-history-head-successor-v1",
                "authority_transaction_domain_key": self.authority_realm_key,
                "selector_id": self.target_history_selector_id,
                "selector_version": self.target_history_selector_version,
                "prior_head_digest": prior_head_digest,
                "event_digest": event_digest,
                **self._target_history_projection(),
            }
        )

    def _next_generation_chain_digest(
        self,
        *,
        target_key: ObserverAttachmentTargetKey,
        prior_chain_digest: str,
        source_generation_count: int,
        source_generation: str,
    ) -> str:
        body: dict[str, Any] = {
            "domain": "observer-target-generation-chain-v1",
            "prior_chain_digest": prior_chain_digest,
            "source_generation": source_generation,
            "source_generation_count": source_generation_count,
        }
        if self.mutation != "generation_chain_omits_target_key":
            body["target_key"] = target_key
        return _digest(body)

    @staticmethod
    def _seal_target_history_entry(
        entry: ObserverAttachmentTargetHistoryEntry,
    ) -> ObserverAttachmentTargetHistoryEntry:
        return replace(
            entry,
            history_entry_digest=_body_digest(entry, "history_entry_digest"),
        )

    def _validate_target_history_entry(
        self,
        entry: ObserverAttachmentTargetHistoryEntry,
    ) -> None:
        key = entry.target_key
        _require(
            key.authority_realm_key == self.authority_realm_key
            and key.source_session_kind in SOURCE_SESSION_KINDS
            and _closed_observer_target_identifier(key.source_logical_session_id)
            and _closed_observer_target_identifier(
                key.authenticated_requester_principal
            )
            and _safe_int(entry.source_generation_count)
            and 1
            <= entry.source_generation_count
            <= self.capacity_manifest.max_source_generation_count
            and HEX64.fullmatch(entry.source_generation_chain_digest) is not None
            and _is_uuid4(entry.current_source_generation)
            and entry.phase in OBSERVER_TARGET_HISTORY_PHASES
            and (
                self.mutation == "history_digest_substitution_accepted"
                or entry.history_entry_digest
                == _body_digest(entry, "history_entry_digest")
            ),
            "observer target history is malformed, unbounded, or digest-substituted",
            CaptureError,
        )

    def _pending_root_digest(
        self,
        root: ObserverPendingTargetRoot,
    ) -> str:
        return _body_digest(root, "unpublished_target_key_digests", "root_digest")

    def _validate_pending_target_root(
        self,
        root: ObserverPendingTargetRoot,
    ) -> None:
        all_key_digests = tuple(
            key_digest
            for key_digest, _history_digest in root.target_history_candidate_digests
        )
        _require(
            root.source_namespace_key.authority_realm_key == self.authority_realm_key
            and root.source_namespace_key.source_session_kind in SOURCE_SESSION_KINDS
            and _closed_observer_target_identifier(
                root.source_namespace_key.source_logical_session_id
            )
            and _is_uuid4(root.source_generation)
            and _is_uuid4(root.observer_authorization_registry_id)
            and 1
            <= len(root.target_history_candidate_digests)
            <= self.capacity_manifest.max_targets_per_source_generation
            and tuple(sorted(set(root.target_history_candidate_digests)))
            == root.target_history_candidate_digests
            and all(
                HEX64.fullmatch(key_digest) is not None
                and HEX64.fullmatch(history_digest) is not None
                for key_digest, history_digest in (
                    root.target_history_candidate_digests
                )
            )
            and tuple(sorted(set(root.unpublished_target_key_digests)))
            == root.unpublished_target_key_digests
            and set(root.unpublished_target_key_digests).issubset(all_key_digests)
            and root.root_digest == self._pending_root_digest(root),
            "observer pending-target root is malformed, incomplete, or "
            "digest-substituted",
            CaptureError,
        )

    def _tombstone_digest(
        self,
        tombstone: ObserverSourceLogicalSessionRetirementTombstone,
    ) -> str:
        body = _body(tombstone, "tombstone_digest")
        if self.mutation == "retirement_tombstone_omits_source_key":
            body.pop("source_namespace_key")
        if self.mutation == "tombstone_depends_on_future_retirement_receipt":
            body["future_retirement_receipt_digest"] = (
                self.mutant_future_retirement_receipt_digest
            )
        return _digest(
            {
                "domain": "observer-source-logical-session-retirement-v1",
                "tombstone": body,
            }
        )

    def _seal_source_retirement_tombstone(
        self,
        tombstone: ObserverSourceLogicalSessionRetirementTombstone,
    ) -> ObserverSourceLogicalSessionRetirementTombstone:
        return replace(
            tombstone,
            tombstone_digest=self._tombstone_digest(tombstone),
        )

    def _validate_source_retirement_tombstone(
        self,
        tombstone: ObserverSourceLogicalSessionRetirementTombstone,
    ) -> None:
        _require(
            tombstone.source_namespace_key.authority_realm_key
            == self.authority_realm_key
            and tombstone.source_namespace_key.source_session_kind
            in SOURCE_SESSION_KINDS
            and _closed_observer_target_identifier(
                tombstone.source_namespace_key.source_logical_session_id
            )
            and _is_uuid4(tombstone.terminal_source_generation)
            and HEX64.fullmatch(tombstone.preparation_receipt_digest) is not None
            and _safe_int(tombstone.retired_target_count)
            and 0
            <= tombstone.retired_target_count
            <= self.capacity_manifest.max_active_target_entries
            and _safe_int(tombstone.published_target_count)
            and _safe_int(tombstone.sealed_unresolved_target_count)
            and tombstone.published_target_count
            + tombstone.sealed_unresolved_target_count
            == tombstone.retired_target_count
            and HEX64.fullmatch(tombstone.retired_target_history_root_digest)
            is not None
            and HEX64.fullmatch(tombstone.target_retirement_branch_root_digest)
            is not None
            and (
                tombstone.sealed_unresolved_target_count == 0
                and tombstone.quarantine_commitment_digest is None
                or tombstone.sealed_unresolved_target_count > 0
                and tombstone.quarantine_commitment_digest is not None
                and HEX64.fullmatch(tombstone.quarantine_commitment_digest) is not None
            )
            and _is_uuid4(tombstone.parent_selector_id)
            and _safe_int(tombstone.prepared_parent_selector_version)
            and tombstone.prepared_parent_selector_version >= 2
            and tombstone.retired_parent_selector_version
            == tombstone.prepared_parent_selector_version + 1
            and tombstone.namespace_reuse_forbidden is True
            and (
                self.mutation == "retirement_tombstone_digest_substitution_accepted"
                or tombstone.tombstone_digest == self._tombstone_digest(tombstone)
            ),
            "observer source logical-session retirement tombstone is malformed "
            "or digest-substituted",
            CaptureError,
        )

    def install_registered_source_generation(
        self,
        context: SourceGenerationObserverContext,
    ) -> ObserverLogicalSessionNamespaceRegistryEntry:
        """Install source-root registration before AttachObserver can run."""

        required_roles = self._required_child_roles(context.source_session_kind)
        source_namespace_key = self._source_namespace_key(
            source_session_kind=context.source_session_kind,
            source_logical_session_id=context.source_logical_session_id,
        )
        existing = self.logical_session_namespace_entries.get(source_namespace_key)
        if existing is not None:
            self._validate_namespace_registry_entry(existing)
        retired_tombstone = self.retired_source_tombstones.get(source_namespace_key)
        if retired_tombstone is not None:
            self._validate_source_retirement_tombstone(retired_tombstone)
        parent_selector = self.source_parent_selectors.get(source_namespace_key)
        _require(
            context.realm_authority == self.realm_authority
            and context.stable_realm_id == self.stable_realm_id
            and _closed_observer_target_identifier(context.source_logical_session_id)
            and _is_uuid4(context.source_generation)
            and context.generation_phase == "GENERATION_LIVE"
            and context.required_child_roles == required_roles
            and context.installed_child_roles == required_roles
            and _is_uuid4(context.observer_authorization_registry_id)
            and retired_tombstone is None
            and (
                parent_selector is None
                or parent_selector.phase != "SOURCE_LOGICAL_SESSION_PERMANENTLY_RETIRED"
            )
            and source_namespace_key not in self.source_retirement_preparations
            and (
                existing is None
                and parent_selector is None
                and context.predecessor_source_generation is None
                or existing is not None
                and parent_selector is not None
                and existing.state == "LIVE_NAMESPACE"
                and (
                    existing.latest_source_generation == context.source_generation
                    and parent_selector.phase == "GENERATION_LIVE"
                    and parent_selector.terminal_source_generation
                    == context.source_generation
                    or context.predecessor_source_generation
                    == existing.latest_source_generation
                    and context.source_generation != existing.latest_source_generation
                    and parent_selector.phase == "GENERATION_FINALIZED"
                    and parent_selector.terminal_source_generation
                    == context.predecessor_source_generation
                )
            ),
            "source generation lacks an authority-installed lineage "
            "registration edge or reuses a permanently retired namespace",
            CaptureError,
        )
        (
            candidate_key,
            candidate_entry,
            added_key_bytes,
        ) = self._namespace_entry_candidate(context)
        _require(
            candidate_key == source_namespace_key,
            "source lineage registration changed its namespace key",
            CaptureError,
        )
        if parent_selector is None:
            allocated = self._seal_source_parent_selector_head(
                ObserverSourceParentSelectorHead(
                    source_namespace_key=source_namespace_key,
                    lineage_incarnation=_u_for(
                        (
                            "observer-source-lineage-incarnation",
                            source_namespace_key,
                        )
                    ),
                    transaction_store_incarnation=(self.transaction_store_incarnation),
                    authority_transaction_domain_qualification_digest=(
                        self.authority_transaction_domain_qualification_digest
                    ),
                    selector_id=_u_for(
                        (
                            "observer-source-lineage-selector",
                            source_namespace_key,
                        )
                    ),
                    selector_version=2,
                    phase="GENERATION_ALLOCATED_PENDING_CHILD_GENESIS",
                    terminal_source_generation=context.source_generation,
                    prior_head_digest=_digest(
                        {
                            "domain": ("observer-source-lineage-no-generation-head-v1"),
                            "source_namespace_key": source_namespace_key,
                            "selector_version": 1,
                        }
                    ),
                    transition_evidence_digest=_digest(
                        {
                            "event": ("ALLOCATE_FIRST_LOGICAL_SESSION_GENERATION"),
                            "source_namespace_key": source_namespace_key,
                            "source_generation": context.source_generation,
                        }
                    ),
                    head_digest="",
                )
            )
        elif parent_selector.terminal_source_generation != context.source_generation:
            _require(
                parent_selector.phase == "GENERATION_FINALIZED"
                and context.predecessor_source_generation
                == parent_selector.terminal_source_generation,
                "source generation registration lacks the exact finalized "
                "lineage predecessor",
                CaptureError,
            )
            allocated = self._seal_source_parent_selector_head(
                replace(
                    parent_selector,
                    selector_version=parent_selector.selector_version + 1,
                    phase="GENERATION_ALLOCATED_PENDING_CHILD_GENESIS",
                    terminal_source_generation=context.source_generation,
                    prior_head_digest=parent_selector.head_digest,
                    transition_evidence_digest=_digest(
                        {
                            "event": ("ALLOCATE_SUCCESSOR_LOGICAL_SESSION_GENERATION"),
                            "source_namespace_key": source_namespace_key,
                            "predecessor_source_generation": (
                                context.predecessor_source_generation
                            ),
                            "source_generation": context.source_generation,
                        }
                    ),
                    head_digest="",
                )
            )
        else:
            allocated = parent_selector
        if allocated.phase == "GENERATION_ALLOCATED_PENDING_CHILD_GENESIS":
            live = self._seal_source_parent_selector_head(
                replace(
                    allocated,
                    selector_version=allocated.selector_version + 1,
                    phase="GENERATION_LIVE",
                    prior_head_digest=allocated.head_digest,
                    transition_evidence_digest=_digest(
                        {
                            "event": ("CONFIRM_LOGICAL_SESSION_GENERATION_LIVE"),
                            "source_namespace_key": source_namespace_key,
                            "source_generation": context.source_generation,
                        }
                    ),
                    head_digest="",
                )
            )
            self._validate_source_parent_selector_head(allocated)
            self._validate_source_parent_selector_head(live)
            installed_parent = live
        else:
            _require(
                allocated.phase == "GENERATION_LIVE"
                and allocated.terminal_source_generation == context.source_generation,
                "source generation registration is not idempotent on the exact "
                "live lineage",
                CaptureError,
            )
            self._validate_source_parent_selector_head(allocated)
            installed_parent = allocated

        # Registration is one authority-domain transaction. Validate both
        # candidates before publishing either namespace membership or lineage.
        if candidate_entry is not None:
            self._commit_namespace_entry(
                source_key=candidate_key,
                entry=candidate_entry,
                added_key_bytes=added_key_bytes,
            )
        self.source_parent_selectors[source_namespace_key] = installed_parent
        installed = self.logical_session_namespace_entries.get(source_namespace_key)
        _require(
            installed is not None
            and installed.state == "LIVE_NAMESPACE"
            and installed.latest_source_generation == context.source_generation,
            "source lineage registration did not install the exact live generation",
            CaptureError,
        )
        if installed is None:
            raise CaptureError("validated source lineage registration is absent")
        return installed

    @staticmethod
    def _required_child_roles(source_session_kind: str) -> tuple[str, ...]:
        roles = REQUIRED_SOURCE_GENERATION_CHILD_ROLES.get(source_session_kind)
        _require(
            roles is not None,
            "source session kind has no observer-authorization child allocation",
            CaptureError,
        )
        if roles is None:
            raise CaptureError("validated source child roles are absent")
        return roles

    def validate_source_context(
        self,
        context: SourceGenerationObserverContext,
    ) -> None:
        """Require one live source generation with its exact sibling children."""

        required_roles = self._required_child_roles(context.source_session_kind)
        source_namespace_key = self._source_namespace_key(
            source_session_kind=context.source_session_kind,
            source_logical_session_id=context.source_logical_session_id,
        )
        retired_tombstone = self.retired_source_tombstones.get(source_namespace_key)
        if retired_tombstone is not None:
            self._validate_source_retirement_tombstone(retired_tombstone)
        namespace_entry = self.logical_session_namespace_entries.get(
            source_namespace_key
        )
        parent_selector = self.source_parent_selectors.get(source_namespace_key)
        if namespace_entry is not None:
            self._validate_namespace_registry_entry(namespace_entry)
        _require(
            context.realm_authority == self.realm_authority
            and context.stable_realm_id == self.stable_realm_id
            and _closed_observer_target_identifier(context.source_logical_session_id)
            and _is_uuid4(context.source_generation)
            and (
                context.predecessor_source_generation is None
                or _is_uuid4(context.predecessor_source_generation)
                and context.predecessor_source_generation != context.source_generation
            )
            and context.generation_phase == "GENERATION_LIVE"
            and context.required_child_roles == required_roles
            and context.installed_child_roles == required_roles
            and _is_uuid4(context.observer_authorization_registry_id),
            "observer attach source lacks its exact live observer-authorization "
            "child and role-specific sibling",
            CaptureError,
        )
        _require(
            retired_tombstone is None
            and (
                namespace_entry is not None
                and namespace_entry.state == "LIVE_NAMESPACE"
                and namespace_entry.latest_source_generation
                == context.source_generation
            )
            and parent_selector is not None
            and parent_selector.phase == "GENERATION_LIVE"
            and parent_selector.terminal_source_generation == context.source_generation
            and source_namespace_key not in self.source_retirement_preparations,
            "observer attach lacks the exact authority-installed source "
            "generation or raced a prepared/permanently retired namespace",
            CaptureError,
        )

    def canonical_target_key(
        self,
        intent: ObserverAttachIntent,
    ) -> ObserverAttachmentTargetKey:
        """Derive the realm-owned key without generation or observer namespace."""

        _require(
            _is_uuid4(intent.intent_id)
            and intent.realm_authority == self.realm_authority
            and intent.stable_realm_id == self.stable_realm_id
            and intent.source_session_kind in SOURCE_SESSION_KINDS
            and _closed_observer_target_identifier(intent.source_logical_session_id)
            and _closed_observer_target_identifier(
                intent.authenticated_requester_principal
            )
            and 1 <= len(intent.requested_scope_digests) <= MAX_REGISTRY_ENTRIES
            and tuple(sorted(set(intent.requested_scope_digests)))
            == intent.requested_scope_digests
            and all(
                HEX64.fullmatch(digest) is not None
                for digest in intent.requested_scope_digests
            )
            and intent.caller_observer_session_id is None
            and intent.caller_source_generation is None
            and intent.caller_authorization_registry_id is None,
            "AttachObserver contains a malformed target or caller-selected "
            "observer session, source generation, or registry namespace",
            CaptureError,
        )
        authority_realm_key = self.authority_realm_key
        if self.mutation == "target_coordinate_omits_server_authority":
            authority_realm_key = ObserverAuthorityRealmKey(
                server_authority_principal="omitted-server-authority",
                stable_realm_id=self.stable_realm_id,
            )
        return ObserverAttachmentTargetKey(
            authority_realm_key=authority_realm_key,
            source_session_kind=intent.source_session_kind,
            source_logical_session_id=intent.source_logical_session_id,
            authenticated_requester_principal=(
                intent.authenticated_requester_principal
            ),
        )

    def attach(
        self,
        *,
        context: SourceGenerationObserverContext,
        intent: ObserverAttachIntent,
    ) -> ObserverAuthorizationRegistryEntry:
        """Install one target in the source registry without ADR-001 allocation."""

        self.validate_source_context(context)
        target_key = self.canonical_target_key(intent)
        _require(
            intent.realm_authority == context.realm_authority
            and intent.stable_realm_id == context.stable_realm_id
            and intent.source_session_kind == context.source_session_kind
            and intent.source_logical_session_id == context.source_logical_session_id,
            "AttachObserver target does not match the selected source generation",
            CaptureError,
        )
        existing_history = self.target_history.get(target_key)
        if existing_history is None:
            target_key_bytes = self._target_key_bytes(target_key)
            active_kind_count = self._active_target_count_for_kind(
                target_key.source_session_kind
            )
            kind_entry_reserve = self._kind_reserve(
                target_key.source_session_kind,
                "active_target_entry",
            )
            kind_capacity_compare = (
                active_kind_count <= kind_entry_reserve
                if self.mutation == "active_target_capacity_off_by_one"
                else active_kind_count < kind_entry_reserve
            )
            _require(
                len(self.target_history)
                < self.capacity_manifest.max_active_target_entries
                and kind_capacity_compare
                and self.active_target_key_bytes + target_key_bytes
                <= self.capacity_manifest.max_active_target_key_bytes
                and self._active_target_key_bytes_for_kind(
                    target_key.source_session_kind
                )
                + target_key_bytes
                <= self._kind_reserve(
                    target_key.source_session_kind,
                    "active_target_key_byte",
                ),
                "observer realm-global active target/key-byte capacity is exhausted",
                CaptureError,
            )
            source_generation_count = 1
            prior_chain_digest = OBSERVER_GENERATION_CHAIN_GENESIS_DIGEST
        else:
            self._validate_target_history_entry(existing_history)
            _require(
                context.predecessor_source_generation is not None
                and existing_history.current_source_generation
                == context.predecessor_source_generation
                and existing_history.phase == "CHECKPOINT_PUBLISHED",
                "observer target rollover lacks its realm-global predecessor "
                "checkpoint",
                CaptureError,
            )
            _require(
                existing_history.source_generation_count
                < self.capacity_manifest.max_source_generation_count,
                "observer target source-generation counter is exhausted",
                CaptureError,
            )
            target_key_bytes = 0
            source_generation_count = existing_history.source_generation_count + 1
            prior_chain_digest = existing_history.source_generation_chain_digest

        registry_scope = (
            context.source_session_kind,
            context.source_logical_session_id,
            context.source_generation,
        )
        prior_scope = self.registry_scopes.get(
            context.observer_authorization_registry_id
        )
        _require(
            prior_scope is None or prior_scope == registry_scope,
            "observer authorization registry was reused across source generations",
            CaptureError,
        )
        registry = dict(
            self.source_authorization_registries.get(
                context.observer_authorization_registry_id,
                {},
            )
        )
        _require(
            target_key not in registry
            and len(registry)
            < self.capacity_manifest.max_targets_per_source_generation,
            "observer authorization target is duplicate or registry capacity is "
            "exhausted",
            CaptureError,
        )
        entry = ObserverAuthorizationRegistryEntry(
            target_key=target_key,
            source_generation=context.source_generation,
            attach_intent_digest=_digest(intent),
            state="ATTACHED_READ_ONLY",
        )
        history = self._seal_target_history_entry(
            ObserverAttachmentTargetHistoryEntry(
                target_key=target_key,
                source_generation_count=source_generation_count,
                source_generation_chain_digest=self._next_generation_chain_digest(
                    target_key=target_key,
                    prior_chain_digest=prior_chain_digest,
                    source_generation_count=source_generation_count,
                    source_generation=context.source_generation,
                ),
                current_source_generation=context.source_generation,
                phase="GENERATION_LIVE",
                history_entry_digest="",
            )
        )
        self._validate_target_history_entry(history)
        registry[target_key] = entry
        self.source_authorization_registries[
            context.observer_authorization_registry_id
        ] = registry
        self.registry_scopes[context.observer_authorization_registry_id] = (
            registry_scope
        )
        self.target_history[target_key] = history
        self.active_target_key_bytes += target_key_bytes
        self._advance_target_history_selector(
            event_digest=_digest(
                {
                    "event": "ATTACH_OBSERVER_TARGET",
                    "registry_entry": entry,
                    "history_entry_digest": history.history_entry_digest,
                }
            )
        )
        return entry

    def finalize_source_generation(
        self,
        context: SourceGenerationObserverContext,
        *,
        server_registry_cut_installed: bool,
        complete_pending_target_root_installed: bool,
    ) -> int:
        """Release the source after auth closure, before transport publication."""

        required_roles = self._required_child_roles(context.source_session_kind)
        _require(
            context.realm_authority == self.realm_authority
            and _closed_observer_target_identifier(context.source_logical_session_id)
            and _is_uuid4(context.source_generation)
            and context.generation_phase == "GENERATION_FINALIZED"
            and context.required_child_roles == required_roles
            and context.installed_child_roles == required_roles
            and _is_uuid4(context.observer_authorization_registry_id),
            "observer closure does not come from the exact finalized source "
            "generation and required child set",
            CaptureError,
        )
        _require(
            server_registry_cut_installed and complete_pending_target_root_installed,
            "source finalization lacks its exact server registry cut or complete "
            "durable pending-target root",
            CaptureError,
        )
        registry = self.source_authorization_registries.get(
            context.observer_authorization_registry_id
        )
        source_scope = (
            context.source_session_kind,
            context.source_logical_session_id,
            context.source_generation,
        )
        source_namespace_key = self._source_namespace_key(
            source_session_kind=context.source_session_kind,
            source_logical_session_id=context.source_logical_session_id,
        )
        namespace_entry = self.logical_session_namespace_entries.get(
            source_namespace_key
        )
        if namespace_entry is not None:
            self._validate_namespace_registry_entry(namespace_entry)
        self._validate_namespace_registry_head(
            self.logical_session_namespace_registry_head
        )
        prior_parent = self.source_parent_selectors.get(source_namespace_key)
        _require(
            namespace_entry is not None
            and namespace_entry.state == "LIVE_NAMESPACE"
            and namespace_entry.latest_source_generation == context.source_generation
            and prior_parent is not None
            and prior_parent.phase == "GENERATION_LIVE"
            and prior_parent.terminal_source_generation == context.source_generation,
            "source finalization lacks its exact live namespace membership or "
            "ADR-001 lineage head",
            CaptureError,
        )
        if prior_parent is None:
            raise CaptureError("validated live source lineage head is absent")
        self._validate_source_parent_selector_head(prior_parent)
        _require(
            registry is not None and bool(registry),
            "observer generation checkpoint has no installed source registry",
            CaptureError,
        )
        if registry is None:
            raise CaptureError("validated observer source registry is absent")
        _require(
            self.registry_scopes.get(context.observer_authorization_registry_id)
            == source_scope
            and source_scope not in self.pending_target_roots,
            "observer source registry scope is stale or already finalized",
            CaptureError,
        )
        pending_histories: dict[
            ObserverAttachmentTargetKey,
            ObserverAttachmentTargetHistoryEntry,
        ] = {}
        for target_key in registry:
            history = self.target_history.get(target_key)
            if history is not None:
                self._validate_target_history_entry(history)
            _require(
                history is not None
                and history.current_source_generation == context.source_generation
                and history.phase == "GENERATION_LIVE",
                "observer source closure lost a realm-global target entry",
                CaptureError,
            )
            if history is None:
                raise CaptureError("validated observer target history is absent")
            pending_histories[target_key] = self._seal_target_history_entry(
                replace(
                    history,
                    phase=("GENERATION_FINALIZED_PENDING_CHECKPOINT_PUBLICATION"),
                    history_entry_digest="",
                )
            )
        candidate_digests = tuple(
            sorted(
                (
                    _digest(target_key),
                    pending_histories[target_key].history_entry_digest,
                )
                for target_key in registry
            )
        )
        pending_root = ObserverPendingTargetRoot(
            source_namespace_key=source_namespace_key,
            source_generation=context.source_generation,
            observer_authorization_registry_id=(
                context.observer_authorization_registry_id
            ),
            target_history_candidate_digests=candidate_digests,
            unpublished_target_key_digests=tuple(
                key_digest for key_digest, _history_digest in candidate_digests
            ),
            root_digest="",
        )
        pending_root = replace(
            pending_root,
            root_digest=self._pending_root_digest(pending_root),
        )
        self._validate_pending_target_root(pending_root)
        installed_parent = self._seal_source_parent_selector_head(
            replace(
                prior_parent,
                selector_version=prior_parent.selector_version + 1,
                phase="GENERATION_FINALIZED",
                prior_head_digest=prior_parent.head_digest,
                transition_evidence_digest=_digest(
                    {
                        "event": ("FINALIZE_LOGICAL_SESSION_GENERATION_IN_LINEAGE"),
                        "source_namespace_key": source_namespace_key,
                        "source_generation": context.source_generation,
                        "pending_target_root_digest": pending_root.root_digest,
                    }
                ),
                head_digest="",
            )
        )
        self._validate_source_parent_selector_head(installed_parent)

        # The validated candidates above are one authority-domain transaction.
        # Publish no target, registry, or lineage member until every compare and
        # candidate validation has succeeded.
        self.target_history.update(pending_histories)
        self.pending_target_roots[source_scope] = pending_root
        del self.source_authorization_registries[
            context.observer_authorization_registry_id
        ]
        del self.registry_scopes[context.observer_authorization_registry_id]
        self._advance_target_history_selector(
            event_digest=_digest(
                {
                    "event": "FINALIZE_SOURCE_OBSERVER_AUTHORIZATION",
                    "pending_target_root_digest": pending_root.root_digest,
                }
            )
        )
        self.source_parent_selectors[source_namespace_key] = installed_parent
        return len(registry)

    def source_successor_and_handover_released(
        self,
        context: SourceGenerationObserverContext,
    ) -> bool:
        """Do not let retained transport publication hold source ownership."""

        source_scope = (
            context.source_session_kind,
            context.source_logical_session_id,
            context.source_generation,
        )
        pending_target_root = self.pending_target_roots.get(source_scope)
        if pending_target_root is None:
            return False
        self._validate_pending_target_root(pending_target_root)
        return True

    def publish_target_checkpoint(
        self,
        *,
        context: SourceGenerationObserverContext,
        target_key: ObserverAttachmentTargetKey,
        distributed_authorization_closed: bool,
        retained_transport_quiescent: bool,
    ) -> ObserverAttachmentTargetHistoryEntry:
        """Publish one target checkpoint after the parent finalization edge."""

        _require(
            self.source_successor_and_handover_released(context),
            "observer target checkpoint precedes source finalization",
            CaptureError,
        )
        _require(
            distributed_authorization_closed and retained_transport_quiescent,
            "observer target checkpoint lacks distributed authorization closure "
            "or retained transport quiescence",
            CaptureError,
        )
        source_scope = (
            context.source_session_kind,
            context.source_logical_session_id,
            context.source_generation,
        )
        pending_root = self.pending_target_roots.get(source_scope)
        history = self.target_history.get(target_key)
        if pending_root is not None:
            self._validate_pending_target_root(pending_root)
        if history is not None:
            self._validate_target_history_entry(history)
        target_key_digest = _digest(target_key)
        _require(
            pending_root is not None
            and pending_root.observer_authorization_registry_id
            == context.observer_authorization_registry_id
            and target_key_digest
            in {
                key_digest
                for key_digest, _history_digest in (
                    pending_root.target_history_candidate_digests
                )
            }
            and target_key_digest in pending_root.unpublished_target_key_digests
            and history is not None
            and history.current_source_generation == context.source_generation
            and history.phase == "GENERATION_FINALIZED_PENDING_CHECKPOINT_PUBLICATION",
            "observer target checkpoint is absent, stale, or already published",
            CaptureError,
        )
        if history is None:
            raise CaptureError("validated observer target history is absent")
        installed = self._seal_target_history_entry(
            replace(
                history,
                phase="CHECKPOINT_PUBLISHED",
                history_entry_digest="",
            )
        )
        self._validate_target_history_entry(installed)
        self.target_history[target_key] = installed
        if pending_root is None:
            raise CaptureError("validated observer pending-target root is absent")
        remaining = tuple(
            digest
            for digest in pending_root.unpublished_target_key_digests
            if digest != target_key_digest
        )
        if remaining:
            installed_root = replace(
                pending_root,
                unpublished_target_key_digests=remaining,
            )
            self._validate_pending_target_root(installed_root)
            self.pending_target_roots[source_scope] = installed_root
        else:
            del self.pending_target_roots[source_scope]
        self._advance_target_history_selector(
            event_digest=_digest(
                {
                    "event": "PUBLISH_OBSERVER_TARGET_CHECKPOINT",
                    "target_key_digest": target_key_digest,
                    "installed_history_entry_digest": (installed.history_entry_digest),
                }
            )
        )
        return installed

    @staticmethod
    def _seal_source_parent_selector_head(
        head: ObserverSourceParentSelectorHead,
    ) -> ObserverSourceParentSelectorHead:
        return replace(head, head_digest=_body_digest(head, "head_digest"))

    def _validate_source_parent_selector_head(
        self,
        head: ObserverSourceParentSelectorHead,
    ) -> None:
        _require(
            head.source_namespace_key.authority_realm_key == self.authority_realm_key
            and head.source_namespace_key.source_session_kind in SOURCE_SESSION_KINDS
            and _closed_observer_target_identifier(
                head.source_namespace_key.source_logical_session_id
            )
            and _is_uuid4(head.lineage_incarnation)
            and head.transaction_store_incarnation == self.transaction_store_incarnation
            and head.authority_transaction_domain_qualification_digest
            == self.authority_transaction_domain_qualification_digest
            and _is_uuid4(head.selector_id)
            and _safe_int(head.selector_version)
            and head.selector_version >= 1
            and head.phase
            in {
                "GENERATION_ALLOCATED_PENDING_CHILD_GENESIS",
                "GENERATION_FINALIZED",
                "GENERATION_LIVE",
                "SOURCE_LOGICAL_SESSION_PERMANENTLY_RETIRED",
                "SOURCE_LOGICAL_SESSION_RETIREMENT_PREPARED",
            }
            and _is_uuid4(head.terminal_source_generation)
            and HEX64.fullmatch(head.prior_head_digest) is not None
            and HEX64.fullmatch(head.transition_evidence_digest) is not None
            and head.head_digest == _body_digest(head, "head_digest"),
            "observer source parent selector head is malformed or digest-substituted",
            CaptureError,
        )

    @staticmethod
    def _seal_source_target_retirement_branch(
        branch: ObserverSourceTargetRetirementBranch,
    ) -> ObserverSourceTargetRetirementBranch:
        return replace(
            branch,
            branch_digest=_body_digest(branch, "branch_digest"),
        )

    def _validate_source_target_retirement_branch(
        self,
        branch: ObserverSourceTargetRetirementBranch,
    ) -> None:
        _require(
            HEX64.fullmatch(branch.target_key_digest) is not None
            and HEX64.fullmatch(branch.history_entry_digest) is not None
            and branch.branch_kind in {"PUBLISHED", "SEALED_UNRESOLVED"}
            and (
                branch.branch_kind == "PUBLISHED"
                and branch.pending_target_root_digest is None
                or branch.branch_kind == "SEALED_UNRESOLVED"
                and branch.pending_target_root_digest is not None
                and HEX64.fullmatch(branch.pending_target_root_digest) is not None
            )
            and branch.branch_digest == _body_digest(branch, "branch_digest"),
            "observer source target retirement branch is malformed, ambiguous, "
            "or digest-substituted",
            CaptureError,
        )

    @staticmethod
    def _seal_source_retirement_preparation_target(
        target: ObserverSourceTargetRetirementPreparationTarget,
    ) -> ObserverSourceTargetRetirementPreparationTarget:
        return replace(
            target,
            target_ancestry_digest=_body_digest(
                target,
                "target_ancestry_digest",
            ),
        )

    def _validate_source_retirement_preparation_target(
        self,
        target: ObserverSourceTargetRetirementPreparationTarget,
    ) -> None:
        _require(
            HEX64.fullmatch(target.target_key_digest) is not None
            and _safe_int(target.source_generation_count)
            and 1
            <= target.source_generation_count
            <= self.capacity_manifest.max_source_generation_count
            and HEX64.fullmatch(target.source_generation_chain_digest) is not None
            and _is_uuid4(target.terminal_source_generation)
            and target.target_ancestry_digest
            == _body_digest(target, "target_ancestry_digest"),
            "observer source retirement preparation target ancestry is "
            "malformed or mutable-phase-dependent",
            CaptureError,
        )

    @staticmethod
    def _seal_source_retirement_preparation_fact(
        fact: ObserverSourceLogicalSessionRetirementPreparationFact,
    ) -> ObserverSourceLogicalSessionRetirementPreparationFact:
        return replace(fact, fact_digest=_body_digest(fact, "fact_digest"))

    def _validate_source_retirement_preparation_fact(
        self,
        fact: ObserverSourceLogicalSessionRetirementPreparationFact,
    ) -> None:
        for target in fact.target_ancestries:
            self._validate_source_retirement_preparation_target(target)
        ancestry_root = _digest(
            {
                "domain": "observer-source-target-retirement-ancestry-root-v1",
                "source_namespace_key": fact.source_namespace_key,
                "terminal_source_generation": fact.terminal_source_generation,
                "target_ancestries": tuple(
                    target.target_ancestry_digest for target in fact.target_ancestries
                ),
            }
        )
        _require(
            _is_uuid4(fact.fact_id)
            and fact.source_namespace_key.authority_realm_key
            == self.authority_realm_key
            and fact.preparation_origin == "FINALIZED_SOURCE_GENERATION"
            and _is_uuid4(fact.terminal_source_generation)
            and HEX64.fullmatch(fact.source_finalization_receipt_digest) is not None
            and _is_uuid4(fact.parent_selector_id)
            and _safe_int(fact.expected_parent_selector_version)
            and fact.expected_parent_selector_version >= 1
            and HEX64.fullmatch(fact.expected_parent_head_digest) is not None
            and _is_uuid4(fact.expected_namespace_registry_selector_id)
            and _safe_int(fact.expected_namespace_registry_selector_version)
            and fact.expected_namespace_registry_selector_version >= 1
            and HEX64.fullmatch(fact.expected_namespace_registry_head_digest)
            is not None
            and HEX64.fullmatch(fact.expected_namespace_registry_entry_digest)
            is not None
            and tuple(
                sorted(
                    fact.target_ancestries,
                    key=lambda target: target.target_key_digest,
                )
            )
            == fact.target_ancestries
            and len({target.target_key_digest for target in fact.target_ancestries})
            == len(fact.target_ancestries)
            and 1
            <= len(fact.target_ancestries)
            <= self.capacity_manifest.max_active_target_entries
            and all(
                target.terminal_source_generation == fact.terminal_source_generation
                for target in fact.target_ancestries
            )
            and fact.target_ancestry_root_digest == ancestry_root
            and fact.fact_digest == _body_digest(fact, "fact_digest"),
            "observer source retirement preparation fact is malformed, "
            "phase-dependent, incomplete, or digest-substituted",
            CaptureError,
        )

    @staticmethod
    def _seal_source_retirement_preparation_receipt(
        receipt: ObserverSourceLogicalSessionRetirementPreparationReceipt,
    ) -> ObserverSourceLogicalSessionRetirementPreparationReceipt:
        return replace(
            receipt,
            receipt_digest=_body_digest(receipt, "receipt_digest"),
        )

    def _validate_source_retirement_preparation_receipt(
        self,
        receipt: ObserverSourceLogicalSessionRetirementPreparationReceipt,
    ) -> None:
        self._validate_source_retirement_preparation_fact(receipt.preparation_fact)
        fact = receipt.preparation_fact
        _require(
            receipt.parent_selector_id == fact.parent_selector_id
            and receipt.prior_parent_selector_version
            == fact.expected_parent_selector_version
            and receipt.prepared_parent_selector_version
            == receipt.prior_parent_selector_version + 1
            and receipt.prior_parent_head_digest == fact.expected_parent_head_digest
            and HEX64.fullmatch(receipt.prepared_parent_head_digest) is not None
            and receipt.compared_namespace_registry_head_digest
            == fact.expected_namespace_registry_head_digest
            and receipt.compared_target_history_selector_id
            == self.target_history_selector_id
            and _safe_int(receipt.compared_target_history_selector_version)
            and receipt.compared_target_history_selector_version >= 1
            and HEX64.fullmatch(receipt.compared_target_history_head_digest) is not None
            and HEX64.fullmatch(receipt.authority_transaction_commit_receipt_digest)
            is not None
            and receipt.receipt_digest == _body_digest(receipt, "receipt_digest"),
            "observer source retirement preparation receipt is malformed, "
            "pre-commit, or digest-substituted",
            CaptureError,
        )

    @staticmethod
    def _seal_source_retirement_receipt(
        receipt: ObserverSourceLogicalSessionRetirementReceipt,
    ) -> ObserverSourceLogicalSessionRetirementReceipt:
        return replace(
            receipt,
            receipt_digest=_body_digest(receipt, "receipt_digest"),
        )

    def _validate_source_retirement_receipt(
        self,
        receipt: ObserverSourceLogicalSessionRetirementReceipt,
    ) -> None:
        _require(
            HEX64.fullmatch(receipt.preparation_receipt_digest) is not None
            and receipt.source_namespace_key.authority_realm_key
            == self.authority_realm_key
            and _is_uuid4(receipt.terminal_source_generation)
            and HEX64.fullmatch(receipt.tombstone_digest) is not None
            and HEX64.fullmatch(receipt.prior_parent_selector_head_digest) is not None
            and HEX64.fullmatch(receipt.installed_parent_selector_head_digest)
            is not None
            and HEX64.fullmatch(receipt.prior_namespace_registry_head_digest)
            is not None
            and HEX64.fullmatch(receipt.installed_namespace_registry_head_digest)
            is not None
            and _safe_int(receipt.prior_target_history_selector_version)
            and receipt.prior_target_history_selector_version >= 1
            and receipt.installed_target_history_selector_version
            == receipt.prior_target_history_selector_version + 1
            and HEX64.fullmatch(receipt.prior_target_history_head_digest) is not None
            and HEX64.fullmatch(receipt.installed_target_history_head_digest)
            is not None
            and HEX64.fullmatch(receipt.target_retirement_branch_root_digest)
            is not None
            and (
                receipt.quarantine_commitment_digest is None
                or HEX64.fullmatch(receipt.quarantine_commitment_digest) is not None
            )
            and receipt.namespace_reuse_forbidden is True
            and HEX64.fullmatch(receipt.authority_transaction_commit_receipt_digest)
            is not None
            and receipt.receipt_digest == _body_digest(receipt, "receipt_digest"),
            "observer permanent source retirement receipt is malformed, "
            "pre-commit, or digest-substituted",
            CaptureError,
        )

    @staticmethod
    def _seal_quarantine_entry(
        entry: ObserverUnresolvedTargetQuarantineEntry,
    ) -> ObserverUnresolvedTargetQuarantineEntry:
        return replace(entry, entry_digest=_body_digest(entry, "entry_digest"))

    def _validate_quarantine_entry(
        self,
        entry: ObserverUnresolvedTargetQuarantineEntry,
    ) -> None:
        _require(
            entry.source_namespace_key.authority_realm_key == self.authority_realm_key
            and _is_uuid4(entry.terminal_source_generation)
            and HEX64.fullmatch(entry.target_key_digest) is not None
            and HEX64.fullmatch(entry.sealed_history_entry_digest) is not None
            and HEX64.fullmatch(entry.pending_target_root_digest) is not None
            and entry.state == "SEALED_UNRESOLVED"
            and entry.entry_digest == _body_digest(entry, "entry_digest"),
            "observer unresolved target quarantine entry is malformed, "
            "authority-bearing, or digest-substituted",
            CaptureError,
        )

    @staticmethod
    def _seal_quarantine_commitment(
        commitment: ObserverUnresolvedTargetQuarantineCommitment,
    ) -> ObserverUnresolvedTargetQuarantineCommitment:
        return replace(
            commitment,
            commitment_digest=_body_digest(commitment, "commitment_digest"),
        )

    @staticmethod
    def _seal_quarantine_late_closure_evidence(
        evidence: ObserverQuarantineLateClosureEvidence,
    ) -> ObserverQuarantineLateClosureEvidence:
        return replace(
            evidence,
            evidence_digest=_body_digest(evidence, "evidence_digest"),
        )

    def install_terminal_source_parent_selector(
        self,
        *,
        source_namespace_key: ObserverSourceLogicalSessionKey,
        terminal_source_generation: str,
    ) -> ObserverSourceParentSelectorHead:
        """Read the exact ADR-001 finalized lineage head used by the race."""

        namespace_entry = self.logical_session_namespace_entries.get(
            source_namespace_key
        )
        head = self.source_parent_selectors.get(source_namespace_key)
        matching_scope = (
            source_namespace_key.source_session_kind,
            source_namespace_key.source_logical_session_id,
        )
        terminal_histories = [
            history
            for target_key, history in self.target_history.items()
            if (
                target_key.source_session_kind,
                target_key.source_logical_session_id,
            )
            == matching_scope
        ]
        for history in terminal_histories:
            self._validate_target_history_entry(history)
        _require(
            source_namespace_key
            == self._source_namespace_key(
                source_session_kind=source_namespace_key.source_session_kind,
                source_logical_session_id=(
                    source_namespace_key.source_logical_session_id
                ),
            )
            and namespace_entry is not None
            and namespace_entry.state == "LIVE_NAMESPACE"
            and namespace_entry.latest_source_generation == terminal_source_generation
            and _is_uuid4(terminal_source_generation)
            and bool(terminal_histories)
            and not any(
                scope[:2] == matching_scope for scope in self.registry_scopes.values()
            )
            and all(
                history.current_source_generation == terminal_source_generation
                and history.phase
                in {
                    "CHECKPOINT_PUBLISHED",
                    "GENERATION_FINALIZED_PENDING_CHECKPOINT_PUBLICATION",
                }
                for history in terminal_histories
            )
            and head is not None
            and head.source_namespace_key == source_namespace_key
            and head.phase == "GENERATION_FINALIZED"
            and head.terminal_source_generation == terminal_source_generation
            and head.transaction_store_incarnation == self.transaction_store_incarnation
            and head.authority_transaction_domain_qualification_digest
            == self.authority_transaction_domain_qualification_digest,
            "observer source terminal parent selector is absent, not finalized, "
            "foreign, or detached from its ADR-001 ancestry",
            CaptureError,
        )
        if head is None:
            raise CaptureError("validated finalized source lineage head is absent")
        self._validate_source_parent_selector_head(head)
        return head

    def allocate_source_successor_from_parent_selector(
        self,
        *,
        source_namespace_key: ObserverSourceLogicalSessionKey,
        expected_selector_version: int,
        successor_generation: str,
    ) -> ObserverSourceParentSelectorHead:
        """Race successor allocation against retirement preparation on one head."""

        prior = self.source_parent_selectors.get(source_namespace_key)
        _require(
            prior is not None
            and prior.phase == "GENERATION_FINALIZED"
            and prior.selector_version == expected_selector_version
            and _is_uuid4(successor_generation)
            and successor_generation != prior.terminal_source_generation,
            "source successor allocation lost the parent-selector race or is malformed",
            CaptureError,
        )
        if prior is None:
            raise CaptureError("validated source parent selector is absent")
        installed = self._seal_source_parent_selector_head(
            replace(
                prior,
                selector_version=prior.selector_version + 1,
                phase="GENERATION_ALLOCATED_PENDING_CHILD_GENESIS",
                terminal_source_generation=successor_generation,
                prior_head_digest=prior.head_digest,
                transition_evidence_digest=_digest(
                    {
                        "domain": "observer-source-successor-allocation-v1",
                        "source_namespace_key": source_namespace_key,
                        "successor_generation": successor_generation,
                    }
                ),
                head_digest="",
            )
        )
        self._validate_source_parent_selector_head(installed)
        self.source_parent_selectors[source_namespace_key] = installed
        return installed

    def prepare_source_logical_session_retirement(
        self,
        *,
        source_namespace_key: ObserverSourceLogicalSessionKey,
        terminal_source_generation: str,
        parent_selector_id: str,
        expected_parent_selector_version: int,
        complete_target_partition_proved: bool,
        no_live_or_allocated_source_generation: bool,
    ) -> ObserverSourceLogicalSessionRetirementPreparationReceipt:
        """Win PREPARED on the same parent selector before hot-state reclamation."""

        prior = self.source_parent_selectors.get(source_namespace_key)
        namespace_entry = self.logical_session_namespace_entries.get(
            source_namespace_key
        )
        _require(
            prior is not None
            and namespace_entry is not None
            and namespace_entry.state == "LIVE_NAMESPACE"
            and namespace_entry.latest_source_generation == terminal_source_generation
            and prior.phase == "GENERATION_FINALIZED"
            and prior.selector_id == parent_selector_id
            and prior.selector_version == expected_parent_selector_version
            and prior.terminal_source_generation == terminal_source_generation
            and complete_target_partition_proved
            and no_live_or_allocated_source_generation
            and source_namespace_key not in self.source_retirement_preparations
            and source_namespace_key not in self.retired_source_tombstones,
            "observer source retirement PREPARED lost the parent-selector race "
            "or lacks the complete terminal target partition",
            CaptureError,
        )
        if prior is None:
            raise CaptureError("validated source parent selector is absent")
        matching = {
            target_key: history
            for target_key, history in self.target_history.items()
            if self._source_namespace_key(
                source_session_kind=target_key.source_session_kind,
                source_logical_session_id=target_key.source_logical_session_id,
            )
            == source_namespace_key
        }
        for history in matching.values():
            self._validate_target_history_entry(history)
        matching_scope = (
            source_namespace_key.source_session_kind,
            source_namespace_key.source_logical_session_id,
        )
        _require(
            not any(
                scope[:2] == matching_scope for scope in self.registry_scopes.values()
            )
            and all(
                history.phase
                in {
                    "CHECKPOINT_PUBLISHED",
                    "GENERATION_FINALIZED_PENDING_CHECKPOINT_PUBLICATION",
                }
                for history in matching.values()
            ),
            "observer source retirement preparation raced live observer authority",
            CaptureError,
        )
        target_ancestries: list[ObserverSourceTargetRetirementPreparationTarget] = []
        for target_key, history in matching.items():
            target_ancestries.append(
                self._seal_source_retirement_preparation_target(
                    ObserverSourceTargetRetirementPreparationTarget(
                        target_key_digest=_digest(target_key),
                        source_generation_count=(history.source_generation_count),
                        source_generation_chain_digest=(
                            history.source_generation_chain_digest
                        ),
                        terminal_source_generation=(history.current_source_generation),
                        target_ancestry_digest="",
                    )
                )
            )
        ordered_ancestries = tuple(
            sorted(
                target_ancestries,
                key=lambda target: target.target_key_digest,
            )
        )
        ancestry_root = _digest(
            {
                "domain": "observer-source-target-retirement-ancestry-root-v1",
                "source_namespace_key": source_namespace_key,
                "terminal_source_generation": terminal_source_generation,
                "target_ancestries": tuple(
                    target.target_ancestry_digest for target in ordered_ancestries
                ),
            }
        )
        namespace_head = self.logical_session_namespace_registry_head
        self._validate_namespace_registry_head(namespace_head)
        fact = self._seal_source_retirement_preparation_fact(
            ObserverSourceLogicalSessionRetirementPreparationFact(
                fact_id=_u_for(
                    (
                        "observer-source-retirement-preparation-fact",
                        source_namespace_key,
                        terminal_source_generation,
                        prior.head_digest,
                    )
                ),
                source_namespace_key=source_namespace_key,
                preparation_origin="FINALIZED_SOURCE_GENERATION",
                terminal_source_generation=terminal_source_generation,
                source_finalization_receipt_digest=(prior.transition_evidence_digest),
                parent_selector_id=parent_selector_id,
                expected_parent_selector_version=prior.selector_version,
                expected_parent_head_digest=prior.head_digest,
                expected_namespace_registry_selector_id=(namespace_head.selector_id),
                expected_namespace_registry_selector_version=(
                    namespace_head.selector_version
                ),
                expected_namespace_registry_head_digest=(namespace_head.head_digest),
                expected_namespace_registry_entry_digest=(namespace_entry.entry_digest),
                target_ancestries=ordered_ancestries,
                target_ancestry_root_digest=ancestry_root,
                fact_digest="",
            )
        )
        self._validate_source_retirement_preparation_fact(fact)
        installed_parent = self._seal_source_parent_selector_head(
            replace(
                prior,
                selector_version=prior.selector_version + 1,
                phase="SOURCE_LOGICAL_SESSION_RETIREMENT_PREPARED",
                prior_head_digest=prior.head_digest,
                transition_evidence_digest=fact.fact_digest,
                head_digest="",
            )
        )
        self._validate_source_parent_selector_head(installed_parent)
        authority_transaction_commit_receipt_digest = _digest(
            {
                "domain": (
                    "observer-source-retirement-preparation-"
                    "authority-transaction-commit-v1"
                ),
                "authority_transaction_domain_key": self.authority_realm_key,
                "transaction_store_incarnation": (prior.transaction_store_incarnation),
                "qualification_digest": (
                    prior.authority_transaction_domain_qualification_digest
                ),
                "fact_digest": fact.fact_digest,
                "prior_parent_head_digest": prior.head_digest,
                "installed_parent_head_digest": installed_parent.head_digest,
                "compared_namespace_registry_head_digest": (namespace_head.head_digest),
                "compared_target_history_selector_id": (
                    self.target_history_selector_id
                ),
                "compared_target_history_selector_version": (
                    self.target_history_selector_version
                ),
                "compared_target_history_head_digest": (
                    self.target_history_head_digest
                ),
            }
        )
        receipt = self._seal_source_retirement_preparation_receipt(
            ObserverSourceLogicalSessionRetirementPreparationReceipt(
                preparation_fact=fact,
                parent_selector_id=parent_selector_id,
                prior_parent_selector_version=prior.selector_version,
                prepared_parent_selector_version=(installed_parent.selector_version),
                prior_parent_head_digest=prior.head_digest,
                prepared_parent_head_digest=installed_parent.head_digest,
                compared_namespace_registry_head_digest=(namespace_head.head_digest),
                compared_target_history_selector_id=(self.target_history_selector_id),
                compared_target_history_selector_version=(
                    self.target_history_selector_version
                ),
                compared_target_history_head_digest=(self.target_history_head_digest),
                authority_transaction_commit_receipt_digest=(
                    authority_transaction_commit_receipt_digest
                ),
                receipt_digest="",
            )
        )
        self._validate_source_retirement_preparation_receipt(receipt)
        self.source_parent_selectors[source_namespace_key] = installed_parent
        self.source_retirement_preparations[source_namespace_key] = receipt
        return receipt

    def permanently_retire_prepared_source_logical_session(
        self,
        *,
        preparation: ObserverSourceLogicalSessionRetirementPreparationReceipt,
        expected_target_history_selector_version: int,
        expected_target_history_head_digest: str,
    ) -> ObserverSourceLogicalSessionRetirementTombstone:
        """Seal unresolved targets, retain anti-ABA membership, then free hot state."""

        fact = preparation.preparation_fact
        source_namespace_key = fact.source_namespace_key
        installed_preparation = self.source_retirement_preparations.get(
            source_namespace_key
        )
        parent = self.source_parent_selectors.get(source_namespace_key)
        namespace_head = self.logical_session_namespace_registry_head
        namespace_entry = self.logical_session_namespace_entries.get(
            source_namespace_key
        )
        self._validate_namespace_registry_head(namespace_head)
        if namespace_entry is not None:
            self._validate_namespace_registry_entry(namespace_entry)
        if self.mutation == "retirement_without_preparation":
            installed_preparation = preparation
            if parent is not None:
                parent = replace(
                    parent,
                    phase="SOURCE_LOGICAL_SESSION_RETIREMENT_PREPARED",
                )
        _require(
            installed_preparation == preparation
            and parent is not None
            and parent.phase == "SOURCE_LOGICAL_SESSION_RETIREMENT_PREPARED"
            and parent.selector_id == preparation.parent_selector_id
            and parent.selector_version == preparation.prepared_parent_selector_version
            and parent.head_digest == preparation.prepared_parent_head_digest
            and parent.transition_evidence_digest == fact.fact_digest
            and namespace_head.selector_id
            == fact.expected_namespace_registry_selector_id
            and namespace_head.selector_version
            >= fact.expected_namespace_registry_selector_version
            and namespace_entry is not None
            and namespace_entry.state == "LIVE_NAMESPACE"
            and namespace_entry.latest_source_generation
            == fact.terminal_source_generation
            and namespace_entry.entry_digest
            == fact.expected_namespace_registry_entry_digest
            and self.target_history_selector_version
            == expected_target_history_selector_version
            and self.target_history_head_digest == expected_target_history_head_digest,
            "observer permanent source retirement lacks the exact installed "
            "PREPARED parent/target-selector compare state",
            CaptureError,
        )
        if parent is None:
            raise CaptureError("validated prepared source parent selector is absent")
        self._validate_source_retirement_preparation_receipt(preparation)
        prior_target_history_selector_version = self.target_history_selector_version
        prior_target_history_head_digest = self.target_history_head_digest
        matching = {
            target_key: history
            for target_key, history in self.target_history.items()
            if self._source_namespace_key(
                source_session_kind=target_key.source_session_kind,
                source_logical_session_id=target_key.source_logical_session_id,
            )
            == source_namespace_key
        }
        ancestry_by_key = {
            target.target_key_digest: target for target in fact.target_ancestries
        }
        _require(
            set(ancestry_by_key) == {_digest(target_key) for target_key in matching},
            "observer permanent source retirement stable target set changed "
            "after PREPARED",
            CaptureError,
        )
        branches: list[ObserverSourceTargetRetirementBranch] = []
        unresolved_key_digests: set[str] = set()
        matching_scope = (
            source_namespace_key.source_session_kind,
            source_namespace_key.source_logical_session_id,
        )
        for target_key, history in matching.items():
            self._validate_target_history_entry(history)
            target_key_digest = _digest(target_key)
            ancestry = ancestry_by_key[target_key_digest]
            _require(
                history.source_generation_count == ancestry.source_generation_count
                and history.source_generation_chain_digest
                == ancestry.source_generation_chain_digest
                and history.current_source_generation
                == ancestry.terminal_source_generation
                == fact.terminal_source_generation
                and history.phase
                in {
                    "CHECKPOINT_PUBLISHED",
                    "GENERATION_FINALIZED_PENDING_CHECKPOINT_PUBLICATION",
                },
                "observer target immutable ancestry changed after retirement PREPARED",
                CaptureError,
            )
            pending_root_digest: str | None = None
            branch_kind = "PUBLISHED"
            if history.phase != "CHECKPOINT_PUBLISHED":
                matching_roots = [
                    root
                    for scope, root in self.pending_target_roots.items()
                    if scope[:2] == matching_scope
                    and target_key_digest in root.unpublished_target_key_digests
                ]
                _require(
                    len(matching_roots) == 1,
                    "terminal unresolved observer target lacks one exact "
                    "pending-target root",
                    CaptureError,
                )
                pending_root_digest = matching_roots[0].root_digest
                branch_kind = "SEALED_UNRESOLVED"
                unresolved_key_digests.add(target_key_digest)
            branches.append(
                self._seal_source_target_retirement_branch(
                    ObserverSourceTargetRetirementBranch(
                        target_key_digest=target_key_digest,
                        history_entry_digest=history.history_entry_digest,
                        branch_kind=branch_kind,
                        pending_target_root_digest=pending_root_digest,
                        branch_digest="",
                    )
                )
            )
        pending_unpublished = {
            target_key_digest
            for scope, root in self.pending_target_roots.items()
            if scope[:2] == matching_scope
            for target_key_digest in root.unpublished_target_key_digests
        }
        _require(
            pending_unpublished == unresolved_key_digests,
            "terminal retirement branch partition omits or invents a pending target",
            CaptureError,
        )
        ordered_branches = tuple(
            sorted(branches, key=lambda branch: branch.target_key_digest)
        )
        branch_root = _digest(
            {
                "domain": "observer-source-target-retirement-branch-root-v1",
                "source_namespace_key": source_namespace_key,
                "terminal_source_generation": fact.terminal_source_generation,
                "branches": tuple(branch.branch_digest for branch in ordered_branches),
            }
        )
        quarantine_entries: list[ObserverUnresolvedTargetQuarantineEntry] = []
        for branch in ordered_branches:
            if branch.branch_kind == "SEALED_UNRESOLVED":
                _require(
                    branch.pending_target_root_digest is not None,
                    "sealed unresolved target lacks a pending-root commitment",
                    CaptureError,
                )
                if branch.pending_target_root_digest is None:
                    raise CaptureError("validated pending-target root is absent")
                quarantine_entries.append(
                    self._seal_quarantine_entry(
                        ObserverUnresolvedTargetQuarantineEntry(
                            source_namespace_key=source_namespace_key,
                            terminal_source_generation=(
                                fact.terminal_source_generation
                            ),
                            target_key_digest=branch.target_key_digest,
                            sealed_history_entry_digest=branch.history_entry_digest,
                            pending_target_root_digest=(
                                branch.pending_target_root_digest
                            ),
                            state="SEALED_UNRESOLVED",
                            entry_digest="",
                        )
                    )
                )
        for entry in quarantine_entries:
            self._validate_quarantine_entry(entry)
        kind = source_namespace_key.source_session_kind
        new_quarantine_key_bytes = 32 * len(quarantine_entries)
        _require(
            len(self.quarantined_targets) + len(quarantine_entries)
            <= self.capacity_manifest.max_quarantined_target_entries
            and self._quarantined_target_count_for_kind(kind) + len(quarantine_entries)
            <= self._kind_reserve(kind, "quarantined_target_entry")
            and self.quarantined_target_key_bytes + new_quarantine_key_bytes
            <= self.capacity_manifest.max_quarantined_target_key_bytes
            and self._quarantined_target_key_bytes_for_kind(kind)
            + new_quarantine_key_bytes
            <= self._kind_reserve(kind, "quarantined_target_key_byte"),
            "observer unresolved-target quarantine shard capacity is exhausted",
            CaptureError,
        )
        source_key_bytes = self._source_key_bytes(source_namespace_key)
        _require(
            source_namespace_key not in self.retired_source_tombstones
            and len(self.retired_source_tombstones)
            < self.capacity_manifest.max_retired_source_tombstones
            and self._retired_source_count_for_kind(kind)
            < self._kind_reserve(kind, "retired_source_tombstone")
            and self.retired_source_key_bytes + source_key_bytes
            <= self.capacity_manifest.max_retired_source_key_bytes
            and self._retired_source_key_bytes_for_kind(kind) + source_key_bytes
            <= self._kind_reserve(kind, "retired_source_key_byte"),
            "observer source retirement tombstone shard capacity is exhausted "
            "or the namespace is already retired",
            CaptureError,
        )
        prior_quarantine_root = self.quarantine_shard_roots[kind]
        quarantine_commitment: ObserverUnresolvedTargetQuarantineCommitment | None = (
            None
        )
        installed_quarantine_root = prior_quarantine_root
        if quarantine_entries:
            installed_quarantine_root = _digest(
                {
                    "domain": "observer-unresolved-quarantine-shard-successor-v1",
                    "prior_shard_root_digest": prior_quarantine_root,
                    "source_namespace_key": source_namespace_key,
                    "entry_digests": tuple(
                        sorted(entry.entry_digest for entry in quarantine_entries)
                    ),
                }
            )
            quarantine_commitment = self._seal_quarantine_commitment(
                ObserverUnresolvedTargetQuarantineCommitment(
                    source_namespace_key=source_namespace_key,
                    entry_digests=tuple(
                        sorted(entry.entry_digest for entry in quarantine_entries)
                    ),
                    prior_shard_root_digest=prior_quarantine_root,
                    installed_shard_root_digest=installed_quarantine_root,
                    commitment_digest="",
                )
            )
        history_root = _digest(
            {
                "domain": "observer-source-terminal-target-history-root-v1",
                "source_namespace_key": source_namespace_key,
                "targets": tuple(
                    sorted(
                        (
                            _digest(target_key),
                            history.history_entry_digest,
                            history.source_generation_chain_digest,
                            history.source_generation_count,
                        )
                        for target_key, history in matching.items()
                    )
                ),
            }
        )
        published_count = sum(
            branch.branch_kind == "PUBLISHED" for branch in ordered_branches
        )
        unresolved_count = len(ordered_branches) - published_count
        tombstone = self._seal_source_retirement_tombstone(
            ObserverSourceLogicalSessionRetirementTombstone(
                source_namespace_key=source_namespace_key,
                terminal_source_generation=fact.terminal_source_generation,
                preparation_receipt_digest=preparation.receipt_digest,
                retired_target_count=len(matching),
                published_target_count=published_count,
                sealed_unresolved_target_count=unresolved_count,
                retired_target_history_root_digest=history_root,
                target_retirement_branch_root_digest=branch_root,
                quarantine_commitment_digest=(
                    quarantine_commitment.commitment_digest
                    if quarantine_commitment is not None
                    else None
                ),
                parent_selector_id=preparation.parent_selector_id,
                prepared_parent_selector_version=(
                    preparation.prepared_parent_selector_version
                ),
                retired_parent_selector_version=(
                    preparation.prepared_parent_selector_version + 1
                ),
                namespace_reuse_forbidden=True,
                tombstone_digest="",
            )
        )
        self._validate_source_retirement_tombstone(tombstone)
        _require(
            tombstone.tombstone_digest
            not in {
                retained.tombstone_digest
                for retained in self.retired_source_tombstones.values()
            },
            "observer source retirement tombstone digest collides with a "
            "different retained namespace",
            CaptureError,
        )
        installed_parent = self._seal_source_parent_selector_head(
            replace(
                parent,
                selector_version=parent.selector_version + 1,
                phase="SOURCE_LOGICAL_SESSION_PERMANENTLY_RETIRED",
                prior_head_digest=parent.head_digest,
                transition_evidence_digest=tombstone.tombstone_digest,
                head_digest="",
            )
        )
        self._validate_source_parent_selector_head(installed_parent)
        reclaimed_key_bytes = sum(
            self._target_key_bytes(target_key) for target_key in matching
        )
        _require(
            self.active_target_key_bytes >= reclaimed_key_bytes
            and self.active_target_key_bytes - reclaimed_key_bytes
            == sum(
                self._target_key_bytes(target_key)
                for target_key in self.target_history
                if target_key not in matching
            ),
            "observer active target-key byte accounting would drift during "
            "permanent retirement",
            CaptureError,
        )
        prior_namespace_head = self.logical_session_namespace_registry_head
        self._validate_namespace_registry_head(prior_namespace_head)
        if self.mutation != "drop_retirement_tombstone":
            _require(
                namespace_entry is not None
                and namespace_entry.state == "LIVE_NAMESPACE",
                "observer authority-global namespace membership vanished before "
                "permanent retirement",
                CaptureError,
            )
            if namespace_entry is None:
                raise CaptureError("validated live namespace entry is absent")
            retired_namespace_entry = self._seal_namespace_registry_entry(
                replace(
                    namespace_entry,
                    state="PERMANENTLY_RETIRED",
                    latest_source_generation=fact.terminal_source_generation,
                    permanent_retirement_tombstone_digest=(tombstone.tombstone_digest),
                    entry_digest="",
                )
            )
            self._commit_namespace_entry(
                source_key=source_namespace_key,
                entry=retired_namespace_entry,
                added_key_bytes=0,
            )
            self.retired_source_tombstones[source_namespace_key] = tombstone
            self.retired_source_key_bytes += source_key_bytes
        for entry in quarantine_entries:
            self.quarantined_targets[
                (source_namespace_key, entry.target_key_digest)
            ] = entry
        self.quarantined_target_key_bytes += new_quarantine_key_bytes
        self.quarantine_shard_roots[kind] = installed_quarantine_root
        if quarantine_commitment is not None:
            self.quarantine_commitments[source_namespace_key] = quarantine_commitment
        for target_key in matching:
            del self.target_history[target_key]
        matching_scope = (
            source_namespace_key.source_session_kind,
            source_namespace_key.source_logical_session_id,
        )
        for scope in tuple(self.pending_target_roots):
            if scope[:2] == matching_scope:
                del self.pending_target_roots[scope]
        self.active_target_key_bytes -= reclaimed_key_bytes
        self._advance_target_history_selector(
            event_digest=_digest(
                {
                    "event": (
                        "RECLAIM_SOURCE_OBSERVER_TARGET_HISTORY_DURING_"
                        "PERMANENT_RETIREMENT"
                    ),
                    "source_namespace_key": source_namespace_key,
                    "target_retirement_branch_root_digest": branch_root,
                    "tombstone_digest": tombstone.tombstone_digest,
                }
            )
        )
        self.source_parent_selectors[source_namespace_key] = installed_parent
        self.source_retirement_preparations.pop(source_namespace_key, None)
        installed_namespace_head = self.logical_session_namespace_registry_head
        authority_transaction_commit_receipt_digest = _digest(
            {
                "domain": (
                    "observer-source-permanent-retirement-"
                    "authority-transaction-commit-v1"
                ),
                "authority_transaction_domain_key": self.authority_realm_key,
                "transaction_store_incarnation": (parent.transaction_store_incarnation),
                "qualification_digest": (
                    parent.authority_transaction_domain_qualification_digest
                ),
                "preparation_receipt_digest": preparation.receipt_digest,
                "prior_parent_head_digest": parent.head_digest,
                "installed_parent_head_digest": installed_parent.head_digest,
                "prior_namespace_registry_head_digest": (
                    prior_namespace_head.head_digest
                ),
                "installed_namespace_registry_head_digest": (
                    installed_namespace_head.head_digest
                ),
                "prior_target_history_selector_version": (
                    prior_target_history_selector_version
                ),
                "installed_target_history_selector_version": (
                    self.target_history_selector_version
                ),
                "prior_target_history_head_digest": (prior_target_history_head_digest),
                "installed_target_history_head_digest": (
                    self.target_history_head_digest
                ),
                "target_retirement_branch_root_digest": branch_root,
                "quarantine_commitment_digest": (
                    tombstone.quarantine_commitment_digest
                ),
                "tombstone_digest": tombstone.tombstone_digest,
            }
        )
        retirement_receipt = self._seal_source_retirement_receipt(
            ObserverSourceLogicalSessionRetirementReceipt(
                preparation_receipt_digest=preparation.receipt_digest,
                source_namespace_key=source_namespace_key,
                terminal_source_generation=fact.terminal_source_generation,
                tombstone_digest=tombstone.tombstone_digest,
                prior_parent_selector_head_digest=parent.head_digest,
                installed_parent_selector_head_digest=installed_parent.head_digest,
                prior_namespace_registry_head_digest=(prior_namespace_head.head_digest),
                installed_namespace_registry_head_digest=(
                    installed_namespace_head.head_digest
                ),
                prior_target_history_selector_version=(
                    prior_target_history_selector_version
                ),
                installed_target_history_selector_version=(
                    self.target_history_selector_version
                ),
                prior_target_history_head_digest=(prior_target_history_head_digest),
                installed_target_history_head_digest=(self.target_history_head_digest),
                target_retirement_branch_root_digest=branch_root,
                quarantine_commitment_digest=(tombstone.quarantine_commitment_digest),
                namespace_reuse_forbidden=True,
                authority_transaction_commit_receipt_digest=(
                    authority_transaction_commit_receipt_digest
                ),
                receipt_digest="",
            )
        )
        self._validate_source_retirement_receipt(retirement_receipt)
        self.source_retirement_receipts[source_namespace_key] = retirement_receipt
        self.source_retirement_branches[source_namespace_key] = ordered_branches
        return tombstone

    def record_quarantined_target_late_closure(
        self,
        *,
        quarantine_entry_digest: str,
        distributed_authorization_closure_digest: str,
        retained_transport_quiescence_digest: str,
    ) -> ObserverQuarantineLateClosureEvidence:
        """Enrich archive evidence without changing target or source authority."""

        matching = [
            entry
            for entry in self.quarantined_targets.values()
            if entry.entry_digest == quarantine_entry_digest
        ]
        _require(
            len(matching) == 1
            and quarantine_entry_digest not in self.quarantine_late_closure_evidence
            and HEX64.fullmatch(distributed_authorization_closure_digest) is not None
            and HEX64.fullmatch(retained_transport_quiescence_digest) is not None,
            "observer quarantine late-closure evidence is absent, duplicate, or "
            "malformed",
            CaptureError,
        )
        evidence = self._seal_quarantine_late_closure_evidence(
            ObserverQuarantineLateClosureEvidence(
                quarantine_entry_digest=quarantine_entry_digest,
                distributed_authorization_closure_digest=(
                    distributed_authorization_closure_digest
                ),
                retained_transport_quiescence_digest=(
                    retained_transport_quiescence_digest
                ),
                authority_effect="ARCHIVE_ENRICHMENT_ONLY_NO_AUTHORITY",
                evidence_digest="",
            )
        )
        self.quarantine_late_closure_evidence[quarantine_entry_digest] = evidence
        return evidence

    def reject_quarantined_target_revival(
        self,
        *,
        source_namespace_key: ObserverSourceLogicalSessionKey,
        target_key_digest: str,
    ) -> None:
        _require(
            (source_namespace_key, target_key_digest) not in self.quarantined_targets,
            "sealed unresolved observer target cannot return to active or "
            "published target history",
            CaptureError,
        )


@dataclass(frozen=True, slots=True)
class ObserverGrant:
    grant_id: str
    receiver_principal: str
    descriptor_digest: str
    security_state_digest: str
    revocation_state_digest: str
    request_challenge: str
    grant_entitlement_digests: tuple[str, ...]
    issuer_utc_not_before: int
    issuer_utc_not_after: int
    maximum_local_duration: int
    grant_digest: str
    protected_body: ProtectedBody


def _grant_body(grant: ObserverGrant) -> dict[str, Any]:
    # Numeric receiver/server deadlines, receipts, self-digest, and successor
    # heads are intentionally absent from the issuer's canonical grant body.
    return _body(grant, "grant_digest", "protected_body")


def _seal_grant(grant: ObserverGrant, *, store: ContentStore) -> ObserverGrant:
    protected = _protect_body(
        _grant_body(grant),
        store=store,
        media_type="application/vnd.ncp.observer-grant+json",
        domain="observer-grant",
        issuer=GRANT_AUTHORITY,
        subject=grant.receiver_principal,
        event_time=grant.issuer_utc_not_before,
    )
    return replace(grant, grant_digest=protected.body_digest, protected_body=protected)


