class LocalSecurityCurrentnessCASCondition:
    condition_id: str
    transaction_store_incarnation: str
    operation_scope_digest: str
    expected_prior_operation_head_digest: str
    security_authority_domain_digest: str
    security_state_lineage_incarnation: str
    security_authority_state_version: int
    security_epoch: int
    revocation_epoch: int
    security_state_digest: str
    revocation_state_digest: str
    security_selector_incarnation: str
    security_selector_version: int
    security_head_digest: str
    security_selector_digest: str
    security_commit_digest: str
    condition_digest: str


def _local_security_currentness_condition_digest(
    condition: LocalSecurityCurrentnessCASCondition,
) -> str:
    return _body_digest(condition, "condition_digest")


def _local_security_operation_scope_digest(
    *,
    namespace: str,
    operation: str,
) -> str:
    return _digest(
        {
            "domain": "local-security-currentness-operation-scope-v1",
            "namespace": namespace,
            "operation": operation,
            "session": SESSION,
            "generation": GENERATION,
        }
    )


def _validate_local_security_currentness_condition(
    condition: LocalSecurityCurrentnessCASCondition,
    *,
    transaction_store_incarnation: str,
    operation_scope_digest: str,
    expected_prior_operation_head_digest: str,
    security_head: SecurityAuthorityStateHead,
    security_selector: InstalledSecurityAuthorityStateSelector,
    security_commit: SecurityAuthorityStateCommitReceipt,
) -> None:
    _require(
        _is_uuid4(condition.condition_id)
        and _is_uuid4(condition.transaction_store_incarnation)
        and condition.transaction_store_incarnation == transaction_store_incarnation
        and condition.operation_scope_digest == operation_scope_digest
        and condition.expected_prior_operation_head_digest
        == expected_prior_operation_head_digest
        and condition.security_authority_domain_digest
        == security_head.authority_domain_digest
        == security_commit.authority_domain_digest
        and condition.security_state_lineage_incarnation
        == security_head.state_lineage_incarnation
        == security_commit.state_lineage_incarnation
        and condition.security_authority_state_version
        == security_head.authority_state_version
        == security_commit.installed_authority_state_version
        and condition.security_epoch
        == security_head.security_epoch
        == security_commit.installed_security_epoch
        and condition.revocation_epoch
        == security_head.revocation_epoch
        == security_commit.installed_revocation_epoch
        and condition.security_state_digest == security_head.security_state_digest
        and condition.revocation_state_digest == security_head.revocation_state_digest
        and condition.security_selector_incarnation
        == security_selector.selector_incarnation
        and condition.security_selector_version
        == security_selector.selector_version
        == security_commit.installed_selector_version
        and security_selector.transaction_store_incarnation
        == transaction_store_incarnation
        and security_selector.state == "INSTALLED"
        and security_selector.ever_used
        and condition.security_head_digest
        == security_head.head_digest
        == security_commit.installed_head_digest
        == security_selector.current_head_digest
        and condition.security_selector_digest == security_selector.selector_digest
        and condition.security_commit_digest
        == security_commit.commit_digest
        == security_selector.last_commit_digest
        and security_head.head_digest == _security_authority_head_digest(security_head)
        and security_selector.selector_digest
        == _security_selector_digest(security_selector)
        and security_commit.commit_digest
        == _security_authority_commit_digest(security_commit)
        and condition.condition_digest
        == _local_security_currentness_condition_digest(condition)
        and not {
            "installed_head_digest",
            "commit_digest",
            "authority_receipt",
            "successor_head_digest",
        }.intersection(_body(condition)),
        "local security currentness condition is stale, cross-store, or cyclic",
        CaptureError,
    )
    for value, domain, digest in (
        (
            security_head,
            "security-authority-state-head",
            security_head.head_digest,
        ),
        (
            security_selector,
            "installed-security-authority-state-selector",
            security_selector.selector_digest,
        ),
        (
            security_commit,
            "security-authority-state-commit",
            security_commit.commit_digest,
        ),
    ):
        _validate_authority(
            value.authority_receipt,
            domain=domain,
            subject_digest=digest,
            issuer=SECURITY_AUTHORITY,
            subject=SESSION_AUTHORITY,
        )


