@dataclass(frozen=True, slots=True)
class NormativeSourceRef:
    session: str
    generation: str
    origin_stream_declaration_digest: str
    origin_stream_epoch: str
    origin_position: int
    origin_frame_digest: str
    origin_payload: ContentRef
    source_ref_digest: str


def _source_ref_digest(reference: NormativeSourceRef) -> str:
    return _body_digest(reference, "source_ref_digest")


@dataclass(frozen=True, slots=True)
class ProducerFrame:
    frame_id: str
    descriptor_digest: str
    session: str
    generation: str
    security_state_digest: str
    stream_declaration_digest: str
    stream_epoch: str
    stream_position: int
    stream_key: tuple[str, str, str]
    publisher_principal: str
    publisher_entity: str
    source_id: str
    schema: ContentRef
    payload: ContentRef
    command_id: str | None
    command_content_digest: str | None
    normative_source: NormativeSourceRef | None
    frame_digest: str
    protected_body: ProtectedBody


def _producer_frame_body(frame: ProducerFrame) -> dict[str, Any]:
    # Receiver clock, observer grant/scope, delivery interval, local admission,
    # correlation, receipts, self-digest, and successor heads are excluded.
    return _body(frame, "frame_digest", "protected_body")


def _seal_producer_frame(
    frame: ProducerFrame,
    *,
    store: ContentStore,
    event_time: int,
) -> ProducerFrame:
    body = _producer_frame_body(frame)
    protected = _protect_body(
        body,
        store=store,
        media_type="application/vnd.ncp.producer-frame+json",
        domain="producer-frame",
        issuer=frame.publisher_principal,
        subject=frame.publisher_principal,
        event_time=event_time,
    )
    return replace(frame, frame_digest=protected.body_digest, protected_body=protected)


def _validate_producer_frame(frame: ProducerFrame, *, store: ContentStore) -> None:
    _require(
        _is_uuid4(frame.frame_id)
        and frame.session == SESSION
        and frame.generation == GENERATION
        and HEX64.fullmatch(frame.descriptor_digest) is not None
        and HEX64.fullmatch(frame.security_state_digest) is not None
        and HEX64.fullmatch(frame.stream_declaration_digest) is not None
        and _is_uuid4(frame.stream_epoch)
        and _safe_int(frame.stream_position)
        and len(frame.stream_key) == 3
        and all(IDENTIFIER.fullmatch(item) is not None for item in frame.stream_key)
        and IDENTIFIER.fullmatch(frame.publisher_principal) is not None
        and IDENTIFIER.fullmatch(frame.publisher_entity) is not None
        and IDENTIFIER.fullmatch(frame.source_id) is not None
        and frame.frame_digest == frame.protected_body.body_digest,
        "producer frame identity is malformed",
        CaptureError,
    )
    store.get(frame.schema)
    store.get(frame.payload)
    if frame.normative_source is not None:
        reference = frame.normative_source
        _require(
            reference.session == frame.session
            and reference.generation == frame.generation
            and HEX64.fullmatch(reference.origin_stream_declaration_digest) is not None
            and _is_uuid4(reference.origin_stream_epoch)
            and _safe_int(reference.origin_position)
            and HEX64.fullmatch(reference.origin_frame_digest) is not None
            and reference.source_ref_digest == _source_ref_digest(reference),
            "producer NormativeSourceRef is malformed or receiver-contaminated",
            CaptureError,
        )
    _validate_protected_body(
        frame.protected_body,
        _producer_frame_body(frame),
        store=store,
        media_type="application/vnd.ncp.producer-frame+json",
        domain="producer-frame",
        issuer=frame.publisher_principal,
        subject=frame.publisher_principal,
    )
    _require(
        frame.protected_body.authority_receipt.clock_domain == "issuer-utc"
        and frame.protected_body.authority_receipt.clock_incarnation == GENERATION,
        "producer frame authority receipt uses the wrong publisher clock",
        CaptureError,
    )


