def _seal_frame_delivery(
    frame: ProducerFrame,
    grant_context: ReceiverGrantContext,
    *,
    received_at: int,
    grant_entitlement_digest: str,
    correlation: ResolvedCaptureSourceCorrelation | None = None,
    index: int,
) -> ReceiverFrameDelivery:
    (
        canonical_scope,
        boundary_membership,
        read_decision,
        retained_authorization_cut,
        release_recipient_context,
        expected_release_transport_context,
        qualified_deadline_mapping,
        expected_deadline_mapping_state_cut,
        grant_currentness_evidence,
        expected_grant_currentness_state_cut,
        release_cas,
        validated_release_cas_receipt,
        committed_outbox_artifact,
        outbox_commit_receipt,
        expected_outbox_commit_state_cut,
        dispatch_context,
        expected_dispatch_destination_cut,
        release_recheck_digest,
    ) = _delivery_read_bridge(
        frame,
        grant_context,
        received_at=received_at,
    )
    delivery = ReceiverFrameDelivery(
        delivery_id=_u(30_000 + index),
        receiver_principal=grant_context.grant.receiver_principal,
        producer_frame_digest=frame.frame_digest,
        exact_received_payload=committed_outbox_artifact.exact_payload,
        grant_digest=grant_context.grant.grant_digest,
        grant_install_receipt_digest=grant_context.install.receipt_digest,
        grant_entitlement_digest=grant_entitlement_digest,
        canonical_read_scope=canonical_scope,
        boundary_scope_membership=boundary_membership,
        read_authorization_decision=read_decision,
        retained_authorization_cut=retained_authorization_cut,
        release_recipient_context=release_recipient_context,
        expected_release_transport_context=(expected_release_transport_context),
        qualified_deadline_mapping=qualified_deadline_mapping,
        expected_deadline_mapping_state_cut=(expected_deadline_mapping_state_cut),
        grant_currentness_evidence=grant_currentness_evidence,
        expected_grant_currentness_state_cut=(expected_grant_currentness_state_cut),
        release_cas=release_cas,
        validated_release_cas_receipt=validated_release_cas_receipt,
        committed_outbox_artifact=committed_outbox_artifact,
        outbox_commit_receipt=outbox_commit_receipt,
        expected_outbox_commit_state_cut=(expected_outbox_commit_state_cut),
        dispatch_context=dispatch_context,
        expected_dispatch_destination_cut=(expected_dispatch_destination_cut),
        release_authority_recheck_digest=release_recheck_digest,
        receiver_clock_incarnation=(grant_context.install.receiver_clock_incarnation),
        received_at=received_at,
        local_not_after=grant_context.install.local_not_after,
        correlation=correlation,
        delivery_digest="",
        authority_receipt=_seal_authority(
            receipt_id=_u(31_000 + index),
            domain="receiver-frame-delivery",
            subject_digest="0" * 64,
            issuer=INGRESS_AUTHORITY,
            subject=grant_context.grant.receiver_principal,
            clock_domain="receiver-monotonic",
            clock_incarnation=grant_context.install.receiver_clock_incarnation,
            event_time=received_at,
        ),
    )
    delivery = replace(delivery, delivery_digest=_frame_delivery_digest(delivery))
    return replace(
        delivery,
        authority_receipt=_seal_authority(
            receipt_id=delivery.authority_receipt.receipt_id,
            domain="receiver-frame-delivery",
            subject_digest=delivery.delivery_digest,
            issuer=INGRESS_AUTHORITY,
            subject=delivery.receiver_principal,
            clock_domain="receiver-monotonic",
            clock_incarnation=delivery.receiver_clock_incarnation,
            event_time=received_at,
        ),
    )


def _validate_retained_delivery_bridge(
    delivery: ReceiverFrameDelivery,
    frame: ProducerFrame,
) -> None:
    observer_identity = (
        delivery.receiver_principal,
        OBSERVER_INSTANCES[delivery.receiver_principal],
    )
    boundary_identity = (
        DELIVERY_SERVER,
        _u_for(("delivery-read-boundary", delivery.receiver_principal)),
        "exclusive-receiver-local-not-after-v1",
    )
    boundary_clock = delivery.receiver_clock_incarnation
    security_state = (
        delivery.read_authorization_decision.security_state_digest,
        delivery.read_authorization_decision.security_epoch,
        delivery.read_authorization_decision.revocation_epoch,
    )
    mapping_policy_artifact_digest = _digest(
        {
            "boundary_clock_incarnation": boundary_clock,
            "boundary_reference_lower": 0,
            "coordinator_reference": 0,
            "minimum_rate_denominator": 1,
            "minimum_rate_numerator": 1,
            "source_clock_incarnation": SERVER_CLOCK,
            "synthetic_mapping_policy": "identity-offset-lower-image-v1",
        }
    )
    release_idempotency_key = _u_for(
        (
            "capture-release-idempotency",
            frame.frame_digest,
            delivery.grant_digest,
            delivery.receiver_principal,
        )
    )
    stable_outbox_item_id = _u_for(
        (
            "capture-dispatch-outbox-item",
            frame.frame_digest,
            delivery.grant_digest,
            delivery.receiver_principal,
        )
    )
    transport_idempotency_key = _u_for(
        ("capture-transport-idempotency", stable_outbox_item_id)
    )
    dispatch_attempt_id = _u_for(("capture-dispatch-attempt", stable_outbox_item_id, 1))
    try:
        validate_read_decision(
            delivery.read_authorization_decision,
            scope=delivery.canonical_read_scope,
            membership=delivery.boundary_scope_membership,
            expected_boundary_identity=boundary_identity,
            expected_observer_identity=observer_identity,
            expected_authorization_audience=AUTHORIZATION_SERVER,
            expected_authorization_cut=delivery.retained_authorization_cut,
            expected_issuer_identity=(
                AUTHORIZATION_SERVER,
                AUTHORIZATION_SERVER_KEY_ID,
                SERVER_CLOCK,
            ),
            fixture_key=_CAPTURE_READ_DECISION_SEAL_KEY,
        )
        validate_release_cas(
            delivery.release_cas,
            scope=delivery.canonical_read_scope,
            membership=delivery.boundary_scope_membership,
            decision=delivery.read_authorization_decision,
            release_context=delivery.release_recipient_context,
            qualified_deadline_mapping=delivery.qualified_deadline_mapping,
            grant_currentness_evidence=delivery.grant_currentness_evidence,
            expected_observer_identity=observer_identity,
            expected_boundary_identity=boundary_identity,
            expected_authorization_audience=AUTHORIZATION_SERVER,
            expected_authorization_cut=delivery.retained_authorization_cut,
            expected_issuer_identity=(
                AUTHORIZATION_SERVER,
                AUTHORIZATION_SERVER_KEY_ID,
                SERVER_CLOCK,
            ),
            expected_release_recipient_identity=observer_identity,
            expected_release_transport_context=(
                delivery.expected_release_transport_context
            ),
            expected_local_security_state=security_state,
            expected_release_context_artifact_digest=(
                release_recipient_artifact_digest(delivery.release_recipient_context)
            ),
            expected_grant_currentness_state_cut=(
                delivery.expected_grant_currentness_state_cut
            ),
            expected_deadline_mapping_state_cut=(
                delivery.expected_deadline_mapping_state_cut
            ),
            release_idempotency_key=release_idempotency_key,
            expected_boundary_clock_incarnation=boundary_clock,
            expected_mapping_policy_artifact_digest=(mapping_policy_artifact_digest),
            checked_at=delivery.received_at - 2,
            fixture_key=_CAPTURE_READ_DECISION_SEAL_KEY,
        )
        validate_dispatch_context(
            delivery.dispatch_context,
            scope=delivery.canonical_read_scope,
            membership=delivery.boundary_scope_membership,
            release_context=delivery.release_recipient_context,
            release_cas=delivery.release_cas,
            validated_release_cas_receipt=(delivery.validated_release_cas_receipt),
            committed_outbox=delivery.committed_outbox_artifact,
            commit_receipt=delivery.outbox_commit_receipt,
            expected_commit_state_cut=(delivery.expected_outbox_commit_state_cut),
            expected_boundary_identity=boundary_identity,
            expected_recipient_identity=observer_identity,
            expected_release_transport_context=(
                delivery.expected_release_transport_context
            ),
            expected_release_security_state=security_state,
            expected_boundary_clock_incarnation=boundary_clock,
            expected_release_context_artifact_digest=(
                release_recipient_artifact_digest(delivery.release_recipient_context)
            ),
            release_context_checked_at=delivery.received_at - 2,
            expected_stable_outbox_item_id=stable_outbox_item_id,
            actual_dispatch_payload=delivery.exact_received_payload,
            expected_committed_outbox_artifact_digest=(
                committed_outbox_artifact_digest(delivery.committed_outbox_artifact)
            ),
            expected_dispatch_attempt_id=dispatch_attempt_id,
            expected_transport_idempotency_key=transport_idempotency_key,
            expected_local_security_state=security_state,
            expected_destination_cut=(delivery.expected_dispatch_destination_cut),
            expected_dispatch_context_artifact_digest=(
                dispatch_artifact_digest(delivery.dispatch_context)
            ),
            checked_at=delivery.received_at,
            fixture_key=_CAPTURE_READ_DECISION_SEAL_KEY,
        )
    except BridgeValidationError as exc:
        raise CaptureError("retained receiver delivery bridge is invalid") from exc


