def _validate_frame_delivery(
    delivery: ReceiverFrameDelivery,
    frame: ProducerFrame,
    grant_context: ReceiverGrantContext,
    *,
    expected_grant_entitlement_digest: str,
) -> None:
    (
        expected_scope,
        expected_membership,
        expected_decision,
        reconstructed_authorization_cut,
        expected_release_context,
        expected_release_transport_context,
        expected_deadline_mapping,
        expected_deadline_mapping_state_cut,
        expected_currentness_evidence,
        reconstructed_currentness_cut,
        expected_release_cas,
        expected_validated_release_cas_receipt,
        expected_committed_outbox,
        expected_outbox_commit_receipt,
        reconstructed_outbox_commit_state_cut,
        expected_dispatch_context,
        expected_dispatch_destination_cut,
        expected_release_recheck_digest,
    ) = _delivery_read_bridge(
        frame,
        grant_context,
        received_at=delivery.received_at,
    )
    expected_receiver = grant_context.grant.receiver_principal
    expected_observer_identity = (
        expected_receiver,
        OBSERVER_INSTANCES[expected_receiver],
    )
    expected_boundary_instance = _u_for(("delivery-read-boundary", expected_receiver))
    expected_boundary_identity = (
        DELIVERY_SERVER,
        expected_boundary_instance,
        "exclusive-receiver-local-not-after-v1",
    )
    expected_boundary_clock = grant_context.install.receiver_clock_incarnation
    expected_security_state = (
        grant_context.grant.security_state_digest,
        1,
        7,
    )
    expected_route_class = _read_route_class(frame)
    expected_route_channel = (
        "" if frame.stream_key[0] == "observation" else frame.stream_key[1]
    )
    expected_stable_grant_key_digest = _digest(
        (
            expected_receiver,
            grant_context.grant.grant_id,
        )
    )
    expected_full_boundary_key_digest = _digest(
        (
            DELIVERY_SERVER,
            expected_boundary_instance,
            grant_context.grant.grant_digest,
        )
    )
    expected_authorization_cut = ExpectedObserverReadAuthorizationCut(
        authorization_ingress_artifact_digest=(
            authorization_ingress_artifact_digest(
                expected_decision.authorization_ingress_context
            )
        ),
        authorization_endpoint_profile=(
            expected_decision.authorization_ingress_context.endpoint_profile
        ),
        authorization_connection_instance=(
            expected_decision.authorization_ingress_context.connection_instance
        ),
        authorization_replay_domain=(
            expected_decision.authorization_ingress_context.replay_domain
        ),
        capability_digest=grant_context.grant.grant_digest,
        capability_seal_digest=_digest(
            grant_context.grant.protected_body.authority_receipt
        ),
        capability_issuer_snapshot_digest=(
            _SYNTHETIC_CAPABILITY_ISSUER_SNAPSHOT_DIGEST
        ),
        manifest_digest=_SYNTHETIC_READ_MANIFEST_DIGEST,
        manifest_entry_digest=_SYNTHETIC_READ_MANIFEST_ENTRY_DIGEST,
        stable_grant_key_digest=expected_stable_grant_key_digest,
        full_boundary_key_digest=expected_full_boundary_key_digest,
        grant_digest=grant_context.grant.grant_digest,
        server_entry_head_digest=_SYNTHETIC_AUTHORIZATION_SERVER_HEAD_DIGEST,
        server_selector_digest=_SYNTHETIC_AUTHORIZATION_SERVER_SELECTOR_DIGEST,
        authority_realm_key=AUTHORITY_REALM_KEY,
        source_session_kind="PLANT_CONTROL",
        logical_session_id=frame.session,
        source_generation=frame.generation,
        security_state_digest=grant_context.grant.security_state_digest,
        security_epoch=1,
        revocation_epoch=7,
        coordinator_clock_incarnation=SERVER_CLOCK,
        exclusive_not_after=grant_context.install.local_not_after,
        maximum_release_count=1,
    )
    _require(
        expected_authorization_cut == reconstructed_authorization_cut,
        "reconstructed authorization cut differs from the independent grant "
        "and authorization-server cut",
        CaptureError,
    )
    expected_mapping_policy_artifact_digest = _digest(
        {
            "boundary_clock_incarnation": expected_boundary_clock,
            "boundary_reference_lower": 0,
            "coordinator_reference": 0,
            "minimum_rate_denominator": 1,
            "minimum_rate_numerator": 1,
            "source_clock_incarnation": SERVER_CLOCK,
            "synthetic_mapping_policy": "identity-offset-lower-image-v1",
        }
    )
    expected_currentness_cut = reconstructed_currentness_cut
    expected_release_idempotency_key = _u_for(
        (
            "capture-release-idempotency",
            frame.frame_digest,
            grant_context.grant.grant_digest,
            expected_receiver,
        )
    )
    expected_stable_outbox_item_id = _u_for(
        (
            "capture-dispatch-outbox-item",
            frame.frame_digest,
            grant_context.grant.grant_digest,
            expected_receiver,
        )
    )
    expected_transport_idempotency_key = _u_for(
        (
            "capture-transport-idempotency",
            expected_stable_outbox_item_id,
        )
    )
    expected_dispatch_attempt_id = _u_for(
        (
            "capture-dispatch-attempt",
            expected_stable_outbox_item_id,
            1,
        )
    )
    try:
        validate_boundary_membership(
            delivery.boundary_scope_membership,
            scope=delivery.canonical_read_scope,
            expected_boundary_identity=expected_boundary_identity,
        )
        validate_read_decision(
            delivery.read_authorization_decision,
            scope=delivery.canonical_read_scope,
            membership=delivery.boundary_scope_membership,
            expected_boundary_identity=expected_boundary_identity,
            expected_observer_identity=expected_observer_identity,
            expected_authorization_audience=AUTHORIZATION_SERVER,
            expected_authorization_cut=expected_authorization_cut,
            expected_issuer_identity=(
                AUTHORIZATION_SERVER,
                AUTHORIZATION_SERVER_KEY_ID,
                SERVER_CLOCK,
            ),
            fixture_key=_CAPTURE_READ_DECISION_SEAL_KEY,
        )
        validate_grant_currentness_evidence(
            delivery.grant_currentness_evidence,
            scope=delivery.canonical_read_scope,
            membership=delivery.boundary_scope_membership,
            decision=delivery.read_authorization_decision,
            expected_observer_identity=expected_observer_identity,
            expected_boundary_identity=expected_boundary_identity,
            expected_boundary_clock_incarnation=expected_boundary_clock,
            expected_security_state=expected_security_state,
            expected_state_cut=expected_currentness_cut,
            checked_at=delivery.received_at - 2,
            fixture_key=_CAPTURE_READ_DECISION_SEAL_KEY,
        )
        validate_release_cas(
            delivery.release_cas,
            scope=delivery.canonical_read_scope,
            membership=delivery.boundary_scope_membership,
            decision=delivery.read_authorization_decision,
            release_context=delivery.release_recipient_context,
            qualified_deadline_mapping=delivery.qualified_deadline_mapping,
            grant_currentness_evidence=delivery.grant_currentness_evidence,
            expected_observer_identity=expected_observer_identity,
            expected_boundary_identity=expected_boundary_identity,
            expected_authorization_audience=AUTHORIZATION_SERVER,
            expected_authorization_cut=expected_authorization_cut,
            expected_issuer_identity=(
                AUTHORIZATION_SERVER,
                AUTHORIZATION_SERVER_KEY_ID,
                SERVER_CLOCK,
            ),
            expected_release_recipient_identity=expected_observer_identity,
            expected_release_transport_context=(expected_release_transport_context),
            expected_local_security_state=expected_security_state,
            expected_release_context_artifact_digest=(
                release_recipient_artifact_digest(expected_release_context)
            ),
            expected_grant_currentness_state_cut=expected_currentness_cut,
            expected_deadline_mapping_state_cut=(expected_deadline_mapping_state_cut),
            release_idempotency_key=expected_release_idempotency_key,
            expected_boundary_clock_incarnation=expected_boundary_clock,
            expected_mapping_policy_artifact_digest=(
                expected_mapping_policy_artifact_digest
            ),
            checked_at=delivery.received_at - 2,
            fixture_key=_CAPTURE_READ_DECISION_SEAL_KEY,
        )
        validate_committed_outbox_artifact(
            delivery.committed_outbox_artifact,
            scope=delivery.canonical_read_scope,
            membership=delivery.boundary_scope_membership,
            release_cas=delivery.release_cas,
            validated_release_cas_receipt=(delivery.validated_release_cas_receipt),
            commit_receipt=delivery.outbox_commit_receipt,
            expected_commit_state_cut=(delivery.expected_outbox_commit_state_cut),
            release_context=delivery.release_recipient_context,
            expected_boundary_identity=expected_boundary_identity,
            expected_recipient_identity=expected_observer_identity,
            expected_boundary_clock_incarnation=expected_boundary_clock,
            expected_stable_outbox_item_id=expected_stable_outbox_item_id,
            expected_exact_payload=_typed_canonical_bytes(frame),
            expected_transport_idempotency_key=(expected_transport_idempotency_key),
            expected_artifact_digest=committed_outbox_artifact_digest(
                expected_committed_outbox
            ),
            checked_at=delivery.received_at - 1,
            fixture_key=_CAPTURE_READ_DECISION_SEAL_KEY,
        )
        validate_dispatch_context(
            delivery.dispatch_context,
            scope=delivery.canonical_read_scope,
            membership=delivery.boundary_scope_membership,
            release_context=delivery.release_recipient_context,
            release_cas=delivery.release_cas,
            validated_release_cas_receipt=(delivery.validated_release_cas_receipt),
            committed_outbox=delivery.committed_outbox_artifact,
            commit_receipt=delivery.outbox_commit_receipt,
            expected_commit_state_cut=(delivery.expected_outbox_commit_state_cut),
            expected_boundary_identity=expected_boundary_identity,
            expected_recipient_identity=expected_observer_identity,
            expected_release_transport_context=(expected_release_transport_context),
            expected_release_security_state=expected_security_state,
            expected_boundary_clock_incarnation=expected_boundary_clock,
            expected_release_context_artifact_digest=(
                release_recipient_artifact_digest(expected_release_context)
            ),
            release_context_checked_at=delivery.received_at - 2,
            expected_stable_outbox_item_id=expected_stable_outbox_item_id,
            actual_dispatch_payload=delivery.exact_received_payload,
            expected_committed_outbox_artifact_digest=(
                committed_outbox_artifact_digest(expected_committed_outbox)
            ),
            expected_dispatch_attempt_id=expected_dispatch_attempt_id,
            expected_transport_idempotency_key=(expected_transport_idempotency_key),
            expected_local_security_state=expected_security_state,
            expected_destination_cut=expected_dispatch_destination_cut,
            expected_dispatch_context_artifact_digest=(
                dispatch_artifact_digest(expected_dispatch_context)
            ),
            checked_at=delivery.received_at,
            fixture_key=_CAPTURE_READ_DECISION_SEAL_KEY,
        )
    except BridgeValidationError as exc:
        raise CaptureError("receiver delivery read bridge is invalid") from exc
    _require(
        _is_uuid4(delivery.delivery_id)
        and delivery.receiver_principal == expected_receiver
        and delivery.producer_frame_digest == frame.frame_digest
        and delivery.exact_received_payload
        == _typed_canonical_bytes(frame)
        == delivery.committed_outbox_artifact.exact_payload
        and delivery.grant_digest == grant_context.grant.grant_digest
        and delivery.grant_install_receipt_digest
        == grant_context.install.receipt_digest
        and delivery.grant_entitlement_digest == expected_grant_entitlement_digest
        and expected_grant_entitlement_digest
        in grant_context.grant.grant_entitlement_digests
        and delivery.canonical_read_scope.declared_stream_digest
        == frame.stream_declaration_digest
        and delivery.canonical_read_scope.schema_digest == frame.schema.sha256
        and delivery.canonical_read_scope.authority_realm_key == AUTHORITY_REALM_KEY
        and delivery.canonical_read_scope.source_session_kind == "PLANT_CONTROL"
        and delivery.canonical_read_scope.logical_session_id == frame.session
        and delivery.canonical_read_scope.source_generation == frame.generation
        and delivery.canonical_read_scope.literal_route
        == canonical_read_route(
            realm=OBSERVER_STABLE_REALM_ID,
            logical_session_id=frame.session,
            route_class=expected_route_class,
            channel=expected_route_channel,
        )
        and delivery.canonical_read_scope.provider_contract_digest
        == _digest(
            {
                "provider_contract": frame.stream_declaration_digest,
                "source_id": frame.source_id,
            }
        )
        and delivery.canonical_read_scope.privacy_projection_digest
        == _digest(
            {
                "descriptor": frame.descriptor_digest,
                "receiver": grant_context.grant.receiver_principal,
            }
        )
        and delivery.canonical_read_scope.authorization_audience == AUTHORIZATION_SERVER
        and (
            delivery.canonical_read_scope.plane,
            delivery.canonical_read_scope.message_class,
        )
        == (frame.stream_key[0], frame.stream_key[2])
        and delivery.canonical_read_scope.channel == expected_route_channel
        and (
            delivery.canonical_read_scope,
            delivery.boundary_scope_membership,
            delivery.read_authorization_decision,
            delivery.retained_authorization_cut,
            delivery.release_recipient_context,
            delivery.expected_release_transport_context,
            delivery.qualified_deadline_mapping,
            delivery.expected_deadline_mapping_state_cut,
            delivery.grant_currentness_evidence,
            delivery.expected_grant_currentness_state_cut,
            delivery.release_cas,
            delivery.validated_release_cas_receipt,
            delivery.committed_outbox_artifact,
            delivery.outbox_commit_receipt,
            delivery.expected_outbox_commit_state_cut,
            delivery.dispatch_context,
            delivery.expected_dispatch_destination_cut,
            delivery.release_authority_recheck_digest,
        )
        == (
            expected_scope,
            expected_membership,
            expected_decision,
            reconstructed_authorization_cut,
            expected_release_context,
            expected_release_transport_context,
            expected_deadline_mapping,
            expected_deadline_mapping_state_cut,
            expected_currentness_evidence,
            reconstructed_currentness_cut,
            expected_release_cas,
            expected_validated_release_cas_receipt,
            expected_committed_outbox,
            expected_outbox_commit_receipt,
            reconstructed_outbox_commit_state_cut,
            expected_dispatch_context,
            expected_dispatch_destination_cut,
            expected_release_recheck_digest,
        )
        and delivery.retained_authorization_cut == expected_authorization_cut
        and delivery.expected_grant_currentness_state_cut == expected_currentness_cut
        and delivery.read_authorization_decision.grant_digest
        == grant_context.grant.grant_digest
        and delivery.read_authorization_decision.capability_digest
        == grant_context.grant.grant_digest
        and delivery.read_authorization_decision.capability_seal_digest
        == _digest(grant_context.grant.protected_body.authority_receipt)
        and delivery.read_authorization_decision.capability_issuer_snapshot_digest
        == _SYNTHETIC_CAPABILITY_ISSUER_SNAPSHOT_DIGEST
        and delivery.read_authorization_decision.manifest_digest
        == _SYNTHETIC_READ_MANIFEST_DIGEST
        and delivery.read_authorization_decision.manifest_entry_digest
        == _SYNTHETIC_READ_MANIFEST_ENTRY_DIGEST
        and delivery.read_authorization_decision.server_entry_head_digest
        == _SYNTHETIC_AUTHORIZATION_SERVER_HEAD_DIGEST
        and delivery.read_authorization_decision.server_selector_digest
        == _SYNTHETIC_AUTHORIZATION_SERVER_SELECTOR_DIGEST
        and delivery.read_authorization_decision.observer_principal
        == delivery.receiver_principal
        and delivery.read_authorization_decision.full_boundary_key_digest
        == expected_full_boundary_key_digest
        and delivery.committed_outbox_artifact.committed_at == delivery.received_at - 1
        and delivery.dispatch_context.verified_at == delivery.received_at
        and delivery.release_authority_recheck_digest
        == _digest(
            {
                "boundary_membership_digest": (
                    delivery.boundary_scope_membership.membership_digest
                ),
                "canonical_scope_digest": (delivery.canonical_read_scope.scope_digest),
                "semantic_decision_digest": (
                    delivery.read_authorization_decision.semantic_decision_digest
                ),
                "decision_artifact_digest": read_decision_artifact_digest(
                    delivery.read_authorization_decision
                ),
                "dispatch_context_artifact_digest": dispatch_artifact_digest(
                    delivery.dispatch_context
                ),
                "committed_outbox_artifact_digest": (
                    committed_outbox_artifact_digest(delivery.committed_outbox_artifact)
                ),
                "validated_release_cas_receipt_artifact_digest": (
                    validated_release_cas_receipt_artifact_digest(
                        delivery.validated_release_cas_receipt
                    )
                ),
                "outbox_commit_receipt_artifact_digest": (
                    outbox_commit_receipt_artifact_digest(
                        delivery.outbox_commit_receipt
                    )
                ),
                "installed_outbox_storage_state_head_digest": (
                    delivery.outbox_commit_receipt.installed_storage_state_head_digest
                ),
                "grant_currentness_artifact_digest": (
                    grant_currentness_artifact_digest(
                        delivery.grant_currentness_evidence
                    )
                ),
                "release_cas_artifact_digest": delivery.release_cas.cas_digest,
                "frame_digest": frame.frame_digest,
                "grant_install_receipt_digest": grant_context.install.receipt_digest,
                "received_at": delivery.received_at,
                "release_recheck": "CURRENT_AT_RELEASE_NO_FUTURE_AUTHORITY",
            }
        )
        and delivery.receiver_clock_incarnation
        == grant_context.install.receiver_clock_incarnation
        and grant_context.install.installed_at
        <= delivery.received_at
        < delivery.local_not_after
        == grant_context.install.local_not_after
        and delivery.delivery_digest == _frame_delivery_digest(delivery),
        "receiver delivery does not bind its local grant/install/deadline",
        CaptureError,
    )
    _validate_authority(
        delivery.authority_receipt,
        domain="receiver-frame-delivery",
        subject_digest=delivery.delivery_digest,
        issuer=INGRESS_AUTHORITY,
        subject=delivery.receiver_principal,
    )
    _require(
        delivery.authority_receipt.clock_domain == "receiver-monotonic"
        and delivery.authority_receipt.clock_incarnation
        == delivery.receiver_clock_incarnation
        and delivery.authority_receipt.event_time == delivery.received_at,
        "receiver frame delivery uses the wrong receiver clock",
        CaptureError,
    )


def _validate_correlation(
    correlation: ResolvedCaptureSourceCorrelation,
    *,
    receiver: str,
    driven_frame: ProducerFrame,
    origin_frame: ProducerFrame,
    origin_admission: ReceiverAdmissionReceipt,
) -> None:
    source = driven_frame.normative_source
    _require(
        source is not None
        and correlation.receiver_principal == receiver
        and correlation.driven_frame_digest == driven_frame.frame_digest
        and correlation.source_ref_digest == source.source_ref_digest
        and correlation.origin_frame_digest
        == source.origin_frame_digest
        == origin_frame.frame_digest
        and source.origin_stream_declaration_digest
        == origin_frame.stream_declaration_digest
        and source.origin_stream_epoch == origin_frame.stream_epoch
        and source.origin_position == origin_frame.stream_position
        and source.origin_payload == origin_frame.payload
        and correlation.origin_admission_receipt_digest
        == origin_admission.receipt_digest
        and origin_admission.key.receiver_principal == receiver
        and origin_admission.frame_digest == origin_frame.frame_digest
        and correlation.correlation_digest == _correlation_digest(correlation),
        "receiver correlation substituted origin, receiver, or admission evidence",
        CaptureError,
    )


@dataclass(frozen=True, slots=True)
class TrustedProjectionRecord:
    projection_id: str
    projector_principal: str
    security_state_digest: str
    audience: str
    original_frame_digest: str
    original_stream_declaration_digest: str
    original_stream_epoch: str
    original_position: int
    original_content: ContentRef
    projection_policy: ContentRef
    transform_artifact: ContentRef
    projected_frame_digest: str
    projected_stream_declaration_digest: str
    projected_content: ContentRef
    record_digest: str
    authority_receipt: AuthorityReceipt


def _projection_record_digest(record: TrustedProjectionRecord) -> str:
    return _body_digest(record, "record_digest", "authority_receipt")


def _projection_admission_basis_digest(
    record: TrustedProjectionRecord,
) -> str:
    return _digest(
        {
            "projection_record_digest": record.record_digest,
            "projection_record_authority_receipt_digest": (
                record.authority_receipt.receipt_digest
            ),
        }
    )


def _seal_projection_record(
    record: TrustedProjectionRecord,
    *,
    event_time: int,
) -> TrustedProjectionRecord:
    record = replace(record, record_digest=_projection_record_digest(record))
    return replace(
        record,
        authority_receipt=_seal_authority(
            receipt_id=record.authority_receipt.receipt_id,
            domain="trusted-projection-record",
            subject_digest=record.record_digest,
            issuer=record.projector_principal,
            subject=record.audience,
            clock_domain="projector-monotonic",
            clock_incarnation=GENERATION,
            event_time=event_time,
        ),
    )


@dataclass(frozen=True, slots=True)
class TrustedProjectionProvenance:
    provenance_id: str
    receiver_principal: str
    evidence_lineage_incarnation: str
    trusted_projection_record_digest: str
    receiver_admission_receipt_digest: str
    projection_digest: str
    authority_receipt: AuthorityReceipt


def _projection_digest(
    provenance: TrustedProjectionProvenance,
) -> str:
    return _body_digest(provenance, "projection_digest", "authority_receipt")


def _seal_projection(
    provenance: TrustedProjectionProvenance,
    *,
    event_time: int,
    receiver_clock_incarnation: str,
) -> TrustedProjectionProvenance:
    provenance = replace(
        provenance,
        projection_digest=_projection_digest(provenance),
    )
    return replace(
        provenance,
        authority_receipt=_seal_authority(
            receipt_id=provenance.authority_receipt.receipt_id,
            domain="trusted-projection-provenance",
            subject_digest=provenance.projection_digest,
            issuer=INGRESS_AUTHORITY,
            subject=provenance.receiver_principal,
            clock_domain="receiver-monotonic",
            clock_incarnation=receiver_clock_incarnation,
            event_time=event_time,
        ),
    )


def _validate_projection(
    provenance: TrustedProjectionProvenance,
    *,
    original_frame: ProducerFrame,
    projected_frame: ProducerFrame,
    receiver: str,
    audience: str,
    receiver_admission_receipt_digest: str,
    receiver_admission: ReceiverAdmissionReceipt,
    projection_record: TrustedProjectionRecord,
    evidence_lineage_incarnation: str,
    store: ContentStore,
) -> None:
    record = projection_record
    policy = _bounded_json_object(store.get(record.projection_policy))
    transform = _bounded_json_object(store.get(record.transform_artifact))
    _require(
        _is_uuid4(record.projection_id)
        and _is_uuid4(provenance.provenance_id)
        and record.projector_principal == PROVIDER_AUTHORITY
        and record.security_state_digest == original_frame.security_state_digest
        and provenance.receiver_principal == receiver
        and provenance.evidence_lineage_incarnation == evidence_lineage_incarnation
        and provenance.trusted_projection_record_digest == record.record_digest
        and record.audience == audience
        and record.original_frame_digest == original_frame.frame_digest
        and record.original_stream_declaration_digest
        == original_frame.stream_declaration_digest
        and record.original_stream_epoch == original_frame.stream_epoch
        and record.original_position == original_frame.stream_position
        and record.original_content == original_frame.payload
        and record.projected_frame_digest == projected_frame.frame_digest
        and record.projected_stream_declaration_digest
        == projected_frame.stream_declaration_digest
        and record.projected_content == projected_frame.payload
        and provenance.receiver_admission_receipt_digest
        == receiver_admission_receipt_digest
        == receiver_admission.receipt_digest
        and receiver_admission.key.receiver_principal == receiver
        and receiver_admission.phase == "live"
        and receiver_admission.receipt_digest
        == _admission_receipt_digest(receiver_admission)
        and receiver_admission.key.evidence_lineage_incarnation
        == evidence_lineage_incarnation
        and receiver_admission.frame_digest == projected_frame.frame_digest
        and receiver_admission.admission_basis_digest
        == _projection_admission_basis_digest(record)
        and record.authority_receipt.clock_domain == "projector-monotonic"
        and record.authority_receipt.clock_incarnation == GENERATION
        and provenance.authority_receipt.clock_domain == "receiver-monotonic"
        and provenance.authority_receipt.clock_incarnation
        == receiver_admission.receiver_clock_incarnation
        and receiver_admission.admitted_at <= provenance.authority_receipt.event_time
        and receiver_admission.authority_receipt.clock_domain == "receiver-monotonic"
        and receiver_admission.authority_receipt.clock_incarnation
        == receiver_admission.receiver_clock_incarnation
        and receiver_admission.authority_receipt.event_time
        == receiver_admission.admitted_at
        and policy
        == {
            "audience": audience,
            "kind": "trusted-projection-policy-v1",
        }
        and transform
        == {
            "kind": "content-addressed-projection-v1",
            "original_content_digest": original_frame.payload.sha256,
            "projected_content_digest": projected_frame.payload.sha256,
        }
        and record.record_digest == _projection_record_digest(record)
        and provenance.projection_digest == _projection_digest(provenance),
        "trusted projection changed original, policy, output, audience, or receiver",
        CaptureError,
    )
    _validate_authority(
        record.authority_receipt,
        domain="trusted-projection-record",
        subject_digest=record.record_digest,
        issuer=PROVIDER_AUTHORITY,
        subject=audience,
    )
    _validate_authority(
        provenance.authority_receipt,
        domain="trusted-projection-provenance",
        subject_digest=provenance.projection_digest,
        issuer=INGRESS_AUTHORITY,
        subject=receiver,
    )
    _validate_authority(
        receiver_admission.authority_receipt,
        domain="receiver-live-admission",
        subject_digest=receiver_admission.receipt_digest,
        issuer=INGRESS_AUTHORITY,
        subject=receiver,
    )


@dataclass(frozen=True, slots=True)
class ResolvedOriginEvidence:
    kind: str
    exact_origin: ResolvedCaptureSourceCorrelation | None
    trusted_projection: TrustedProjectionProvenance | None


def _validate_resolved_origin(
    evidence: ResolvedOriginEvidence,
    *,
    receiver: str,
    driven_frame: ProducerFrame,
    origin_frame: ProducerFrame,
    origin_admission: ReceiverAdmissionReceipt,
    projected_frame: ProducerFrame | None,
    projected_admission: ReceiverAdmissionReceipt | None,
    projection_record: TrustedProjectionRecord | None,
    evidence_lineage_incarnation: str | None,
    audience: str,
    store: ContentStore,
) -> None:
    if evidence.kind == "EXACT_ORIGIN":
        _require(
            evidence.exact_origin is not None and evidence.trusted_projection is None,
            "exact origin union is ambiguous",
            CaptureError,
        )
        if evidence.exact_origin is not None:
            _validate_correlation(
                evidence.exact_origin,
                receiver=receiver,
                driven_frame=driven_frame,
                origin_frame=origin_frame,
                origin_admission=origin_admission,
            )
        return
    _require(
        evidence.kind == "TRUSTED_PROJECTED_ORIGIN"
        and evidence.exact_origin is None
        and evidence.trusted_projection is not None
        and projected_frame is not None
        and projected_admission is not None
        and projection_record is not None
        and evidence_lineage_incarnation is not None,
        "resolved origin union is unknown or ambiguous",
        CaptureError,
    )
    if (
        evidence.trusted_projection is not None
        and projected_frame is not None
        and projected_admission is not None
        and projection_record is not None
        and evidence_lineage_incarnation is not None
    ):
        _validate_projection(
            evidence.trusted_projection,
            original_frame=origin_frame,
            projected_frame=projected_frame,
            receiver=receiver,
            audience=audience,
            receiver_admission_receipt_digest=(projected_admission.receipt_digest),
            receiver_admission=projected_admission,
            projection_record=projection_record,
            evidence_lineage_incarnation=evidence_lineage_incarnation,
            store=store,
        )


# The active fixture store is set only while deterministic fixture validation
# runs. It avoids embedding mutable content maps inside signed model objects.
_ACTIVE_STORE = ContentStore()


@dataclass(frozen=True, slots=True, order=True)
class AdmissionLineageKey:
    receiver_principal: str
    stream_declaration_digest: str
    stream_epoch: str
    evidence_lineage_incarnation: str


@dataclass(frozen=True, slots=True)
class FrameAdmissionHeadCommitReceipt:
    commit_id: str
    key: AdmissionLineageKey
    operation: str
    prior_head_digest: str
    installed_head_digest: str
    selector_version: int
    operation_evidence_digest: str
    commit_digest: str
    authority_receipt: AuthorityReceipt


def _frame_head_commit_digest(
    receipt: FrameAdmissionHeadCommitReceipt,
) -> str:
    return _body_digest(receipt, "commit_digest", "authority_receipt")


def _seal_frame_head_commit(
    receipt: FrameAdmissionHeadCommitReceipt,
    *,
    receiver_clock_incarnation: str,
    committed_at: int,
) -> FrameAdmissionHeadCommitReceipt:
    receipt = replace(
        receipt,
        commit_digest=_frame_head_commit_digest(receipt),
    )
    return replace(
        receipt,
        authority_receipt=_seal_authority(
            receipt_id=receipt.authority_receipt.receipt_id,
            domain="frame-admission-head-commit",
            subject_digest=receipt.commit_digest,
            issuer=INGRESS_AUTHORITY,
            subject=receipt.key.receiver_principal,
            clock_domain="receiver-monotonic",
            clock_incarnation=receiver_clock_incarnation,
            event_time=committed_at,
        ),
    )


def _validate_frame_head_commit(
    receipt: FrameAdmissionHeadCommitReceipt,
    *,
    key: AdmissionLineageKey,
    operation: str,
    prior_head_digest: str,
    installed_head_digest: str,
    selector_version: int,
    operation_evidence_digest: str,
) -> None:
    _require(
        _is_uuid4(receipt.commit_id)
        and receipt.key == key
        and receipt.operation == operation
        and receipt.prior_head_digest == prior_head_digest
        and receipt.installed_head_digest == installed_head_digest
        and receipt.selector_version == selector_version
        and receipt.operation_evidence_digest == operation_evidence_digest
        and receipt.commit_digest == _frame_head_commit_digest(receipt),
        "live admission head lacks its exact successful selector commit",
        CaptureError,
    )
    _validate_authority(
        receipt.authority_receipt,
        domain="frame-admission-head-commit",
        subject_digest=receipt.commit_digest,
        issuer=INGRESS_AUTHORITY,
        subject=key.receiver_principal,
    )


@dataclass(frozen=True, slots=True)
class AdmissionPositionEvidence:
    source_position: int
    frame_digest: str
    admission_receipt_digest: str


@dataclass(frozen=True, slots=True)
class LiveAdmissionHead:
    key: AdmissionLineageKey
    ledger_incarnation: str
    state_version: int
    order_policy: str
    high_water: int
    admitted_positions: tuple[AdmissionPositionEvidence, ...]
    finalized_gap_ranges: tuple[tuple[int, int], ...]
    capacity_limit: int
    prior_head_digest: str | None
    head_digest: str
    last_commit: FrameAdmissionHeadCommitReceipt | None


def _live_head_digest(head: LiveAdmissionHead) -> str:
    return _body_digest(head, "head_digest", "last_commit")


def _live_genesis_digest(head: LiveAdmissionHead) -> str:
    return _digest(
        {
            "key": head.key,
            "ledger_incarnation": head.ledger_incarnation,
            "state": "live-admission-head-genesis",
        }
    )


def _new_live_head(
    key: AdmissionLineageKey,
    *,
    ledger_incarnation: str,
    starting_position: int,
    capacity_limit: int = MAX_ADMISSION_POSITIONS,
) -> LiveAdmissionHead:
    head = LiveAdmissionHead(
        key,
        ledger_incarnation,
        0,
        "STRICT_MONOTONIC",
        starting_position - 1,
        (),
        (),
        capacity_limit,
        None,
        "",
        None,
    )
    head = replace(head, head_digest=_live_head_digest(head))
    genesis = _live_genesis_digest(head)
    commit = _seal_frame_head_commit(
        FrameAdmissionHeadCommitReceipt(
            commit_id=_u_for(("live-genesis-commit", key, ledger_incarnation)),
            key=key,
            operation="live_genesis",
            prior_head_digest=genesis,
            installed_head_digest=head.head_digest,
            selector_version=0,
            operation_evidence_digest=genesis,
            commit_digest="",
            authority_receipt=_seal_authority(
                receipt_id=_u_for(
                    ("live-genesis-commit-authority", key, ledger_incarnation)
                ),
                domain="frame-admission-head-commit",
                subject_digest="0" * 64,
                issuer=INGRESS_AUTHORITY,
                subject=key.receiver_principal,
                clock_domain="receiver-monotonic",
                clock_incarnation=(
                    RECEIVER_A_CLOCK
                    if key.receiver_principal == OBSERVER_A
                    else RECEIVER_B_CLOCK
                ),
                event_time=starting_position,
            ),
        ),
        receiver_clock_incarnation=(
            RECEIVER_A_CLOCK
            if key.receiver_principal == OBSERVER_A
            else RECEIVER_B_CLOCK
        ),
        committed_at=starting_position,
    )
    return replace(head, last_commit=commit)


@dataclass(frozen=True, slots=True)
class ReceiverAdmissionReceipt:
    receipt_id: str
    key: AdmissionLineageKey
    phase: str
    frame_digest: str
    source_position: int
    state_version: int
    prior_head_digest: str
    installed_head_digest: str
    receiver_clock_incarnation: str
    admitted_at: int
    provider_history_provenance_digest: str | None
    head_commit_digest: str
    receipt_digest: str
    authority_receipt: AuthorityReceipt
    admission_basis_digest: str | None = None
    delivery_digest: str | None = None
    canonical_scope_digest: str | None = None
    boundary_scope_membership_digest: str | None = None
    read_authorization_decision_digest: str | None = None
    release_authority_recheck_digest: str | None = None


def _admission_receipt_digest(receipt: ReceiverAdmissionReceipt) -> str:
    return _body_digest(receipt, "receipt_digest", "authority_receipt")


def _merge_gap_ranges(
    existing: tuple[tuple[int, int], ...],
    start: int,
    end: int,
) -> tuple[tuple[int, int], ...]:
    if start > end:
        return existing
    ranges = sorted((*existing, (start, end)))
    merged: list[tuple[int, int]] = []
    for left, right in ranges:
        if not merged or left > merged[-1][1] + 1:
            merged.append((left, right))
        else:
            merged[-1] = (merged[-1][0], max(merged[-1][1], right))
    return tuple(merged)


def _admit_live(
    head: LiveAdmissionHead,
    *,
    frame_digest: str,
    source_position: int,
    receiver_clock_incarnation: str,
    admitted_at: int,
    index: int,
    admission_basis_digest: str | None = None,
    delivery: ReceiverFrameDelivery | None = None,
    delivery_frame: ProducerFrame | None = None,
    delivery_grant_context: ReceiverGrantContext | None = None,
    expected_grant_entitlement_digest: str | None = None,
) -> tuple[LiveAdmissionHead, ReceiverAdmissionReceipt]:
    if delivery is not None:
        _require(
            type(delivery_frame) is ProducerFrame
            and type(delivery_grant_context) is ReceiverGrantContext
            and type(expected_grant_entitlement_digest) is str,
            "live admission lacks the exact frame, grant, or entitlement "
            "needed to validate its delivery before state construction",
            CaptureError,
        )
        _require(
            delivery_frame.frame_digest == frame_digest
            and delivery_frame.stream_position == source_position,
            "live admission frame arguments differ from the validated delivery frame",
            CaptureError,
        )
        _validate_frame_delivery(
            delivery,
            delivery_frame,
            delivery_grant_context,
            expected_grant_entitlement_digest=(expected_grant_entitlement_digest),
        )
    else:
        _require(
            delivery_frame is None
            and delivery_grant_context is None
            and expected_grant_entitlement_digest is None,
            "live admission received orphaned delivery validation inputs",
            CaptureError,
        )
    _require(head.last_commit is not None, "live head has no installed selector")
    if head.last_commit is not None:
        _validate_frame_head_commit(
            head.last_commit,
            key=head.key,
            operation="live_genesis" if head.state_version == 0 else "live_update",
            prior_head_digest=(
                _live_genesis_digest(head)
                if head.state_version == 0
                else head.prior_head_digest or ""
            ),
            installed_head_digest=head.head_digest,
            selector_version=head.state_version,
            operation_evidence_digest=(
                _live_genesis_digest(head)
                if head.state_version == 0
                else head.admitted_positions[-1].admission_receipt_digest
            ),
        )
    _require(
        head.order_policy == "STRICT_MONOTONIC"
        and source_position > head.high_water
        and len(head.admitted_positions) < head.capacity_limit,
        "live admission is duplicate, behind high water, or at capacity",
        CaptureError,
    )
    next_version = head.state_version + 1
    if delivery is not None:
        _require(
            delivery.receiver_principal == head.key.receiver_principal
            and delivery.producer_frame_digest == frame_digest
            and delivery.receiver_clock_incarnation == receiver_clock_incarnation
            and delivery.received_at <= admitted_at < delivery.local_not_after,
            "live admission delivery is cross-frame, cross-receiver, or stale",
            CaptureError,
        )
    provisional_receipt = ReceiverAdmissionReceipt(
        receipt_id=_u(40_000 + index),
        key=head.key,
        phase="live",
        frame_digest=frame_digest,
        source_position=source_position,
        state_version=next_version,
        prior_head_digest=head.head_digest,
        installed_head_digest="",
        receiver_clock_incarnation=receiver_clock_incarnation,
        admitted_at=admitted_at,
        provider_history_provenance_digest=None,
        head_commit_digest="",
        receipt_digest="",
        authority_receipt=_seal_authority(
            receipt_id=_u(41_000 + index),
            domain="receiver-live-admission",
            subject_digest="0" * 64,
            issuer=INGRESS_AUTHORITY,
            subject=head.key.receiver_principal,
            clock_domain="receiver-monotonic",
            clock_incarnation=receiver_clock_incarnation,
            event_time=admitted_at,
        ),
        admission_basis_digest=admission_basis_digest,
        delivery_digest=(delivery.delivery_digest if delivery is not None else None),
        canonical_scope_digest=(
            delivery.canonical_read_scope.scope_digest if delivery is not None else None
        ),
        boundary_scope_membership_digest=(
            delivery.boundary_scope_membership.membership_digest
            if delivery is not None
            else None
        ),
        read_authorization_decision_digest=(
            delivery.read_authorization_decision.semantic_decision_digest
            if delivery is not None
            else None
        ),
        release_authority_recheck_digest=(
            delivery.release_authority_recheck_digest if delivery is not None else None
        ),
    )
    provisional_evidence = AdmissionPositionEvidence(
        source_position,
        frame_digest,
        "0" * 64,
    )
    next_head = LiveAdmissionHead(
        head.key,
        head.ledger_incarnation,
        next_version,
        head.order_policy,
        source_position,
        (*head.admitted_positions, provisional_evidence),
        _merge_gap_ranges(
            head.finalized_gap_ranges,
            head.high_water + 1,
            source_position - 1,
        ),
        head.capacity_limit,
        head.head_digest,
        "",
        None,
    )
    # The receipt and head are acyclic: the head commits the frame/position and
    # a receipt-independent admission event digest, then the receipt binds the
    # installed head. It never appears inside that head.
    event_digest = _digest(
        {
            "key": head.key,
            "frame_digest": frame_digest,
            "source_position": source_position,
            "state_version": next_version,
            "prior_head_digest": head.head_digest,
            "admission_basis_digest": admission_basis_digest,
            "delivery_digest": provisional_receipt.delivery_digest,
            "canonical_scope_digest": provisional_receipt.canonical_scope_digest,
            "boundary_scope_membership_digest": (
                provisional_receipt.boundary_scope_membership_digest
            ),
            "read_authorization_decision_digest": (
                provisional_receipt.read_authorization_decision_digest
            ),
            "release_authority_recheck_digest": (
                provisional_receipt.release_authority_recheck_digest
            ),
        }
    )
    next_head = replace(
        next_head,
        admitted_positions=(
            *head.admitted_positions,
            replace(
                provisional_evidence,
                admission_receipt_digest=event_digest,
            ),
        ),
    )
    next_head = replace(next_head, head_digest=_live_head_digest(next_head))
    commit = _seal_frame_head_commit(
        FrameAdmissionHeadCommitReceipt(
            commit_id=_u(39_500 + index),
            key=head.key,
            operation="live_update",
            prior_head_digest=head.head_digest,
            installed_head_digest=next_head.head_digest,
            selector_version=next_version,
            operation_evidence_digest=event_digest,
            commit_digest="",
            authority_receipt=_pending_authority(39_500 + index),
        ),
        receiver_clock_incarnation=receiver_clock_incarnation,
        committed_at=admitted_at,
    )
    next_head = replace(next_head, last_commit=commit)
    receipt = replace(
        provisional_receipt,
        installed_head_digest=next_head.head_digest,
        head_commit_digest=commit.commit_digest,
    )
    receipt = replace(
        receipt,
        receipt_digest=_admission_receipt_digest(receipt),
    )
    receipt = replace(
        receipt,
        authority_receipt=_seal_authority(
            receipt_id=receipt.authority_receipt.receipt_id,
            domain="receiver-live-admission",
            subject_digest=receipt.receipt_digest,
            issuer=INGRESS_AUTHORITY,
            subject=head.key.receiver_principal,
            clock_domain="receiver-monotonic",
            clock_incarnation=receiver_clock_incarnation,
            event_time=admitted_at,
        ),
    )
    return next_head, receipt


@dataclass(frozen=True, slots=True)
class ProviderHistoryProvenance:
    provenance_id: str
    provider_principal: str
    key: AdmissionLineageKey
    original_frame_digest: str
    original_frame_bytes: ContentRef
    provider_live_head: ProtectedBody
    provider_retirement_checkpoint: ProtectedBody
    retained_position: int
    retained_membership_digest: str
    projection_chain_digest: str
    provenance_digest: str
    authority_receipt: AuthorityReceipt


def _provider_history_digest(provenance: ProviderHistoryProvenance) -> str:
    return _body_digest(provenance, "provenance_digest", "authority_receipt")


def _seal_provider_history(
    provenance: ProviderHistoryProvenance,
    *,
    event_time: int,
) -> ProviderHistoryProvenance:
    provenance = replace(
        provenance,
        provenance_digest=_provider_history_digest(provenance),
    )
    return replace(
        provenance,
        authority_receipt=_seal_authority(
            receipt_id=provenance.authority_receipt.receipt_id,
            domain="provider-history-provenance",
            subject_digest=provenance.provenance_digest,
            issuer=PROVIDER_AUTHORITY,
            subject=provenance.key.receiver_principal,
            clock_domain="provider-journal-monotonic",
            clock_incarnation=provenance.key.stream_epoch,
            event_time=event_time,
        ),
    )


def _validate_provider_history(
    provenance: ProviderHistoryProvenance,
    *,
    frame: ProducerFrame,
    expected_projection_chain_digest: str,
    store: ContentStore,
) -> None:
    live_body = _bounded_json_object(store.get(provenance.provider_live_head.body))
    retirement_body = _bounded_json_object(
        store.get(provenance.provider_retirement_checkpoint.body)
    )
    expected_member = {
        "frame_digest": frame.frame_digest,
        "original_frame_body": _normalize(frame.protected_body.body),
        "position": frame.stream_position,
    }
    expected_live_body = {
        "admitted_positions": [expected_member],
        "generation": frame.generation,
        "kind": "provider-live-history-head-v1",
        "provider_principal": PROVIDER_AUTHORITY,
        "session": frame.session,
        "state_version": 1,
        "stream_declaration_digest": frame.stream_declaration_digest,
        "stream_epoch": frame.stream_epoch,
    }
    membership_digest = _digest(
        {
            "provider_live_head_digest": provenance.provider_live_head.body_digest,
            "frame_digest": frame.frame_digest,
            "position": frame.stream_position,
        }
    )
    expected_retirement_body = {
        "kind": "provider-retirement-checkpoint-v1",
        "provider_live_head_digest": provenance.provider_live_head.body_digest,
        "retained_membership_digests": [membership_digest],
        "retention_state": "retained",
    }
    _require(
        _is_uuid4(provenance.provenance_id)
        and provenance.provider_principal == PROVIDER_AUTHORITY
        and provenance.key.receiver_principal == OBSERVER_A
        and provenance.key.stream_declaration_digest == frame.stream_declaration_digest
        and provenance.key.stream_epoch == frame.stream_epoch
        and provenance.original_frame_digest == frame.frame_digest
        and provenance.original_frame_bytes == frame.protected_body.body
        and store.get(provenance.original_frame_bytes)
        == store.get(frame.protected_body.body)
        and live_body == expected_live_body
        and retirement_body == expected_retirement_body
        and provenance.provider_live_head.body.media_type
        == "application/vnd.ncp.provider-live-history-head+json"
        and provenance.provider_retirement_checkpoint.body.media_type
        == "application/vnd.ncp.provider-retirement-checkpoint+json"
        and provenance.provider_live_head.body_digest
        == provenance.provider_live_head.body.sha256
        and provenance.provider_retirement_checkpoint.body_digest
        == provenance.provider_retirement_checkpoint.body.sha256
        and provenance.provider_live_head.authority_receipt.clock_domain == "issuer-utc"
        and provenance.provider_live_head.authority_receipt.clock_incarnation
        == GENERATION
        and provenance.provider_retirement_checkpoint.authority_receipt.clock_domain
        == "issuer-utc"
        and (
            provenance.provider_retirement_checkpoint.authority_receipt.clock_incarnation
            == GENERATION
        )
        and provenance.provider_live_head.authority_receipt.event_time
        <= provenance.provider_retirement_checkpoint.authority_receipt.event_time
        and provenance.authority_receipt.clock_domain == "provider-journal-monotonic"
        and provenance.authority_receipt.clock_incarnation
        == provenance.key.stream_epoch
        and provenance.retained_position == frame.stream_position
        and provenance.retained_membership_digest == membership_digest
        and provenance.projection_chain_digest == expected_projection_chain_digest
        and provenance.provenance_digest == _provider_history_digest(provenance),
        "history lacks pre-retirement provider admission and retained byte membership",
        CaptureError,
    )
    _validate_authority(
        provenance.provider_live_head.authority_receipt,
        domain="provider-live-history-head",
        subject_digest=provenance.provider_live_head.body_digest,
        issuer=PROVIDER_AUTHORITY,
        subject=provenance.key.receiver_principal,
    )
    _validate_authority(
        provenance.provider_retirement_checkpoint.authority_receipt,
        domain="provider-retirement-checkpoint",
        subject_digest=provenance.provider_retirement_checkpoint.body_digest,
        issuer=PROVIDER_AUTHORITY,
        subject=provenance.key.receiver_principal,
    )
    _validate_authority(
        provenance.authority_receipt,
        domain="provider-history-provenance",
        subject_digest=provenance.provenance_digest,
        issuer=PROVIDER_AUTHORITY,
        subject=provenance.key.receiver_principal,
    )


def _observer_admission_state_head_digest(
    head: ObserverAdmissionStateHead,
) -> str:
    return _composite_record_digest(head, "head_digest")


def _observer_admission_selector_digest(
    selector: InstalledObserverAdmissionStateSelector,
) -> str:
    return _composite_record_digest(selector, "selector_digest")


def _observer_admission_commit_digest(
    commit: ObserverAdmissionStateCommitReceipt,
) -> str:
    return _composite_record_digest(commit, "commit_digest")


@dataclass(frozen=True, slots=True)
class ObserverAdmissionLifecycleGenesisEvidence:
    uninitialized_selector: InstalledObserverAdmissionStateSelector
    installed_head: ObserverAdmissionStateHead
    commit: ObserverAdmissionStateCommitReceipt
    installed_selector: InstalledObserverAdmissionStateSelector


@dataclass(frozen=True, slots=True)
class ObserverAdmissionStateTransitionEvidence:
    transition_kind: str
    operation_evidence_digest: str
    changed_stream_declaration_digest: str
    prior_head: ObserverAdmissionStateHead
    prior_selector: InstalledObserverAdmissionStateSelector
    installed_head: ObserverAdmissionStateHead
    commit: ObserverAdmissionStateCommitReceipt
    installed_selector: InstalledObserverAdmissionStateSelector


OBSERVER_ADMISSION_TRANSITION_SCHEMAS: dict[str, str] = {
    "RETIREMENT_FREEZE_COMPARE_AND_SWAP": "NO_SUBORDINATE_STATE",
    "HISTORY_GENESIS_COMPARE_AND_SWAP": "STRICT_SUBORDINATE_SUCCESSOR",
    "HISTORY_UPDATE_COMPARE_AND_SWAP": "STRICT_SUBORDINATE_SUCCESSOR",
    "TERMINALIZE_FROM_HISTORY_HEAD": "STRICT_SUBORDINATE_SUCCESSOR",
    "TERMINALIZE_FROM_RETIREMENT_ANCHOR": "STRICT_SUBORDINATE_SUCCESSOR",
}


def _observer_admission_transition_schema(transition_kind: str) -> str:
    schema = OBSERVER_ADMISSION_TRANSITION_SCHEMAS.get(transition_kind)
    _require(
        schema is not None,
        "observer admission transition kind is not allocated",
        CaptureError,
    )
    return schema


def _build_observer_admission_lifecycle_genesis(
    *,
    grant_context: ReceiverGrantContext,
    descriptor: ObserverDescriptor,
    revocation_state_digest: str,
    frame_heads: tuple[tuple[str, str], ...],
    event_time: int,
    index: int,
) -> ObserverAdmissionLifecycleGenesisEvidence:
    grant = grant_context.grant
    admission_lineage = _u_for(
        (
            "observer-admission-lifecycle",
            grant.receiver_principal,
            grant.grant_digest,
            index,
        )
    )
    canonical_frame_heads = tuple(sorted(set(frame_heads)))
    _require(
        len(canonical_frame_heads) == len(frame_heads)
        and len({key for key, _ in frame_heads}) == len(frame_heads),
        "observer admission lifecycle genesis has duplicate frame-map siblings",
        CaptureError,
    )
    uninitialized = _seal_composite_record(
        InstalledObserverAdmissionStateSelector(
            selector_id=_u_for(
                ("observer-admission-lifecycle-uninitialized", admission_lineage)
            ),
            admission_lineage_incarnation=admission_lineage,
            selector_version=0,
            state="UNINITIALIZED",
            ever_used=False,
            current_head_digest=None,
            prior_selector_digest=None,
            last_commit_digest=None,
            selector_digest="",
            authority_receipt=_pending_authority(42_100 + index),
        ),
        digest_field="selector_digest",
        domain="installed-observer-admission-state-selector",
        issuer=INGRESS_AUTHORITY,
        subject=grant.receiver_principal,
        clock_domain="receiver-monotonic",
        clock_incarnation=grant_context.install.receiver_clock_incarnation,
        event_time=event_time,
    )
    genesis_anchor = _digest(
        {
            "admission_lineage_incarnation": admission_lineage,
            "domain": "observer-admission-state-genesis-v1",
            "selector_digest": uninitialized.selector_digest,
        }
    )
    head = _seal_composite_record(
        ObserverAdmissionStateHead(
            head_id=_u_for(("observer-admission-lifecycle-head", admission_lineage, 1)),
            observer_principal=grant.receiver_principal,
            admission_lineage_incarnation=admission_lineage,
            state_version=1,
            grant_digest=grant.grant_digest,
            installed_server_registry_entry_digest=_digest(
                {
                    "grant_digest": grant.grant_digest,
                    "state": "synthetic-installed-grant-entry",
                }
            ),
            descriptor_revision=1,
            descriptor_digest=descriptor.descriptor_digest,
            request_challenge=grant.request_challenge,
            maximum_local_duration=grant.maximum_local_duration,
            request_started_at=grant_context.install.request_started_at,
            installed_at=event_time,
            local_not_after=grant_context.install.local_not_after,
            observer_clock_policy_digest=_digest(
                "observer-grant-local-monotonic-deadline-policy-v1"
            ),
            observer_clock_incarnation=(
                grant_context.install.receiver_clock_incarnation
            ),
            revocation_state_digest=revocation_state_digest,
            security_state_digest=grant.security_state_digest,
            frame_admission_heads=canonical_frame_heads,
            prior_head_digest=None,
            head_digest="",
            authority_receipt=_pending_authority(42_200 + index),
        ),
        digest_field="head_digest",
        domain="observer-admission-state-head",
        issuer=INGRESS_AUTHORITY,
        subject=grant.receiver_principal,
        clock_domain="receiver-monotonic",
        clock_incarnation=grant_context.install.receiver_clock_incarnation,
        event_time=event_time,
    )
    commit = _seal_composite_record(
        ObserverAdmissionStateCommitReceipt(
            commit_id=_u_for(
                ("observer-admission-lifecycle-genesis-commit", admission_lineage)
            ),
            transition_kind="OBSERVER_ADMISSION_GENESIS_FROM_GRANT",
            admission_lineage_incarnation=admission_lineage,
            prior_head_digest=genesis_anchor,
            installed_head_digest=head.head_digest,
            installed_selector_version=1,
            subordinate_state_incarnation=None,
            prior_subordinate_state_version=None,
            installed_subordinate_state_version=None,
            commit_digest="",
            authority_receipt=_pending_authority(42_300 + index),
        ),
        digest_field="commit_digest",
        domain="observer-admission-state-commit",
        issuer=INGRESS_AUTHORITY,
        subject=grant.receiver_principal,
        clock_domain="receiver-monotonic",
        clock_incarnation=head.observer_clock_incarnation,
        event_time=event_time,
    )
    installed = _seal_composite_record(
        InstalledObserverAdmissionStateSelector(
            selector_id=_u_for(
                ("observer-admission-lifecycle-selector", admission_lineage, 1)
            ),
            admission_lineage_incarnation=admission_lineage,
            selector_version=1,
            state="INSTALLED",
            ever_used=True,
            current_head_digest=head.head_digest,
            prior_selector_digest=uninitialized.selector_digest,
            last_commit_digest=commit.commit_digest,
            selector_digest="",
            authority_receipt=_pending_authority(42_400 + index),
        ),
        digest_field="selector_digest",
        domain="installed-observer-admission-state-selector",
        issuer=INGRESS_AUTHORITY,
        subject=grant.receiver_principal,
        clock_domain="receiver-monotonic",
        clock_incarnation=head.observer_clock_incarnation,
        event_time=event_time,
    )
    return ObserverAdmissionLifecycleGenesisEvidence(
        uninitialized,
        head,
        commit,
        installed,
    )


def _build_observer_admission_state_transition(
    prior_head: ObserverAdmissionStateHead,
    prior_selector: InstalledObserverAdmissionStateSelector,
    *,
    transition_kind: str,
    changed_stream_declaration_digest: str,
    operation_evidence_digest: str,
    subordinate_state_incarnation: str | None = None,
    prior_subordinate_state_version: int | None = None,
    installed_subordinate_state_version: int | None = None,
    event_time: int,
) -> ObserverAdmissionStateTransitionEvidence:
    schema = _observer_admission_transition_schema(transition_kind)
    subordinate_values = (
        subordinate_state_incarnation,
        prior_subordinate_state_version,
        installed_subordinate_state_version,
    )
    _require(
        (schema == "NO_SUBORDINATE_STATE" and subordinate_values == (None, None, None))
        or (
            schema == "STRICT_SUBORDINATE_SUCCESSOR"
            and subordinate_state_incarnation is not None
            and prior_subordinate_state_version is not None
            and installed_subordinate_state_version is not None
        ),
        "observer admission transition does not match its closed schema",
        CaptureError,
    )
    _require(
        prior_selector.state == "INSTALLED"
        and prior_selector.ever_used
        and prior_selector.current_head_digest == prior_head.head_digest
        and prior_selector.admission_lineage_incarnation
        == prior_head.admission_lineage_incarnation,
        "observer admission transition did not start from its sole installed selector",
        CaptureError,
    )
    prior_map = dict(prior_head.frame_admission_heads)
    _require(
        changed_stream_declaration_digest in prior_map
        and HEX64.fullmatch(operation_evidence_digest) is not None,
        "observer admission transition names an absent sibling or malformed fact",
        CaptureError,
    )
    installed_map = dict(prior_map)
    installed_map[changed_stream_declaration_digest] = operation_evidence_digest
    installed_head = _seal_composite_record(
        replace(
            prior_head,
            head_id=_u_for(
                (
                    "observer-admission-transition-head",
                    prior_head.head_digest,
                    transition_kind,
                    operation_evidence_digest,
                )
            ),
            state_version=prior_head.state_version + 1,
            installed_at=event_time,
            frame_admission_heads=tuple(sorted(installed_map.items())),
            prior_head_digest=prior_head.head_digest,
            head_digest="",
            authority_receipt=_pending_authority(42_500 + prior_head.state_version),
        ),
        digest_field="head_digest",
        domain="observer-admission-state-head",
        issuer=INGRESS_AUTHORITY,
        subject=prior_head.observer_principal,
        clock_domain="receiver-monotonic",
        clock_incarnation=prior_head.observer_clock_incarnation,
        event_time=event_time,
    )
    commit = _seal_composite_record(
        ObserverAdmissionStateCommitReceipt(
            commit_id=_u_for(
                (
                    "observer-admission-transition-commit",
                    prior_head.head_digest,
                    transition_kind,
                    operation_evidence_digest,
                )
            ),
            transition_kind=transition_kind,
            admission_lineage_incarnation=(prior_head.admission_lineage_incarnation),
            prior_head_digest=prior_head.head_digest,
            installed_head_digest=installed_head.head_digest,
            installed_selector_version=prior_selector.selector_version + 1,
            subordinate_state_incarnation=subordinate_state_incarnation,
            prior_subordinate_state_version=prior_subordinate_state_version,
            installed_subordinate_state_version=(installed_subordinate_state_version),
            commit_digest="",
            authority_receipt=_pending_authority(42_600 + prior_head.state_version),
        ),
        digest_field="commit_digest",
        domain="observer-admission-state-commit",
        issuer=INGRESS_AUTHORITY,
        subject=prior_head.observer_principal,
        clock_domain="receiver-monotonic",
        clock_incarnation=prior_head.observer_clock_incarnation,
        event_time=event_time,
    )
    installed_selector = _seal_composite_record(
        replace(
            prior_selector,
            selector_id=_u_for(
                (
                    "observer-admission-transition-selector",
                    prior_selector.selector_digest,
                    transition_kind,
                )
            ),
            selector_version=prior_selector.selector_version + 1,
            current_head_digest=installed_head.head_digest,
            prior_selector_digest=prior_selector.selector_digest,
            last_commit_digest=commit.commit_digest,
            selector_digest="",
            authority_receipt=_pending_authority(42_700 + prior_head.state_version),
        ),
        digest_field="selector_digest",
        domain="installed-observer-admission-state-selector",
        issuer=INGRESS_AUTHORITY,
        subject=prior_head.observer_principal,
        clock_domain="receiver-monotonic",
        clock_incarnation=prior_head.observer_clock_incarnation,
        event_time=event_time,
    )
    return ObserverAdmissionStateTransitionEvidence(
        transition_kind,
        operation_evidence_digest,
        changed_stream_declaration_digest,
        prior_head,
        prior_selector,
        installed_head,
        commit,
        installed_selector,
    )


def _validate_observer_admission_state_transition(
    evidence: ObserverAdmissionStateTransitionEvidence,
) -> None:
    prior_head = evidence.prior_head
    prior_selector = evidence.prior_selector
    installed_head = evidence.installed_head
    commit = evidence.commit
    installed_selector = evidence.installed_selector
    before = dict(prior_head.frame_admission_heads)
    after = dict(installed_head.frame_admission_heads)
    changed = evidence.changed_stream_declaration_digest
    subordinate_versions_absent = (
        commit.subordinate_state_incarnation is None
        and commit.prior_subordinate_state_version is None
        and commit.installed_subordinate_state_version is None
    )
    subordinate_versions_strict = (
        commit.subordinate_state_incarnation is not None
        and _is_uuid4(commit.subordinate_state_incarnation)
        and commit.prior_subordinate_state_version is not None
        and _safe_int(commit.prior_subordinate_state_version)
        and commit.prior_subordinate_state_version >= 0
        and commit.installed_subordinate_state_version is not None
        and _safe_int(commit.installed_subordinate_state_version)
        and commit.installed_subordinate_state_version
        == commit.prior_subordinate_state_version + 1
    )
    transition_schema = _observer_admission_transition_schema(evidence.transition_kind)
    history_transition = transition_schema == "STRICT_SUBORDINATE_SUCCESSOR"
    _require(
        prior_selector.state == "INSTALLED"
        and prior_selector.ever_used
        and prior_selector.current_head_digest == prior_head.head_digest
        and before.get(changed) != evidence.operation_evidence_digest
        and after.get(changed) == evidence.operation_evidence_digest
        and set(before) == set(after)
        and all(key == changed or after[key] == value for key, value in before.items())
        and installed_head.state_version == prior_head.state_version + 1
        and installed_head.prior_head_digest == prior_head.head_digest
        and installed_head.head_digest
        == _observer_admission_state_head_digest(installed_head)
        and commit.transition_kind == evidence.transition_kind
        and commit.admission_lineage_incarnation
        == prior_head.admission_lineage_incarnation
        and commit.prior_head_digest == prior_head.head_digest
        and commit.installed_head_digest == installed_head.head_digest
        and commit.installed_selector_version == prior_selector.selector_version + 1
        and (
            history_transition
            and subordinate_versions_strict
            or not history_transition
            and subordinate_versions_absent
        )
        and commit.commit_digest == _observer_admission_commit_digest(commit)
        and installed_selector.admission_lineage_incarnation
        == prior_selector.admission_lineage_incarnation
        and installed_selector.selector_version == prior_selector.selector_version + 1
        and installed_selector.state == "INSTALLED"
        and installed_selector.ever_used
        and installed_selector.current_head_digest == installed_head.head_digest
        and installed_selector.prior_selector_digest == prior_selector.selector_digest
        and installed_selector.last_commit_digest == commit.commit_digest
        and installed_selector.selector_digest
        == _observer_admission_selector_digest(installed_selector),
        "observer admission transition forked its sole selector or changed a sibling",
        CaptureError,
    )
    for value, field, domain in (
        (installed_head, "head_digest", "observer-admission-state-head"),
        (commit, "commit_digest", "observer-admission-state-commit"),
        (
            installed_selector,
            "selector_digest",
            "installed-observer-admission-state-selector",
        ),
    ):
        _validate_authority(
            value.authority_receipt,
            domain=domain,
            subject_digest=_capture_artifact_field_value(value, field),
            issuer=INGRESS_AUTHORITY,
            subject=prior_head.observer_principal,
        )


@dataclass(frozen=True, slots=True)
class RetirementAnchor:
    anchor_id: str
    key: AdmissionLineageKey
    history_incarnation: str
    installed_live_head_digest: str
    installed_live_frame_selector_version: int
    installed_live_head_commit_digest: str
    expected_prior_observer_head_digest: str
    expected_prior_observer_selector_digest: str
    expected_prior_observer_selector_version: int
    retired_at: int
    anchor_digest: str


def _retirement_anchor_digest(anchor: RetirementAnchor) -> str:
    return _body_digest(anchor, "anchor_digest")


@dataclass(frozen=True, slots=True)
class RetirementFreezeReceipt:
    receipt_id: str
    operation: str
    retirement_anchor_digest: str
    installed_live_head_digest: str
    installed_live_frame_selector_version: int
    installed_live_head_commit_digest: str
    prior_observer_head_digest: str
    prior_observer_selector_digest: str
    prior_observer_selector_version: int
    installed_observer_head_digest: str
    installed_observer_selector_digest: str
    installed_observer_selector_version: int
    observer_state_commit_digest: str
    freeze_digest: str
    authority_receipt: AuthorityReceipt


def _retirement_freeze_digest(receipt: RetirementFreezeReceipt) -> str:
    return _body_digest(receipt, "freeze_digest", "authority_receipt")


@dataclass(frozen=True, slots=True)
class RetirementEvidence:
    anchor: RetirementAnchor
    observer_transition: ObserverAdmissionStateTransitionEvidence
    freeze_receipt: RetirementFreezeReceipt


def _retire_live_head(
    head: LiveAdmissionHead,
    prior_observer_head: ObserverAdmissionStateHead,
    prior_observer_selector: InstalledObserverAdmissionStateSelector,
    *,
    retired_at: int,
    index: int,
) -> RetirementEvidence:
    _require(
        head.state_version > 0
        and bool(head.admitted_positions)
        and head.last_commit is not None,
        "retirement cannot invent an uninstalled former live state",
        CaptureError,
    )
    if head.last_commit is None:
        raise CaptureError("validated live head commit is absent")
    _validate_frame_head_commit(
        head.last_commit,
        key=head.key,
        operation="live_update",
        prior_head_digest=head.prior_head_digest or "",
        installed_head_digest=head.head_digest,
        selector_version=head.state_version,
        operation_evidence_digest=(
            head.admitted_positions[-1].admission_receipt_digest
        ),
    )
    prior_map = dict(prior_observer_head.frame_admission_heads)
    anchor = RetirementAnchor(
        anchor_id=_u(42_000 + index),
        key=head.key,
        history_incarnation=_u_for(
            (
                "historical-admission-incarnation",
                head.key,
                head.head_digest,
                prior_observer_selector.selector_digest,
            )
        ),
        installed_live_head_digest=head.head_digest,
        installed_live_frame_selector_version=head.state_version,
        installed_live_head_commit_digest=head.last_commit.commit_digest,
        expected_prior_observer_head_digest=prior_observer_head.head_digest,
        expected_prior_observer_selector_digest=(
            prior_observer_selector.selector_digest
        ),
        expected_prior_observer_selector_version=(
            prior_observer_selector.selector_version
        ),
        retired_at=retired_at,
        anchor_digest="",
    )
    anchor = replace(anchor, anchor_digest=_retirement_anchor_digest(anchor))
    _require(
        prior_map.get(head.key.stream_declaration_digest) == head.head_digest,
        "retirement anchor does not start from the observer-selected live head",
        CaptureError,
    )
    transition = _build_observer_admission_state_transition(
        prior_observer_head,
        prior_observer_selector,
        transition_kind="RETIREMENT_FREEZE_COMPARE_AND_SWAP",
        changed_stream_declaration_digest=head.key.stream_declaration_digest,
        operation_evidence_digest=anchor.anchor_digest,
        event_time=retired_at,
    )
    freeze = RetirementFreezeReceipt(
        receipt_id=_u(43_000 + index),
        operation="RETIREMENT_FREEZE",
        retirement_anchor_digest=anchor.anchor_digest,
        installed_live_head_digest=head.head_digest,
        installed_live_frame_selector_version=head.state_version,
        installed_live_head_commit_digest=head.last_commit.commit_digest,
        prior_observer_head_digest=prior_observer_head.head_digest,
        prior_observer_selector_digest=prior_observer_selector.selector_digest,
        prior_observer_selector_version=prior_observer_selector.selector_version,
        installed_observer_head_digest=transition.installed_head.head_digest,
        installed_observer_selector_digest=(
            transition.installed_selector.selector_digest
        ),
        installed_observer_selector_version=(
            transition.installed_selector.selector_version
        ),
        observer_state_commit_digest=transition.commit.commit_digest,
        freeze_digest="",
        authority_receipt=_pending_authority(43_000 + index),
    )
    freeze = replace(
        freeze,
        freeze_digest=_retirement_freeze_digest(freeze),
    )
    freeze = replace(
        freeze,
        authority_receipt=_seal_authority(
            receipt_id=freeze.authority_receipt.receipt_id,
            domain="retirement-freeze",
            subject_digest=freeze.freeze_digest,
            issuer=INGRESS_AUTHORITY,
            subject=head.key.receiver_principal,
            clock_domain="receiver-monotonic",
            clock_incarnation=prior_observer_head.observer_clock_incarnation,
            event_time=retired_at,
        ),
    )
    return RetirementEvidence(anchor, transition, freeze)


@dataclass(frozen=True, slots=True)
class HistoricalAdmissionHead:
    key: AdmissionLineageKey
    ledger_incarnation: str
    history_incarnation: str
    history_state_version: int
    retirement_anchor_digest: str
    authorized_horizon: tuple[int, int]
    live_positions: tuple[int, ...]
    preserved_live_gap_ranges: tuple[tuple[int, int], ...]
    historical_positions: tuple[AdmissionPositionEvidence, ...]
    capacity_limit: int
    horizon_open: bool
    prior_head_digest: str
    head_digest: str


def _history_head_digest(head: HistoricalAdmissionHead) -> str:
    return _body_digest(head, "head_digest")


def _validate_retirement_evidence(
    evidence: RetirementEvidence,
    *,
    frozen_live_head: LiveAdmissionHead,
) -> None:
    anchor = evidence.anchor
    transition = evidence.observer_transition
    freeze = evidence.freeze_receipt
    _require(
        frozen_live_head.last_commit is not None,
        "retirement evidence lacks the already-installed live commit",
        CaptureError,
    )
    if frozen_live_head.last_commit is None:
        raise CaptureError("validated live retirement commit is absent")
    _validate_frame_head_commit(
        frozen_live_head.last_commit,
        key=frozen_live_head.key,
        operation="live_update",
        prior_head_digest=frozen_live_head.prior_head_digest or "",
        installed_head_digest=frozen_live_head.head_digest,
        selector_version=frozen_live_head.state_version,
        operation_evidence_digest=(
            frozen_live_head.admitted_positions[-1].admission_receipt_digest
        ),
    )
    _validate_observer_admission_state_transition(transition)
    _require(
        anchor.key == frozen_live_head.key
        and _is_uuid4(anchor.history_incarnation)
        and anchor.history_incarnation != frozen_live_head.ledger_incarnation
        and anchor.history_incarnation != anchor.key.evidence_lineage_incarnation
        and anchor.installed_live_head_digest == frozen_live_head.head_digest
        and anchor.installed_live_frame_selector_version
        == frozen_live_head.state_version
        and anchor.installed_live_head_commit_digest
        == frozen_live_head.last_commit.commit_digest
        and anchor.expected_prior_observer_head_digest
        == transition.prior_head.head_digest
        and anchor.expected_prior_observer_selector_digest
        == transition.prior_selector.selector_digest
        and anchor.expected_prior_observer_selector_version
        == transition.prior_selector.selector_version
        and anchor.anchor_digest == _retirement_anchor_digest(anchor)
        and not {
            "authority_receipt",
            "freeze_digest",
            "observer_state_commit_digest",
            "installed_observer_head_digest",
        }.intersection(_body(anchor))
        and transition.transition_kind == "RETIREMENT_FREEZE_COMPARE_AND_SWAP"
        and transition.operation_evidence_digest == anchor.anchor_digest
        and transition.changed_stream_declaration_digest
        == anchor.key.stream_declaration_digest
        and freeze.operation == "RETIREMENT_FREEZE"
        and freeze.retirement_anchor_digest == anchor.anchor_digest
        and freeze.installed_live_head_digest == frozen_live_head.head_digest
        and freeze.installed_live_frame_selector_version
        == frozen_live_head.state_version
        and freeze.installed_live_head_commit_digest
        == frozen_live_head.last_commit.commit_digest
        and freeze.prior_observer_head_digest == transition.prior_head.head_digest
        and freeze.prior_observer_selector_digest
        == transition.prior_selector.selector_digest
        and freeze.prior_observer_selector_version
        == transition.prior_selector.selector_version
        and freeze.installed_observer_head_digest
        == transition.installed_head.head_digest
        and freeze.installed_observer_selector_digest
        == transition.installed_selector.selector_digest
        and freeze.installed_observer_selector_version
        == transition.installed_selector.selector_version
        and freeze.observer_state_commit_digest == transition.commit.commit_digest
        and freeze.freeze_digest == _retirement_freeze_digest(freeze),
        "retirement freeze is cyclic, stale, or not the exact post-CAS result",
        CaptureError,
    )
    _validate_authority(
        freeze.authority_receipt,
        domain="retirement-freeze",
        subject_digest=freeze.freeze_digest,
        issuer=INGRESS_AUTHORITY,
        subject=anchor.key.receiver_principal,
    )


@dataclass(frozen=True, slots=True)
class HistoricalAdmissionHeadInstallationEvidence:
    head: HistoricalAdmissionHead
    observer_transition: ObserverAdmissionStateTransitionEvidence


def _open_history_head(
    retirement: RetirementEvidence,
    frozen_live_head: LiveAdmissionHead,
    *,
    authorized_horizon: tuple[int, int],
    capacity_limit: int = MAX_ADMISSION_POSITIONS,
) -> HistoricalAdmissionHeadInstallationEvidence:
    _validate_retirement_evidence(retirement, frozen_live_head=frozen_live_head)
    anchor = retirement.anchor
    _require(
        authorized_horizon[0] <= authorized_horizon[1] and capacity_limit > 0,
        "history horizon or capacity is invalid",
        CaptureError,
    )
    head = HistoricalAdmissionHead(
        key=anchor.key,
        ledger_incarnation=frozen_live_head.ledger_incarnation,
        history_incarnation=anchor.history_incarnation,
        history_state_version=1,
        retirement_anchor_digest=anchor.anchor_digest,
        authorized_horizon=authorized_horizon,
        live_positions=tuple(
            evidence.source_position for evidence in frozen_live_head.admitted_positions
        ),
        preserved_live_gap_ranges=frozen_live_head.finalized_gap_ranges,
        historical_positions=(),
        capacity_limit=capacity_limit,
        horizon_open=True,
        prior_head_digest=anchor.anchor_digest,
        head_digest="",
    )
    head = replace(head, head_digest=_history_head_digest(head))
    transition = _build_observer_admission_state_transition(
        retirement.observer_transition.installed_head,
        retirement.observer_transition.installed_selector,
        transition_kind="HISTORY_GENESIS_COMPARE_AND_SWAP",
        changed_stream_declaration_digest=anchor.key.stream_declaration_digest,
        operation_evidence_digest=head.head_digest,
        subordinate_state_incarnation=head.history_incarnation,
        prior_subordinate_state_version=0,
        installed_subordinate_state_version=head.history_state_version,
        event_time=anchor.retired_at + 1,
    )
    return HistoricalAdmissionHeadInstallationEvidence(head, transition)


@dataclass(frozen=True, slots=True)
class HistoricalAdmissionUpdateEvidence:
    head: HistoricalAdmissionHead
    observer_transition: ObserverAdmissionStateTransitionEvidence
    admission_receipt: ReceiverAdmissionReceipt


def _admit_history(
    installed_history: HistoricalAdmissionHeadInstallationEvidence,
    *,
    frame: ProducerFrame,
    provenance: ProviderHistoryProvenance,
    expected_projection_chain_digest: str,
    receiver_clock_incarnation: str,
    admitted_at: int,
    store: ContentStore,
    index: int,
) -> HistoricalAdmissionUpdateEvidence:
    head = installed_history.head
    _validate_observer_admission_state_transition(installed_history.observer_transition)
    _require(
        installed_history.observer_transition.operation_evidence_digest
        == head.head_digest,
        "history genesis is not installed by the observer selector",
        CaptureError,
    )
    _validate_provider_history(
        provenance,
        frame=frame,
        expected_projection_chain_digest=expected_projection_chain_digest,
        store=store,
    )
    existing = {
        *head.live_positions,
        *(evidence.source_position for evidence in head.historical_positions),
    }
    _require(
        head.horizon_open
        and head.authorized_horizon[0]
        <= frame.stream_position
        <= head.authorized_horizon[1]
        and frame.stream_position not in existing
        and len(head.historical_positions) < head.capacity_limit,
        "history admission is duplicate, outside horizon, closed, or at capacity",
        CaptureError,
    )
    next_version = head.history_state_version + 1
    event_digest = _digest(
        {
            "key": head.key,
            "phase": "history",
            "frame_digest": frame.frame_digest,
            "source_position": frame.stream_position,
            "state_version": next_version,
            "prior_head_digest": head.head_digest,
            "provider_history_provenance_digest": provenance.provenance_digest,
        }
    )
    evidence = AdmissionPositionEvidence(
        frame.stream_position,
        frame.frame_digest,
        event_digest,
    )
    next_head = replace(
        head,
        history_state_version=next_version,
        historical_positions=(*head.historical_positions, evidence),
        prior_head_digest=head.head_digest,
        head_digest="",
    )
    next_head = replace(next_head, head_digest=_history_head_digest(next_head))
    transition = _build_observer_admission_state_transition(
        installed_history.observer_transition.installed_head,
        installed_history.observer_transition.installed_selector,
        transition_kind="HISTORY_UPDATE_COMPARE_AND_SWAP",
        changed_stream_declaration_digest=head.key.stream_declaration_digest,
        operation_evidence_digest=next_head.head_digest,
        subordinate_state_incarnation=head.history_incarnation,
        prior_subordinate_state_version=head.history_state_version,
        installed_subordinate_state_version=next_head.history_state_version,
        event_time=admitted_at,
    )
    receipt = ReceiverAdmissionReceipt(
        _u(44_000 + index),
        head.key,
        "history",
        frame.frame_digest,
        frame.stream_position,
        next_version,
        head.head_digest,
        next_head.head_digest,
        receiver_clock_incarnation,
        admitted_at,
        provenance.provenance_digest,
        transition.commit.commit_digest,
        "",
        _seal_authority(
            receipt_id=_u(45_000 + index),
            domain="receiver-history-admission",
            subject_digest="0" * 64,
            issuer=INGRESS_AUTHORITY,
            subject=head.key.receiver_principal,
            clock_domain="receiver-monotonic",
            clock_incarnation=receiver_clock_incarnation,
            event_time=admitted_at,
        ),
    )
    receipt = replace(receipt, receipt_digest=_admission_receipt_digest(receipt))
    receipt = replace(
        receipt,
        authority_receipt=_seal_authority(
            receipt_id=receipt.authority_receipt.receipt_id,
            domain="receiver-history-admission",
            subject_digest=receipt.receipt_digest,
            issuer=INGRESS_AUTHORITY,
            subject=head.key.receiver_principal,
            clock_domain="receiver-monotonic",
            clock_incarnation=receiver_clock_incarnation,
            event_time=admitted_at,
        ),
    )
    return HistoricalAdmissionUpdateEvidence(next_head, transition, receipt)


@dataclass(frozen=True, slots=True)
class FrameAdmissionTerminalCheckpoint:
    checkpoint_id: str
    operation: str
    key: AdmissionLineageKey
    retirement_anchor_digest: str
    history_incarnation: str
    prior_history_state_version: int
    terminal_history_state_version: int
    prior_evidence_digest: str
    prior_installed_receipt_digest: str
    expected_prior_observer_head_digest: str
    expected_prior_observer_selector_digest: str
    expected_prior_observer_selector_version: int
    declaration_tombstone_digest: str
    closed_horizon: tuple[int, int]
    retention_state: str
    closed_at: int
    checkpoint_digest: str


def _terminal_checkpoint_digest(
    checkpoint: FrameAdmissionTerminalCheckpoint,
) -> str:
    return _body_digest(checkpoint, "checkpoint_digest")


TerminalAdmissionCheckpoint = FrameAdmissionTerminalCheckpoint


@dataclass(frozen=True, slots=True)
class FrameAdmissionTerminalizationReceipt:
    receipt_id: str
    operation: str
    checkpoint_digest: str
    history_incarnation: str
    prior_history_state_version: int
    installed_history_state_version: int
    prior_evidence_digest: str
    prior_installed_receipt_digest: str
    prior_observer_head_digest: str
    prior_observer_selector_digest: str
    prior_observer_selector_version: int
    installed_observer_head_digest: str
    installed_observer_selector_digest: str
    installed_observer_selector_version: int
    observer_state_commit_digest: str
    receipt_digest: str
    authority_receipt: AuthorityReceipt


def _frame_terminalization_receipt_digest(
    receipt: FrameAdmissionTerminalizationReceipt,
) -> str:
    return _body_digest(receipt, "receipt_digest", "authority_receipt")


@dataclass(frozen=True, slots=True)
class FrameAdmissionTerminalizationEvidence:
    checkpoint: FrameAdmissionTerminalCheckpoint
    observer_transition: ObserverAdmissionStateTransitionEvidence
    receipt: FrameAdmissionTerminalizationReceipt


def _terminalize_frame_admission(
    *,
    anchor: RetirementAnchor,
    prior_observer_head: ObserverAdmissionStateHead,
    prior_observer_selector: InstalledObserverAdmissionStateSelector,
    history_incarnation: str,
    prior_history_state_version: int,
    prior_evidence_digest: str,
    prior_installed_receipt_digest: str,
    operation: str,
    closed_horizon: tuple[int, int],
    closed_at: int,
    index: int,
) -> FrameAdmissionTerminalizationEvidence:
    _require(
        operation
        in {
            "TERMINALIZE_FROM_HISTORY_HEAD",
            "TERMINALIZE_FROM_RETIREMENT_ANCHOR",
        }
        and dict(prior_observer_head.frame_admission_heads).get(
            anchor.key.stream_declaration_digest
        )
        == prior_evidence_digest,
        "terminalization did not start from the observer-selected prior evidence",
        CaptureError,
    )
    _require(
        history_incarnation == anchor.history_incarnation
        and _is_uuid4(history_incarnation)
        and _safe_int(prior_history_state_version)
        and prior_history_state_version >= 0,
        "terminalization did not start from the observer-selected prior evidence",
        CaptureError,
    )
    terminal_history_state_version = prior_history_state_version + 1
    checkpoint = FrameAdmissionTerminalCheckpoint(
        checkpoint_id=_u(46_000 + index),
        operation=operation,
        key=anchor.key,
        retirement_anchor_digest=anchor.anchor_digest,
        history_incarnation=history_incarnation,
        prior_history_state_version=prior_history_state_version,
        terminal_history_state_version=terminal_history_state_version,
        prior_evidence_digest=prior_evidence_digest,
        prior_installed_receipt_digest=prior_installed_receipt_digest,
        expected_prior_observer_head_digest=prior_observer_head.head_digest,
        expected_prior_observer_selector_digest=(
            prior_observer_selector.selector_digest
        ),
        expected_prior_observer_selector_version=(
            prior_observer_selector.selector_version
        ),
        declaration_tombstone_digest=_digest(
            {
                "declaration": anchor.key.stream_declaration_digest,
                "epoch": anchor.key.stream_epoch,
                "state": "retired",
            }
        ),
        closed_horizon=closed_horizon,
        retention_state="retained",
        closed_at=closed_at,
        checkpoint_digest="",
    )
    checkpoint = replace(
        checkpoint,
        checkpoint_digest=_terminal_checkpoint_digest(checkpoint),
    )
    transition = _build_observer_admission_state_transition(
        prior_observer_head,
        prior_observer_selector,
        transition_kind=operation,
        changed_stream_declaration_digest=anchor.key.stream_declaration_digest,
        operation_evidence_digest=checkpoint.checkpoint_digest,
        subordinate_state_incarnation=history_incarnation,
        prior_subordinate_state_version=prior_history_state_version,
        installed_subordinate_state_version=terminal_history_state_version,
        event_time=closed_at,
    )
    receipt = FrameAdmissionTerminalizationReceipt(
        receipt_id=_u(47_000 + index),
        operation=operation,
        checkpoint_digest=checkpoint.checkpoint_digest,
        history_incarnation=history_incarnation,
        prior_history_state_version=prior_history_state_version,
        installed_history_state_version=terminal_history_state_version,
        prior_evidence_digest=prior_evidence_digest,
        prior_installed_receipt_digest=prior_installed_receipt_digest,
        prior_observer_head_digest=prior_observer_head.head_digest,
        prior_observer_selector_digest=prior_observer_selector.selector_digest,
        prior_observer_selector_version=prior_observer_selector.selector_version,
        installed_observer_head_digest=transition.installed_head.head_digest,
        installed_observer_selector_digest=(
            transition.installed_selector.selector_digest
        ),
        installed_observer_selector_version=(
            transition.installed_selector.selector_version
        ),
        observer_state_commit_digest=transition.commit.commit_digest,
        receipt_digest="",
        authority_receipt=_pending_authority(47_000 + index),
    )
    receipt = replace(
        receipt,
        receipt_digest=_frame_terminalization_receipt_digest(receipt),
    )
    receipt = replace(
        receipt,
        authority_receipt=_seal_authority(
            receipt_id=receipt.authority_receipt.receipt_id,
            domain="frame-admission-terminalization",
            subject_digest=receipt.receipt_digest,
            issuer=INGRESS_AUTHORITY,
            subject=anchor.key.receiver_principal,
            clock_domain="receiver-monotonic",
            clock_incarnation=prior_observer_head.observer_clock_incarnation,
            event_time=closed_at,
        ),
    )
    return FrameAdmissionTerminalizationEvidence(
        checkpoint,
        transition,
        receipt,
    )


def _validate_frame_terminalization_evidence(
    evidence: FrameAdmissionTerminalizationEvidence,
    *,
    anchor: RetirementAnchor,
    expected_prior_evidence_digest: str,
    expected_prior_receipt_digest: str,
) -> None:
    checkpoint = evidence.checkpoint
    transition = evidence.observer_transition
    receipt = evidence.receipt
    _validate_observer_admission_state_transition(transition)
    _require(
        checkpoint.operation
        in {
            "TERMINALIZE_FROM_HISTORY_HEAD",
            "TERMINALIZE_FROM_RETIREMENT_ANCHOR",
        }
        and checkpoint.key == anchor.key
        and checkpoint.retirement_anchor_digest == anchor.anchor_digest
        and checkpoint.history_incarnation == anchor.history_incarnation
        and checkpoint.prior_history_state_version >= 0
        and checkpoint.terminal_history_state_version
        == checkpoint.prior_history_state_version + 1
        and checkpoint.prior_evidence_digest == expected_prior_evidence_digest
        and checkpoint.prior_installed_receipt_digest == expected_prior_receipt_digest
        and checkpoint.expected_prior_observer_head_digest
        == transition.prior_head.head_digest
        and checkpoint.expected_prior_observer_selector_digest
        == transition.prior_selector.selector_digest
        and checkpoint.expected_prior_observer_selector_version
        == transition.prior_selector.selector_version
        and checkpoint.checkpoint_digest == _terminal_checkpoint_digest(checkpoint)
        and not {
            "authority_receipt",
            "receipt_digest",
            "observer_state_commit_digest",
            "installed_observer_head_digest",
        }.intersection(_body(checkpoint))
        and transition.transition_kind == checkpoint.operation
        and transition.operation_evidence_digest == checkpoint.checkpoint_digest
        and transition.commit.subordinate_state_incarnation
        == checkpoint.history_incarnation
        and transition.commit.prior_subordinate_state_version
        == checkpoint.prior_history_state_version
        and transition.commit.installed_subordinate_state_version
        == checkpoint.terminal_history_state_version
        and transition.changed_stream_declaration_digest
        == checkpoint.key.stream_declaration_digest
        and receipt.operation == checkpoint.operation
        and receipt.checkpoint_digest == checkpoint.checkpoint_digest
        and receipt.history_incarnation == checkpoint.history_incarnation
        and receipt.prior_history_state_version
        == checkpoint.prior_history_state_version
        and receipt.installed_history_state_version
        == checkpoint.terminal_history_state_version
        and receipt.prior_evidence_digest == expected_prior_evidence_digest
        and receipt.prior_installed_receipt_digest == expected_prior_receipt_digest
        and receipt.prior_observer_head_digest == transition.prior_head.head_digest
        and receipt.prior_observer_selector_digest
        == transition.prior_selector.selector_digest
        and receipt.prior_observer_selector_version
        == transition.prior_selector.selector_version
        and receipt.installed_observer_head_digest
        == transition.installed_head.head_digest
        and receipt.installed_observer_selector_digest
        == transition.installed_selector.selector_digest
        and receipt.installed_observer_selector_version
        == transition.installed_selector.selector_version
        and receipt.observer_state_commit_digest == transition.commit.commit_digest
        and receipt.receipt_digest == _frame_terminalization_receipt_digest(receipt),
        "frame terminalization is cyclic, stale, or not the exact observer CAS",
        CaptureError,
    )
    _validate_authority(
        receipt.authority_receipt,
        domain="frame-admission-terminalization",
        subject_digest=receipt.receipt_digest,
        issuer=INGRESS_AUTHORITY,
        subject=checkpoint.key.receiver_principal,
    )


def _close_history(
    update: HistoricalAdmissionUpdateEvidence,
    *,
    anchor: RetirementAnchor,
    closed_at: int,
    index: int,
) -> FrameAdmissionTerminalizationEvidence:
    head = update.head
    _require(
        head.horizon_open
        and head.retirement_anchor_digest == anchor.anchor_digest
        and head.key == anchor.key,
        "terminal checkpoint does not close the installed history lineage",
        CaptureError,
    )
    _validate_observer_admission_state_transition(update.observer_transition)
    _require(
        update.observer_transition.operation_evidence_digest == head.head_digest
        and update.admission_receipt.installed_head_digest == head.head_digest
        and update.admission_receipt.head_commit_digest
        == update.observer_transition.commit.commit_digest,
        "history closure lacks its installed observer selector predecessor",
        CaptureError,
    )
    return _terminalize_frame_admission(
        anchor=anchor,
        prior_observer_head=update.observer_transition.installed_head,
        prior_observer_selector=update.observer_transition.installed_selector,
        history_incarnation=head.history_incarnation,
        prior_history_state_version=head.history_state_version,
        prior_evidence_digest=head.head_digest,
        prior_installed_receipt_digest=update.admission_receipt.receipt_digest,
        operation="TERMINALIZE_FROM_HISTORY_HEAD",
        closed_horizon=head.authorized_horizon,
        closed_at=closed_at,
        index=index,
    )


@dataclass(frozen=True, slots=True)
class AdmissionLineageFence:
    fence_id: str
    key: AdmissionLineageKey
    terminal_checkpoint_digest: str
    reason: str
    fenced_at: int
    fence_digest: str
    authority_receipt: AuthorityReceipt


def _lineage_fence_digest(fence: AdmissionLineageFence) -> str:
    return _body_digest(fence, "fence_digest", "authority_receipt")


def _fence_lineage(
    checkpoint: TerminalAdmissionCheckpoint,
    *,
    fenced_at: int,
    index: int,
) -> AdmissionLineageFence:
    fence = AdmissionLineageFence(
        _u(48_000 + index),
        checkpoint.key,
        checkpoint.checkpoint_digest,
        "bounded-retention-capacity",
        fenced_at,
        "",
        _seal_authority(
            receipt_id=_u(49_000 + index),
            domain="admission-lineage-fence",
            subject_digest="0" * 64,
            issuer=INGRESS_AUTHORITY,
            subject=checkpoint.key.receiver_principal,
            clock_domain="receiver-monotonic",
            clock_incarnation=RECEIVER_A_CLOCK,
            event_time=fenced_at,
        ),
    )
    fence = replace(fence, fence_digest=_lineage_fence_digest(fence))
    return replace(
        fence,
        authority_receipt=_seal_authority(
            receipt_id=fence.authority_receipt.receipt_id,
            domain="admission-lineage-fence",
            subject_digest=fence.fence_digest,
            issuer=INGRESS_AUTHORITY,
            subject=checkpoint.key.receiver_principal,
            clock_domain="receiver-monotonic",
            clock_incarnation=RECEIVER_A_CLOCK,
            event_time=fenced_at,
        ),
    )


@dataclass(frozen=True, slots=True)
class LineageRegistryEntry:
    key: AdmissionLineageKey
    phase: str
    evidence_head_digest: str


@dataclass(frozen=True, slots=True)
class LineageRegistryTransition:
    operation: str
    state_version: int
    key: AdmissionLineageKey
    evidence_head_digest: str
    prior_registry_head_digest: str
    entries: tuple[LineageRegistryEntry, ...]
    installed_registry_head_digest: str


def _registry_transition_digest(
    transition: LineageRegistryTransition,
) -> str:
    return _body_digest(transition, "installed_registry_head_digest")


@dataclass(frozen=True, slots=True)
class ReceiverEvidenceLineageRegistryHead:
    registry_id: str
    receiver_principal: str
    registry_incarnation: str
    state_version: int
    transitions: tuple[LineageRegistryTransition, ...]
    current_entries: tuple[LineageRegistryEntry, ...]
    current_head_digest: str
    installed_at: int
    authority_receipt: AuthorityReceipt


def _registry_genesis(receiver: str, incarnation: str) -> str:
    return _digest(
        {
            "receiver_principal": receiver,
            "registry_incarnation": incarnation,
            "state": "empty-registry-genesis",
        }
    )


def _build_lineage_registry(
    receiver: str,
    operations: tuple[tuple[str, AdmissionLineageKey, str, str], ...],
    *,
    installed_at: int,
    index: int,
) -> ReceiverEvidenceLineageRegistryHead:
    incarnation = _u(50_000 + index)
    prior = _registry_genesis(receiver, incarnation)
    entries: dict[AdmissionLineageKey, LineageRegistryEntry] = {}
    transitions: list[LineageRegistryTransition] = []
    for version, (operation, key, phase, evidence_digest) in enumerate(
        operations,
        start=1,
    ):
        _require(key.receiver_principal == receiver, "registry mixed receivers")
        current = entries.get(key)
        if operation in {"authorize_genesis", "authorize_fresh_lineage"}:
            _require(current is None and phase == "LIVE", "lineage already exists")
        elif operation == "live_update":
            _require(current is not None and current.phase == "LIVE", "not live")
        elif operation == "retire_open_history":
            _require(
                current is not None
                and current.phase == "LIVE"
                and phase == "HISTORY_OPEN",
                "history did not CAS from live",
            )
        elif operation == "history_update":
            _require(
                current is not None
                and current.phase == "HISTORY_OPEN"
                and phase == "HISTORY_OPEN",
                "history head is not current",
            )
        elif operation == "close_horizon":
            _require(
                current is not None
                and current.phase == "HISTORY_OPEN"
                and phase == "TERMINAL",
                "terminal checkpoint preceded horizon close",
            )
        elif operation == "fence":
            _require(
                current is not None
                and current.phase == "TERMINAL"
                and phase == "FENCED",
                "fence did not follow a terminal checkpoint",
            )
        else:
            raise CaptureError("unknown lineage registry operation")
        entries[key] = LineageRegistryEntry(key, phase, evidence_digest)
        canonical_entries = tuple(sorted(entries.values(), key=lambda item: item.key))
        transition = LineageRegistryTransition(
            operation,
            version,
            key,
            evidence_digest,
            prior,
            canonical_entries,
            "",
        )
        transition = replace(
            transition,
            installed_registry_head_digest=_registry_transition_digest(transition),
        )
        transitions.append(transition)
        prior = transition.installed_registry_head_digest
    head = ReceiverEvidenceLineageRegistryHead(
        _u(51_000 + index),
        receiver,
        incarnation,
        len(transitions),
        tuple(transitions),
        tuple(sorted(entries.values(), key=lambda item: item.key)),
        prior,
        installed_at,
        _seal_authority(
            receipt_id=_u(52_000 + index),
            domain="installed-lineage-registry-head",
            subject_digest=prior,
            issuer=INGRESS_AUTHORITY,
            subject=receiver,
            clock_domain="receiver-monotonic",
            clock_incarnation=RECEIVER_A_CLOCK,
            event_time=installed_at,
        ),
    )
    return head


def _validate_lineage_registry(
    head: ReceiverEvidenceLineageRegistryHead,
) -> None:
    _require(
        _is_uuid4(head.registry_id)
        and _is_uuid4(head.registry_incarnation)
        and 1 <= len(head.transitions) <= MAX_REGISTRY_ENTRIES
        and head.state_version == len(head.transitions),
        "lineage registry is empty, malformed, or unbounded",
        CaptureError,
    )
    prior = _registry_genesis(head.receiver_principal, head.registry_incarnation)
    entries: dict[AdmissionLineageKey, LineageRegistryEntry] = {}
    expected_phase_by_operation = {
        "authorize_genesis": "LIVE",
        "authorize_fresh_lineage": "LIVE",
        "live_update": "LIVE",
        "retire_open_history": "HISTORY_OPEN",
        "history_update": "HISTORY_OPEN",
        "close_horizon": "TERMINAL",
        "fence": "FENCED",
    }
    for version, transition in enumerate(head.transitions, start=1):
        before = dict(entries)
        current = entries.get(transition.key)
        operation = transition.operation
        if operation in {"authorize_genesis", "authorize_fresh_lineage"}:
            _require(current is None, "registry replay authorized an existing key")
        elif operation == "live_update":
            _require(current is not None and current.phase == "LIVE", "not live")
        elif operation == "retire_open_history":
            _require(current is not None and current.phase == "LIVE", "not live")
        elif operation == "history_update":
            _require(
                current is not None and current.phase == "HISTORY_OPEN",
                "history not open",
            )
        elif operation == "close_horizon":
            _require(
                current is not None and current.phase == "HISTORY_OPEN",
                "history not open",
            )
        elif operation == "fence":
            _require(
                current is not None and current.phase == "TERMINAL",
                "lineage not terminal",
            )
        else:
            raise CaptureError("unknown lineage registry transition")
        changed_candidates = tuple(
            entry for entry in transition.entries if entry.key == transition.key
        )
        _require(
            len(changed_candidates) == 1
            and transition.key.receiver_principal == head.receiver_principal
            and 1 <= len(transition.entries) <= MAX_REGISTRY_ENTRIES
            and transition.entries
            == tuple(sorted(set(transition.entries), key=lambda item: item.key)),
            "lineage registry transition is duplicate, missing, or cross-receiver",
            CaptureError,
        )
        changed = changed_candidates[0]
        entries[transition.key] = changed
        expected_entries = tuple(sorted(entries.values(), key=lambda item: item.key))
        _require(
            transition.state_version == version
            and changed.phase == expected_phase_by_operation[operation]
            and HEX64.fullmatch(changed.evidence_head_digest) is not None
            and transition.prior_registry_head_digest == prior
            and transition.evidence_head_digest == changed.evidence_head_digest
            and transition.entries == expected_entries
            and all(
                before_key == transition.key or entries.get(before_key) == before_entry
                for before_key, before_entry in before.items()
            )
            and transition.installed_registry_head_digest
            == _registry_transition_digest(transition),
            "lineage registry CAS changed an unrelated entry or forked",
            CaptureError,
        )
        prior = transition.installed_registry_head_digest
    _require(
        head.current_entries
        == tuple(sorted(entries.values(), key=lambda item: item.key))
        and head.current_head_digest == prior,
        "lineage registry current selection is stale or caller-controlled",
        CaptureError,
    )
    _validate_authority(
        head.authority_receipt,
        domain="installed-lineage-registry-head",
        subject_digest=head.current_head_digest,
        issuer=INGRESS_AUTHORITY,
        subject=head.receiver_principal,
    )


def _validate_live_admission(
    receipt: ReceiverAdmissionReceipt,
    head: LiveAdmissionHead,
    registry: ReceiverEvidenceLineageRegistryHead,
    frame: ProducerFrame,
    delivery: ReceiverFrameDelivery,
) -> None:
    _validate_lineage_registry(registry)
    current = next(
        (entry for entry in registry.current_entries if entry.key == receipt.key),
        None,
    )
    evidence = next(
        (
            item
            for item in head.admitted_positions
            if item.source_position == receipt.source_position
            and item.frame_digest == receipt.frame_digest
        ),
        None,
    )
    expected_event_digest = _digest(
        {
            "key": receipt.key,
            "frame_digest": receipt.frame_digest,
            "source_position": receipt.source_position,
            "state_version": receipt.state_version,
            "prior_head_digest": receipt.prior_head_digest,
            "admission_basis_digest": receipt.admission_basis_digest,
            "delivery_digest": receipt.delivery_digest,
            "canonical_scope_digest": receipt.canonical_scope_digest,
            "boundary_scope_membership_digest": (
                receipt.boundary_scope_membership_digest
            ),
            "read_authorization_decision_digest": (
                receipt.read_authorization_decision_digest
            ),
            "release_authority_recheck_digest": (
                receipt.release_authority_recheck_digest
            ),
        }
    )
    _require(head.last_commit is not None, "live head lost its last commit")
    if head.last_commit is None:
        raise CaptureError("validated live head commit is absent")
    _validate_frame_head_commit(
        head.last_commit,
        key=head.key,
        operation="live_update",
        prior_head_digest=head.prior_head_digest or "",
        installed_head_digest=head.head_digest,
        selector_version=head.state_version,
        operation_evidence_digest=expected_event_digest,
    )
    _require(
        receipt.phase == "live"
        and (
            receipt.admission_basis_digest is None
            or HEX64.fullmatch(receipt.admission_basis_digest) is not None
        )
        and receipt.key == head.key
        and head.order_policy == "STRICT_MONOTONIC"
        and bool(head.admitted_positions)
        and head.state_version == len(head.admitted_positions)
        and head.high_water
        == max(item.source_position for item in head.admitted_positions)
        and tuple(item.source_position for item in head.admitted_positions)
        == tuple(sorted(item.source_position for item in head.admitted_positions))
        and head.head_digest == _live_head_digest(head)
        and receipt.key.receiver_principal == delivery.receiver_principal
        and receipt.delivery_digest == delivery.delivery_digest
        and receipt.canonical_scope_digest == delivery.canonical_read_scope.scope_digest
        and receipt.boundary_scope_membership_digest
        == delivery.boundary_scope_membership.membership_digest
        and receipt.read_authorization_decision_digest
        == delivery.read_authorization_decision.semantic_decision_digest
        and receipt.release_authority_recheck_digest
        == delivery.release_authority_recheck_digest
        and receipt.frame_digest == frame.frame_digest
        and receipt.source_position == frame.stream_position
        and delivery.producer_frame_digest == frame.frame_digest
        and receipt.receiver_clock_incarnation == delivery.receiver_clock_incarnation
        and receipt.admitted_at >= delivery.received_at
        and receipt.admitted_at < delivery.local_not_after
        and receipt.installed_head_digest == head.head_digest
        and receipt.prior_head_digest == head.prior_head_digest
        and receipt.state_version == head.state_version
        and receipt.head_commit_digest == head.last_commit.commit_digest
        and head.last_commit.authority_receipt.clock_domain == "receiver-monotonic"
        and head.last_commit.authority_receipt.clock_incarnation
        == receipt.receiver_clock_incarnation
        and head.last_commit.authority_receipt.event_time == receipt.admitted_at
        and evidence is not None
        and evidence.admission_receipt_digest == expected_event_digest
        and current is not None
        and current.phase == "LIVE"
        and current.evidence_head_digest == head.head_digest
        and receipt.receipt_digest == _admission_receipt_digest(receipt)
        and receipt.authority_receipt.clock_domain == "receiver-monotonic"
        and receipt.authority_receipt.clock_incarnation
        == receipt.receiver_clock_incarnation
        and receipt.authority_receipt.event_time == receipt.admitted_at,
        "live admission is not the exact installed receiver-lineage result",
        CaptureError,
    )
    _validate_authority(
        receipt.authority_receipt,
        domain="receiver-live-admission",
        subject_digest=receipt.receipt_digest,
        issuer=INGRESS_AUTHORITY,
        subject=receipt.key.receiver_principal,
    )


def _validate_history_admission(
    receipt: ReceiverAdmissionReceipt,
    *,
    head: HistoricalAdmissionHead,
    checkpoint: TerminalAdmissionCheckpoint,
    frozen_live_head: LiveAdmissionHead,
    retirement: RetirementEvidence,
    installed_history: HistoricalAdmissionHeadInstallationEvidence,
    update: HistoricalAdmissionUpdateEvidence,
    terminalization: FrameAdmissionTerminalizationEvidence,
    fence: AdmissionLineageFence | None,
    registry: ReceiverEvidenceLineageRegistryHead,
    frame: ProducerFrame,
    provenance: ProviderHistoryProvenance,
    expected_projection_chain_digest: str,
    store: ContentStore,
) -> None:
    _validate_lineage_registry(registry)
    _validate_retirement_evidence(
        retirement,
        frozen_live_head=frozen_live_head,
    )
    _validate_observer_admission_state_transition(installed_history.observer_transition)
    _validate_observer_admission_state_transition(update.observer_transition)
    _validate_observer_admission_state_transition(terminalization.observer_transition)
    _validate_frame_terminalization_evidence(
        terminalization,
        anchor=retirement.anchor,
        expected_prior_evidence_digest=head.head_digest,
        expected_prior_receipt_digest=receipt.receipt_digest,
    )
    _validate_provider_history(
        provenance,
        frame=frame,
        expected_projection_chain_digest=expected_projection_chain_digest,
        store=store,
    )
    evidence = next(
        (
            item
            for item in head.historical_positions
            if item.source_position == receipt.source_position
            and item.frame_digest == receipt.frame_digest
        ),
        None,
    )
    expected_event_digest = _digest(
        {
            "key": receipt.key,
            "phase": "history",
            "frame_digest": receipt.frame_digest,
            "source_position": receipt.source_position,
            "state_version": receipt.state_version,
            "prior_head_digest": receipt.prior_head_digest,
            "provider_history_provenance_digest": (
                receipt.provider_history_provenance_digest
            ),
        }
    )
    terminal_receipt = terminalization.receipt
    phases = tuple(
        transition.entries[
            next(
                index
                for index, entry in enumerate(transition.entries)
                if entry.key == receipt.key
            )
        ].phase
        for transition in registry.transitions
        if any(entry.key == receipt.key for entry in transition.entries)
    )
    _require(
        receipt.phase == "history"
        and receipt.key == head.key == checkpoint.key
        and update.head == head
        and update.admission_receipt == receipt
        and installed_history.head.retirement_anchor_digest
        == retirement.anchor.anchor_digest
        and installed_history.head.history_incarnation
        == retirement.anchor.history_incarnation
        and installed_history.head.history_state_version == 1
        and installed_history.head.prior_head_digest == retirement.anchor.anchor_digest
        and installed_history.observer_transition.commit.subordinate_state_incarnation
        == retirement.anchor.history_incarnation
        and installed_history.observer_transition.commit.prior_subordinate_state_version
        == 0
        and (
            installed_history.observer_transition.commit.installed_subordinate_state_version
        )
        == 1
        and installed_history.observer_transition.prior_head
        == retirement.observer_transition.installed_head
        and installed_history.observer_transition.prior_selector
        == retirement.observer_transition.installed_selector
        and update.observer_transition.prior_head
        == installed_history.observer_transition.installed_head
        and update.observer_transition.prior_selector
        == installed_history.observer_transition.installed_selector
        and terminalization.checkpoint == checkpoint
        and terminalization.observer_transition.prior_head
        == update.observer_transition.installed_head
        and terminalization.observer_transition.prior_selector
        == update.observer_transition.installed_selector
        and head.horizon_open
        and head.head_digest == _history_head_digest(head)
        and head.history_incarnation == retirement.anchor.history_incarnation
        and head.history_state_version == len(head.historical_positions) + 1
        and head.prior_head_digest == installed_history.head.head_digest
        and update.observer_transition.commit.subordinate_state_incarnation
        == head.history_incarnation
        and update.observer_transition.commit.prior_subordinate_state_version
        == installed_history.head.history_state_version
        and update.observer_transition.commit.installed_subordinate_state_version
        == head.history_state_version
        and receipt.frame_digest == frame.frame_digest
        and receipt.source_position == frame.stream_position
        and receipt.provider_history_provenance_digest == provenance.provenance_digest
        and receipt.installed_head_digest == head.head_digest
        and receipt.prior_head_digest == head.prior_head_digest
        and receipt.state_version == head.history_state_version
        and receipt.head_commit_digest
        == update.observer_transition.commit.commit_digest
        and evidence is not None
        and evidence.admission_receipt_digest == expected_event_digest
        and checkpoint.operation == "TERMINALIZE_FROM_HISTORY_HEAD"
        and checkpoint.prior_evidence_digest == head.head_digest
        and checkpoint.prior_installed_receipt_digest == receipt.receipt_digest
        and checkpoint.expected_prior_observer_head_digest
        == update.observer_transition.installed_head.head_digest
        and checkpoint.expected_prior_observer_selector_digest
        == update.observer_transition.installed_selector.selector_digest
        and checkpoint.expected_prior_observer_selector_version
        == update.observer_transition.installed_selector.selector_version
        and checkpoint.retirement_anchor_digest == head.retirement_anchor_digest
        and checkpoint.history_incarnation == head.history_incarnation
        and checkpoint.prior_history_state_version == head.history_state_version
        and checkpoint.terminal_history_state_version == head.history_state_version + 1
        and checkpoint.closed_horizon == head.authorized_horizon
        and checkpoint.retention_state == "retained"
        and checkpoint.checkpoint_digest == _terminal_checkpoint_digest(checkpoint)
        and not {
            "authority_receipt",
            "receipt_digest",
            "observer_state_commit_digest",
            "installed_observer_head_digest",
        }.intersection(_body(checkpoint))
        and terminalization.observer_transition.transition_kind == checkpoint.operation
        and terminalization.observer_transition.operation_evidence_digest
        == checkpoint.checkpoint_digest
        and terminal_receipt.operation == checkpoint.operation
        and terminal_receipt.checkpoint_digest == checkpoint.checkpoint_digest
        and terminal_receipt.prior_evidence_digest == head.head_digest
        and terminal_receipt.prior_installed_receipt_digest == receipt.receipt_digest
        and terminal_receipt.prior_observer_head_digest
        == update.observer_transition.installed_head.head_digest
        and terminal_receipt.prior_observer_selector_digest
        == update.observer_transition.installed_selector.selector_digest
        and terminal_receipt.prior_observer_selector_version
        == update.observer_transition.installed_selector.selector_version
        and terminal_receipt.installed_observer_head_digest
        == terminalization.observer_transition.installed_head.head_digest
        and terminal_receipt.installed_observer_selector_digest
        == terminalization.observer_transition.installed_selector.selector_digest
        and terminal_receipt.installed_observer_selector_version
        == terminalization.observer_transition.installed_selector.selector_version
        and terminal_receipt.observer_state_commit_digest
        == terminalization.observer_transition.commit.commit_digest
        and terminal_receipt.receipt_digest
        == _frame_terminalization_receipt_digest(terminal_receipt)
        and "HISTORY_OPEN" in phases
        and "TERMINAL" in phases
        and (
            fence is None
            or fence.key == receipt.key
            and fence.terminal_checkpoint_digest == checkpoint.checkpoint_digest
            and fence.fence_digest == _lineage_fence_digest(fence)
            and phases[-1] == "FENCED"
        )
        and receipt.receipt_digest == _admission_receipt_digest(receipt),
        "historical admission lacks exact anchor/head/checkpoint/fence ancestry",
        CaptureError,
    )
    _validate_authority(
        receipt.authority_receipt,
        domain="receiver-history-admission",
        subject_digest=receipt.receipt_digest,
        issuer=INGRESS_AUTHORITY,
        subject=receipt.key.receiver_principal,
    )
    _validate_authority(
        terminal_receipt.authority_receipt,
        domain="frame-admission-terminalization",
        subject_digest=terminal_receipt.receipt_digest,
        issuer=INGRESS_AUTHORITY,
        subject=receipt.key.receiver_principal,
    )
    if fence is not None:
        _validate_authority(
            fence.authority_receipt,
            domain="admission-lineage-fence",
            subject_digest=fence.fence_digest,
            issuer=INGRESS_AUTHORITY,
            subject=receipt.key.receiver_principal,
        )


@dataclass(frozen=True, slots=True)
class SecurityAuthorityTransitionFact:
    fact_id: str
    operation: str
    session: str
    generation: str
    authority_domain_digest: str
    state_lineage_incarnation: str
    external_trust_root_enrollment_digest: str
    expected_prior_head_digest: str
    expected_prior_selector_digest: str
    expected_prior_selector_version: int
    prior_authority_state_version: int
    successor_authority_state_version: int
    prior_security_epoch: int
    successor_security_epoch: int
    successor_security_state_digest: str
    prior_revocation_epoch: int
    successor_revocation_epoch: int
    successor_revocation_state_digest: str
    transition_authorization_digest: str
    fact_digest: str


def _security_authority_transition_fact_digest(
    fact: SecurityAuthorityTransitionFact,
) -> str:
    return _body_digest(fact, "fact_digest")


def _security_authority_domain_digest() -> str:
    return _digest(
        {
            "authority": SECURITY_AUTHORITY,
            "domain": "ncp-security-authority-state-v1",
            "generation": GENERATION,
            "session": SESSION,
        }
    )


@dataclass(frozen=True, slots=True)
class SecurityAuthorityStateHead:
    head_id: str
    session: str
    generation: str
    authority_domain_digest: str
    state_lineage_incarnation: str
    authority_state_version: int
    security_epoch: int
    security_state_digest: str
    revocation_epoch: int
    revocation_state_digest: str
    external_trust_root_enrollment_digest: str
    prior_head_digest: str | None
    retained_head_digests: tuple[str, ...]
    transition_fact_digest: str | None
    retained_transition_authorization_digests: tuple[str, ...]
    head_digest: str
    authority_receipt: AuthorityReceipt


def _security_authority_head_digest(head: SecurityAuthorityStateHead) -> str:
    return _body_digest(head, "head_digest", "authority_receipt")


def _security_trust_root_enrollment_digest() -> str:
    return _digest(
        {
            "authority": SECURITY_AUTHORITY,
            "generation": GENERATION,
            "trust_root": "synthetic-external-root",
        }
    )


def _seal_security_authority_head(
    head: SecurityAuthorityStateHead,
    *,
    event_time: int,
) -> SecurityAuthorityStateHead:
    head = replace(head, head_digest=_security_authority_head_digest(head))
    return replace(
        head,
        authority_receipt=_seal_authority(
            receipt_id=head.authority_receipt.receipt_id,
            domain="security-authority-state-head",
            subject_digest=head.head_digest,
            issuer=SECURITY_AUTHORITY,
            subject=SESSION_AUTHORITY,
            clock_domain="security-authority-monotonic",
            clock_incarnation=head.generation,
            event_time=event_time,
        ),
    )


@dataclass(frozen=True, slots=True)
class InstalledSecurityAuthorityStateSelector:
    selector_id: str
    session: str
    generation: str
    selector_incarnation: str
    transaction_store_incarnation: str
    selector_version: int
    state: str
    ever_used: bool
    current_head_digest: str | None
    prior_selector_digest: str | None
    last_commit_digest: str | None
    selector_digest: str
    authority_receipt: AuthorityReceipt


def _security_selector_digest(
    selector: InstalledSecurityAuthorityStateSelector,
) -> str:
    return _body_digest(selector, "selector_digest", "authority_receipt")


def _seal_security_selector(
    selector: InstalledSecurityAuthorityStateSelector,
    *,
    event_time: int,
) -> InstalledSecurityAuthorityStateSelector:
    selector = replace(
        selector,
        selector_digest=_security_selector_digest(selector),
    )
    return replace(
        selector,
        authority_receipt=_seal_authority(
            receipt_id=selector.authority_receipt.receipt_id,
            domain="installed-security-authority-state-selector",
            subject_digest=selector.selector_digest,
            issuer=SECURITY_AUTHORITY,
            subject=SESSION_AUTHORITY,
            clock_domain="security-authority-monotonic",
            clock_incarnation=selector.selector_incarnation,
            event_time=event_time,
        ),
    )


@dataclass(frozen=True, slots=True)
class SecurityAuthorityStateCommitReceipt:
    commit_id: str
    operation: str
    session: str
    generation: str
    authority_domain_digest: str
    state_lineage_incarnation: str
    external_trust_root_enrollment_digest: str
    prior_selector_digest: str
    prior_head_digest: str | None
    operation_evidence_digest: str
    installed_head_digest: str
    installed_selector_version: int
    prior_authority_state_version: int
    installed_authority_state_version: int
    installed_security_epoch: int
    installed_revocation_epoch: int
    commit_digest: str
    authority_receipt: AuthorityReceipt


def _security_authority_commit_digest(
    receipt: SecurityAuthorityStateCommitReceipt,
) -> str:
    return _body_digest(receipt, "commit_digest", "authority_receipt")


def _seal_security_authority_commit(
    receipt: SecurityAuthorityStateCommitReceipt,
    *,
    event_time: int,
) -> SecurityAuthorityStateCommitReceipt:
    receipt = replace(
        receipt,
        commit_digest=_security_authority_commit_digest(receipt),
    )
    return replace(
        receipt,
        authority_receipt=_seal_authority(
            receipt_id=receipt.authority_receipt.receipt_id,
            domain="security-authority-state-commit",
            subject_digest=receipt.commit_digest,
            issuer=SECURITY_AUTHORITY,
            subject=SESSION_AUTHORITY,
            clock_domain="security-authority-monotonic",
            clock_incarnation=receipt.generation,
            event_time=event_time,
        ),
    )


@dataclass(frozen=True, slots=True)
class SecurityAuthorityTransitionEvidence:
    transition_fact: SecurityAuthorityTransitionFact
    prior_head: SecurityAuthorityStateHead
    prior_selector: InstalledSecurityAuthorityStateSelector
    successor_head: SecurityAuthorityStateHead
    state_commit: SecurityAuthorityStateCommitReceipt
    installed_selector: InstalledSecurityAuthorityStateSelector
    committed_at: int


def _build_security_authority_transition(
    prior_head: SecurityAuthorityStateHead,
    prior_selector: InstalledSecurityAuthorityStateSelector,
    *,
    successor_security_state_digest: str,
    event_time: int,
) -> SecurityAuthorityTransitionEvidence:
    _require(
        prior_selector.current_head_digest == prior_head.head_digest
        and prior_selector.state == "INSTALLED"
        and prior_selector.ever_used,
        "security transition did not start from the installed selector",
        CaptureError,
    )
    transition_authorization_digest = _digest(
        {
            "authority_domain_digest": prior_head.authority_domain_digest,
            "domain": "security-authority-transition-authorization-v1",
            "operation": "ROTATE_SECURITY_AUTHORITY_STATE",
            "prior_head_digest": prior_head.head_digest,
            "prior_revocation_epoch": prior_head.revocation_epoch,
            "prior_security_epoch": prior_head.security_epoch,
            "state_lineage_incarnation": prior_head.state_lineage_incarnation,
            "successor_revocation_epoch": prior_head.revocation_epoch,
            "successor_security_epoch": prior_head.security_epoch + 1,
        }
    )
    fact = SecurityAuthorityTransitionFact(
        fact_id=_u_for(
            (
                "security-authority-transition-fact",
                prior_head.head_digest,
                prior_selector.selector_digest,
            )
        ),
        operation="ROTATE_SECURITY_AUTHORITY_STATE",
        session=SESSION,
        generation=GENERATION,
        authority_domain_digest=prior_head.authority_domain_digest,
        state_lineage_incarnation=prior_head.state_lineage_incarnation,
        external_trust_root_enrollment_digest=(
            prior_head.external_trust_root_enrollment_digest
        ),
        expected_prior_head_digest=prior_head.head_digest,
        expected_prior_selector_digest=prior_selector.selector_digest,
        expected_prior_selector_version=prior_selector.selector_version,
        prior_authority_state_version=prior_head.authority_state_version,
        successor_authority_state_version=(prior_head.authority_state_version + 1),
        prior_security_epoch=prior_head.security_epoch,
        successor_security_epoch=prior_head.security_epoch + 1,
        successor_security_state_digest=successor_security_state_digest,
        prior_revocation_epoch=prior_head.revocation_epoch,
        successor_revocation_epoch=prior_head.revocation_epoch,
        successor_revocation_state_digest=prior_head.revocation_state_digest,
        transition_authorization_digest=transition_authorization_digest,
        fact_digest="",
    )
    fact = replace(
        fact,
        fact_digest=_security_authority_transition_fact_digest(fact),
    )
    successor_head = _seal_security_authority_head(
        SecurityAuthorityStateHead(
            head_id=_u_for(("security-authority-successor-head", fact.fact_digest)),
            session=SESSION,
            generation=GENERATION,
            authority_domain_digest=fact.authority_domain_digest,
            state_lineage_incarnation=fact.state_lineage_incarnation,
            authority_state_version=fact.successor_authority_state_version,
            security_epoch=fact.successor_security_epoch,
            security_state_digest=fact.successor_security_state_digest,
            revocation_epoch=fact.successor_revocation_epoch,
            revocation_state_digest=fact.successor_revocation_state_digest,
            external_trust_root_enrollment_digest=(
                fact.external_trust_root_enrollment_digest
            ),
            prior_head_digest=prior_head.head_digest,
            retained_head_digests=(
                *prior_head.retained_head_digests,
                prior_head.head_digest,
            ),
            transition_fact_digest=fact.fact_digest,
            retained_transition_authorization_digests=(
                prior_head.retained_transition_authorization_digests
            ),
            head_digest="",
            authority_receipt=_pending_authority(39_500),
        ),
        event_time=event_time,
    )
    state_commit = _seal_security_authority_commit(
        SecurityAuthorityStateCommitReceipt(
            commit_id=_u_for(
                ("security-authority-transition-commit", fact.fact_digest)
            ),
            operation="ROTATE_FROM_INSTALLED",
            session=SESSION,
            generation=GENERATION,
            authority_domain_digest=fact.authority_domain_digest,
            state_lineage_incarnation=fact.state_lineage_incarnation,
            external_trust_root_enrollment_digest=(
                fact.external_trust_root_enrollment_digest
            ),
            prior_selector_digest=prior_selector.selector_digest,
            prior_head_digest=prior_head.head_digest,
            operation_evidence_digest=fact.fact_digest,
            installed_head_digest=successor_head.head_digest,
            installed_selector_version=prior_selector.selector_version + 1,
            prior_authority_state_version=prior_head.authority_state_version,
            installed_authority_state_version=(successor_head.authority_state_version),
            installed_security_epoch=successor_head.security_epoch,
            installed_revocation_epoch=successor_head.revocation_epoch,
            commit_digest="",
            authority_receipt=_pending_authority(39_501),
        ),
        event_time=event_time,
    )
    installed_selector = _seal_security_selector(
        replace(
            prior_selector,
            selector_id=_u_for(
                ("security-authority-transition-selector", fact.fact_digest)
            ),
            selector_version=prior_selector.selector_version + 1,
            current_head_digest=successor_head.head_digest,
            prior_selector_digest=prior_selector.selector_digest,
            last_commit_digest=state_commit.commit_digest,
            selector_digest="",
            authority_receipt=_pending_authority(39_502),
        ),
        event_time=event_time,
    )
    return SecurityAuthorityTransitionEvidence(
        fact,
        prior_head,
        prior_selector,
        successor_head,
        state_commit,
        installed_selector,
        event_time,
    )


def _validate_security_authority_transition(
    evidence: SecurityAuthorityTransitionEvidence,
) -> None:
    fact = evidence.transition_fact
    prior_head = evidence.prior_head
    prior_selector = evidence.prior_selector
    successor_head = evidence.successor_head
    commit = evidence.state_commit
    installed = evidence.installed_selector
    _require(
        _is_uuid4(fact.fact_id)
        and fact.operation == "ROTATE_SECURITY_AUTHORITY_STATE"
        and fact.session == SESSION
        and fact.generation == GENERATION
        and fact.authority_domain_digest
        == prior_head.authority_domain_digest
        == _security_authority_domain_digest()
        and fact.state_lineage_incarnation == prior_head.state_lineage_incarnation
        and _is_uuid4(fact.state_lineage_incarnation)
        and fact.external_trust_root_enrollment_digest
        == prior_head.external_trust_root_enrollment_digest
        and fact.expected_prior_head_digest == prior_head.head_digest
        and fact.expected_prior_selector_digest == prior_selector.selector_digest
        and fact.expected_prior_selector_version == prior_selector.selector_version
        and fact.prior_authority_state_version == prior_head.authority_state_version
        and fact.successor_authority_state_version
        == fact.prior_authority_state_version + 1
        and fact.prior_security_epoch == prior_head.security_epoch
        and fact.successor_security_epoch == fact.prior_security_epoch + 1
        and fact.successor_security_state_digest != prior_head.security_state_digest
        and HEX64.fullmatch(fact.successor_security_state_digest) is not None
        and fact.prior_revocation_epoch == prior_head.revocation_epoch
        and fact.successor_revocation_epoch == fact.prior_revocation_epoch
        and fact.successor_revocation_state_digest == prior_head.revocation_state_digest
        and fact.transition_authorization_digest
        == _digest(
            {
                "authority_domain_digest": fact.authority_domain_digest,
                "domain": "security-authority-transition-authorization-v1",
                "operation": fact.operation,
                "prior_head_digest": fact.expected_prior_head_digest,
                "prior_revocation_epoch": fact.prior_revocation_epoch,
                "prior_security_epoch": fact.prior_security_epoch,
                "state_lineage_incarnation": fact.state_lineage_incarnation,
                "successor_revocation_epoch": fact.successor_revocation_epoch,
                "successor_security_epoch": fact.successor_security_epoch,
            }
        )
        and fact.fact_digest == _security_authority_transition_fact_digest(fact),
        "security transition fact predicts a result or misses the exact predecessor",
        CaptureError,
    )
    _require(
        prior_selector.current_head_digest == prior_head.head_digest
        and successor_head.session == SESSION
        and successor_head.generation == GENERATION
        and successor_head.authority_domain_digest == fact.authority_domain_digest
        and successor_head.state_lineage_incarnation == fact.state_lineage_incarnation
        and successor_head.authority_state_version
        == prior_head.authority_state_version + 1
        and successor_head.authority_state_version
        == fact.successor_authority_state_version
        and successor_head.security_epoch == fact.successor_security_epoch
        and successor_head.security_state_digest == fact.successor_security_state_digest
        and successor_head.revocation_epoch == fact.successor_revocation_epoch
        and successor_head.revocation_state_digest
        == fact.successor_revocation_state_digest
        and successor_head.external_trust_root_enrollment_digest
        == fact.external_trust_root_enrollment_digest
        and successor_head.prior_head_digest == prior_head.head_digest
        and successor_head.retained_head_digests
        == (*prior_head.retained_head_digests, prior_head.head_digest)
        and successor_head.transition_fact_digest == fact.fact_digest
        and successor_head.retained_transition_authorization_digests
        == prior_head.retained_transition_authorization_digests
        and successor_head.head_digest
        == _security_authority_head_digest(successor_head),
        "security successor head is not derived only from the pre-CAS fact",
        CaptureError,
    )
    _require(
        commit.operation == "ROTATE_FROM_INSTALLED"
        and commit.session == SESSION
        and commit.generation == GENERATION
        and commit.authority_domain_digest == fact.authority_domain_digest
        and commit.state_lineage_incarnation == fact.state_lineage_incarnation
        and commit.external_trust_root_enrollment_digest
        == fact.external_trust_root_enrollment_digest
        and commit.prior_selector_digest == prior_selector.selector_digest
        and commit.prior_head_digest == prior_head.head_digest
        and commit.operation_evidence_digest == fact.fact_digest
        and commit.installed_head_digest == successor_head.head_digest
        and commit.installed_selector_version == prior_selector.selector_version + 1
        and commit.prior_authority_state_version == prior_head.authority_state_version
        and commit.installed_authority_state_version
        == successor_head.authority_state_version
        and commit.installed_authority_state_version
        == commit.prior_authority_state_version + 1
        and commit.installed_security_epoch == successor_head.security_epoch
        and commit.installed_revocation_epoch == successor_head.revocation_epoch
        and commit.commit_digest == _security_authority_commit_digest(commit)
        and installed.selector_incarnation == prior_selector.selector_incarnation
        and installed.transaction_store_incarnation
        == prior_selector.transaction_store_incarnation
        and installed.selector_version == prior_selector.selector_version + 1
        and installed.state == "INSTALLED"
        and installed.ever_used
        and installed.current_head_digest == successor_head.head_digest
        and installed.prior_selector_digest == prior_selector.selector_digest
        and installed.last_commit_digest == commit.commit_digest
        and installed.selector_digest == _security_selector_digest(installed),
        "security transition did not install one successor through the generic CAS",
        CaptureError,
    )
    for value, domain, digest in (
        (
            successor_head,
            "security-authority-state-head",
            successor_head.head_digest,
        ),
        (
            commit,
            "security-authority-state-commit",
            commit.commit_digest,
        ),
        (
            installed,
            "installed-security-authority-state-selector",
            installed.selector_digest,
        ),
    ):
        _validate_authority(
            value.authority_receipt,
            domain=domain,
            subject_digest=digest,
            issuer=SECURITY_AUTHORITY,
            subject=SESSION_AUTHORITY,
        )
        _require(
            value.authority_receipt.clock_domain == "security-authority-monotonic"
            and value.authority_receipt.event_time == evidence.committed_at,
            "security transition CAS members use mismatched authority time",
            CaptureError,
        )


def _validate_security_authority_provision(
    uninitialized: InstalledSecurityAuthorityStateSelector,
    head: SecurityAuthorityStateHead,
    commit: SecurityAuthorityStateCommitReceipt,
    installed: InstalledSecurityAuthorityStateSelector,
) -> None:
    _require(
        _is_uuid4(uninitialized.selector_id)
        and _is_uuid4(uninitialized.selector_incarnation)
        and _is_uuid4(uninitialized.transaction_store_incarnation)
        and uninitialized.session == SESSION
        and uninitialized.generation == GENERATION
        and uninitialized.state == "UNINITIALIZED"
        and uninitialized.selector_version == 0
        and not uninitialized.ever_used
        and uninitialized.current_head_digest is None
        and uninitialized.prior_selector_digest is None
        and uninitialized.last_commit_digest is None
        and uninitialized.selector_digest == _security_selector_digest(uninitialized)
        and _is_uuid4(head.head_id)
        and head.session == SESSION
        and head.generation == GENERATION
        and head.authority_domain_digest
        == commit.authority_domain_digest
        == _security_authority_domain_digest()
        and _is_uuid4(head.state_lineage_incarnation)
        and head.state_lineage_incarnation == commit.state_lineage_incarnation
        and head.authority_state_version == 1
        and head.security_epoch == 1
        and head.security_state_digest == SECURITY_STATE_DIGEST
        and head.revocation_epoch == commit.installed_revocation_epoch == 7
        and HEX64.fullmatch(head.revocation_state_digest) is not None
        and head.prior_head_digest is None
        and not head.retained_head_digests
        and head.transition_fact_digest is None
        and not head.retained_transition_authorization_digests
        and head.external_trust_root_enrollment_digest
        == commit.external_trust_root_enrollment_digest
        == _security_trust_root_enrollment_digest()
        and head.head_digest == _security_authority_head_digest(head)
        and _is_uuid4(commit.commit_id)
        and commit.operation == "PROVISION_FROM_UNINITIALIZED"
        and commit.session == SESSION
        and commit.generation == GENERATION
        and commit.prior_selector_digest == uninitialized.selector_digest
        and commit.prior_head_digest is None
        and commit.operation_evidence_digest
        == commit.external_trust_root_enrollment_digest
        and commit.installed_head_digest == head.head_digest
        and commit.installed_selector_version == 1
        and commit.prior_authority_state_version == 0
        and commit.installed_authority_state_version == 1
        and commit.installed_security_epoch == 1
        and commit.installed_revocation_epoch == head.revocation_epoch
        and commit.commit_digest == _security_authority_commit_digest(commit)
        and _is_uuid4(installed.selector_id)
        and installed.session == SESSION
        and installed.generation == GENERATION
        and installed.selector_incarnation == uninitialized.selector_incarnation
        and installed.transaction_store_incarnation
        == uninitialized.transaction_store_incarnation
        and installed.selector_version == 1
        and installed.state == "INSTALLED"
        and installed.ever_used
        and installed.current_head_digest == head.head_digest
        and installed.prior_selector_digest == uninitialized.selector_digest
        and installed.last_commit_digest == commit.commit_digest
        and installed.selector_digest == _security_selector_digest(installed),
        "security state did not provision from a never-used trusted selector",
        CaptureError,
    )
    for receipt, domain, subject_digest in (
        (
            uninitialized.authority_receipt,
            "installed-security-authority-state-selector",
            uninitialized.selector_digest,
        ),
        (
            head.authority_receipt,
            "security-authority-state-head",
            head.head_digest,
        ),
        (
            commit.authority_receipt,
            "security-authority-state-commit",
            commit.commit_digest,
        ),
        (
            installed.authority_receipt,
            "installed-security-authority-state-selector",
            installed.selector_digest,
        ),
    ):
        _validate_authority(
            receipt,
            domain=domain,
            subject_digest=subject_digest,
            issuer=SECURITY_AUTHORITY,
            subject=SESSION_AUTHORITY,
        )


@dataclass(frozen=True, slots=True)
class SessionSecurityContext:
    session: str
    generation: str
    descriptor_digest: str
    transcript_digest: str
    security_state_digest: str
    security_authority_selector_digest: str
    security_authority_selector_version: int
    selector_transaction_store_incarnation: str
    plant_profile_digest: str
    context_digest: str


def _security_context_digest(context: SessionSecurityContext) -> str:
    return _body_digest(context, "context_digest")


def _seal_security_context(
    context: SessionSecurityContext,
) -> SessionSecurityContext:
    return replace(context, context_digest=_security_context_digest(context))


def _validate_security_context(context: SessionSecurityContext) -> None:
    _require(
        context.session == SESSION
        and context.generation == GENERATION
        and all(
            HEX64.fullmatch(value) is not None
            for value in (
                context.descriptor_digest,
                context.transcript_digest,
                context.security_state_digest,
                context.security_authority_selector_digest,
                context.plant_profile_digest,
            )
        )
        and _safe_int(context.security_authority_selector_version)
        and _is_uuid4(context.selector_transaction_store_incarnation)
        and context.context_digest == _security_context_digest(context),
        "session security context is malformed or self-selected",
        CaptureError,
    )


@dataclass(frozen=True, slots=True)
class SecurityStateTransitionAuthorization:
    closure_id: str
    transition_mode: str
    ambiguity_state: str
    generation_disposition: str
    hold_state: str
    new_admission_state: str
    active_tip_fence_policy_digest: str
    security_transition_fact_digest: str
    prior_security_authority_head_digest: str
    installed_security_authority_head_digest: str
    prior_security_epoch: int
    installed_security_epoch: int
    prior_security_selector_digest: str
    installed_security_selector_digest: str
    installed_security_selector_version: int
    security_authority_commit_digest: str
    successor_security_context_digest: str | None
    prior_security_context_digest: str
    prior_disposition_head_digest: str
    admission_registry_head_digest: str
    admission_gate_state: str
    retired_stream_declaration_digests: tuple[str, ...]
    retired_grant_digests: tuple[str, ...]
    retired_lease_digests: tuple[str, ...]
    closed_at: int
    closure_digest: str
    authority_receipt: AuthorityReceipt


@dataclass(frozen=True, slots=True)
class SecurityRetirementExpectation:
    admission_registry_head_digest: str
    retired_stream_declaration_digests: tuple[str, ...]
    retired_grant_digests: tuple[str, ...]
    retired_lease_digests: tuple[str, ...]


def _security_transition_authorization_digest(
    closure: SecurityStateTransitionAuthorization,
) -> str:
    return _body_digest(closure, "closure_digest", "authority_receipt")


def _seal_security_transition_authorization(
    closure: SecurityStateTransitionAuthorization,
) -> SecurityStateTransitionAuthorization:
    closure = replace(
        closure,
        closure_digest=_security_transition_authorization_digest(closure),
    )
    return replace(
        closure,
        authority_receipt=_seal_authority(
            receipt_id=closure.authority_receipt.receipt_id,
            domain="session-security-retirement-closure",
            subject_digest=closure.closure_digest,
            issuer=SESSION_AUTHORITY,
            subject=BODY_AUTHORITY,
            clock_domain="session-monotonic",
            clock_incarnation=GENERATION,
            event_time=closure.closed_at,
        ),
    )


def _validate_security_transition_authorization(
    closure: SecurityStateTransitionAuthorization,
    *,
    security_transition: SecurityAuthorityTransitionEvidence,
    prior_context: SessionSecurityContext,
    successor_context: SessionSecurityContext | None,
    prior_disposition_head_digest: str,
    expected_retirement: SecurityRetirementExpectation,
) -> None:
    successor_retained_authorizations = (
        security_transition.successor_head.retained_transition_authorization_digests
    )
    prior_retained_authorizations = (
        security_transition.prior_head.retained_transition_authorization_digests
    )
    _require(
        closure.closure_digest not in successor_retained_authorizations
        and successor_retained_authorizations == prior_retained_authorizations,
        "security head retained an authorization that points back to itself",
        CaptureError,
    )
    _validate_security_authority_transition(security_transition)
    planned = (
        closure.transition_mode == "PLANNED"
        and closure.ambiguity_state == "RESOLVED"
        and closure.generation_disposition == "CONTINUE_SAME_GENERATION"
        and closure.hold_state == "NOT_ACTIVE"
        and closure.new_admission_state == "BLOCKED_DURING_CUTOVER"
    )
    emergency = (
        closure.transition_mode == "EMERGENCY"
        and closure.ambiguity_state == "RESOLVED"
        and closure.generation_disposition == "CONTINUE_SAME_GENERATION"
        and closure.hold_state == "ACTIVE"
        and closure.new_admission_state == "BLOCKED"
    )
    ambiguous = (
        closure.transition_mode == "AMBIGUOUS"
        and closure.ambiguity_state == "AMBIGUOUS"
        and closure.generation_disposition == "RETIRE_GENERATION"
        and closure.hold_state == "ACTIVE"
        and closure.new_admission_state == "BLOCKED"
    )
    _require(
        _is_uuid4(closure.closure_id)
        and (planned or emergency or ambiguous)
        and HEX64.fullmatch(closure.active_tip_fence_policy_digest) is not None
        and closure.security_transition_fact_digest
        == security_transition.transition_fact.fact_digest
        and closure.prior_security_authority_head_digest
        == security_transition.prior_head.head_digest
        and closure.installed_security_authority_head_digest
        == security_transition.successor_head.head_digest
        and closure.prior_security_epoch
        == security_transition.prior_head.security_epoch
        and closure.installed_security_epoch
        == security_transition.successor_head.security_epoch
        and closure.prior_security_selector_digest
        == security_transition.prior_selector.selector_digest
        and closure.installed_security_selector_digest
        == security_transition.installed_selector.selector_digest
        and closure.installed_security_selector_version
        == security_transition.installed_selector.selector_version
        and closure.security_authority_commit_digest
        == security_transition.state_commit.commit_digest
        and closure.successor_security_context_digest
        == (successor_context.context_digest if successor_context is not None else None)
        and prior_context.security_state_digest
        == security_transition.prior_head.head_digest
        and prior_context.security_authority_selector_digest
        == security_transition.prior_selector.selector_digest
        and prior_context.security_authority_selector_version
        == security_transition.prior_selector.selector_version
        and prior_context.selector_transaction_store_incarnation
        == security_transition.prior_selector.transaction_store_incarnation
        and (
            successor_context is None
            or successor_context.security_state_digest
            == security_transition.successor_head.head_digest
            and successor_context.security_authority_selector_digest
            == security_transition.installed_selector.selector_digest
            and successor_context.security_authority_selector_version
            == security_transition.installed_selector.selector_version
            and successor_context.selector_transaction_store_incarnation
            == security_transition.installed_selector.transaction_store_incarnation
        )
        and closure.closed_at >= security_transition.committed_at
        and closure.prior_security_context_digest == prior_context.context_digest
        and closure.prior_disposition_head_digest == prior_disposition_head_digest
        and closure.admission_registry_head_digest
        == expected_retirement.admission_registry_head_digest
        and HEX64.fullmatch(closure.admission_registry_head_digest) is not None
        and closure.admission_gate_state == "CLOSED"
        and len(closure.retired_stream_declaration_digests) <= MAX_REGISTRY_ENTRIES
        and tuple(sorted(set(closure.retired_stream_declaration_digests)))
        == closure.retired_stream_declaration_digests
        and tuple(sorted(set(closure.retired_grant_digests)))
        == closure.retired_grant_digests
        and tuple(sorted(set(closure.retired_lease_digests)))
        == closure.retired_lease_digests
        and (
            not (planned or emergency)
            or closure.retired_stream_declaration_digests
            == expected_retirement.retired_stream_declaration_digests
            and closure.retired_grant_digests
            == expected_retirement.retired_grant_digests
            and closure.retired_lease_digests
            == expected_retirement.retired_lease_digests
            and bool(closure.retired_stream_declaration_digests)
            and bool(closure.retired_grant_digests)
            and bool(closure.retired_lease_digests)
        )
        and all(
            HEX64.fullmatch(value) is not None
            for value in (
                *closure.retired_stream_declaration_digests,
                *closure.retired_grant_digests,
                *closure.retired_lease_digests,
            )
        )
        and _safe_int(closure.closed_at)
        and closure.closure_digest
        == _security_transition_authorization_digest(closure),
        "security rebind lacks exact old admission/stream/lease/grant retirement",
        CaptureError,
    )
    _validate_authority(
        closure.authority_receipt,
        domain="session-security-retirement-closure",
        subject_digest=closure.closure_digest,
        issuer=SESSION_AUTHORITY,
        subject=BODY_AUTHORITY,
    )
    _require(
        closure.authority_receipt.clock_domain == "session-monotonic"
        and closure.authority_receipt.clock_incarnation == prior_context.generation
        and closure.authority_receipt.event_time == closure.closed_at,
        "security retirement closure uses the wrong session clock",
        CaptureError,
    )


@dataclass(frozen=True, slots=True)
class SecurityRebindJournalRecord:
    rebind_id: str
    journal_incarnation: str
    rebind_nonce: str
    rebind_mode: str
    prior_installed_head_digest: str
    prior_security_context: SessionSecurityContext
    successor_security_context: SessionSecurityContext | None
    security_authority_transition: SecurityAuthorityTransitionEvidence
    transition_authorization: SecurityStateTransitionAuthorization
    global_event_sequence: int
    body_local_time: int
    session_event_time: int
    rebind_digest: str


def _security_rebind_body(record: SecurityRebindJournalRecord) -> dict[str, Any]:
    return _body(record, "rebind_digest")


@dataclass(frozen=True, slots=True)
class SealedSecurityRebindJournalRecord:
    semantic_record: SecurityRebindJournalRecord
    protected_record: ProtectedBody


def _seal_security_rebind(
    record: SecurityRebindJournalRecord,
    *,
    store: ContentStore,
) -> SealedSecurityRebindJournalRecord:
    protected = _protect_body(
        _security_rebind_body(record),
        store=store,
        media_type="application/vnd.ncp.session-security-rebind+json",
        domain="session-security-rebind",
        issuer=SESSION_AUTHORITY,
        subject=BODY_AUTHORITY,
        event_time=record.session_event_time,
        clock_domain="session-monotonic",
        clock_incarnation=(
            record.successor_security_context.generation
            if record.successor_security_context is not None
            else record.prior_security_context.generation
        ),
    )
    return SealedSecurityRebindJournalRecord(
        replace(record, rebind_digest=protected.body_digest),
        protected,
    )


def _validate_sealed_security_rebind(
    sealed: SealedSecurityRebindJournalRecord,
    *,
    store: ContentStore,
) -> None:
    record = sealed.semantic_record
    _validate_protected_body(
        sealed.protected_record,
        _security_rebind_body(record),
        store=store,
        media_type="application/vnd.ncp.session-security-rebind+json",
        domain="session-security-rebind",
        issuer=SESSION_AUTHORITY,
        subject=BODY_AUTHORITY,
    )
    _require(
        record.rebind_digest == sealed.protected_record.body_digest
        and sealed.protected_record.authority_receipt.clock_domain
        == "session-monotonic"
        and sealed.protected_record.authority_receipt.clock_incarnation
        == record.prior_security_context.generation
        and _safe_int(record.session_event_time)
        and record.transition_authorization.closed_at <= record.session_event_time
        and sealed.protected_record.authority_receipt.event_time
        == record.session_event_time,
        "security rebind protected record uses the wrong session clock or bytes",
        CaptureError,
    )


@dataclass(frozen=True, slots=True)
class SecurityRebindJournalCommitReceipt:
    commit_id: str
    rebind_digest: str
    prior_head_digest: str
    installed_head_digest: str
    state_version: int
    commit_digest: str
    authority_receipt: AuthorityReceipt


def _security_rebind_commit_digest(
    receipt: SecurityRebindJournalCommitReceipt,
) -> str:
    return _body_digest(receipt, "commit_digest", "authority_receipt")


@dataclass(frozen=True, slots=True)
class CommandDispositionRecord:
    record_id: str
    journal_incarnation: str
    security_context_digest: str
    global_event_sequence: int
    command_id: str
    proposal_frame_digest: str
    proposal_content_digest: str
    state_sequence: int
    state: str
    prior_command_record_digest: str | None
    admitted_record_digest: str | None
    body_clock_incarnation: str
    body_local_time: int
    boundary_name: str | None
    body_axis_contract_digest: str | None
    applied_value: ContentRef | None
    record_digest: str


DISPOSITION_ALLOWED = {
    "received": frozenset({"rejected", "admitted"}),
    "admitted": frozenset(
        {
            "applied",
            "superseded",
            "expired",
            "failed",
            "unknown_after_boundary",
            "stop_latched",
        }
    ),
}
TERMINAL_STATES = frozenset(
    {
        "rejected",
        "applied",
        "superseded",
        "expired",
        "failed",
        "unknown_after_boundary",
        "stop_latched",
    }
)


def _disposition_body(record: CommandDispositionRecord) -> dict[str, Any]:
    return _body(record, "record_digest")


@dataclass(frozen=True, slots=True)
class SealedDisposition:
    semantic_record: CommandDispositionRecord
    protected_record: ProtectedBody


def _seal_disposition(
    record: CommandDispositionRecord,
    *,
    store: ContentStore,
) -> SealedDisposition:
    protected = _protect_body(
        _disposition_body(record),
        store=store,
        media_type="application/vnd.ncp.command-disposition-record+json",
        domain="body-command-disposition",
        issuer=BODY_AUTHORITY,
        subject=BODY_AUTHORITY,
        event_time=record.body_local_time,
        clock_domain="body-monotonic",
        clock_incarnation=record.body_clock_incarnation,
    )
    return SealedDisposition(
        replace(record, record_digest=protected.body_digest),
        protected,
    )


def _validate_sealed_disposition(
    sealed: SealedDisposition,
    *,
    store: ContentStore,
) -> None:
    record = sealed.semantic_record
    _require(
        _is_uuid4(record.record_id)
        and _is_uuid4(record.journal_incarnation)
        and HEX64.fullmatch(record.security_context_digest) is not None
        and _safe_int(record.global_event_sequence)
        and _is_uuid4(record.command_id)
        and HEX64.fullmatch(record.proposal_frame_digest) is not None
        and HEX64.fullmatch(record.proposal_content_digest) is not None
        and _safe_int(record.state_sequence)
        and record.state in {"received", "admitted", *TERMINAL_STATES}
        and (
            record.state == "received"
            and record.state_sequence == 0
            and record.prior_command_record_digest is None
            or record.state != "received"
            and record.state_sequence > 0
            and record.prior_command_record_digest is not None
            and HEX64.fullmatch(record.prior_command_record_digest) is not None
        )
        and (
            record.state == "applied"
            and record.admitted_record_digest is not None
            and HEX64.fullmatch(record.admitted_record_digest) is not None
            or record.state != "applied"
            and record.admitted_record_digest is None
        )
        and (
            record.state == "applied"
            and IDENTIFIER.fullmatch(record.boundary_name or "") is not None
            and HEX64.fullmatch(record.body_axis_contract_digest or "") is not None
            and record.applied_value is not None
            or record.state != "applied"
            and record.boundary_name is None
            and record.body_axis_contract_digest is None
            and record.applied_value is None
        )
        and _is_uuid4(record.body_clock_incarnation)
        and _safe_int(record.body_local_time)
        and record.record_digest == sealed.protected_record.body_digest,
        "body disposition semantic record is malformed",
        CaptureError,
    )
    if record.applied_value is not None:
        store.get(record.applied_value)
    _validate_protected_body(
        sealed.protected_record,
        _disposition_body(record),
        store=store,
        media_type="application/vnd.ncp.command-disposition-record+json",
        domain="body-command-disposition",
        issuer=BODY_AUTHORITY,
        subject=BODY_AUTHORITY,
    )
    _require(
        sealed.protected_record.authority_receipt.clock_domain == "body-monotonic"
        and sealed.protected_record.authority_receipt.clock_incarnation
        == record.body_clock_incarnation
        and sealed.protected_record.authority_receipt.event_time
        == record.body_local_time,
        "body disposition protected record uses the wrong body clock",
        CaptureError,
    )


@dataclass(frozen=True, slots=True, order=True)
class CommandTip:
    command_id: str
    proposal_frame_digest: str
    record_digest: str
    state_sequence: int
    state: str


@dataclass(frozen=True, slots=True)
class BodyClockRestartBridge:
    bridge_id: str
    journal_incarnation: str
    security_context_digest: str
    prior_installed_head_digest: str
    last_old_event_digest: str
    last_old_global_event_sequence: int
    prior_clock_incarnation: str
    successor_clock_incarnation: str
    bridge_global_event_sequence: int
    bridge_local_time: int
    first_successor_command_id: str
    first_successor_proposal_frame_digest: str
    first_successor_state: str
    first_successor_global_event_sequence: int
    bridge_digest: str


def _bridge_body(bridge: BodyClockRestartBridge) -> dict[str, Any]:
    return _body(bridge, "bridge_digest")


@dataclass(frozen=True, slots=True)
class SealedBodyClockRestartBridge:
    semantic_bridge: BodyClockRestartBridge
    protected_bridge: ProtectedBody


def _seal_restart_bridge(
    bridge: BodyClockRestartBridge,
    *,
    store: ContentStore,
) -> SealedBodyClockRestartBridge:
    protected = _protect_body(
        _bridge_body(bridge),
        store=store,
        media_type="application/vnd.ncp.body-clock-restart-bridge+json",
        domain="body-clock-restart-bridge",
        issuer=BODY_AUTHORITY,
        subject=BODY_AUTHORITY,
        event_time=bridge.bridge_local_time,
        clock_domain="body-monotonic",
        clock_incarnation=bridge.successor_clock_incarnation,
    )
    return SealedBodyClockRestartBridge(
        replace(bridge, bridge_digest=protected.body_digest),
        protected,
    )


def _validate_sealed_restart_bridge(
    sealed: SealedBodyClockRestartBridge,
    *,
    store: ContentStore,
) -> None:
    bridge = sealed.semantic_bridge
    _validate_protected_body(
        sealed.protected_bridge,
        _bridge_body(bridge),
        store=store,
        media_type="application/vnd.ncp.body-clock-restart-bridge+json",
        domain="body-clock-restart-bridge",
        issuer=BODY_AUTHORITY,
        subject=BODY_AUTHORITY,
    )
    _require(
        _is_uuid4(bridge.bridge_id)
        and _is_uuid4(bridge.journal_incarnation)
        and all(
            HEX64.fullmatch(value) is not None
            for value in (
                bridge.security_context_digest,
                bridge.prior_installed_head_digest,
                bridge.last_old_event_digest,
                bridge.first_successor_proposal_frame_digest,
            )
        )
        and _safe_int(bridge.last_old_global_event_sequence)
        and _is_uuid4(bridge.prior_clock_incarnation)
        and _is_uuid4(bridge.successor_clock_incarnation)
        and bridge.successor_clock_incarnation != bridge.prior_clock_incarnation
        and _safe_int(bridge.bridge_global_event_sequence)
        and _safe_int(bridge.bridge_local_time)
        and _is_uuid4(bridge.first_successor_command_id)
        and bridge.first_successor_state in {"received", "admitted", *TERMINAL_STATES}
        and _safe_int(bridge.first_successor_global_event_sequence)
        and bridge.bridge_digest == sealed.protected_bridge.body_digest
        and sealed.protected_bridge.authority_receipt.clock_domain == "body-monotonic"
        and sealed.protected_bridge.authority_receipt.clock_incarnation
        == bridge.successor_clock_incarnation
        and sealed.protected_bridge.authority_receipt.event_time
        == bridge.bridge_local_time,
        "body clock bridge is malformed or sealed in the wrong clock domain",
        CaptureError,
    )


