def _fail_safe_journal_genesis(
    journal_incarnation: str,
    active_command_tips: tuple[CommandTip, ...],
    terminal_command_tips: tuple[CommandTip, ...],
) -> str:
    return _digest(
        {
            "active_command_tips": active_command_tips,
            "generation": GENERATION,
            "journal_incarnation": journal_incarnation,
            "logical_session": SESSION,
            "state": "body-fail-safe-side-effect-journal-genesis",
            "terminal_command_tips": terminal_command_tips,
        }
    )


class BodyFailSafeSideEffectJournalBuilder:
    def __init__(
        self,
        journal_incarnation: str,
        *,
        active_command_tips: tuple[CommandTip, ...],
        terminal_command_tips: tuple[CommandTip, ...],
    ) -> None:
        self.journal_incarnation = journal_incarnation
        self.active_command_tips = tuple(sorted(active_command_tips))
        self.terminal_command_tips = tuple(sorted(terminal_command_tips))
        self.transitions: list[BodyFailSafeSideEffectJournalTransition] = []
        self.pending_operations: dict[str, BodyActuationArbiterPendingOperation] = {}
        self.unresolved: set[str] = set()
        self.effects: dict[str, tuple[str, ...]] = {}
        self.arbiter_results: dict[str, str] = {}
        self.body_completions: set[str] = set()
        self.prior_head = _fail_safe_journal_genesis(
            journal_incarnation,
            self.active_command_tips,
            self.terminal_command_tips,
        )

    def _append(self, transition_kind: str, event_digest: str) -> None:
        transition = BodyFailSafeSideEffectJournalTransition(
            len(self.transitions) + 1,
            transition_kind,
            event_digest,
            self.prior_head,
            "",
            tuple(sorted(self.unresolved)),
            self.active_command_tips,
            self.terminal_command_tips,
        )
        transition = replace(
            transition,
            installed_head_digest=_fail_safe_transition_digest(transition),
        )
        self.transitions.append(transition)
        self.prior_head = transition.installed_head_digest

    def append_pending_operation(
        self,
        operation: BodyActuationArbiterPendingOperation,
    ) -> None:
        _require(
            operation.journal_incarnation == self.journal_incarnation
            and operation.operation_digest not in self.pending_operations
            and operation.operation_digest
            == _body_actuation_pending_operation_digest(operation),
            "body actuation pending operation is stale, replayed, or foreign",
            CaptureError,
        )
        self.pending_operations[operation.operation_digest] = operation
        self._append("arbiter_pending", operation.operation_digest)

    def append_reservation(
        self,
        reservation: BodyFailSafeSideEffectReservation,
    ) -> None:
        pending = self.pending_operations.get(
            reservation.arbiter_pending_operation_digest
        )
        _require(
            pending is not None
            and reservation.journal_incarnation == self.journal_incarnation
            and reservation.reservation_digest not in self.unresolved
            and pending.expected_body_reservation_id == reservation.reservation_id
            and pending.attempt_digest == reservation.attempt_digest
            and pending.restrictive_token_id == reservation.restrictive_token_id
            and pending.fence_epoch == reservation.fence_epoch
            and reservation.reservation_digest
            == _fail_safe_reservation_digest(reservation),
            "body fail-safe mirror does not consume the exact pending operation",
            CaptureError,
        )
        self.unresolved.add(reservation.reservation_digest)
        self._append("body_reservation_mirror", reservation.reservation_digest)

    def append_record(self, record: BodyFailSafeSideEffectRecord) -> None:
        _require(
            record.reservation_digest in self.unresolved
            and record.reservation_digest not in self.effects
            and record.record_digest == _fail_safe_side_effect_record_digest(record),
            "fail-safe side effect lacks one durable unresolved reservation",
            CaptureError,
        )
        self.effects[record.reservation_digest] = record.side_effects
        self._append("physical_boundary_invocation", record.record_digest)

    def append_arbiter_resolution(
        self,
        resolution: BodyActuationArbiterResolution,
    ) -> None:
        _require(
            resolution.reservation_digest in self.unresolved
            and resolution.reservation_digest in self.effects
            and resolution.reservation_digest not in self.arbiter_results
            and resolution.resolution_digest
            == _body_actuation_arbiter_resolution_digest(resolution),
            "arbiter result lacks its single unresolved physical invocation",
            CaptureError,
        )
        self.arbiter_results[resolution.reservation_digest] = (
            resolution.resolution_digest
        )
        self._append("arbiter_resolution", resolution.resolution_digest)

    def append_resolution(
        self,
        resolution: BodyFailSafeSideEffectResolution,
    ) -> None:
        _require(
            resolution.reservation_digest in self.unresolved
            and resolution.reservation_digest in self.effects
            and self.arbiter_results.get(resolution.reservation_digest)
            == resolution.arbiter_resolution_digest
            and resolution.reservation_digest not in self.body_completions
            and resolution.resolution_digest
            == _fail_safe_resolution_digest(resolution),
            "body completion lacks its exact installed arbiter result",
            CaptureError,
        )
        self.unresolved.remove(resolution.reservation_digest)
        self.body_completions.add(resolution.reservation_digest)
        self._append("body_completion", resolution.resolution_digest)

    def append_association(
        self,
        association: BodyFailSafeEffectAssociation,
        *,
        body_completion: BodyFailSafeSideEffectResolution,
        attempt_resolution: CommandIngressAttemptResolution,
    ) -> None:
        _require(
            body_completion.reservation_digest in self.body_completions
            and association.body_completion_digest == body_completion.resolution_digest
            and association.attempt_resolution_digest
            == attempt_resolution.resolution_digest
            and not association.additional_side_effect_performed
            and association.association_digest
            == _fail_safe_effect_association_digest(association),
            "post-admission association precedes completion or repeats actuation",
            CaptureError,
        )
        self._append("post_admission_association", association.association_digest)

    def installed_head(self, *, installed_at: int) -> BodyFailSafeSideEffectJournalHead:
        if self.unresolved:
            active_state = "BLOCKED_UNRESOLVED_RESERVATION"
        elif any("ESTOP_LATCHED" in effects for effects in self.effects.values()):
            active_state = "BLOCKED_ESTOP_LATCHED"
        elif any(
            "ACTIVE_AUTHORITY_CLEARED" in effects for effects in self.effects.values()
        ):
            active_state = "BLOCKED_HOLD"
        else:
            active_state = "ENABLED"
        return BodyFailSafeSideEffectJournalHead(
            _u_for(("fail-safe-journal-head", self.journal_incarnation)),
            self.journal_incarnation,
            len(self.transitions),
            tuple(self.transitions),
            tuple(sorted(self.unresolved)),
            active_state,
            self.active_command_tips,
            self.terminal_command_tips,
            self.prior_head,
            installed_at,
            _seal_authority(
                receipt_id=_u_for(
                    ("fail-safe-journal-head-authority", self.journal_incarnation)
                ),
                domain="installed-body-fail-safe-side-effect-journal-head",
                subject_digest=self.prior_head,
                issuer=BODY_AUTHORITY,
                subject=BODY_AUTHORITY,
                clock_domain="body-monotonic",
                clock_incarnation=BODY_CLOCK_2,
                event_time=installed_at,
            ),
        )


