    envelope_digest: str
    manifest_authorized: bool
    minimum_context_accepted: bool
    remaining_semantics_evaluated: bool
    remaining_semantics_accepted: bool
    disposition_path: tuple[str, ...]
    new_disposition_appended: bool
    attempt: CommandIngressAttemptRecord | None
    attempt_resolution: CommandIngressAttemptResolution | None
    retained_command_chain: RetainedCommandIngressChain | None
    pending_operation: BodyActuationArbiterPendingOperation | None
