def _fail_safe_minimum_context_valid(
    envelope: BodyFailSafeIngressEnvelope,
    *,
    expected_security_context_digest: str,
    store: ContentStore,
) -> bool:
    if envelope.protected_envelope.body.byte_length > MAX_FAIL_SAFE_ENVELOPE_BYTES:
        return False
    try:
        _validate_protected_body(
            envelope.protected_envelope,
            _fail_safe_ingress_body(envelope),
            store=store,
            media_type="application/vnd.ncp.body-fail-safe-ingress+json",
            domain="body-fail-safe-ingress",
            issuer=SESSION_AUTHORITY,
            subject=BODY_AUTHORITY,
        )
    except CaptureError:
        return False
    receipt = envelope.protected_envelope.authority_receipt
    return (
        _is_uuid4(envelope.ingress_id)
        and envelope.envelope_digest == envelope.protected_envelope.body_digest
        and envelope.logical_session == SESSION
        and envelope.generation == GENERATION
        and envelope.security_context_digest == expected_security_context_digest
        and envelope.audience == BODY_AUTHORITY
        and envelope.mode_state == "UNAMBIGUOUS"
        and _is_uuid4(envelope.command_id)
        and receipt.clock_domain == "session-monotonic"
        and receipt.clock_incarnation == envelope.generation
    )


def _fail_safe_manifest_authorizes(
    envelope: BodyFailSafeIngressEnvelope,
    manifest: InstalledBodyFailSafeAuthorizationManifest,
) -> bool:
    try:
        _validate_body_fail_safe_authorization_manifest(manifest)
    except CaptureError:
        return False
    receipt = envelope.protected_envelope.authority_receipt
    return any(
        receipt.issuer_principal == rule.authenticated_issuer
        and envelope.actor_role == rule.authenticated_actor_role
        and envelope.plane == rule.plane
        and envelope.route == rule.route
        and envelope.audience == rule.audience
        and envelope.action in rule.permitted_actions
        for rule in manifest.route_rules
    )


def _fail_safe_remaining_semantics_valid(
    envelope: BodyFailSafeIngressEnvelope,
    *,
    expected_stream_declaration_digest: str,
    expected_stream_epoch: str,
    store: ContentStore,
) -> bool:
    try:
        payload = _bounded_json_object(store.get(envelope.semantic_payload))
    except CaptureError:
        return False
    return (
        envelope.action in {"ACTIVE", "HOLD", "ESTOP"}
        and envelope.stream_declaration_digest == expected_stream_declaration_digest
        and envelope.stream_epoch == expected_stream_epoch
        and _safe_int(envelope.sequence)
        and envelope.sequence > 0
        and envelope.freshness_state == "CURRENT"
        and envelope.replay_state == "FRESH"
        and envelope.semantic_payload.media_type
        == "application/vnd.ncp.body-fail-safe-command+json"
        and payload
        == {
            "action": envelope.action,
            "kind": "body-fail-safe-command-v1",
        }
    )


COMMAND_INGRESS_ATTEMPT_RESOLUTIONS = {
    "NEW_COMMAND_CHAIN",
    "REJECTED_BEFORE_COMMAND_IDENTITY",
}


def _received_command_authority_candidate(
    envelope: BodyFailSafeIngressEnvelope,
) -> CommandAuthorityCandidateEvidence:
    return _seal_command_authority_evidence(
        CommandAuthorityCandidateEvidence(
            phase="received",
            evidence_state=(
                "UNEVALUATED_RAW_BYTES"
                if envelope.authority_candidate is not None
                else "UNEVALUATED_ABSENCE"
            ),
            raw_candidate=envelope.authority_candidate,
            raw_candidate_digest=(
                envelope.authority_candidate.sha256
                if envelope.authority_candidate is not None
                else None
            ),
            verified_term_digest=None,
            verified_lease_id=None,
            verified_holder=None,
            evidence_digest="",
        )
    )


def _command_authority_candidate_values(
    envelope: BodyFailSafeIngressEnvelope,
    *,
    store: ContentStore,
) -> tuple[bool, str | None, str | None, str | None]:
    candidate = envelope.authority_candidate
    if candidate is None:
        return envelope.action == "ESTOP", None, None, None
    try:
        body = _bounded_json_object(store.get(candidate))
    except CaptureError:
        return False, None, None, None
    valid = (
        candidate.media_type == "application/vnd.ncp.command-authority-candidate+json"
        and body.get("kind") == "body-command-authority-lease-v1"
        and body.get("holder") == "command-authority"
        and isinstance(body.get("term_digest"), str)
        and HEX64.fullmatch(str(body.get("term_digest"))) is not None
        and isinstance(body.get("lease_id"), str)
        and _is_uuid4(str(body.get("lease_id")))
        and body.get("security_context_digest") == envelope.security_context_digest
        and body.get("clock_incarnation") == BODY_CLOCK_2
        and _safe_int(body.get("not_after"))
        and int(body["not_after"]) > 300
    )
    if not valid:
        return False, None, None, None
    return (
        True,
        str(body["term_digest"]),
        str(body["lease_id"]),
        str(body["holder"]),
    )


def _resolved_command_authority_evidence(
    envelope: BodyFailSafeIngressEnvelope,
    *,
    admitted: bool,
    store: ContentStore,
) -> CommandAuthorityCandidateEvidence:
    valid, term_digest, lease_id, holder = _command_authority_candidate_values(
        envelope,
        store=store,
    )
    permitted_estop_absence = (
        admitted
        and valid
        and envelope.action == "ESTOP"
        and envelope.authority_candidate is None
    )
    verified_lease = admitted and valid and envelope.authority_candidate is not None
    return _seal_command_authority_evidence(
        CommandAuthorityCandidateEvidence(
            phase="admitted" if admitted else "rejected",
            evidence_state=(
                "VERIFIED_BODY_LEASE"
                if verified_lease
                else "PERMITTED_ESTOP_ABSENCE"
                if permitted_estop_absence
                else "INVALID_OR_NOT_ADMITTED"
            ),
            raw_candidate=envelope.authority_candidate,
            raw_candidate_digest=(
                envelope.authority_candidate.sha256
                if envelope.authority_candidate is not None
                else None
            ),
            verified_term_digest=term_digest if verified_lease else None,
            verified_lease_id=lease_id if verified_lease else None,
            verified_holder=holder if verified_lease else None,
            evidence_digest="",
        )
    )


def _validate_command_authority_evidence_pair(
    received: CommandAuthorityCandidateEvidence,
    resolved: CommandAuthorityCandidateEvidence,
    *,
    envelope: BodyFailSafeIngressEnvelope,
    admitted: bool,
    store: ContentStore,
) -> None:
    expected_received = _received_command_authority_candidate(envelope)
    expected_resolved = _resolved_command_authority_evidence(
        envelope,
        admitted=admitted,
        store=store,
    )
    _require(
        received == expected_received
        and resolved == expected_resolved
        and received.phase == "received"
        and received.evidence_state in {"UNEVALUATED_RAW_BYTES", "UNEVALUATED_ABSENCE"}
        and received.verified_term_digest is None
        and received.verified_lease_id is None
        and received.verified_holder is None
        and (
            resolved.phase == "admitted"
            and resolved.evidence_state
            in {"VERIFIED_BODY_LEASE", "PERMITTED_ESTOP_ABSENCE"}
            or resolved.phase == "rejected"
            and resolved.evidence_state == "INVALID_OR_NOT_ADMITTED"
            and resolved.verified_term_digest is None
            and resolved.verified_lease_id is None
            and resolved.verified_holder is None
        ),
        "command authority candidate was evaluated early or laundered into "
        "verified rejected evidence",
        CaptureError,
    )


def _validate_command_ingress_attempt(
    attempt: CommandIngressAttemptRecord,
    *,
    envelope: BodyFailSafeIngressEnvelope,
    minimum_context_accepted: bool,
) -> None:
    _require(
        _is_uuid4(attempt.attempt_id)
        and _safe_int(attempt.attempt_ordinal)
        and attempt.attempt_ordinal > 0
        and attempt.ingress_envelope_digest == envelope.envelope_digest
        and attempt.side_effect_intent
        == (
            {
                "ACTIVE": "NONE_ACTIVE",
                "HOLD": "CLEAR_ACTIVE",
                "ESTOP": "CLEAR_AND_LATCH_ESTOP",
            }.get(envelope.action, "NONE_ACTIVE")
            if minimum_context_accepted
            else "NONE_ACTIVE"
        )
        and attempt.side_effect_intent
        in {"NONE_ACTIVE", "CLEAR_ACTIVE", "CLEAR_AND_LATCH_ESTOP"}
        and attempt.received_authority_candidate
        == _received_command_authority_candidate(envelope)
        and attempt.active_command_tips_before == attempt.active_command_tips_after
        and attempt.terminal_command_tips_before == attempt.terminal_command_tips_after
        and _safe_int(attempt.recorded_at)
        and attempt.attempt_digest == _command_ingress_attempt_digest(attempt),
        "command ingress attempt duplicates a command chain, loses maps, "
        "or uses an open resolution",
        CaptureError,
    )
    _validate_authority(
        attempt.authority_receipt,
        domain="body-command-ingress-attempt",
        subject_digest=attempt.attempt_digest,
        issuer=BODY_AUTHORITY,
        subject=BODY_AUTHORITY,
    )
    _require(
        attempt.authority_receipt.clock_domain == "body-monotonic"
        and attempt.authority_receipt.clock_incarnation == BODY_CLOCK_2
        and attempt.authority_receipt.event_time == attempt.recorded_at,
        "command ingress attempt uses the wrong body clock",
        CaptureError,
    )


def _validate_command_ingress_attempt_resolution(
    resolution: CommandIngressAttemptResolution,
    attempt: CommandIngressAttemptRecord,
    *,
    envelope: BodyFailSafeIngressEnvelope,
    minimum_context_accepted: bool,
    admitted: bool,
    store: ContentStore,
    expected_existing_chain: RetainedCommandIngressChain | None,
) -> None:
    before_identity = resolution.resolution == "REJECTED_BEFORE_COMMAND_IDENTITY"
    new_chain = resolution.resolution == "NEW_COMMAND_CHAIN"
    expected_resolution = (
        "REJECTED_BEFORE_COMMAND_IDENTITY"
        if not minimum_context_accepted
        else "NEW_COMMAND_CHAIN"
    )
    _require(
        _is_uuid4(resolution.resolution_id)
        and expected_existing_chain is None
        and resolution.attempt_digest == attempt.attempt_digest
        and resolution.resolution in COMMAND_INGRESS_ATTEMPT_RESOLUTIONS
        and resolution.resolution == expected_resolution
        and (
            before_identity
            and not minimum_context_accepted
            and resolution.command_id is None
            and resolution.command_identity_digest is None
            and resolution.existing_command_chain_digest is None
            and not resolution.new_disposition_path
            or not before_identity
            and minimum_context_accepted
            and resolution.command_id == envelope.command_id
            and resolution.command_identity_digest
            == _fail_safe_command_identity_digest(envelope)
            and (
                new_chain
                and resolution.existing_command_chain_digest is None
                and resolution.new_disposition_path
                in {
                    ("received", "admitted"),
                    ("received", "rejected"),
                }
            )
        )
        and resolution.active_command_tips_before
        == resolution.active_command_tips_after
        and resolution.terminal_command_tips_before
        == resolution.terminal_command_tips_after
        and attempt.recorded_at <= resolution.resolved_at
        and resolution.resolution_digest
        == _command_ingress_attempt_resolution_digest(resolution),
        "command ingress attempt resolution duplicates a command chain, "
        "loses maps, or uses an open result",
        CaptureError,
    )
    _validate_command_authority_evidence_pair(
        attempt.received_authority_candidate,
        resolution.resolved_authority_evidence,
        envelope=envelope,
        admitted=admitted,
        store=store,
    )
    _validate_authority(
        resolution.authority_receipt,
        domain="body-command-ingress-attempt-resolution",
        subject_digest=resolution.resolution_digest,
        issuer=BODY_AUTHORITY,
        subject=BODY_AUTHORITY,
    )
    _require(
        resolution.authority_receipt.clock_domain == "body-monotonic"
        and resolution.authority_receipt.clock_incarnation == BODY_CLOCK_2
        and resolution.authority_receipt.event_time == resolution.resolved_at,
        "command ingress attempt resolution uses the wrong body clock",
        CaptureError,
    )


def _validate_body_actuation_pending_operation(
    operation: BodyActuationArbiterPendingOperation,
    envelope: BodyFailSafeIngressEnvelope,
    attempt: CommandIngressAttemptRecord,
) -> None:
    _require(
        _is_uuid4(operation.operation_id)
        and _is_uuid4(operation.journal_incarnation)
        and operation.attempt_digest == attempt.attempt_digest
        and operation.ingress_envelope_digest == envelope.envelope_digest
        and operation.command_id == envelope.command_id
        and operation.action == envelope.action
        and operation.action in {"HOLD", "ESTOP"}
        and operation.actuation_authority_domain_key_digest
        == _actuation_authority_domain_key_digest()
        and _is_uuid4(operation.restrictive_token_id)
        and operation.fence_epoch > 0
        and _is_uuid4(operation.expected_body_reservation_id)
        and _safe_int(operation.started_at)
        and operation.operation_digest
        == _body_actuation_pending_operation_digest(operation),
        "body actuation arbiter pending operation is not exact or restrictive",
        CaptureError,
    )
    _validate_authority(
        operation.authority_receipt,
        domain="body-actuation-arbiter-pending-operation",
        subject_digest=operation.operation_digest,
        issuer=BODY_AUTHORITY,
        subject=BODY_AUTHORITY,
    )
    _require(
        operation.authority_receipt.clock_domain == "body-monotonic"
        and operation.authority_receipt.clock_incarnation == BODY_CLOCK_2
        and operation.authority_receipt.event_time == operation.started_at,
        "body actuation pending operation uses the wrong body clock",
        CaptureError,
    )


def _validate_fail_safe_reservation(
    reservation: BodyFailSafeSideEffectReservation,
    pending_operation: BodyActuationArbiterPendingOperation,
    envelope: BodyFailSafeIngressEnvelope,
    attempt: CommandIngressAttemptRecord,
) -> None:
    _require(
        _is_uuid4(reservation.reservation_id)
        and _is_uuid4(reservation.journal_incarnation)
        and reservation.reservation_id == pending_operation.expected_body_reservation_id
        and reservation.journal_incarnation == pending_operation.journal_incarnation
        and reservation.arbiter_pending_operation_digest
        == pending_operation.operation_digest
        and reservation.restrictive_token_id == pending_operation.restrictive_token_id
        and reservation.fence_epoch == pending_operation.fence_epoch
        and reservation.attempt_digest == attempt.attempt_digest
        and reservation.ingress_envelope_digest == envelope.envelope_digest
        and reservation.command_id == envelope.command_id
        and reservation.action == envelope.action
        and reservation.action in {"HOLD", "ESTOP"}
        and reservation.actuation_authority_domain_key_digest
        == pending_operation.actuation_authority_domain_key_digest
        == _actuation_authority_domain_key_digest()
        and _safe_int(reservation.reserved_at)
        and reservation.reservation_digest
        == _fail_safe_reservation_digest(reservation),
        "fail-safe reservation is not exact or is not for a non-Active action",
        CaptureError,
    )
    _validate_authority(
        reservation.authority_receipt,
        domain="body-fail-safe-side-effect-reservation",
        subject_digest=reservation.reservation_digest,
        issuer=BODY_AUTHORITY,
        subject=BODY_AUTHORITY,
    )
    _require(
        reservation.authority_receipt.clock_domain == "body-monotonic"
        and reservation.authority_receipt.clock_incarnation == BODY_CLOCK_2
        and reservation.authority_receipt.event_time == reservation.reserved_at,
        "fail-safe reservation uses the wrong body clock",
        CaptureError,
    )


def _validate_fail_safe_side_effect_record(
    record: BodyFailSafeSideEffectRecord,
    reservation: BodyFailSafeSideEffectReservation,
) -> None:
    expected_effects = {
        "HOLD": ("ACTIVE_AUTHORITY_CLEARED",),
        "ESTOP": ("ACTIVE_AUTHORITY_CLEARED", "ESTOP_LATCHED"),
    }[reservation.action]
    _require(
        _is_uuid4(record.record_id)
        and record.reservation_digest == reservation.reservation_digest
        and record.attempt_digest == reservation.attempt_digest
        and record.ingress_envelope_digest == reservation.ingress_envelope_digest
        and record.command_id == reservation.command_id
        and record.action == reservation.action
        and record.actuation_authority_domain_key_digest
        == reservation.actuation_authority_domain_key_digest
        == _actuation_authority_domain_key_digest()
        and record.side_effects == expected_effects
        and record.active_command_tips_before == record.active_command_tips_after
        and record.terminal_command_tips_before == record.terminal_command_tips_after
        and _safe_int(record.performed_at)
        and reservation.reserved_at <= record.performed_at
        and record.record_digest == _fail_safe_side_effect_record_digest(record),
        "fail-safe side effect changed command maps or performed the wrong effect",
        CaptureError,
    )
    _validate_authority(
        record.authority_receipt,
        domain="body-fail-safe-side-effect-record",
        subject_digest=record.record_digest,
        issuer=BODY_AUTHORITY,
        subject=BODY_AUTHORITY,
    )
    _require(
        record.authority_receipt.clock_domain == "body-monotonic"
        and record.authority_receipt.clock_incarnation == BODY_CLOCK_2
        and record.authority_receipt.event_time == record.performed_at,
        "fail-safe side effect record uses the wrong body clock",
        CaptureError,
    )


def _validate_body_actuation_arbiter_resolution(
    resolution: BodyActuationArbiterResolution,
    pending_operation: BodyActuationArbiterPendingOperation,
    reservation: BodyFailSafeSideEffectReservation,
    record: BodyFailSafeSideEffectRecord,
) -> None:
    expected_result = f"APPLIED_{reservation.action}"
    _require(
        _is_uuid4(resolution.resolution_id)
        and resolution.pending_operation_digest == pending_operation.operation_digest
        and resolution.reservation_digest == reservation.reservation_digest
        and resolution.side_effect_record_digest == record.record_digest
        and resolution.restrictive_token_id == pending_operation.restrictive_token_id
        and resolution.fence_epoch == pending_operation.fence_epoch
        and resolution.actuation_authority_domain_key_digest
        == pending_operation.actuation_authority_domain_key_digest
        == reservation.actuation_authority_domain_key_digest
        == record.actuation_authority_domain_key_digest
        == _actuation_authority_domain_key_digest()
        and resolution.boundary_result == expected_result
        and resolution.physical_invocation_count == 1
        and _safe_int(resolution.resolved_at)
        and record.performed_at <= resolution.resolved_at
        and resolution.resolution_digest
        == _body_actuation_arbiter_resolution_digest(resolution),
        "body actuation arbiter result is stale, duplicated, or unbound",
        CaptureError,
    )
    _validate_authority(
        resolution.authority_receipt,
        domain="body-actuation-arbiter-resolution",
        subject_digest=resolution.resolution_digest,
        issuer=BODY_AUTHORITY,
        subject=BODY_AUTHORITY,
    )
    _require(
        resolution.authority_receipt.clock_domain == "body-monotonic"
        and resolution.authority_receipt.clock_incarnation == BODY_CLOCK_2
        and resolution.authority_receipt.event_time == resolution.resolved_at,
        "body actuation arbiter result uses the wrong body clock",
        CaptureError,
    )


def _validate_fail_safe_resolution(
    resolution: BodyFailSafeSideEffectResolution,
    reservation: BodyFailSafeSideEffectReservation,
    record: BodyFailSafeSideEffectRecord,
    arbiter_resolution: BodyActuationArbiterResolution,
) -> None:
    expected_after = (
        "BLOCKED_ESTOP_LATCHED" if reservation.action == "ESTOP" else "BLOCKED_HOLD"
    )
    normal = (
        resolution.resolution_kind == "BODY_COMPLETE"
        and resolution.recovery_actuation == "NOT_APPLICABLE"
        and resolution.active_admission_before == "BLOCKED_UNRESOLVED_RESERVATION"
    )
    recovery = (
        resolution.resolution_kind == "BODY_COMPLETE_RECOVERY"
        and resolution.recovery_actuation == "NONE"
        and resolution.active_admission_before == "BLOCKED_UNRESOLVED_RESERVATION"
    )
    _require(
        _is_uuid4(resolution.resolution_id)
        and resolution.reservation_digest == reservation.reservation_digest
        and resolution.side_effect_record_digest == record.record_digest
        and resolution.arbiter_resolution_digest == arbiter_resolution.resolution_digest
        and resolution.attempt_digest == reservation.attempt_digest
        and resolution.attempt_resolution == "PENDING_COMMAND_ADMISSION"
        and resolution.command_id == reservation.command_id
        and resolution.action == reservation.action
        and resolution.actuation_authority_domain_key_digest
        == reservation.actuation_authority_domain_key_digest
        == record.actuation_authority_domain_key_digest
        == arbiter_resolution.actuation_authority_domain_key_digest
        == _actuation_authority_domain_key_digest()
        and (normal or recovery)
        and resolution.remaining_semantics_state == "NOT_EVALUATED"
        and resolution.disposition_path == ()
        and resolution.post_admission_association_state is None
        and not resolution.additional_side_effect_performed
        and resolution.active_admission_after == expected_after
        and resolution.active_command_tips_before
        == resolution.active_command_tips_after
        and resolution.terminal_command_tips_before
        == resolution.terminal_command_tips_after
        and _safe_int(resolution.resolved_at)
        and arbiter_resolution.resolved_at <= resolution.resolved_at
        and resolution.resolution_digest == _fail_safe_resolution_digest(resolution),
        "fail-safe resolution actuates on recovery, mutates maps, or "
        "launders disposition",
        CaptureError,
    )
    _validate_authority(
        resolution.authority_receipt,
        domain="body-fail-safe-side-effect-resolution",
        subject_digest=resolution.resolution_digest,
        issuer=BODY_AUTHORITY,
        subject=BODY_AUTHORITY,
    )
    _require(
        resolution.authority_receipt.clock_domain == "body-monotonic"
        and resolution.authority_receipt.clock_incarnation == BODY_CLOCK_2
        and resolution.authority_receipt.event_time == resolution.resolved_at,
        "fail-safe resolution uses the wrong body clock",
        CaptureError,
    )


def _validate_fail_safe_effect_association(
    association: BodyFailSafeEffectAssociation,
    *,
    attempt_resolution: CommandIngressAttemptResolution,
    body_completion: BodyFailSafeSideEffectResolution,
) -> None:
    expected_state = {
        "HOLD": "hold_effective",
        "ESTOP": "stop_latched",
    }[body_completion.action]
    expected_associated_path = (
        *association.admitted_disposition_path,
        expected_state,
    )
    _require(
        _is_uuid4(association.association_id)
        and association.attempt_resolution_digest
        == attempt_resolution.resolution_digest
        and association.body_completion_digest == body_completion.resolution_digest
        and association.command_id == body_completion.command_id
        and association.action == body_completion.action
        and association.association_state == expected_state
        and attempt_resolution.resolution == "NEW_COMMAND_CHAIN"
        and attempt_resolution.new_disposition_path == ("received", "admitted")
        and association.admitted_disposition_path
        == attempt_resolution.new_disposition_path
        and association.associated_disposition_path == expected_associated_path
        and not association.additional_side_effect_performed
        and _safe_int(association.associated_at)
        and attempt_resolution.resolved_at <= association.associated_at
        and body_completion.resolved_at < association.associated_at
        and association.association_digest
        == _fail_safe_effect_association_digest(association),
        "restrictive association is early, substituted, or re-actuating",
        CaptureError,
    )
    _validate_authority(
        association.authority_receipt,
        domain="body-fail-safe-effect-association",
        subject_digest=association.association_digest,
        issuer=BODY_AUTHORITY,
        subject=BODY_AUTHORITY,
    )
    _require(
        association.authority_receipt.clock_domain == "body-monotonic"
        and association.authority_receipt.clock_incarnation == BODY_CLOCK_2
        and association.authority_receipt.event_time == association.associated_at,
        "restrictive association uses the wrong body clock",
        CaptureError,
    )


def _validate_fail_safe_side_effect_journal(
    head: BodyFailSafeSideEffectJournalHead,
    *,
    active_command_tips: tuple[CommandTip, ...],
    terminal_command_tips: tuple[CommandTip, ...],
    pending_operations: tuple[BodyActuationArbiterPendingOperation, ...],
    reservations: tuple[BodyFailSafeSideEffectReservation, ...],
    records: tuple[BodyFailSafeSideEffectRecord, ...],
    arbiter_resolutions: tuple[BodyActuationArbiterResolution, ...],
    resolutions: tuple[BodyFailSafeSideEffectResolution, ...],
    attempt_resolutions: tuple[CommandIngressAttemptResolution, ...],
    associations: tuple[BodyFailSafeEffectAssociation, ...],
) -> None:
    pending_by_digest = {item.operation_digest: item for item in pending_operations}
    reservation_by_digest = {item.reservation_digest: item for item in reservations}
    record_by_digest = {item.record_digest: item for item in records}
    arbiter_resolution_by_digest = {
        item.resolution_digest: item for item in arbiter_resolutions
    }
    resolution_by_digest = {item.resolution_digest: item for item in resolutions}
    attempt_resolution_by_digest = {
        item.resolution_digest: item for item in attempt_resolutions
    }
    association_by_digest = {item.association_digest: item for item in associations}
    for operation in pending_operations:
        _require(
            _is_uuid4(operation.operation_id)
            and operation.journal_incarnation == head.journal_incarnation
            and HEX64.fullmatch(operation.attempt_digest) is not None
            and _is_uuid4(operation.command_id)
            and operation.action in {"HOLD", "ESTOP"}
            and operation.actuation_authority_domain_key_digest
            == _actuation_authority_domain_key_digest()
            and _is_uuid4(operation.restrictive_token_id)
            and operation.fence_epoch > 0
            and _is_uuid4(operation.expected_body_reservation_id)
            and operation.operation_digest
            == _body_actuation_pending_operation_digest(operation),
            "fail-safe journal carries a malformed arbiter pending operation",
            CaptureError,
        )
        _validate_authority(
            operation.authority_receipt,
            domain="body-actuation-arbiter-pending-operation",
            subject_digest=operation.operation_digest,
            issuer=BODY_AUTHORITY,
            subject=BODY_AUTHORITY,
        )
    for reservation in reservations:
        _require(
            _is_uuid4(reservation.reservation_id)
            and reservation.journal_incarnation == head.journal_incarnation
            and HEX64.fullmatch(reservation.attempt_digest) is not None
            and _is_uuid4(reservation.command_id)
            and reservation.action in {"HOLD", "ESTOP"}
            and reservation.actuation_authority_domain_key_digest
            == _actuation_authority_domain_key_digest()
            and _safe_int(reservation.reserved_at)
            and reservation.reservation_digest
            == _fail_safe_reservation_digest(reservation),
            "fail-safe journal carries a malformed reservation",
            CaptureError,
        )
        _validate_authority(
            reservation.authority_receipt,
            domain="body-fail-safe-side-effect-reservation",
            subject_digest=reservation.reservation_digest,
            issuer=BODY_AUTHORITY,
            subject=BODY_AUTHORITY,
        )
        _require(
            reservation.authority_receipt.clock_domain == "body-monotonic"
            and reservation.authority_receipt.clock_incarnation == BODY_CLOCK_2
            and reservation.authority_receipt.event_time == reservation.reserved_at,
            "fail-safe journal reservation uses the wrong body clock",
            CaptureError,
        )
    prior = _fail_safe_journal_genesis(
        head.journal_incarnation,
        tuple(sorted(active_command_tips)),
        tuple(sorted(terminal_command_tips)),
    )
    installed_pending: set[str] = set()
    unresolved: set[str] = set()
    effects: dict[str, tuple[str, ...]] = {}
    installed_arbiter_results: dict[str, str] = {}
    body_completions: set[str] = set()
    for index, transition in enumerate(head.transitions):
        _require(
            transition.state_version == index + 1
            and transition.prior_head_digest == prior
            and transition.installed_head_digest
            == _fail_safe_transition_digest(transition)
            and transition.active_command_tips == tuple(sorted(active_command_tips))
            and transition.terminal_command_tips
            == tuple(sorted(terminal_command_tips)),
            "fail-safe journal transition forked or changed command maps",
            CaptureError,
        )
        if transition.transition_kind == "arbiter_pending":
            pending_operation = pending_by_digest.get(transition.event_digest)
            _require(
                pending_operation is not None
                and pending_operation.operation_digest not in installed_pending,
                "fail-safe journal pending operation is absent or replayed",
                CaptureError,
            )
            installed_pending.add(pending_operation.operation_digest)
        elif transition.transition_kind == "body_reservation_mirror":
            reservation = reservation_by_digest.get(transition.event_digest)
            pending_operation = (
                pending_by_digest.get(reservation.arbiter_pending_operation_digest)
                if reservation is not None
                else None
            )
            _require(
                reservation is not None
                and pending_operation is not None
                and pending_operation.operation_digest in installed_pending
                and reservation.reservation_digest not in unresolved,
                "fail-safe journal reservation is absent or replayed",
                CaptureError,
            )
            _require(
                pending_operation.expected_body_reservation_id
                == reservation.reservation_id
                and pending_operation.restrictive_token_id
                == reservation.restrictive_token_id
                and pending_operation.fence_epoch == reservation.fence_epoch
                and pending_operation.actuation_authority_domain_key_digest
                == reservation.actuation_authority_domain_key_digest,
                "body reservation mirror is not bound to the pending operation",
                CaptureError,
            )
            unresolved.add(reservation.reservation_digest)
        elif transition.transition_kind == "physical_boundary_invocation":
            record = record_by_digest.get(transition.event_digest)
            _require(
                record is not None
                and record.reservation_digest in unresolved
                and record.reservation_digest not in effects,
                "fail-safe journal side effect lacks its unresolved reservation",
                CaptureError,
            )
            reservation = reservation_by_digest[record.reservation_digest]
            _validate_fail_safe_side_effect_record(record, reservation)
            effects[record.reservation_digest] = record.side_effects
        elif transition.transition_kind == "arbiter_resolution":
            arbiter_resolution = arbiter_resolution_by_digest.get(
                transition.event_digest
            )
            _require(
                arbiter_resolution is not None
                and arbiter_resolution.reservation_digest in unresolved
                and arbiter_resolution.reservation_digest in effects
                and arbiter_resolution.reservation_digest
                not in installed_arbiter_results,
                "fail-safe arbiter result is absent, early, or replayed",
                CaptureError,
            )
            reservation = reservation_by_digest[arbiter_resolution.reservation_digest]
            pending_operation = pending_by_digest[
                reservation.arbiter_pending_operation_digest
            ]
            record = record_by_digest[arbiter_resolution.side_effect_record_digest]
            _validate_body_actuation_arbiter_resolution(
                arbiter_resolution,
                pending_operation,
                reservation,
                record,
            )
            installed_arbiter_results[arbiter_resolution.reservation_digest] = (
                arbiter_resolution.resolution_digest
            )
        elif transition.transition_kind == "body_completion":
            resolution = resolution_by_digest.get(transition.event_digest)
            _require(
                resolution is not None
                and resolution.reservation_digest in unresolved
                and installed_arbiter_results.get(resolution.reservation_digest)
                == resolution.arbiter_resolution_digest,
                "fail-safe journal resolution is absent or already resolved",
                CaptureError,
            )
            record = next(
                (
                    item
                    for item in records
                    if item.reservation_digest == resolution.reservation_digest
                ),
                None,
            )
            _require(record is not None, "fail-safe resolution record is absent")
            if record is None:
                raise CaptureError("validated fail-safe record is absent")
            reservation = reservation_by_digest[resolution.reservation_digest]
            arbiter_resolution = arbiter_resolution_by_digest[
                resolution.arbiter_resolution_digest
            ]
            _validate_fail_safe_resolution(
                resolution,
                reservation,
                record,
                arbiter_resolution,
            )
            unresolved.remove(resolution.reservation_digest)
            body_completions.add(resolution.resolution_digest)
        elif transition.transition_kind == "post_admission_association":
            association = association_by_digest.get(transition.event_digest)
            attempt_resolution = (
                attempt_resolution_by_digest.get(association.attempt_resolution_digest)
                if association is not None
                else None
            )
            body_completion = (
                resolution_by_digest.get(association.body_completion_digest)
                if association is not None
                else None
            )
            _require(
                association is not None
                and attempt_resolution is not None
                and body_completion is not None
                and association.body_completion_digest in body_completions
                and not association.additional_side_effect_performed,
                "fail-safe association is absent, early, or re-actuating",
                CaptureError,
            )
            _validate_fail_safe_effect_association(
                association,
                attempt_resolution=attempt_resolution,
                body_completion=body_completion,
            )
        else:
            raise CaptureError("unknown fail-safe journal transition")
        _require(
            transition.unresolved_reservation_digests == tuple(sorted(unresolved)),
            "fail-safe journal unresolved reservation set is stale",
            CaptureError,
        )
        prior = transition.installed_head_digest
    transition_kinds = tuple(item.transition_kind for item in head.transitions)
    required_prefix = (
        "arbiter_pending",
        "body_reservation_mirror",
        "physical_boundary_invocation",
        "arbiter_resolution",
        "body_completion",
        "post_admission_association",
    )
    _require(
        transition_kinds == required_prefix[: len(transition_kinds)],
        "fail-safe journal does not follow the unified physical-boundary DAG",
        CaptureError,
    )
    expected_active_state = (
        "BLOCKED_UNRESOLVED_RESERVATION"
        if unresolved
        else "BLOCKED_ESTOP_LATCHED"
        if any("ESTOP_LATCHED" in item for item in effects.values())
        else "BLOCKED_HOLD"
        if any("ACTIVE_AUTHORITY_CLEARED" in item for item in effects.values())
        else "ENABLED"
    )
    _require(
        _is_uuid4(head.head_id)
        and _is_uuid4(head.journal_incarnation)
        and head.state_version == len(head.transitions)
        and head.unresolved_reservation_digests == tuple(sorted(unresolved))
        and head.active_admission_state == expected_active_state
        and head.active_command_tips == tuple(sorted(active_command_tips))
        and head.terminal_command_tips == tuple(sorted(terminal_command_tips))
        and head.current_head_digest == prior
        and _safe_int(head.installed_at),
        "installed fail-safe journal head is stale or changes command maps",
        CaptureError,
    )
    _validate_authority(
        head.authority_receipt,
        domain="installed-body-fail-safe-side-effect-journal-head",
        subject_digest=head.current_head_digest,
        issuer=BODY_AUTHORITY,
        subject=BODY_AUTHORITY,
    )
    _require(
        head.authority_receipt.clock_domain == "body-monotonic"
        and head.authority_receipt.clock_incarnation == BODY_CLOCK_2
        and head.authority_receipt.event_time == head.installed_at,
        "installed fail-safe journal head uses the wrong body clock",
        CaptureError,
    )


def _evaluate_fail_safe_ingress(
    envelope: BodyFailSafeIngressEnvelope,
    *,
    installed_authorization_manifest: InstalledBodyFailSafeAuthorizationManifest,
    expected_security_context_digest: str,
    expected_stream_declaration_digest: str,
    expected_stream_epoch: str,
    active_command_tips: tuple[CommandTip, ...],
    terminal_command_tips: tuple[CommandTip, ...],
    store: ContentStore,
    crash_after_side_effect: bool = False,
    known_command_chains: Mapping[str, RetainedCommandIngressChain] | None = None,
    attempt_ordinal: int = 1,
) -> BodyFailSafeIngressEvaluation:
    known_chains = dict(known_command_chains or {})
    authenticated_context = _fail_safe_minimum_context_valid(
        envelope,
        expected_security_context_digest=expected_security_context_digest,
        store=store,
    )
    manifest_authorized = authenticated_context and _fail_safe_manifest_authorizes(
        envelope,
        installed_authorization_manifest,
    )
    if authenticated_context and not manifest_authorized:
        return BodyFailSafeIngressEvaluation(
            envelope_digest=envelope.envelope_digest,
            manifest_authorized=False,
            minimum_context_accepted=False,
            remaining_semantics_evaluated=False,
            remaining_semantics_accepted=False,
            disposition_path=("manifest_authorization_denied",),
            new_disposition_appended=False,
            attempt=None,
            attempt_resolution=None,
            retained_command_chain=None,
            pending_operation=None,
            reservation=None,
            side_effect_record=None,
            arbiter_resolution=None,
            resolution=None,
            association=None,
            side_effect_journal_head=None,
        )
    minimum = authenticated_context and manifest_authorized
    if minimum:
        command_identity = _fail_safe_command_identity_digest(envelope)
        existing_chain = known_chains.get(envelope.command_id)
        if existing_chain is not None:
            _require(
                existing_chain.command_id == envelope.command_id
                and _is_uuid4(existing_chain.command_id)
                and HEX64.fullmatch(existing_chain.command_identity_digest) is not None
                and existing_chain.disposition_path
                in {
                    ("received", "admitted"),
                    ("received", "admitted", "hold_effective"),
                    ("received", "admitted", "stop_latched"),
                    ("received", "rejected"),
                }
                and existing_chain.chain_digest
                == _retained_command_chain_digest(existing_chain),
                "known command chain is malformed or belongs to another identity",
                CaptureError,
            )
            exact_replay = existing_chain.command_identity_digest == command_identity
            return BodyFailSafeIngressEvaluation(
                envelope_digest=envelope.envelope_digest,
                manifest_authorized=True,
                minimum_context_accepted=True,
                remaining_semantics_evaluated=False,
                remaining_semantics_accepted=False,
                disposition_path=(
                    existing_chain.disposition_path
                    if exact_replay
                    else ("identity_conflict_rejected_before_durable_attempt",)
                ),
                new_disposition_appended=False,
                attempt=None,
                attempt_resolution=None,
                retained_command_chain=existing_chain,
                pending_operation=None,
                reservation=None,
                side_effect_record=None,
                arbiter_resolution=None,
                resolution=None,
                association=None,
                side_effect_journal_head=None,
            )
    attempt = _seal_command_ingress_attempt(
        CommandIngressAttemptRecord(
            attempt_id=_u_for(
                (
                    "body-command-ingress-attempt",
                    envelope.envelope_digest,
                    attempt_ordinal,
                )
            ),
            attempt_ordinal=attempt_ordinal,
            ingress_envelope_digest=envelope.envelope_digest,
            side_effect_intent=(
                {
                    "ACTIVE": "NONE_ACTIVE",
                    "HOLD": "CLEAR_ACTIVE",
                    "ESTOP": "CLEAR_AND_LATCH_ESTOP",
                }.get(envelope.action, "NONE_ACTIVE")
                if minimum
                else "NONE_ACTIVE"
            ),
            received_authority_candidate=_received_command_authority_candidate(
                envelope
            ),
            active_command_tips_before=tuple(sorted(active_command_tips)),
            active_command_tips_after=tuple(sorted(active_command_tips)),
            terminal_command_tips_before=tuple(sorted(terminal_command_tips)),
            terminal_command_tips_after=tuple(sorted(terminal_command_tips)),
            recorded_at=300,
            attempt_digest="",
            authority_receipt=_pending_authority(88_000 + attempt_ordinal),
        )
    )
    _validate_command_ingress_attempt(
        attempt,
        envelope=envelope,
        minimum_context_accepted=minimum,
    )

    def resolve_attempt(
        *,
        outcome: str,
        existing_chain: RetainedCommandIngressChain | None,
        new_path: tuple[str, ...],
        admitted: bool,
        resolved_at: int,
    ) -> CommandIngressAttemptResolution:
        resolution = _seal_command_ingress_attempt_resolution(
            CommandIngressAttemptResolution(
                resolution_id=_u_for(
                    (
                        "body-command-ingress-attempt-resolution",
                        attempt.attempt_digest,
                    )
                ),
                attempt_digest=attempt.attempt_digest,
                command_id=(envelope.command_id if minimum else None),
                command_identity_digest=(
                    _fail_safe_command_identity_digest(envelope) if minimum else None
                ),
                resolution=outcome,
                existing_command_chain_digest=(
                    existing_chain.chain_digest if existing_chain is not None else None
                ),
                new_disposition_path=new_path,
                resolved_authority_evidence=(
                    _resolved_command_authority_evidence(
                        envelope,
                        admitted=admitted,
                        store=store,
                    )
                ),
                active_command_tips_before=tuple(sorted(active_command_tips)),
                active_command_tips_after=tuple(sorted(active_command_tips)),
                terminal_command_tips_before=tuple(sorted(terminal_command_tips)),
                terminal_command_tips_after=tuple(sorted(terminal_command_tips)),
                resolved_at=resolved_at,
                resolution_digest="",
                authority_receipt=_pending_authority(88_100 + attempt_ordinal),
            )
        )
        _validate_command_ingress_attempt_resolution(
            resolution,
            attempt,
            envelope=envelope,
            minimum_context_accepted=minimum,
            admitted=admitted,
            store=store,
            expected_existing_chain=existing_chain,
        )
        return resolution

    if not minimum:
        attempt_resolution = resolve_attempt(
            outcome="REJECTED_BEFORE_COMMAND_IDENTITY",
            existing_chain=None,
            new_path=(),
            admitted=False,
            resolved_at=301,
        )
        return BodyFailSafeIngressEvaluation(
            envelope_digest=envelope.envelope_digest,
            manifest_authorized=False,
            minimum_context_accepted=False,
            remaining_semantics_evaluated=False,
            remaining_semantics_accepted=False,
            disposition_path=("pre_context_rejected",),
            new_disposition_appended=False,
            attempt=attempt,
            attempt_resolution=attempt_resolution,
            retained_command_chain=None,
            pending_operation=None,
            reservation=None,
            side_effect_record=None,
            arbiter_resolution=None,
            resolution=None,
            association=None,
            side_effect_journal_head=None,
        )
    command_identity = _fail_safe_command_identity_digest(envelope)
    existing_chain = None
    attempt_outcome = "NEW_COMMAND_CHAIN"

    pending_operation: BodyActuationArbiterPendingOperation | None = None
    reservation: BodyFailSafeSideEffectReservation | None = None
    record: BodyFailSafeSideEffectRecord | None = None
    arbiter_resolution: BodyActuationArbiterResolution | None = None
    association: BodyFailSafeEffectAssociation | None = None
    builder: BodyFailSafeSideEffectJournalBuilder | None = None
    if envelope.action in {"HOLD", "ESTOP"}:
        journal_incarnation = _u_for(
            ("body-fail-safe-side-effect-journal", attempt.attempt_digest)
        )
        reservation_id = _u_for(("fail-safe-reservation", attempt.attempt_digest))
        restrictive_token_id = _u_for(
            ("body-actuation-restrictive-token", attempt.attempt_digest)
        )
        builder = BodyFailSafeSideEffectJournalBuilder(
            journal_incarnation,
            active_command_tips=active_command_tips,
            terminal_command_tips=terminal_command_tips,
        )
        pending_operation = _seal_body_actuation_pending_operation(
            BodyActuationArbiterPendingOperation(
                operation_id=_u_for(
                    ("body-actuation-arbiter-operation", attempt.attempt_digest)
                ),
                journal_incarnation=journal_incarnation,
                attempt_digest=attempt.attempt_digest,
                ingress_envelope_digest=envelope.envelope_digest,
                command_id=envelope.command_id,
                action=envelope.action,
                actuation_authority_domain_key_digest=(
                    _actuation_authority_domain_key_digest()
                ),
                restrictive_token_id=restrictive_token_id,
                fence_epoch=attempt_ordinal,
                expected_body_reservation_id=reservation_id,
                started_at=301,
                operation_digest="",
                authority_receipt=_pending_authority(88_150 + attempt_ordinal),
            )
        )
        _validate_body_actuation_pending_operation(
            pending_operation,
            envelope,
            attempt,
        )
        builder.append_pending_operation(pending_operation)
        reservation = _seal_fail_safe_reservation(
            BodyFailSafeSideEffectReservation(
                reservation_id=reservation_id,
                journal_incarnation=journal_incarnation,
                arbiter_pending_operation_digest=(pending_operation.operation_digest),
                restrictive_token_id=restrictive_token_id,
                fence_epoch=pending_operation.fence_epoch,
                attempt_digest=attempt.attempt_digest,
                ingress_envelope_digest=envelope.envelope_digest,
                command_id=envelope.command_id,
                action=envelope.action,
                actuation_authority_domain_key_digest=(
                    pending_operation.actuation_authority_domain_key_digest
                ),
                reserved_at=302,
                reservation_digest="",
                authority_receipt=_pending_authority(88_200 + attempt_ordinal),
            )
        )
        _validate_fail_safe_reservation(
            reservation,
            pending_operation,
            envelope,
            attempt,
        )
        builder.append_reservation(reservation)
        side_effects = (
            ("ACTIVE_AUTHORITY_CLEARED", "ESTOP_LATCHED")
            if envelope.action == "ESTOP"
            else ("ACTIVE_AUTHORITY_CLEARED",)
        )
        record = _seal_fail_safe_side_effect_record(
            BodyFailSafeSideEffectRecord(
                record_id=_u_for(("fail-safe-side-effect", attempt.attempt_digest)),
                reservation_digest=reservation.reservation_digest,
                attempt_digest=attempt.attempt_digest,
                ingress_envelope_digest=envelope.envelope_digest,
                command_id=envelope.command_id,
                action=envelope.action,
                actuation_authority_domain_key_digest=(
                    reservation.actuation_authority_domain_key_digest
                ),
                side_effects=side_effects,
                active_command_tips_before=tuple(sorted(active_command_tips)),
                active_command_tips_after=tuple(sorted(active_command_tips)),
                terminal_command_tips_before=tuple(sorted(terminal_command_tips)),
                terminal_command_tips_after=tuple(sorted(terminal_command_tips)),
                performed_at=303,
                record_digest="",
                authority_receipt=_pending_authority(88_300 + attempt_ordinal),
            )
        )
        _validate_fail_safe_side_effect_record(record, reservation)
        builder.append_record(record)
        if crash_after_side_effect:
            head = builder.installed_head(installed_at=304)
            _validate_fail_safe_side_effect_journal(
                head,
                active_command_tips=active_command_tips,
                terminal_command_tips=terminal_command_tips,
                pending_operations=(pending_operation,),
                reservations=(reservation,),
                records=(record,),
                arbiter_resolutions=(),
                resolutions=(),
                attempt_resolutions=(),
                associations=(),
            )
            return BodyFailSafeIngressEvaluation(
                envelope_digest=envelope.envelope_digest,
                manifest_authorized=True,
                minimum_context_accepted=True,
                remaining_semantics_evaluated=False,
                remaining_semantics_accepted=False,
                disposition_path=(),
                new_disposition_appended=False,
                attempt=attempt,
                attempt_resolution=None,
                retained_command_chain=existing_chain,
                pending_operation=pending_operation,
                reservation=reservation,
                side_effect_record=record,
                arbiter_resolution=None,
                resolution=None,
                association=None,
                side_effect_journal_head=head,
            )
    else:
        _require(
            attempt.side_effect_intent == "NONE_ACTIVE",
            "Active or unknown command has non-absent side-effect intent",
            CaptureError,
        )

    resolution: BodyFailSafeSideEffectResolution | None = None
    head: BodyFailSafeSideEffectJournalHead | None = None
    if (
        pending_operation is not None
        and reservation is not None
        and record is not None
        and builder is not None
    ):
        arbiter_resolution = _seal_body_actuation_arbiter_resolution(
            BodyActuationArbiterResolution(
                resolution_id=_u_for(
                    ("body-actuation-arbiter-resolution", attempt.attempt_digest)
                ),
                pending_operation_digest=pending_operation.operation_digest,
                reservation_digest=reservation.reservation_digest,
                side_effect_record_digest=record.record_digest,
                restrictive_token_id=pending_operation.restrictive_token_id,
                fence_epoch=pending_operation.fence_epoch,
                actuation_authority_domain_key_digest=(
                    pending_operation.actuation_authority_domain_key_digest
                ),
                boundary_result=f"APPLIED_{envelope.action}",
                physical_invocation_count=1,
                resolved_at=304,
                resolution_digest="",
                authority_receipt=_pending_authority(88_350 + attempt_ordinal),
            )
        )
        _validate_body_actuation_arbiter_resolution(
            arbiter_resolution,
            pending_operation,
            reservation,
            record,
        )
        builder.append_arbiter_resolution(arbiter_resolution)
        resolution = _seal_fail_safe_resolution(
            BodyFailSafeSideEffectResolution(
                resolution_id=_u_for(("fail-safe-resolution", attempt.attempt_digest)),
                reservation_digest=reservation.reservation_digest,
                side_effect_record_digest=record.record_digest,
                arbiter_resolution_digest=arbiter_resolution.resolution_digest,
                attempt_digest=attempt.attempt_digest,
                attempt_resolution="PENDING_COMMAND_ADMISSION",
                command_id=envelope.command_id,
                action=envelope.action,
                actuation_authority_domain_key_digest=(
                    arbiter_resolution.actuation_authority_domain_key_digest
                ),
                resolution_kind="BODY_COMPLETE",
                remaining_semantics_state="NOT_EVALUATED",
                disposition_path=(),
                post_admission_association_state=None,
                additional_side_effect_performed=False,
                recovery_actuation="NOT_APPLICABLE",
                active_admission_before="BLOCKED_UNRESOLVED_RESERVATION",
                active_admission_after=(
                    "BLOCKED_ESTOP_LATCHED"
                    if envelope.action == "ESTOP"
                    else "BLOCKED_HOLD"
                ),
                active_command_tips_before=tuple(sorted(active_command_tips)),
                active_command_tips_after=tuple(sorted(active_command_tips)),
                terminal_command_tips_before=tuple(sorted(terminal_command_tips)),
                terminal_command_tips_after=tuple(sorted(terminal_command_tips)),
                resolved_at=305,
                resolution_digest="",
                authority_receipt=_pending_authority(88_400 + attempt_ordinal),
            )
        )
        _validate_fail_safe_resolution(
            resolution,
            reservation,
            record,
            arbiter_resolution,
        )
        builder.append_resolution(resolution)

    semantic_valid = _fail_safe_remaining_semantics_valid(
        envelope,
        expected_stream_declaration_digest=expected_stream_declaration_digest,
        expected_stream_epoch=expected_stream_epoch,
        store=store,
    )
    authority_valid = _command_authority_candidate_values(
        envelope,
        store=store,
    )[0]
    remaining_evaluated = True
    remaining = remaining_evaluated and semantic_valid and authority_valid
    admission_path = ("received", "admitted") if remaining else ("received", "rejected")
    attempt_resolution = resolve_attempt(
        outcome=attempt_outcome,
        existing_chain=existing_chain,
        new_path=admission_path,
        admitted=remaining,
        resolved_at=306 if resolution is not None else 303,
    )
    if resolution is not None and builder is not None and remaining:
        association = _seal_fail_safe_effect_association(
            BodyFailSafeEffectAssociation(
                association_id=_u_for(
                    ("fail-safe-effect-association", attempt.attempt_digest)
                ),
                attempt_resolution_digest=attempt_resolution.resolution_digest,
                body_completion_digest=resolution.resolution_digest,
                command_id=envelope.command_id,
                action=envelope.action,
                association_state=(
                    "stop_latched" if envelope.action == "ESTOP" else "hold_effective"
                ),
                admitted_disposition_path=admission_path,
                associated_disposition_path=(
                    *admission_path,
                    (
                        "stop_latched"
                        if envelope.action == "ESTOP"
                        else "hold_effective"
                    ),
                ),
                additional_side_effect_performed=False,
                associated_at=307,
                association_digest="",
                authority_receipt=_pending_authority(88_450 + attempt_ordinal),
            )
        )
        _validate_fail_safe_effect_association(
            association,
            attempt_resolution=attempt_resolution,
            body_completion=resolution,
        )
        builder.append_association(
            association,
            body_completion=resolution,
            attempt_resolution=attempt_resolution,
        )
    path = (
        association.associated_disposition_path
        if association is not None
        else admission_path
    )
    new_disposition_appended = True
    retained_chain = _seal_retained_command_chain(
        RetainedCommandIngressChain(
            envelope.command_id,
            command_identity,
            path,
            "",
        )
    )
    if (
        pending_operation is not None
        and reservation is not None
        and record is not None
        and arbiter_resolution is not None
        and resolution is not None
        and builder is not None
    ):
        head = builder.installed_head(installed_at=308)
        _validate_fail_safe_side_effect_journal(
            head,
            active_command_tips=active_command_tips,
            terminal_command_tips=terminal_command_tips,
            pending_operations=(pending_operation,),
            reservations=(reservation,),
            records=(record,),
            arbiter_resolutions=(arbiter_resolution,),
            resolutions=(resolution,),
            attempt_resolutions=(attempt_resolution,),
            associations=((association,) if association is not None else ()),
        )
    return BodyFailSafeIngressEvaluation(
        envelope_digest=envelope.envelope_digest,
        manifest_authorized=True,
        minimum_context_accepted=True,
        remaining_semantics_evaluated=remaining_evaluated,
        remaining_semantics_accepted=remaining,
        disposition_path=path,
        new_disposition_appended=new_disposition_appended,
        attempt=attempt,
        attempt_resolution=attempt_resolution,
        retained_command_chain=retained_chain,
        pending_operation=pending_operation,
        reservation=reservation,
        side_effect_record=record,
        arbiter_resolution=arbiter_resolution,
        resolution=resolution,
        association=association,
        side_effect_journal_head=head,
    )


def _recover_unresolved_fail_safe_ingress(
    crashed: BodyFailSafeIngressEvaluation,
    *,
    envelope: BodyFailSafeIngressEnvelope,
    store: ContentStore,
    active_command_tips: tuple[CommandTip, ...],
    terminal_command_tips: tuple[CommandTip, ...],
) -> BodyFailSafeIngressEvaluation:
    _require(
        crashed.minimum_context_accepted
        and crashed.manifest_authorized
        and crashed.attempt is not None
        and crashed.pending_operation is not None
        and crashed.reservation is not None
        and crashed.side_effect_record is not None
        and crashed.arbiter_resolution is None
        and crashed.attempt_resolution is None
        and crashed.retained_command_chain is None
        and crashed.resolution is None
        and crashed.association is None
        and crashed.envelope_digest == envelope.envelope_digest
        and crashed.side_effect_journal_head is not None
        and crashed.side_effect_journal_head.active_admission_state
        == "BLOCKED_UNRESOLVED_RESERVATION",
        "recovery input has no durable unresolved side effect",
        CaptureError,
    )
    pending_operation = crashed.pending_operation
    reservation = crashed.reservation
    record = crashed.side_effect_record
    command_identity = _fail_safe_command_identity_digest(envelope)
    attempt_outcome = "NEW_COMMAND_CHAIN"
    disposition_path = ("received", "rejected")
    new_path = disposition_path
    retained_chain = _seal_retained_command_chain(
        RetainedCommandIngressChain(
            envelope.command_id,
            command_identity,
            disposition_path,
            "",
        )
    )
    builder = BodyFailSafeSideEffectJournalBuilder(
        reservation.journal_incarnation,
        active_command_tips=active_command_tips,
        terminal_command_tips=terminal_command_tips,
    )
    builder.append_pending_operation(pending_operation)
    builder.append_reservation(reservation)
    builder.append_record(record)
    arbiter_resolution = _seal_body_actuation_arbiter_resolution(
        BodyActuationArbiterResolution(
            resolution_id=_u_for(
                (
                    "body-actuation-arbiter-recovery-resolution",
                    crashed.envelope_digest,
                )
            ),
            pending_operation_digest=pending_operation.operation_digest,
            reservation_digest=reservation.reservation_digest,
            side_effect_record_digest=record.record_digest,
            restrictive_token_id=pending_operation.restrictive_token_id,
            fence_epoch=pending_operation.fence_epoch,
            actuation_authority_domain_key_digest=(
                pending_operation.actuation_authority_domain_key_digest
            ),
            boundary_result=f"APPLIED_{reservation.action}",
            physical_invocation_count=1,
            resolved_at=304,
            resolution_digest="",
            authority_receipt=_pending_authority(88_350),
        )
    )
    _validate_body_actuation_arbiter_resolution(
        arbiter_resolution,
        pending_operation,
        reservation,
        record,
    )
    builder.append_arbiter_resolution(arbiter_resolution)
    resolution = _seal_fail_safe_resolution(
        BodyFailSafeSideEffectResolution(
            resolution_id=_u_for(
                ("fail-safe-recovery-resolution", crashed.envelope_digest)
            ),
            reservation_digest=reservation.reservation_digest,
            side_effect_record_digest=record.record_digest,
            arbiter_resolution_digest=arbiter_resolution.resolution_digest,
            attempt_digest=crashed.attempt.attempt_digest,
            attempt_resolution="PENDING_COMMAND_ADMISSION",
            command_id=reservation.command_id,
            action=reservation.action,
            actuation_authority_domain_key_digest=(
                arbiter_resolution.actuation_authority_domain_key_digest
            ),
            resolution_kind="BODY_COMPLETE_RECOVERY",
            remaining_semantics_state="NOT_EVALUATED",
            disposition_path=(),
            post_admission_association_state=None,
            additional_side_effect_performed=False,
            recovery_actuation="NONE",
            active_admission_before="BLOCKED_UNRESOLVED_RESERVATION",
            active_admission_after=(
                "BLOCKED_ESTOP_LATCHED"
                if reservation.action == "ESTOP"
                else "BLOCKED_HOLD"
            ),
            active_command_tips_before=tuple(sorted(active_command_tips)),
            active_command_tips_after=tuple(sorted(active_command_tips)),
            terminal_command_tips_before=tuple(sorted(terminal_command_tips)),
            terminal_command_tips_after=tuple(sorted(terminal_command_tips)),
            resolved_at=305,
            resolution_digest="",
            authority_receipt=_pending_authority(88_003),
        )
    )
    _validate_fail_safe_resolution(
        resolution,
        reservation,
        record,
        arbiter_resolution,
    )
    builder.append_resolution(resolution)
    attempt_resolution = _seal_command_ingress_attempt_resolution(
        CommandIngressAttemptResolution(
            _u_for(
                (
                    "body-command-ingress-recovery-resolution",
                    crashed.attempt.attempt_digest,
                )
            ),
            crashed.attempt.attempt_digest,
            envelope.command_id,
            command_identity,
            attempt_outcome,
            None,
            new_path,
            _resolved_command_authority_evidence(
                envelope,
                admitted=False,
                store=store,
            ),
            tuple(sorted(active_command_tips)),
            tuple(sorted(active_command_tips)),
            tuple(sorted(terminal_command_tips)),
            tuple(sorted(terminal_command_tips)),
            306,
            "",
            _pending_authority(88_500),
        )
    )
    _validate_command_ingress_attempt_resolution(
        attempt_resolution,
        crashed.attempt,
        envelope=envelope,
        minimum_context_accepted=True,
        admitted=False,
        store=store,
        expected_existing_chain=None,
    )
    head = builder.installed_head(installed_at=307)
    _validate_fail_safe_side_effect_journal(
        head,
        active_command_tips=active_command_tips,
        terminal_command_tips=terminal_command_tips,
        pending_operations=(pending_operation,),
        reservations=(reservation,),
        records=(record,),
        arbiter_resolutions=(arbiter_resolution,),
        resolutions=(resolution,),
        attempt_resolutions=(attempt_resolution,),
        associations=(),
    )
    return BodyFailSafeIngressEvaluation(
        envelope_digest=crashed.envelope_digest,
        manifest_authorized=crashed.manifest_authorized,
        minimum_context_accepted=True,
        remaining_semantics_evaluated=False,
        remaining_semantics_accepted=False,
        disposition_path=disposition_path,
        new_disposition_appended=attempt_outcome == "NEW_COMMAND_CHAIN",
        attempt=crashed.attempt,
        attempt_resolution=attempt_resolution,
        retained_command_chain=retained_chain,
        pending_operation=pending_operation,
        reservation=reservation,
        side_effect_record=record,
        arbiter_resolution=arbiter_resolution,
        resolution=resolution,
        association=None,
        side_effect_journal_head=head,
    )


@dataclass(frozen=True, slots=True)
class BodyBoundaryApplicationEvidence:
    application_id: str
    command_id: str
    proposal_frame_digest: str
    applied_record_digest: str
    admitted_record_digest: str
    prior_journal_head_digest: str
    installed_journal_head_digest: str
    boundary_name: str
    body_axis_contract_digest: str
    applied_value: ContentRef
    application_digest: str
    authority_receipt: AuthorityReceipt


def _application_digest(
    evidence: BodyBoundaryApplicationEvidence,
) -> str:
    return _body_digest(evidence, "application_digest", "authority_receipt")


def _seal_application(
    evidence: BodyBoundaryApplicationEvidence,
    *,
    body_local_time: int,
    body_clock_incarnation: str,
) -> BodyBoundaryApplicationEvidence:
    evidence = replace(evidence, application_digest=_application_digest(evidence))
    return replace(
        evidence,
        authority_receipt=_seal_authority(
            receipt_id=evidence.authority_receipt.receipt_id,
            domain="body-boundary-application",
            subject_digest=evidence.application_digest,
            issuer=BODY_AUTHORITY,
            subject=BODY_AUTHORITY,
            clock_domain="body-monotonic",
            clock_incarnation=body_clock_incarnation,
            event_time=body_local_time,
        ),
    )


def _validate_application(
    evidence: BodyBoundaryApplicationEvidence,
    *,
    head: DispositionJournalHead,
    records: tuple[SealedDisposition, ...],
    store: ContentStore,
) -> None:
    applied = next(
        (
            item.semantic_record
            for item in records
            if item.semantic_record.record_digest == evidence.applied_record_digest
        ),
        None,
    )
    transition = next(
        (
            item
            for item in head.transitions
            if item.transition_kind == "record_append"
            and item.event_digest == evidence.applied_record_digest
        ),
        None,
    )
    _require(
        applied is not None
        and transition is not None
        and applied.state == "applied"
        and evidence.command_id == applied.command_id
        and evidence.proposal_frame_digest == applied.proposal_frame_digest
        and evidence.admitted_record_digest == applied.admitted_record_digest
        and evidence.prior_journal_head_digest == transition.prior_head_digest
        and evidence.installed_journal_head_digest == transition.installed_head_digest
        and evidence.boundary_name == applied.boundary_name
        and evidence.body_axis_contract_digest == applied.body_axis_contract_digest
        and evidence.applied_value == applied.applied_value
        and evidence.applied_record_digest in head.retained_record_digests
        and (
            transition.installed_head_digest == head.current_head_digest
            or any(
                later.prior_head_digest == transition.installed_head_digest
                for later in head.transitions
            )
        )
        and evidence.application_digest == _application_digest(evidence),
        "application evidence is a losing sibling, stale head, or wrong body value",
        CaptureError,
    )
    store.get(evidence.applied_value)
    _validate_authority(
        evidence.authority_receipt,
        domain="body-boundary-application",
        subject_digest=evidence.application_digest,
        issuer=BODY_AUTHORITY,
        subject=BODY_AUTHORITY,
    )


@dataclass(frozen=True, slots=True)
class BodyRecordReceiverDelivery:
    delivery_id: str
    receiver_principal: str
    body_record_digest: str
    protected_record: ContentRef
    receiver_clock_incarnation: str
    received_at: int
    admission_receipt_digest: str
    delivery_digest: str
    authority_receipt: AuthorityReceipt


def _body_record_delivery_digest(
    delivery: BodyRecordReceiverDelivery,
) -> str:
    return _body_digest(delivery, "delivery_digest", "authority_receipt")


def _seal_body_record_delivery(
    sealed: SealedDisposition,
    *,
    receiver: str,
    receiver_clock: str,
    received_at: int,
    admission_receipt_digest: str,
    index: int,
) -> BodyRecordReceiverDelivery:
    delivery = BodyRecordReceiverDelivery(
        _u(63_000 + index),
        receiver,
        sealed.semantic_record.record_digest,
        sealed.protected_record.body,
        receiver_clock,
        received_at,
        admission_receipt_digest,
        "",
        _seal_authority(
            receipt_id=_u(64_000 + index),
            domain="body-record-receiver-delivery",
            subject_digest="0" * 64,
            issuer=INGRESS_AUTHORITY,
            subject=receiver,
            clock_domain="receiver-monotonic",
            clock_incarnation=receiver_clock,
            event_time=received_at,
        ),
    )
    delivery = replace(
        delivery,
        delivery_digest=_body_record_delivery_digest(delivery),
    )
    return replace(
        delivery,
        authority_receipt=_seal_authority(
            receipt_id=delivery.authority_receipt.receipt_id,
            domain="body-record-receiver-delivery",
            subject_digest=delivery.delivery_digest,
            issuer=INGRESS_AUTHORITY,
            subject=receiver,
            clock_domain="receiver-monotonic",
            clock_incarnation=receiver_clock,
            event_time=received_at,
        ),
    )


def _validate_body_record_delivery(
    delivery: BodyRecordReceiverDelivery,
    sealed: SealedDisposition,
    *,
    receiver_admission: ReceiverAdmissionReceipt,
    store: ContentStore,
) -> None:
    _validate_sealed_disposition(sealed, store=store)
    _require(
        _is_uuid4(delivery.delivery_id)
        and delivery.receiver_principal in {OBSERVER_A, OBSERVER_B}
        and delivery.body_record_digest == sealed.semantic_record.record_digest
        and delivery.protected_record == sealed.protected_record.body
        and _is_uuid4(delivery.receiver_clock_incarnation)
        and _safe_int(delivery.received_at)
        and delivery.admission_receipt_digest == receiver_admission.receipt_digest
        and receiver_admission.key.receiver_principal == delivery.receiver_principal
        and receiver_admission.receipt_digest
        == _admission_receipt_digest(receiver_admission)
        and delivery.delivery_digest == _body_record_delivery_digest(delivery),
        "body record receiver delivery changed the body-global identity",
        CaptureError,
    )
    _validate_authority(
        delivery.authority_receipt,
        domain="body-record-receiver-delivery",
        subject_digest=delivery.delivery_digest,
        issuer=INGRESS_AUTHORITY,
        subject=delivery.receiver_principal,
    )
    _validate_authority(
        receiver_admission.authority_receipt,
        domain=(
            "receiver-live-admission"
            if receiver_admission.phase == "live"
            else "receiver-history-admission"
        ),
        subject_digest=receiver_admission.receipt_digest,
        issuer=INGRESS_AUTHORITY,
        subject=delivery.receiver_principal,
    )


