@dataclass(frozen=True, slots=True)
class FrozenLanguageEmbeddingContract:
    mode: str
    instruction_content: ContentRef
    instruction_content_digest: str
    tokenizer_digest: str | None
    encoder_digest: str | None
    model_digest: str | None
    config_digest: str | None
    pooling: str | None
    runtime_digest: str | None
    opset_version: int | None
    backend: str | None
    precision: str | None
    determinism_profile_digest: str | None
    output_vector_digest: str | None
    member_order: tuple[str, ...]
    dimension: int
    numeric_domain: tuple[float, float]
    dtype: str
    categorical_vocabulary: ContentRef | None
    categorical_vocabulary_digest: str | None
    categorical_map: tuple[tuple[str, int], ...]
    unknown_policy: str | None
    missing_policy: str | None
    categorical_encoding: str | None
    transform_artifact: ContentRef
    execution_receipt: FrozenLanguageExecutionReceipt
    contract_digest: str


def _language_contract_digest(
    contract: FrozenLanguageEmbeddingContract,
) -> str:
    return _body_digest(contract, "contract_digest")


def _language_output_vector_digest(
    vector: list[Any],
    *,
    dtype: str,
) -> str:
    _require(
        dtype == "float64",
        "language output digest requires exact IEEE-754 binary64",
        CaptureError,
    )
    return hashlib.sha256(_language_output_bytes(vector)).hexdigest()


def _language_output_bytes(vector: list[Any]) -> bytes:
    _require(
        len(vector) <= 4096
        and all(
            type(value) in (int, float) and math.isfinite(float(value))
            for value in vector
        ),
        "language output vector is not bounded finite binary64",
        CaptureError,
    )
    return len(vector).to_bytes(8, "big") + b"".join(
        struct.pack(">d", float(value)) for value in vector
    )


def _language_execution_profile_digest(
    contract: FrozenLanguageEmbeddingContract,
    *,
    environment_digest: str,
) -> str:
    return _digest(
        {
            "contract_profile": _body(
                contract,
                "execution_receipt",
                "contract_digest",
            ),
            "environment_digest": environment_digest,
        }
    )


def _expected_language_environment(
    contract: FrozenLanguageEmbeddingContract,
    transform: Mapping[str, Any],
) -> dict[str, Any]:
    if contract.mode == "FROZEN_NEURAL_NUMERIC":
        return {
            "accelerator_model": None,
            "backend": contract.backend,
            "cpu_architecture": "x86_64",
            "deterministic_kernels": True,
            "device": "cpu:0",
            "driver_digest": None,
            "dtype": contract.dtype,
            "firmware_digest": None,
            "graph_digest": _digest("language-onnx-graph-v1"),
            "intra_op_threads": 1,
            "isa_digest": _digest("x86_64-v3-sse2-avx2"),
            "kernel_digest": _digest("linux-6.12.10"),
            "kind": "frozen-neural-execution-environment-v1",
            "library_closure_digest": _digest(
                {
                    "libraries": (
                        "libc-2.40",
                        "libm-2.40",
                        "onnxruntime-1.22.1",
                    )
                }
            ),
            "member_order": list(contract.member_order),
            "microcode_digest": _digest("synthetic-microcode-0x2f"),
            "model_config_digest": contract.config_digest,
            "model_digest": contract.model_digest,
            "opset_version": contract.opset_version,
            "operating_system_digest": _digest("linux-amd64-image-v1"),
            "padding": "fixed_length_128",
            "pooling": contract.pooling,
            "precision": contract.precision,
            "provider": "CPUExecutionProvider",
            "quantization": "NONE",
            "runtime_build_digest": _digest(
                {
                    "compiler": "clang-20.1.8",
                    "features": ("cpu", "deterministic"),
                    "runtime": "onnxruntime-1.22.1",
                }
            ),
            "runtime_executable_digest": contract.runtime_digest,
            "scheduling": "SEQUENTIAL",
            "seed": 0,
            "tokenizer_config_digest": _digest(
                {
                    "normalization": "NFC",
                    "padding": "fixed_length_128",
                    "truncation": "reject_over_128",
                }
            ),
            "tokenizer_digest": contract.tokenizer_digest,
            "transform_artifact_digest": contract.transform_artifact.sha256,
            "truncation": "reject_over_128",
        }
    return {
        "categorical_encoding": contract.categorical_encoding,
        "categorical_map": [
            [category, index] for category, index in contract.categorical_map
        ],
        "categorical_vocabulary_digest": contract.categorical_vocabulary_digest,
        "deterministic": True,
        "dtype": contract.dtype,
        "kind": "frozen-categorical-execution-environment-v1",
        "member_order": list(contract.member_order),
        "missing_policy": contract.missing_policy,
        "selected_category": transform.get("selected_category"),
        "transform_artifact_digest": contract.transform_artifact.sha256,
        "unknown_policy": contract.unknown_policy,
    }


def _build_prisoma_numeric_executor_evidence(
    contract: FrozenLanguageEmbeddingContract,
    transform: Mapping[str, Any],
    *,
    environment: ContentRef,
    output_bytes: ContentRef,
    event_time: int,
    index: int,
) -> PrisomaNumericExecutorEvidence:
    base = index * 100
    process_incarnation = _u(base + 1)
    trust_state_digest = _digest(
        {
            "authority": PRISOMA_AUTHORITY,
            "domain": "prisoma-numeric-executor-trust-state-v1",
            "security_state_digest": SECURITY_STATE_DIGEST,
        }
    )
    policy_head_digest = _digest(
        {
            "contract_profile": _body(
                contract,
                "execution_receipt",
                "contract_digest",
            ),
            "domain": "prisoma-numeric-executor-policy-head-v1",
        }
    )
    exact_input_digest = _digest(
        {
            "contract_profile": _body(
                contract,
                "execution_receipt",
                "contract_digest",
            ),
            "instruction_content_digest": contract.instruction_content_digest,
            "selected_category": transform.get("selected_category"),
            "transform_artifact_digest": contract.transform_artifact.sha256,
        }
    )
    operation_id = _u(base + 2)
    run_id = _u(base + 3)
    pending_operation = PrisomaNumericExecutorPendingOperation(
        operation_id=operation_id,
        run_id=run_id,
        process_incarnation=process_incarnation,
        trust_state_digest=trust_state_digest,
        policy_head_digest=policy_head_digest,
        mode=contract.mode,
        exact_input_digest=exact_input_digest,
        operation_digest="",
    )
    pending_operation = replace(
        pending_operation,
        operation_digest=_prisoma_numeric_executor_pending_operation_digest(
            pending_operation
        ),
    )
    operation_digest = pending_operation.operation_digest
    executable_digest = (
        contract.runtime_digest
        if contract.mode == "FROZEN_NEURAL_NUMERIC"
        else _digest(
            {
                "categorical_encoding": contract.categorical_encoding,
                "categorical_map": contract.categorical_map,
                "domain": "prisoma-frozen-categorical-executable-v1",
            }
        )
    )
    _require(
        executable_digest is not None
        and HEX64.fullmatch(executable_digest) is not None,
        "Prisoma numeric executor has no exact executable digest",
        CaptureError,
    )
    dependency_closure_digest = _digest(
        {
            "backend": contract.backend,
            "categorical_vocabulary_digest": (contract.categorical_vocabulary_digest),
            "domain": "prisoma-numeric-executor-dependency-closure-v1",
            "environment_digest": environment.sha256,
            "executable_digest": executable_digest,
            "runtime_digest": contract.runtime_digest,
        }
    )
    self_inspection_digest = _digest(
        {
            "dependency_closure_digest": dependency_closure_digest,
            "domain": "prisoma-numeric-executor-self-inspection-v1",
            "environment_digest": environment.sha256,
            "executable_digest": executable_digest,
            "process_incarnation": process_incarnation,
        }
    )
    execution_fact = PrisomaNumericExecutionFact(
        fact_id=_u(base + 4),
        operation_id=operation_id,
        run_id=run_id,
        process_incarnation=process_incarnation,
        trust_state_digest=trust_state_digest,
        policy_head_digest=policy_head_digest,
        result_variant=(
            "NEURAL_EXECUTION"
            if contract.mode == "FROZEN_NEURAL_NUMERIC"
            else "CATEGORICAL_EXECUTION"
        ),
        mode=contract.mode,
        exact_input_digest=exact_input_digest,
        instruction_content_digest=contract.instruction_content_digest,
        selected_category=(
            str(transform["selected_category"])
            if contract.mode == "FROZEN_CATEGORICAL_NUMERIC"
            else None
        ),
        environment_digest=environment.sha256,
        executable_digest=executable_digest,
        dependency_closure_digest=dependency_closure_digest,
        self_inspection_digest=self_inspection_digest,
        output_bytes_digest=output_bytes.sha256,
        output_dimension=contract.dimension,
        exclusion_reason=None,
        estimator_invoked=True,
        fact_digest="",
    )
    execution_fact = replace(
        execution_fact,
        fact_digest=_prisoma_numeric_execution_fact_digest(execution_fact),
    )
    exclusion_witnesses: list[PrisomaNumericExecutionFact] = []
    excluded_environment_digest = _digest(
        {
            "domain": "prisoma-numeric-executor-excluded-environment-v1",
            "mode": contract.mode,
            "state": "INPUT_EXCLUDED_BEFORE_EXECUTION_ENVIRONMENT_BINDING",
        }
    )
    excluded_self_inspection_digest = _digest(
        {
            "dependency_closure_digest": dependency_closure_digest,
            "domain": "prisoma-numeric-executor-excluded-self-inspection-v1",
            "environment_digest": excluded_environment_digest,
            "executable_digest": executable_digest,
            "process_incarnation": process_incarnation,
        }
    )
    for offset, reason in enumerate(
        ("SOURCE_ABSENT", "EMPTY", "UNBOUND", "PARSE_FAILED"),
        start=20,
    ):
        witness = PrisomaNumericExecutionFact(
            fact_id=_u(base + offset),
            operation_id=_u(base + offset + 10),
            run_id=_u(base + offset + 20),
            process_incarnation=process_incarnation,
            trust_state_digest=trust_state_digest,
            policy_head_digest=policy_head_digest,
            result_variant="INPUT_EXCLUDED",
            mode=contract.mode,
            exact_input_digest=_digest(
                {
                    "attempted_input_state": reason,
                    "domain": "prisoma-excluded-numeric-input-v1",
                    "expected_input_digest": exact_input_digest,
                }
            ),
            instruction_content_digest=contract.instruction_content_digest,
            selected_category=None,
            environment_digest=excluded_environment_digest,
            executable_digest=executable_digest,
            dependency_closure_digest=dependency_closure_digest,
            self_inspection_digest=excluded_self_inspection_digest,
            output_bytes_digest=None,
            output_dimension=None,
            exclusion_reason=reason,
            estimator_invoked=False,
            fact_digest="",
        )
        exclusion_witnesses.append(
            replace(
                witness,
                fact_digest=_prisoma_numeric_execution_fact_digest(witness),
            )
        )

    def seal_selector(
        selector: InstalledPrisomaNumericExecutorStateSelector,
        *,
        at: int,
    ) -> InstalledPrisomaNumericExecutorStateSelector:
        return _seal_installed_prisoma_numeric_executor_selector(
            selector,
            event_time=at,
        )

    uninitialized = seal_selector(
        InstalledPrisomaNumericExecutorStateSelector(
            selector_id=_u(base + 5),
            process_incarnation=process_incarnation,
            selector_version=0,
            state="UNINITIALIZED",
            ever_used=False,
            current_head_digest=None,
            prior_selector_digest=None,
            last_commit_digest=None,
            selector_digest="",
            authority_receipt=_pending_authority(base + 5),
        ),
        at=event_time - 2,
    )

    def seal_head(
        head: PrisomaNumericExecutorStateHead,
        *,
        at: int,
    ) -> PrisomaNumericExecutorStateHead:
        return _seal_prisoma_numeric_executor_head(head, event_time=at)

    def install(
        *,
        prior_head_digest: str,
        head: PrisomaNumericExecutorStateHead,
        prior_selector: InstalledPrisomaNumericExecutorStateSelector,
        transition_kind: str,
        operation_evidence_digest: str,
        commit_offset: int,
        selector_offset: int,
        at: int,
    ) -> tuple[
        PrisomaNumericExecutorStateCommitReceipt,
        InstalledPrisomaNumericExecutorStateSelector,
    ]:
        commit = _seal_prisoma_numeric_executor_commit(
            PrisomaNumericExecutorStateCommitReceipt(
                commit_id=_u(base + commit_offset),
                transition_kind=transition_kind,
                process_incarnation=process_incarnation,
                prior_head_digest=prior_head_digest,
                installed_head_digest=head.head_digest,
                installed_selector_version=prior_selector.selector_version + 1,
                operation_evidence_digest=operation_evidence_digest,
                commit_digest="",
                authority_receipt=_pending_authority(base + commit_offset),
            ),
            event_time=at,
        )
        selector = seal_selector(
            replace(
                prior_selector,
                selector_id=_u(base + selector_offset),
                selector_version=prior_selector.selector_version + 1,
                state="INSTALLED",
                ever_used=True,
                current_head_digest=head.head_digest,
                prior_selector_digest=prior_selector.selector_digest,
                last_commit_digest=commit.commit_digest,
                selector_digest="",
                authority_receipt=_pending_authority(base + selector_offset),
            ),
            at=at,
        )
        return commit, selector

    genesis = seal_head(
        PrisomaNumericExecutorStateHead(
            head_id=_u(base + 6),
            owner_principal=PRISOMA_AUTHORITY,
            executor_principal="prisoma-frozen-numeric-executor",
            process_incarnation=process_incarnation,
            trust_state_digest=trust_state_digest,
            policy_head_digest=policy_head_digest,
            state_version=1,
            bounded_pending_capacity=16,
            pending_operations=(),
            pending_operation_digests=(),
            consumed_operation_ids=(),
            consumed_run_ids=(),
            terminal_operation_bindings=(),
            terminal_execution_fact_digests=(),
            exclusion_tombstone_digests=(),
            execution_facts=(),
            prior_head_digest=None,
            head_digest="",
            authority_receipt=_pending_authority(base + 6),
        ),
        at=event_time - 2,
    )
    genesis_anchor = _digest(
        {
            "domain": "prisoma-numeric-executor-state-genesis-v1",
            "process_incarnation": process_incarnation,
            "selector_digest": uninitialized.selector_digest,
        }
    )
    genesis_commit, selector_1 = install(
        prior_head_digest=genesis_anchor,
        head=genesis,
        prior_selector=uninitialized,
        transition_kind="NUMERIC_EXECUTOR_GENESIS_FROM_UNINITIALIZED",
        operation_evidence_digest=_digest("empty-prisoma-numeric-executor"),
        commit_offset=7,
        selector_offset=8,
        at=event_time - 2,
    )
    pending = seal_head(
        replace(
            genesis,
            head_id=_u(base + 9),
            state_version=2,
            pending_operations=(pending_operation,),
            pending_operation_digests=(operation_digest,),
            prior_head_digest=genesis.head_digest,
            head_digest="",
            authority_receipt=_pending_authority(base + 9),
        ),
        at=event_time - 1,
    )
    pending_commit, selector_2 = install(
        prior_head_digest=genesis.head_digest,
        head=pending,
        prior_selector=selector_1,
        transition_kind="NUMERIC_EXECUTION_RESERVED",
        operation_evidence_digest=operation_digest,
        commit_offset=10,
        selector_offset=11,
        at=event_time - 1,
    )
    terminal = seal_head(
        replace(
            pending,
            head_id=_u(base + 12),
            state_version=3,
            pending_operations=(),
            pending_operation_digests=(),
            consumed_operation_ids=(execution_fact.operation_id,),
            consumed_run_ids=(execution_fact.run_id,),
            terminal_operation_bindings=(
                (
                    execution_fact.operation_id,
                    execution_fact.run_id,
                    execution_fact.fact_digest,
                ),
            ),
            terminal_execution_fact_digests=(execution_fact.fact_digest,),
            execution_facts=(execution_fact,),
            prior_head_digest=pending.head_digest,
            head_digest="",
            authority_receipt=_pending_authority(base + 12),
        ),
        at=event_time,
    )
    terminal_commit, selector_3 = install(
        prior_head_digest=pending.head_digest,
        head=terminal,
        prior_selector=selector_2,
        transition_kind="NUMERIC_EXECUTION_TERMINALIZED",
        operation_evidence_digest=execution_fact.fact_digest,
        commit_offset=13,
        selector_offset=14,
        at=event_time,
    )
    evidence = PrisomaNumericExecutorEvidence(
        evidence_id=_u(base + 15),
        execution_fact=execution_fact,
        input_exclusion_witnesses=tuple(exclusion_witnesses),
        uninitialized_selector=uninitialized,
        state_heads=(genesis, pending, terminal),
        state_commits=(genesis_commit, pending_commit, terminal_commit),
        selectors=(selector_1, selector_2, selector_3),
        installed_selector=selector_3,
        evidence_digest="",
        authority_receipt=_pending_authority(base + 15),
    )
    evidence = replace(
        evidence,
        evidence_digest=_prisoma_numeric_executor_evidence_digest(evidence),
    )
    return replace(
        evidence,
        authority_receipt=_seal_authority(
            receipt_id=evidence.authority_receipt.receipt_id,
            domain="prisoma-numeric-executor-evidence",
            subject_digest=evidence.evidence_digest,
            issuer=PRISOMA_AUTHORITY,
            subject="synthetic-evidence-auditor",
            clock_domain="prisoma-executor-monotonic",
            clock_incarnation=process_incarnation,
            event_time=event_time,
        ),
    )


def _build_language_execution_receipt(
    contract: FrozenLanguageEmbeddingContract,
    transform: Mapping[str, Any],
    vector: list[Any],
    *,
    store: ContentStore,
    event_time: int,
    index: int,
) -> FrozenLanguageExecutionReceipt:
    environment = store.put_json(
        _expected_language_environment(contract, transform),
        "application/vnd.prisoma.language-execution-environment+json",
    )
    output_bytes = store.put_bytes(
        _language_output_bytes(vector),
        "application/vnd.prisoma.language-output.binary64",
    )
    executor_evidence = _build_prisoma_numeric_executor_evidence(
        contract,
        transform,
        environment=environment,
        output_bytes=output_bytes,
        event_time=event_time,
        index=index,
    )
    return _seal_language_execution_receipt(
        FrozenLanguageExecutionReceipt(
            receipt_id=_u(index),
            mode=contract.mode,
            instruction_content=contract.instruction_content,
            instruction_content_digest=contract.instruction_content_digest,
            selected_category=(
                str(transform["selected_category"])
                if contract.mode == "FROZEN_CATEGORICAL_NUMERIC"
                else None
            ),
            environment_artifact=environment,
            environment_digest=environment.sha256,
            execution_profile_digest=_language_execution_profile_digest(
                contract,
                environment_digest=environment.sha256,
            ),
            output_bytes=output_bytes,
            output_bytes_digest=output_bytes.sha256,
            output_dimension=contract.dimension,
            replay_kat_id=(
                "categorical-one-hot-exact-replay-v1"
                if contract.mode == "FROZEN_CATEGORICAL_NUMERIC"
                else "neural-binary64-exact-replay-v1"
            ),
            executor_evidence=executor_evidence,
            receipt_digest="",
            authority_receipt=_pending_authority(index),
        ),
        event_time=event_time,
    )


def _empty_language_execution_receipt(
    *,
    index: int,
    mode: str,
    instruction: ContentRef,
    dimension: int,
) -> FrozenLanguageExecutionReceipt:
    return FrozenLanguageExecutionReceipt(
        receipt_id=_u(index),
        mode=mode,
        instruction_content=instruction,
        instruction_content_digest=instruction.sha256,
        selected_category=None,
        environment_artifact=instruction,
        environment_digest="",
        execution_profile_digest="",
        output_bytes=instruction,
        output_bytes_digest="",
        output_dimension=dimension,
        replay_kat_id="",
        executor_evidence=None,
        receipt_digest="",
        authority_receipt=_pending_authority(index),
    )


@dataclass(frozen=True, slots=True)
class DeliveredAdmissionEvidenceCapsule:
    capsule_id: str
    authority_realm_key: tuple[str, str]
    source_session_kind: str
    source_logical_session_id: str
    source_generation: str
    route_class: str
    producer_frame: ProducerFrame
    delivery: ReceiverFrameDelivery
    admission_head: LiveAdmissionHead
    admission_receipt: ReceiverAdmissionReceipt
    retained_payload: ContentRef
    admission_cut_digest: str
    authority_effect: str
    capsule_digest: str


def _delivered_admission_capsule_digest(
    capsule: DeliveredAdmissionEvidenceCapsule,
) -> str:
    return _body_digest(capsule, "capsule_digest")


def _seal_delivered_admission_capsule(
    *,
    frame: ProducerFrame,
    delivery: ReceiverFrameDelivery,
    admission_head: LiveAdmissionHead,
    admission_receipt: ReceiverAdmissionReceipt,
    index: int,
) -> DeliveredAdmissionEvidenceCapsule:
    _require(
        admission_head.last_commit is not None,
        "delivered admission capsule lacks its admission cut",
        CaptureError,
    )
    capsule = DeliveredAdmissionEvidenceCapsule(
        capsule_id=_u_for(
            (
                "delivered-admission-capsule",
                frame.frame_digest,
                delivery.delivery_digest,
                admission_receipt.receipt_digest,
                index,
            )
        ),
        authority_realm_key=AUTHORITY_REALM_KEY,
        source_session_kind=delivery.canonical_read_scope.source_session_kind,
        source_logical_session_id=frame.session,
        source_generation=frame.generation,
        route_class=delivery.canonical_read_scope.route_class,
        producer_frame=frame,
        delivery=delivery,
        admission_head=admission_head,
        admission_receipt=admission_receipt,
        retained_payload=frame.payload,
        admission_cut_digest=admission_head.last_commit.commit_digest,
        authority_effect="HISTORICAL_EVIDENCE_ONLY_NO_FUTURE_READ_AUTHORITY",
        capsule_digest="",
    )
    return replace(
        capsule,
        capsule_digest=_delivered_admission_capsule_digest(capsule),
    )


def _validate_delivered_admission_capsule(
    capsule: DeliveredAdmissionEvidenceCapsule,
    *,
    store: ContentStore,
) -> None:
    _require(
        type(capsule) is DeliveredAdmissionEvidenceCapsule
        and _is_uuid4(capsule.capsule_id)
        and capsule.authority_realm_key == AUTHORITY_REALM_KEY
        and capsule.source_session_kind == "PLANT_CONTROL"
        and capsule.source_logical_session_id == capsule.producer_frame.session
        and capsule.source_generation == capsule.producer_frame.generation
        and capsule.route_class == capsule.delivery.canonical_read_scope.route_class
        and capsule.retained_payload == capsule.producer_frame.payload
        and capsule.authority_effect
        == "HISTORICAL_EVIDENCE_ONLY_NO_FUTURE_READ_AUTHORITY"
        and capsule.capsule_digest == _delivered_admission_capsule_digest(capsule),
        "delivered admission capsule is malformed or claims future authority",
        CaptureError,
    )
    _validate_producer_frame(capsule.producer_frame, store=store)
    delivery = capsule.delivery
    receipt = capsule.admission_receipt
    head = capsule.admission_head
    _validate_retained_delivery_bridge(delivery, capsule.producer_frame)
    expected_event_digest = _digest(
        {
            "key": receipt.key,
            "frame_digest": receipt.frame_digest,
            "source_position": receipt.source_position,
            "state_version": receipt.state_version,
            "prior_head_digest": receipt.prior_head_digest,
            "admission_basis_digest": receipt.admission_basis_digest,
            "delivery_digest": receipt.delivery_digest,
            "canonical_scope_digest": receipt.canonical_scope_digest,
            "boundary_scope_membership_digest": (
                receipt.boundary_scope_membership_digest
            ),
            "read_authorization_decision_digest": (
                receipt.read_authorization_decision_digest
            ),
            "release_authority_recheck_digest": (
                receipt.release_authority_recheck_digest
            ),
        }
    )
    position = next(
        (
            item
            for item in head.admitted_positions
            if item.source_position == receipt.source_position
            and item.frame_digest == receipt.frame_digest
        ),
        None,
    )
    _require(head.last_commit is not None, "capsule admission head lost its commit")
    if head.last_commit is None:
        raise CaptureError("capsule admission commit is absent")
    _validate_frame_head_commit(
        head.last_commit,
        key=head.key,
        operation="live_update",
        prior_head_digest=head.prior_head_digest or "",
        installed_head_digest=head.head_digest,
        selector_version=head.state_version,
        operation_evidence_digest=expected_event_digest,
    )
    _require(
        delivery.delivery_digest == _frame_delivery_digest(delivery)
        and delivery.producer_frame_digest == capsule.producer_frame.frame_digest
        and delivery.canonical_read_scope.declared_stream_digest
        == capsule.producer_frame.stream_declaration_digest
        and delivery.canonical_read_scope.schema_digest
        == capsule.producer_frame.schema.sha256
        and delivery.canonical_read_scope.authority_realm_key == AUTHORITY_REALM_KEY
        and delivery.canonical_read_scope.logical_session_id
        == capsule.producer_frame.session
        and delivery.canonical_read_scope.source_generation
        == capsule.producer_frame.generation
        and (
            delivery.canonical_read_scope.plane,
            delivery.canonical_read_scope.message_class,
        )
        == (
            capsule.producer_frame.stream_key[0],
            capsule.producer_frame.stream_key[2],
        )
        and delivery.canonical_read_scope.channel
        == (
            ""
            if capsule.producer_frame.stream_key[0] == "observation"
            else capsule.producer_frame.stream_key[1]
        )
        and delivery.release_authority_recheck_digest
        == _digest(
            {
                "boundary_membership_digest": (
                    delivery.boundary_scope_membership.membership_digest
                ),
                "canonical_scope_digest": (delivery.canonical_read_scope.scope_digest),
                "semantic_decision_digest": (
                    delivery.read_authorization_decision.semantic_decision_digest
                ),
                "decision_artifact_digest": read_decision_artifact_digest(
                    delivery.read_authorization_decision
                ),
                "dispatch_context_artifact_digest": dispatch_artifact_digest(
                    delivery.dispatch_context
                ),
                "committed_outbox_artifact_digest": (
                    committed_outbox_artifact_digest(delivery.committed_outbox_artifact)
                ),
                "validated_release_cas_receipt_artifact_digest": (
                    validated_release_cas_receipt_artifact_digest(
                        delivery.validated_release_cas_receipt
                    )
                ),
                "outbox_commit_receipt_artifact_digest": (
                    outbox_commit_receipt_artifact_digest(
                        delivery.outbox_commit_receipt
                    )
                ),
                "installed_outbox_storage_state_head_digest": (
                    delivery.outbox_commit_receipt.installed_storage_state_head_digest
                ),
                "grant_currentness_artifact_digest": (
                    grant_currentness_artifact_digest(
                        delivery.grant_currentness_evidence
                    )
                ),
                "release_cas_artifact_digest": delivery.release_cas.cas_digest,
                "frame_digest": capsule.producer_frame.frame_digest,
                "grant_install_receipt_digest": (delivery.grant_install_receipt_digest),
                "received_at": delivery.received_at,
                "release_recheck": "CURRENT_AT_RELEASE_NO_FUTURE_AUTHORITY",
            }
        )
        and receipt.phase == "live"
        and receipt.delivery_digest == delivery.delivery_digest
        and receipt.frame_digest == capsule.producer_frame.frame_digest
        and receipt.source_position == capsule.producer_frame.stream_position
        and receipt.key.receiver_principal == delivery.receiver_principal
        and receipt.canonical_scope_digest == delivery.canonical_read_scope.scope_digest
        and receipt.boundary_scope_membership_digest
        == delivery.boundary_scope_membership.membership_digest
        and receipt.read_authorization_decision_digest
        == delivery.read_authorization_decision.semantic_decision_digest
        and receipt.release_authority_recheck_digest
        == delivery.release_authority_recheck_digest
        and receipt.prior_head_digest == head.prior_head_digest
        and receipt.installed_head_digest == head.head_digest
        and receipt.state_version == head.state_version
        and receipt.head_commit_digest == head.last_commit.commit_digest
        and capsule.admission_cut_digest == head.last_commit.commit_digest
        and position is not None
        and position.admission_receipt_digest == expected_event_digest
        and receipt.receipt_digest == _admission_receipt_digest(receipt),
        "capsule substituted delivery, admission, frame, or cut evidence",
        CaptureError,
    )
    _validate_authority(
        delivery.authority_receipt,
        domain="receiver-frame-delivery",
        subject_digest=delivery.delivery_digest,
        issuer=INGRESS_AUTHORITY,
        subject=delivery.receiver_principal,
    )
    _validate_authority(
        receipt.authority_receipt,
        domain="receiver-live-admission",
        subject_digest=receipt.receipt_digest,
        issuer=INGRESS_AUTHORITY,
        subject=receipt.key.receiver_principal,
    )
    store.get(capsule.retained_payload)


@dataclass(frozen=True, slots=True)
class DeterministicExtractionContract:
    contract_id: str
    member_id: str
    route_class: str
    json_member_path: tuple[str, ...]
    source_value_kind: str
    output_encoding: str
    output_dimension: int
    output_dtype: str
    transform_contract_digest: str | None
    maximum_payload_bytes: int
    maximum_depth: int
    maximum_nodes: int
    contract_digest: str


def _extraction_contract_digest(
    contract: DeterministicExtractionContract,
) -> str:
    return _body_digest(contract, "contract_digest")


def _seal_extraction_contract(
    contract: DeterministicExtractionContract,
) -> DeterministicExtractionContract:
    return replace(
        contract,
        contract_digest=_extraction_contract_digest(contract),
    )


@dataclass(frozen=True, slots=True)
class DeterministicExtractionReceipt:
    receipt_id: str
    contract_digest: str
    capsule_digest: str
    retained_payload_digest: str
    retained_payload_length: int
    extracted_source_value: ContentRef
    extracted_source_value_digest: str
    canonical_output: ContentRef
    canonical_output_digest: str
    transform_contract_digest: str | None
    replay_digest: str
    receipt_digest: str


def _extraction_receipt_digest(
    receipt: DeterministicExtractionReceipt,
) -> str:
    return _body_digest(receipt, "receipt_digest")


def _bounded_binary64_vector_bytes(
    vector: Any,
    *,
    expected_dimension: int,
) -> bytes:
    _require(
        type(expected_dimension) is int
        and 1 <= expected_dimension <= MAX_LANGUAGE_OUTPUT_DIMENSION
        and type(vector) is list
        and len(vector) == expected_dimension,
        "binary64 vector dimension or container is outside its exact bound",
        CaptureError,
    )
    _require(
        all(
            type(item) in (int, float) and math.isfinite(float(item)) for item in vector
        ),
        "binary64 vector contains a subclassed or non-finite member",
        CaptureError,
    )
    return b"".join(struct.pack(">d", float(item)) for item in vector)


def _execute_deterministic_extraction(
    contract: DeterministicExtractionContract,
    capsule: DeliveredAdmissionEvidenceCapsule,
    *,
    store: ContentStore,
    language_contract: FrozenLanguageEmbeddingContract | None = None,
) -> DeterministicExtractionReceipt:
    _validate_delivered_admission_capsule(capsule, store=store)
    _require(
        type(contract) is DeterministicExtractionContract
        and _is_uuid4(contract.contract_id)
        and IDENTIFIER.fullmatch(contract.member_id) is not None
        and contract.route_class == capsule.route_class
        and type(contract.json_member_path) is tuple
        and 1 <= len(contract.json_member_path) <= MAX_JSON_DEPTH
        and all(
            type(item) is str and IDENTIFIER.fullmatch(item) is not None
            for item in contract.json_member_path
        )
        and contract.source_value_kind in {"FINITE_NUMBER", "UTF8_TEXT"}
        and contract.output_encoding
        in {"BINARY64_BE", "BINARY64_BE_VECTOR_AFTER_FROZEN_TRANSFORM"}
        and type(contract.output_dimension) is int
        and 1 <= contract.output_dimension <= MAX_LANGUAGE_OUTPUT_DIMENSION
        and contract.output_dtype == "float64"
        and contract.maximum_payload_bytes == MAX_JSON_BYTES
        and contract.maximum_depth == MAX_JSON_DEPTH
        and contract.maximum_nodes == MAX_JSON_NODES
        and contract.contract_digest == _extraction_contract_digest(contract),
        "deterministic extraction contract is malformed or unbounded",
        CaptureError,
    )
    payload_bytes = store.get(capsule.retained_payload)
    _require(
        len(payload_bytes) <= contract.maximum_payload_bytes,
        "retained extraction payload exceeds its contract bound",
        CaptureError,
    )
    value: Any = _bounded_json_object(payload_bytes)
    for member in contract.json_member_path:
        _require(
            type(value) is dict and member in value,
            "deterministic extraction member is absent",
            CaptureError,
        )
        value = value[member]
    if contract.source_value_kind == "FINITE_NUMBER":
        _require(
            isinstance(value, (int, float))
            and not isinstance(value, bool)
            and math.isfinite(float(value))
            and contract.output_encoding == "BINARY64_BE"
            and contract.output_dimension == 1
            and contract.transform_contract_digest is None
            and language_contract is None,
            "numeric extraction value or output mode is invalid",
            CaptureError,
        )
        source_bytes = json.dumps(
            value,
            allow_nan=False,
            ensure_ascii=False,
            separators=(",", ":"),
        ).encode("utf-8")
        output_bytes = struct.pack(">d", float(value))
    else:
        _require(
            type(language_contract) is FrozenLanguageEmbeddingContract,
            "text extraction lacks one exact frozen language contract",
            CaptureError,
        )
        if language_contract is None:
            raise CaptureError("validated language extraction contract is absent")
        transform = _validate_language_contract(language_contract, store=store)
        vector = transform.get("numeric_vector")
        _require(
            type(value) is str
            and 0 < len(value) <= MAX_JSON_STRING_CHARS
            and contract.output_encoding == "BINARY64_BE_VECTOR_AFTER_FROZEN_TRANSFORM"
            and type(contract.transform_contract_digest) is str
            and contract.transform_contract_digest == language_contract.contract_digest
            and contract.output_dimension == language_contract.dimension
            and contract.output_dtype == language_contract.dtype == "float64"
            and type(vector) is list
            and len(vector) == contract.output_dimension
            and value.encode("utf-8")
            == store.get(language_contract.instruction_content),
            "text extraction does not match its frozen transform input or output",
            CaptureError,
        )
        source_bytes = value.encode("utf-8")
        output_bytes = _bounded_binary64_vector_bytes(
            vector,
            expected_dimension=contract.output_dimension,
        )
    _require(
        len(source_bytes) <= MAX_CONTENT_BYTES
        and len(output_bytes) == contract.output_dimension * 8
        and len(output_bytes) <= MAX_CONTENT_BYTES,
        "deterministic extraction output exceeds its exact byte dimension",
        CaptureError,
    )
    source_write = store.stage_bytes(
        source_bytes,
        "application/vnd.ncp.extracted-source-value",
    )
    output_write = store.stage_bytes(
        output_bytes,
        "application/vnd.ncp.canonical-binary64-output",
    )
    source_ref = source_write.reference
    output_ref = output_write.reference
    replay_digest = _digest(
        {
            "capsule_digest": capsule.capsule_digest,
            "contract_digest": contract.contract_digest,
            "output": output_ref,
            "retained_payload": capsule.retained_payload,
            "source_value": source_ref,
            "transform_contract_digest": contract.transform_contract_digest,
        }
    )
    receipt = DeterministicExtractionReceipt(
        receipt_id=_u_for(
            (
                "deterministic-extraction-receipt",
                capsule.capsule_digest,
                contract.contract_digest,
                replay_digest,
            )
        ),
        contract_digest=contract.contract_digest,
        capsule_digest=capsule.capsule_digest,
        retained_payload_digest=capsule.retained_payload.sha256,
        retained_payload_length=capsule.retained_payload.byte_length,
        extracted_source_value=source_ref,
        extracted_source_value_digest=source_ref.sha256,
        canonical_output=output_ref,
        canonical_output_digest=output_ref.sha256,
        transform_contract_digest=contract.transform_contract_digest,
        replay_digest=replay_digest,
        receipt_digest="",
    )
    receipt = replace(
        receipt,
        receipt_digest=_extraction_receipt_digest(receipt),
    )
    staged_writes = (source_write, output_write)
    visible_references = tuple(
        sorted(
            (source_ref, output_ref),
            key=lambda reference: (
                reference.sha256,
                reference.media_type,
                reference.byte_length,
            ),
        )
    )
    extraction_namespace = (
        f"extraction:{_u_for((capsule.capsule_digest, contract.contract_digest))}"
    )
    store.commit_atomic(
        namespace=extraction_namespace,
        staged_writes=staged_writes,
        visible_references=visible_references,
        allow_exact_retry=True,
    )
    return receipt


