def _closed_segment_interval(segment: CaptureSegment) -> ClosedSemanticSegmentInterval:
    _require(
        segment.closed and segment.valid_until is not None and bool(segment.samples),
        "terminal interval requires one nonempty closed segment",
        CaptureError,
    )
    if segment.valid_until is None or not segment.samples:
        raise CaptureError("validated terminal segment is incomplete")
    return ClosedSemanticSegmentInterval(
        segment.segment_id,
        segment.semantic_snapshot_digest,
        segment.semantic_head_digest,
        segment.valid_from,
        segment.valid_until,
        segment.samples[-1].sample_digest,
        segment.samples[-1].admission_receipt_digest,
    )


def _validate_semantic_terminal(
    commitment: ConsumerSemanticRegistryTerminalCommitment,
    finalization: ConsumerSemanticRegistryFinalizationReceipt,
    *,
    versions: tuple[SemanticRegistryVersion, ...],
    closed_segments: tuple[CaptureSegment, ...],
    store: ContentStore,
) -> None:
    _require(bool(versions), "semantic terminal has no installed lineage")
    final_version = versions[-1]
    final_head = final_version.head
    final_head_commit = final_version.head_commit
    _require(
        isinstance(
            final_head_commit,
            ConsumerSemanticRegistryHeadCommitReceipt,
        ),
        "semantic terminal lacks the last installed head commit",
        CaptureError,
    )
    if not isinstance(
        final_head_commit,
        ConsumerSemanticRegistryHeadCommitReceipt,
    ):
        raise CaptureError("validated final semantic head commit is absent")
    expected_intervals = tuple(
        sorted(_closed_segment_interval(segment) for segment in closed_segments)
    )
    _require(
        bool(expected_intervals),
        "semantic terminal cannot finalize a zero-entry registry",
        CaptureError,
    )
    expected_horizon = (
        min(item.valid_from for item in expected_intervals),
        max(item.valid_until for item in expected_intervals),
    )
    expected_snapshots = tuple(
        sorted(
            {
                *final_head.retained_snapshot_digests,
                final_head.snapshot_digest,
            }
        )
    )
    expected_heads = tuple(
        sorted(
            {
                *final_head.retained_head_digests,
                final_head.head_digest,
            }
        )
    )
    _require(
        _is_uuid4(commitment.commitment_id)
        and commitment.registry_incarnation == final_head.registry_incarnation
        and commitment.capture_owner_trust_digest
        == final_head.capture_owner_trust_digest
        and commitment.final_installed_head_digest == final_head.head_digest
        and commitment.final_state_version == final_head.state_version
        and commitment.final_selector_version == final_head.state_version
        and commitment.last_head_commit_digest == final_head_commit.commit_digest
        and commitment.retained_snapshot_digests == expected_snapshots
        and commitment.retained_head_digests == expected_heads
        and commitment.closed_segment_intervals == expected_intervals
        and commitment.reference_horizon == expected_horizon
        and commitment.commitment_digest == commitment.protected_body.body_digest
        and _is_uuid4(finalization.receipt_id)
        and finalization.registry_incarnation == final_head.registry_incarnation
        and finalization.prior_installed_head_digest == final_head.head_digest
        and finalization.terminal_commitment_digest == commitment.commitment_digest
        and finalization.prior_selector_version == final_head.state_version
        and finalization.terminal_selector_version == final_head.state_version + 1
        and finalization.receipt_digest == _semantic_finalization_digest(finalization)
        and commitment.protected_body.authority_receipt.clock_domain
        == "consumer-monotonic"
        and commitment.protected_body.authority_receipt.clock_incarnation
        == commitment.registry_incarnation
        and commitment.protected_body.authority_receipt.event_time
        >= commitment.reference_horizon[1]
        and finalization.authority_receipt.clock_domain == "consumer-monotonic"
        and finalization.authority_receipt.clock_incarnation
        == finalization.registry_incarnation
        and finalization.authority_receipt.event_time
        == commitment.protected_body.authority_receipt.event_time,
        "semantic terminal is stale, fabricated, or lacks its successful final CAS",
        CaptureError,
    )
    _validate_protected_body(
        commitment.protected_body,
        _semantic_terminal_body(commitment),
        store=store,
        media_type="application/vnd.prisoma.semantic-registry-terminal+json",
        domain="consumer-semantic-registry-terminal",
        issuer=PRISOMA_AUTHORITY,
        subject=PRISOMA_AUTHORITY,
    )
    _validate_authority(
        finalization.authority_receipt,
        domain="consumer-semantic-registry-finalization",
        subject_digest=finalization.receipt_digest,
        issuer=PRISOMA_AUTHORITY,
        subject=PRISOMA_AUTHORITY,
    )


def _validate_prisoma_numeric_executor_evidence(
    evidence: PrisomaNumericExecutorEvidence,
    *,
    contract: FrozenLanguageEmbeddingContract,
    transform: Mapping[str, Any],
    receipt: FrozenLanguageExecutionReceipt,
) -> None:
    fact = evidence.execution_fact
    uninitialized = evidence.uninitialized_selector
    heads = evidence.state_heads
    commits = evidence.state_commits
    selectors = evidence.selectors
    expected_trust_state_digest = _digest(
        {
            "authority": PRISOMA_AUTHORITY,
            "domain": "prisoma-numeric-executor-trust-state-v1",
            "security_state_digest": SECURITY_STATE_DIGEST,
        }
    )
    expected_policy_head_digest = _digest(
        {
            "contract_profile": _body(
                contract,
                "execution_receipt",
                "contract_digest",
            ),
            "domain": "prisoma-numeric-executor-policy-head-v1",
        }
    )
    exact_input_digest = _digest(
        {
            "contract_profile": _body(
                contract,
                "execution_receipt",
                "contract_digest",
            ),
            "instruction_content_digest": contract.instruction_content_digest,
            "selected_category": transform.get("selected_category"),
            "transform_artifact_digest": contract.transform_artifact.sha256,
        }
    )
    expected_pending_operation = PrisomaNumericExecutorPendingOperation(
        operation_id=fact.operation_id,
        run_id=fact.run_id,
        process_incarnation=uninitialized.process_incarnation,
        trust_state_digest=expected_trust_state_digest,
        policy_head_digest=expected_policy_head_digest,
        mode=contract.mode,
        exact_input_digest=exact_input_digest,
        operation_digest="",
    )
    expected_pending_operation = replace(
        expected_pending_operation,
        operation_digest=_prisoma_numeric_executor_pending_operation_digest(
            expected_pending_operation
        ),
    )
    operation_digest = expected_pending_operation.operation_digest
    expected_variant = (
        "NEURAL_EXECUTION"
        if contract.mode == "FROZEN_NEURAL_NUMERIC"
        else "CATEGORICAL_EXECUTION"
    )
    expected_selected_category = (
        str(transform["selected_category"])
        if contract.mode == "FROZEN_CATEGORICAL_NUMERIC"
        else None
    )
    expected_executable_digest = (
        contract.runtime_digest
        if contract.mode == "FROZEN_NEURAL_NUMERIC"
        else _digest(
            {
                "categorical_encoding": contract.categorical_encoding,
                "categorical_map": contract.categorical_map,
                "domain": "prisoma-frozen-categorical-executable-v1",
            }
        )
    )
    _require(
        expected_executable_digest is not None,
        "validated Prisoma numeric executable digest is absent",
        CaptureError,
    )
    if expected_executable_digest is None:
        raise CaptureError("validated Prisoma numeric executable digest is absent")
    expected_dependency_closure_digest = _digest(
        {
            "backend": contract.backend,
            "categorical_vocabulary_digest": (contract.categorical_vocabulary_digest),
            "domain": "prisoma-numeric-executor-dependency-closure-v1",
            "environment_digest": receipt.environment_digest,
            "executable_digest": expected_executable_digest,
            "runtime_digest": contract.runtime_digest,
        }
    )
    expected_self_inspection_digest = _digest(
        {
            "dependency_closure_digest": expected_dependency_closure_digest,
            "domain": "prisoma-numeric-executor-self-inspection-v1",
            "environment_digest": receipt.environment_digest,
            "executable_digest": expected_executable_digest,
            "process_incarnation": evidence.uninitialized_selector.process_incarnation,
        }
    )
    _require(
        _is_uuid4(evidence.evidence_id)
        and _is_uuid4(fact.fact_id)
        and _is_uuid4(fact.operation_id)
        and _is_uuid4(fact.run_id)
        and fact.process_incarnation == uninitialized.process_incarnation
        and fact.trust_state_digest == expected_trust_state_digest
        and fact.policy_head_digest == expected_policy_head_digest
        and fact.result_variant == expected_variant
        and fact.mode == contract.mode
        and fact.exact_input_digest == exact_input_digest
        and fact.instruction_content_digest == contract.instruction_content_digest
        and fact.selected_category == expected_selected_category
        and fact.environment_digest == receipt.environment_digest
        and fact.executable_digest == expected_executable_digest
        and fact.dependency_closure_digest == expected_dependency_closure_digest
        and fact.self_inspection_digest == expected_self_inspection_digest
        and fact.output_bytes_digest == receipt.output_bytes_digest
        and fact.output_dimension == contract.dimension
        and fact.exclusion_reason is None
        and fact.estimator_invoked
        and fact.fact_digest == _prisoma_numeric_execution_fact_digest(fact),
        "Prisoma pre-CAS numeric execution fact is incomplete, remade, or "
        "detached from its exact input/environment/output",
        CaptureError,
    )
    exclusion_reasons = tuple(
        witness.exclusion_reason for witness in evidence.input_exclusion_witnesses
    )
    excluded_environment_digest = _digest(
        {
            "domain": "prisoma-numeric-executor-excluded-environment-v1",
            "mode": contract.mode,
            "state": "INPUT_EXCLUDED_BEFORE_EXECUTION_ENVIRONMENT_BINDING",
        }
    )
    excluded_self_inspection_digest = _digest(
        {
            "dependency_closure_digest": fact.dependency_closure_digest,
            "domain": "prisoma-numeric-executor-excluded-self-inspection-v1",
            "environment_digest": excluded_environment_digest,
            "executable_digest": fact.executable_digest,
            "process_incarnation": evidence.uninitialized_selector.process_incarnation,
        }
    )
    _require(
        exclusion_reasons == ("SOURCE_ABSENT", "EMPTY", "UNBOUND", "PARSE_FAILED")
        and len({witness.fact_digest for witness in evidence.input_exclusion_witnesses})
        == 4
        and all(
            _is_uuid4(witness.fact_id)
            and _is_uuid4(witness.operation_id)
            and _is_uuid4(witness.run_id)
            and witness.process_incarnation == uninitialized.process_incarnation
            and witness.trust_state_digest == expected_trust_state_digest
            and witness.policy_head_digest == expected_policy_head_digest
            and witness.result_variant == "INPUT_EXCLUDED"
            and witness.mode == contract.mode
            and witness.instruction_content_digest
            == contract.instruction_content_digest
            and witness.selected_category is None
            and witness.environment_digest == excluded_environment_digest
            and witness.environment_digest != fact.environment_digest
            and witness.executable_digest == fact.executable_digest
            and witness.dependency_closure_digest == fact.dependency_closure_digest
            and witness.self_inspection_digest == excluded_self_inspection_digest
            and witness.output_bytes_digest is None
            and witness.output_dimension is None
            and witness.exclusion_reason
            in {"SOURCE_ABSENT", "EMPTY", "UNBOUND", "PARSE_FAILED"}
            and not witness.estimator_invoked
            and witness.fact_digest == _prisoma_numeric_execution_fact_digest(witness)
            for witness in evidence.input_exclusion_witnesses
        ),
        "Prisoma INPUT_EXCLUDED branch produced a category, row, output, or "
        "estimator call instead of one closed exclusion fact",
        CaptureError,
    )
    _require(
        uninitialized.state == "UNINITIALIZED"
        and uninitialized.selector_version == 0
        and not uninitialized.ever_used
        and uninitialized.current_head_digest is None
        and uninitialized.prior_selector_digest is None
        and uninitialized.last_commit_digest is None
        and uninitialized.selector_digest
        == _installed_prisoma_numeric_executor_selector_digest(uninitialized)
        and len(heads) == len(commits) == len(selectors) == 3,
        "Prisoma numeric executor reused a selector or omitted a state transition",
        CaptureError,
    )
    _validate_authority(
        uninitialized.authority_receipt,
        domain="installed-prisoma-numeric-executor-state-selector",
        subject_digest=uninitialized.selector_digest,
        issuer=PRISOMA_AUTHORITY,
        subject=PRISOMA_AUTHORITY,
    )
    expected_transitions = (
        "NUMERIC_EXECUTOR_GENESIS_FROM_UNINITIALIZED",
        "NUMERIC_EXECUTION_RESERVED",
        "NUMERIC_EXECUTION_TERMINALIZED",
    )
    expected_operation_evidence = (
        _digest("empty-prisoma-numeric-executor"),
        operation_digest,
        fact.fact_digest,
    )
    prior_selector = uninitialized
    prior_head_digest = _digest(
        {
            "domain": "prisoma-numeric-executor-state-genesis-v1",
            "process_incarnation": uninitialized.process_incarnation,
            "selector_digest": uninitialized.selector_digest,
        }
    )
    for index, (head, commit, selector) in enumerate(
        zip(heads, commits, selectors, strict=True)
    ):
        _require(
            head.owner_principal == PRISOMA_AUTHORITY
            and head.executor_principal == "prisoma-frozen-numeric-executor"
            and head.process_incarnation == uninitialized.process_incarnation
            and head.trust_state_digest == expected_trust_state_digest
            and head.policy_head_digest == expected_policy_head_digest
            and head.state_version == index + 1
            and 1 <= head.bounded_pending_capacity <= 64
            and len(head.pending_operations) <= head.bounded_pending_capacity
            and tuple(
                operation.operation_digest for operation in head.pending_operations
            )
            == head.pending_operation_digests
            and len(set(head.consumed_operation_ids))
            == len(head.consumed_operation_ids)
            and len(set(head.consumed_run_ids)) == len(head.consumed_run_ids)
            and head.prior_head_digest
            == (None if index == 0 else heads[index - 1].head_digest)
            and head.head_digest == _prisoma_numeric_executor_state_head_digest(head)
            and commit.transition_kind == expected_transitions[index]
            and commit.process_incarnation == head.process_incarnation
            and commit.prior_head_digest == prior_head_digest
            and commit.installed_head_digest == head.head_digest
            and commit.installed_selector_version == prior_selector.selector_version + 1
            and commit.operation_evidence_digest == expected_operation_evidence[index]
            and commit.commit_digest == _prisoma_numeric_executor_commit_digest(commit)
            and selector.process_incarnation == head.process_incarnation
            and selector.selector_version == prior_selector.selector_version + 1
            and selector.state == "INSTALLED"
            and selector.ever_used
            and selector.current_head_digest == head.head_digest
            and selector.prior_selector_digest == prior_selector.selector_digest
            and selector.last_commit_digest == commit.commit_digest
            and selector.selector_digest
            == _installed_prisoma_numeric_executor_selector_digest(selector),
            "Prisoma numeric executor state forked, skipped pending allocation, "
            "or installed a fact under a mismatched selector/commit",
            CaptureError,
        )
        for value, digest, domain in (
            (
                head,
                head.head_digest,
                "prisoma-numeric-executor-state-head",
            ),
            (
                commit,
                commit.commit_digest,
                "prisoma-numeric-executor-state-commit",
            ),
            (
                selector,
                selector.selector_digest,
                "installed-prisoma-numeric-executor-state-selector",
            ),
        ):
            _validate_authority(
                value.authority_receipt,
                domain=domain,
                subject_digest=digest,
                issuer=PRISOMA_AUTHORITY,
                subject=PRISOMA_AUTHORITY,
            )
        prior_head_digest = head.head_digest
        prior_selector = selector
    _require(
        not heads[0].pending_operations
        and not heads[0].pending_operation_digests
        and not heads[0].consumed_operation_ids
        and not heads[0].consumed_run_ids
        and not heads[0].terminal_operation_bindings
        and not heads[0].terminal_execution_fact_digests
        and not heads[0].execution_facts
        and heads[1].pending_operations == (expected_pending_operation,)
        and heads[1].pending_operation_digests == (operation_digest,)
        and not heads[1].consumed_operation_ids
        and not heads[1].consumed_run_ids
        and not heads[1].terminal_operation_bindings
        and not heads[1].terminal_execution_fact_digests
        and not heads[1].execution_facts
        and not heads[2].pending_operations
        and not heads[2].pending_operation_digests
        and heads[2].consumed_operation_ids == (fact.operation_id,)
        and heads[2].consumed_run_ids == (fact.run_id,)
        and heads[2].terminal_operation_bindings
        == ((fact.operation_id, fact.run_id, fact.fact_digest),)
        and heads[2].terminal_execution_fact_digests == (fact.fact_digest,)
        and heads[2].execution_facts == (fact,)
        and not any(head.exclusion_tombstone_digests for head in heads)
        and evidence.installed_selector == selectors[-1]
        and evidence.evidence_digest
        == _prisoma_numeric_executor_evidence_digest(evidence)
        and "installed_head_digest" not in _body(fact)
        and "installed_selector_version" not in _body(fact)
        and "commit_digest" not in _body(fact)
        and "evidence_digest" not in _body(heads[2])
        and "receipt_digest" not in _body(evidence),
        "Prisoma execution fact, terminal head, generic commit, post-CAS "
        "evidence, or language receipt form a hash cycle",
        CaptureError,
    )
    _validate_authority(
        evidence.authority_receipt,
        domain="prisoma-numeric-executor-evidence",
        subject_digest=evidence.evidence_digest,
        issuer=PRISOMA_AUTHORITY,
        subject="synthetic-evidence-auditor",
    )


def _validate_language_contract(
    contract: FrozenLanguageEmbeddingContract,
    *,
    store: ContentStore,
) -> dict[str, Any]:
    neural = contract.mode == "FROZEN_NEURAL_NUMERIC"
    categorical = contract.mode == "FROZEN_CATEGORICAL_NUMERIC"
    _require(
        (neural or categorical)
        and contract.instruction_content_digest == contract.instruction_content.sha256
        and 1 <= contract.dimension <= 4096
        and len(contract.member_order) == contract.dimension
        and len(set(contract.member_order)) == contract.dimension
        and len(contract.numeric_domain) == 2
        and all(math.isfinite(value) for value in contract.numeric_domain)
        and contract.numeric_domain[0] < contract.numeric_domain[1]
        and contract.dtype == "float64"
        and contract.contract_digest == _language_contract_digest(contract),
        "language mode lacks its exact frozen content/model/shape contract",
        CaptureError,
    )
    instruction = store.get(contract.instruction_content)
    _require(
        hashlib.sha256(instruction).hexdigest() == contract.instruction_content_digest,
        "language instruction content reference is stale",
        CaptureError,
    )
    _require(
        contract.instruction_content.media_type == "text/plain"
        and contract.transform_artifact.media_type
        == "application/vnd.prisoma.language-transform+json",
        "language contract content uses an unexpected media type",
        CaptureError,
    )
    transform = _bounded_json_object(store.get(contract.transform_artifact))
    common = {
        "dimension": contract.dimension,
        "dtype": contract.dtype,
        "instruction_content_digest": contract.instruction_content_digest,
        "member_order": list(contract.member_order),
        "numeric_domain": list(contract.numeric_domain),
    }
    if neural:
        _require(
            all(
                value is not None and HEX64.fullmatch(value) is not None
                for value in (
                    contract.tokenizer_digest,
                    contract.encoder_digest,
                    contract.model_digest,
                    contract.config_digest,
                )
            )
            and contract.pooling in {"mean", "cls", "last_token"}
            and contract.runtime_digest is not None
            and HEX64.fullmatch(contract.runtime_digest) is not None
            and contract.opset_version == 17
            and contract.backend == "onnxruntime-cpu"
            and contract.precision == "float64"
            and contract.determinism_profile_digest is not None
            and HEX64.fullmatch(contract.determinism_profile_digest) is not None
            and contract.output_vector_digest is not None
            and HEX64.fullmatch(contract.output_vector_digest) is not None
            and contract.categorical_vocabulary is None
            and contract.categorical_vocabulary_digest is None
            and not contract.categorical_map
            and contract.unknown_policy is None
            and contract.missing_policy is None
            and contract.categorical_encoding is None,
            "neural L contract mixed categorical or absent neural members",
            CaptureError,
        )
        vector = transform.get("numeric_vector")
        expected_transform = {
            **common,
            "config_digest": contract.config_digest,
            "encoder_digest": contract.encoder_digest,
            "kind": "frozen-neural-numeric-v1",
            "model_digest": contract.model_digest,
            "numeric_vector": vector,
            "opset_version": contract.opset_version,
            "output_vector_digest": contract.output_vector_digest,
            "pooling": contract.pooling,
            "precision": contract.precision,
            "runtime_digest": contract.runtime_digest,
            "backend": contract.backend,
            "determinism_profile_digest": (contract.determinism_profile_digest),
            "tokenizer_digest": contract.tokenizer_digest,
        }
    else:
        vocabulary = contract.categorical_vocabulary
        _require(
            vocabulary is not None
            and contract.categorical_vocabulary_digest == vocabulary.sha256
            and contract.tokenizer_digest is None
            and contract.encoder_digest is None
            and contract.model_digest is None
            and contract.config_digest is None
            and contract.pooling is None
            and contract.runtime_digest is None
            and contract.opset_version is None
            and contract.backend is None
            and contract.precision is None
            and contract.determinism_profile_digest is None
            and contract.output_vector_digest is None
            and tuple(sorted(contract.categorical_map)) == contract.categorical_map
            and tuple(index for _, index in contract.categorical_map)
            == tuple(range(contract.dimension))
            and tuple(category for category, _ in contract.categorical_map)
            == contract.member_order
            and contract.unknown_policy == "REJECT"
            and contract.missing_policy == "REJECT"
            and contract.categorical_encoding == "ONE_HOT",
            "categorical L contract lacks exact vocabulary/map/failure semantics",
            CaptureError,
        )
        if vocabulary is None:
            raise CaptureError("validated categorical vocabulary is absent")
        vocabulary_body = _bounded_json_object(store.get(vocabulary))
        _require(
            vocabulary.media_type == "application/vnd.prisoma.language-vocabulary+json"
            and vocabulary_body
            == {
                "categories": list(contract.member_order),
                "kind": "frozen-categorical-vocabulary-v1",
            },
            "categorical vocabulary bytes differ from the exact ordered map",
            CaptureError,
        )
        vector = transform.get("numeric_vector")
        selected_category = transform.get("selected_category")
        expected_transform = {
            **common,
            "categorical_encoding": contract.categorical_encoding,
            "categorical_map": [
                [category, index] for category, index in contract.categorical_map
            ],
            "categorical_vocabulary_digest": (contract.categorical_vocabulary_digest),
            "kind": "frozen-categorical-numeric-v1",
            "missing_policy": contract.missing_policy,
            "numeric_vector": vector,
            "selected_category": selected_category,
            "unknown_policy": contract.unknown_policy,
        }
    _require(
        transform == expected_transform
        and isinstance(vector, list)
        and len(vector) == contract.dimension
        and all(
            isinstance(value, (int, float))
            and not isinstance(value, bool)
            and math.isfinite(float(value))
            and contract.numeric_domain[0] <= float(value) <= contract.numeric_domain[1]
            for value in vector
        ),
        "frozen language transform has no exact bounded numeric vector output",
        CaptureError,
    )
    if categorical:
        selected_category = transform["selected_category"]
        selected_index = dict(contract.categorical_map).get(selected_category)
        _require(
            isinstance(selected_category, str)
            and selected_index is not None
            and tuple(float(value) for value in vector)
            == tuple(
                1.0 if index == selected_index else 0.0
                for index in range(contract.dimension)
            ),
            "categorical transform is not the exact one-hot selected category",
            CaptureError,
        )
    else:
        _require(
            contract.output_vector_digest
            == _language_output_vector_digest(vector, dtype=contract.dtype),
            "neural transform output vector digest does not bind exact output",
            CaptureError,
        )
    receipt = contract.execution_receipt
    environment = _bounded_json_object(store.get(receipt.environment_artifact))
    output_bytes = store.get(receipt.output_bytes)
    expected_output_bytes = _language_output_bytes(vector)
    expected_selected_category = transform["selected_category"] if categorical else None
    expected_kat = (
        "categorical-one-hot-exact-replay-v1"
        if categorical
        else "neural-binary64-exact-replay-v1"
    )
    _require(
        _is_uuid4(receipt.receipt_id)
        and receipt.mode == contract.mode
        and receipt.instruction_content == contract.instruction_content
        and receipt.instruction_content_digest == contract.instruction_content_digest
        and receipt.selected_category == expected_selected_category
        and receipt.environment_artifact.media_type
        == "application/vnd.prisoma.language-execution-environment+json"
        and receipt.environment_digest == receipt.environment_artifact.sha256
        and environment == _expected_language_environment(contract, transform)
        and receipt.execution_profile_digest
        == _language_execution_profile_digest(
            contract,
            environment_digest=receipt.environment_digest,
        )
        and receipt.output_bytes.media_type
        == "application/vnd.prisoma.language-output.binary64"
        and receipt.output_bytes_digest == receipt.output_bytes.sha256
        and receipt.output_bytes_digest
        == hashlib.sha256(expected_output_bytes).hexdigest()
        and output_bytes == expected_output_bytes
        and receipt.output_dimension == contract.dimension
        and receipt.replay_kat_id == expected_kat
        and receipt.executor_evidence is not None
        and receipt.receipt_digest == _language_execution_receipt_digest(receipt),
        "language execution receipt does not reproduce its exact environment "
        "and canonical output bytes",
        CaptureError,
    )
    if receipt.executor_evidence is None:
        raise CaptureError("validated Prisoma numeric executor evidence is absent")
    _validate_prisoma_numeric_executor_evidence(
        receipt.executor_evidence,
        contract=contract,
        transform=transform,
        receipt=receipt,
    )
    _validate_authority(
        receipt.authority_receipt,
        domain="frozen-language-execution",
        subject_digest=receipt.receipt_digest,
        issuer=PRISOMA_AUTHORITY,
        subject=PRISOMA_AUTHORITY,
    )
    _require(
        receipt.authority_receipt.clock_domain == "consumer-monotonic"
        and receipt.authority_receipt.clock_incarnation == GENERATION,
        "language execution receipt uses an unrecognized consumer clock",
        CaptureError,
    )
    return transform


def _validate_axis_contract(
    contract: ConsumerAxisContract,
    *,
    store: ContentStore,
) -> None:
    _require(
        contract.axis_slot in PRISOMA_REQUIRED_AXIS_SLOTS
        and IDENTIFIER.fullmatch(contract.axis_id) is not None
        and 1 <= len(contract.ordered_members) <= MAX_REGISTRY_ENTRIES
        and tuple(member.member_id for member in contract.ordered_members)
        == tuple(sorted({member.member_id for member in contract.ordered_members}))
        and contract.contract_digest == _axis_contract_digest(contract),
        "consumer axis contract is malformed, duplicate, or noncanonical",
        CaptureError,
    )
    for member in contract.ordered_members:
        _require(
            IDENTIFIER.fullmatch(member.member_id) is not None
            and HEX64.fullmatch(member.stream_declaration_digest) is not None
            and len(member.stream_key) == 3
            and HEX64.fullmatch(member.provider_contract_digest) is not None
            and member.channel_id == member.stream_key[1]
            and IDENTIFIER.fullmatch(member.record_member) is not None
            and bool(member.unit)
            and IDENTIFIER.fullmatch(member.coordinate_frame) is not None,
            "consumer axis member binding is incomplete",
            CaptureError,
        )
    if contract.axis_slot == "L":
        _require(
            contract.language_contract is not None,
            "L has no declared text or frozen embedding contract",
            CaptureError,
        )
        if contract.language_contract is not None:
            _validate_language_contract(contract.language_contract, store=store)
    else:
        _require(
            contract.language_contract is None,
            "non-language axis carries a language contract",
            CaptureError,
        )


def _validate_semantic_lineage(
    versions: tuple[SemanticRegistryVersion, ...],
    *,
    store: ContentStore,
) -> None:
    _require(
        1 <= len(versions) <= MAX_REGISTRY_ENTRIES,
        "semantic registry lineage is empty or unbounded",
        CaptureError,
    )
    expected_capture_owner_trust_digest = _digest(
        {
            "capture_owner": PRISOMA_AUTHORITY,
            "domain": "consumer-semantic-capture-owner-trust-v1",
            "security_state_digest": SECURITY_STATE_DIGEST,
        }
    )
    prior: SemanticRegistryVersion | None = None
    for version in versions:
        snapshot = version.snapshot
        head = version.head
        _require(
            _is_uuid4(snapshot.registry_id)
            and snapshot.owner_principal == PRISOMA_AUTHORITY
            and _is_uuid4(snapshot.registry_incarnation)
            and snapshot.capture_owner_trust_digest
            == expected_capture_owner_trust_digest
            and _safe_int(snapshot.state_version)
            and _safe_int(snapshot.valid_from)
            and (
                snapshot.valid_until is None
                or _safe_int(snapshot.valid_until)
                and snapshot.valid_from < snapshot.valid_until
            )
            and 1 <= len(snapshot.axis_contracts) <= MAX_REGISTRY_ENTRIES
            and tuple(item.axis_slot for item in snapshot.axis_contracts)
            == PRISOMA_REQUIRED_AXIS_SLOTS
            and tuple(
                (item.axis_slot, item.contract_digest)
                for item in snapshot.axis_contracts
            )
            == tuple(
                sorted(
                    {
                        (item.axis_slot, item.contract_digest)
                        for item in snapshot.axis_contracts
                    }
                )
            )
            and snapshot.snapshot_digest == _semantic_snapshot_digest(snapshot),
            "semantic registry snapshot is malformed or self-selected",
            CaptureError,
        )
        for contract in snapshot.axis_contracts:
            _validate_axis_contract(contract, store=store)
        _require(
            _is_uuid4(head.head_id)
            and head.owner_principal == PRISOMA_AUTHORITY
            and head.registry_incarnation == snapshot.registry_incarnation
            and head.capture_owner_trust_digest == snapshot.capture_owner_trust_digest
            and head.state_version == snapshot.state_version
            and head.snapshot_digest == snapshot.snapshot_digest
            and head.valid_from == snapshot.valid_from
            and head.valid_until == snapshot.valid_until
            and not {
                "cutover_receipt",
                "last_head_commit",
            }.intersection(_body(head))
            and head.head_digest == _semantic_head_digest(head),
            "consumer semantic registry head does not install its exact snapshot",
            CaptureError,
        )
        commit = version.head_commit
        _require(
            isinstance(commit, ConsumerSemanticRegistryHeadCommitReceipt),
            "semantic head lacks its exact post-CAS selector commit",
            CaptureError,
        )
        if not isinstance(commit, ConsumerSemanticRegistryHeadCommitReceipt):
            raise CaptureError("validated semantic head commit is absent")
        expected_prior = head.prior_head_digest or _semantic_head_genesis_digest(head)
        _require(
            _is_uuid4(commit.commit_id)
            and commit.registry_incarnation == head.registry_incarnation
            and commit.prior_head_digest == expected_prior
            and commit.installed_head_digest == head.head_digest
            and commit.selector_version == head.state_version
            and commit.operation_evidence_digest
            == (
                head.cutover_fact.fact_digest
                if head.cutover_fact is not None
                else head.snapshot_digest
            )
            and commit.commit_digest == _semantic_head_commit_digest(commit),
            "semantic head lacks its exact post-CAS selector commit",
            CaptureError,
        )
        _validate_authority(
            commit.authority_receipt,
            domain="consumer-semantic-registry-head-commit",
            subject_digest=commit.commit_digest,
            issuer=PRISOMA_AUTHORITY,
            subject=PRISOMA_AUTHORITY,
        )
        if prior is None:
            _require(
                head.state_version == 0
                and head.prior_head_digest is None
                and not head.retained_snapshot_digests
                and not head.retained_head_digests
                and head.cutover_fact is None
                and version.cutover_receipt is None,
                "semantic registry does not start at an authenticated genesis",
                CaptureError,
            )
        else:
            fact = head.cutover_fact
            receipt = version.cutover_receipt
            _require(
                snapshot.registry_incarnation == prior.snapshot.registry_incarnation
                and snapshot.capture_owner_trust_digest
                == prior.snapshot.capture_owner_trust_digest
                == prior.head.capture_owner_trust_digest
                and snapshot.state_version == prior.snapshot.state_version + 1
                and prior.snapshot.valid_until == snapshot.valid_from
                and head.prior_head_digest == prior.head.head_digest
                and prior.snapshot.snapshot_digest in head.retained_snapshot_digests
                and prior.head.head_digest in head.retained_head_digests
                and fact is not None
                and fact.registry_incarnation == snapshot.registry_incarnation
                and fact.capture_owner_trust_digest
                == snapshot.capture_owner_trust_digest
                and fact.prior_snapshot_digest == prior.snapshot.snapshot_digest
                and fact.successor_snapshot_digest == snapshot.snapshot_digest
                and fact.cutover_at == snapshot.valid_from
                and fact.expected_prior_head_digest == prior.head.head_digest
                and fact.expected_prior_selector_version == prior.head.state_version
                and fact.fact_digest == _semantic_cutover_fact_digest(fact)
                and not {
                    "cutover_digest",
                    "head_commit_digest",
                    "installed_head_digest",
                }.intersection(_body(fact))
                and receipt is not None
                and receipt.registry_incarnation == snapshot.registry_incarnation
                and receipt.transition_fact_digest == fact.fact_digest
                and receipt.prior_snapshot_digest == prior.snapshot.snapshot_digest
                and receipt.successor_snapshot_digest == snapshot.snapshot_digest
                and receipt.closed_segment_tips == fact.closed_segment_tips
                and receipt.cutover_at == snapshot.valid_from
                and receipt.prior_head_digest == prior.head.head_digest
                and receipt.installed_head_digest == head.head_digest
                and receipt.installed_selector_version == head.state_version
                and receipt.head_commit_digest == commit.commit_digest
                and receipt.cutover_digest == _semantic_cutover_digest(receipt),
                "semantic registry successor lacks exact cutover/retained ancestry",
                CaptureError,
            )
            if receipt is not None:
                _validate_authority(
                    receipt.authority_receipt,
                    domain="consumer-semantic-registry-cutover",
                    subject_digest=receipt.cutover_digest,
                    issuer=PRISOMA_AUTHORITY,
                    subject=PRISOMA_AUTHORITY,
                )
        _validate_authority(
            head.authority_receipt,
            domain="installed-consumer-semantic-registry-head",
            subject_digest=head.head_digest,
            issuer=PRISOMA_AUTHORITY,
            subject=PRISOMA_AUTHORITY,
        )
        prior = version


def _validate_segment(
    segment: CaptureSegment,
    *,
    versions: tuple[SemanticRegistryVersion, ...],
    current_head: ConsumerSemanticRegistryHead,
    store: ContentStore,
    opening_new: bool,
    terminal_commitment: (ConsumerSemanticRegistryTerminalCommitment | None) = None,
) -> None:
    version = next(
        (
            item
            for item in versions
            if item.snapshot.snapshot_digest == segment.semantic_snapshot_digest
            and item.head.head_digest == segment.semantic_head_digest
        ),
        None,
    )
    _require(version is not None, "segment semantic head is absent from lineage")
    if version is None:
        raise CaptureError("validated segment registry version is absent")
    contract = next(
        (
            item
            for item in version.snapshot.axis_contracts
            if item.axis_slot == segment.axis_slot
            and item.contract_digest == segment.axis_contract_digest
        ),
        None,
    )
    _require(contract is not None, "segment axis was not authorized at capture time")
    if contract is None:
        raise CaptureError("validated segment axis is absent")
    binding = next(
        (
            item
            for item in contract.ordered_members
            if item.member_id == segment.member_id
        ),
        None,
    )
    _require(
        binding is not None
        and tuple(item.member_id for item in contract.ordered_members)
        == tuple(
            item.member_id
            for item in next(
                authorized
                for authorized in version.snapshot.axis_contracts
                if authorized.contract_digest == contract.contract_digest
            ).ordered_members
        )
        and binding.stream_declaration_digest == segment.stream_declaration_digest
        and binding.stream_key == segment.stream_key
        and binding.provider_contract_digest == segment.provider_contract_digest
        and segment.authority_realm_key == AUTHORITY_REALM_KEY
        and segment.source_session_kind == "PLANT_CONTROL"
        and segment.source_logical_session_id == SESSION
        and segment.source_generation == GENERATION
        and type(segment.admission_lineage_key) is AdmissionLineageKey
        and segment.valid_from == version.snapshot.valid_from
        and segment.valid_until == version.snapshot.valid_until
        and 1 <= len(segment.samples) <= MAX_JOURNAL_RECORDS
        and segment.segment_digest == _segment_digest(segment),
        "segment did not select its exact member from the complete ordered binding set",
        CaptureError,
    )
    if opening_new:
        _require(
            segment.semantic_head_digest == current_head.head_digest
            and not segment.closed,
            "new segment attempted to use a former semantic head",
            CaptureError,
        )
    elif segment.semantic_head_digest != current_head.head_digest:
        current_version = next(
            (
                item
                for item in versions
                if item.head.head_digest == current_head.head_digest
            ),
            None,
        )
        cutover = (
            current_version.cutover_receipt if current_version is not None else None
        )
        tip = (
            next(
                (
                    item
                    for item in cutover.closed_segment_tips
                    if item.segment_id == segment.segment_id
                ),
                None,
            )
            if cutover is not None
            else None
        )
        _require(
            segment.closed
            and segment.semantic_head_digest in current_head.retained_head_digests
            and segment.semantic_snapshot_digest
            in current_head.retained_snapshot_digests
            and tip is not None
            and bool(segment.samples)
            and tip.last_sample_digest == segment.samples[-1].sample_digest
            and tip.last_admission_receipt_digest
            == segment.samples[-1].admission_receipt_digest,
            "archived segment lacks exact predecessor cutover and retained ancestry",
            CaptureError,
        )
        _require(
            terminal_commitment is not None
            and _closed_segment_interval(segment)
            in terminal_commitment.closed_segment_intervals,
            "archived semantic ancestry does not terminate at the final commitment",
            CaptureError,
        )
    for sample in segment.samples:
        capsule = sample.delivered_admission_capsule
        _validate_delivered_admission_capsule(capsule, store=store)
        replay = _execute_deterministic_extraction(
            sample.extraction_contract,
            capsule,
            store=store,
            language_contract=(
                contract.language_contract if contract.axis_slot == "L" else None
            ),
        )
        _require(
            _is_uuid4(sample.sample_id)
            and sample.member_id == segment.member_id
            and sample.frame_digest == capsule.producer_frame.frame_digest
            and sample.admission_receipt_digest
            == capsule.admission_receipt.receipt_digest
            and segment.stream_declaration_digest
            == capsule.producer_frame.stream_declaration_digest
            and segment.stream_key == capsule.producer_frame.stream_key
            and segment.authority_realm_key == capsule.authority_realm_key
            and segment.source_session_kind == capsule.source_session_kind
            and segment.source_logical_session_id == capsule.source_logical_session_id
            and segment.source_generation == capsule.source_generation
            and segment.admission_lineage_key == capsule.admission_receipt.key
            and sample.extraction_contract.member_id == sample.member_id
            and sample.extraction_contract.json_member_path == (binding.record_member,)
            and sample.extraction_receipt == replay
            and sample.extraction_receipt.capsule_digest == capsule.capsule_digest
            and sample.extraction_receipt.contract_digest
            == sample.extraction_contract.contract_digest
            and sample.canonical_output_digest
            == sample.extraction_receipt.canonical_output_digest
            and _safe_int(sample.sampled_at)
            and segment.valid_from <= sample.sampled_at
            and (segment.valid_until is None or sample.sampled_at < segment.valid_until)
            and sample.sample_digest == _member_sample_digest(sample),
            "segment sample is outside its exact semantic validity interval",
            CaptureError,
        )
        if contract.axis_slot == "L":
            language = contract.language_contract
            _require(language is not None, "language sample lacks its contract")
            if language is None:
                raise CaptureError("validated language contract is absent")
            transform = _validate_language_contract(language, store=store)
            _require(
                sample.instruction_content == language.instruction_content,
                "language sample instruction reference differs from its contract",
                CaptureError,
            )
            _require(
                store.get(sample.extraction_receipt.extracted_source_value)
                == store.get(language.instruction_content)
                and sample.extraction_contract.transform_contract_digest
                == language.contract_digest,
                "language extraction does not replay from the retained instruction",
                CaptureError,
            )
            expected = tuple(float(item) for item in transform["numeric_vector"])
            _require(
                sample.value == expected
                and sample.canonical_output_digest
                == hashlib.sha256(
                    struct.pack(f">{len(expected)}d", *expected)
                ).hexdigest(),
                "frozen embedding does not match its exact transform output",
                CaptureError,
            )
        else:
            _require(
                sample.instruction_content is None
                and type(sample.value) in (int, float)
                and math.isfinite(float(sample.value)),
                "non-language sample is not one finite numeric value",
                CaptureError,
            )
            _require(
                sample.canonical_output_digest
                == hashlib.sha256(struct.pack(">d", float(sample.value))).hexdigest(),
                "numeric sample differs from deterministic retained-byte extraction",
                CaptureError,
            )


@dataclass(frozen=True, slots=True)
class EvaluatedPolicyHead:
    head_id: str
    policy_domain_digest: str
    policy_lineage_incarnation: str
    state_version: int
    deny_state: str
    prior_head_digest: str | None
    retained_head_digests: tuple[str, ...]
    head_digest: str
    authority_receipt: AuthorityReceipt


def _evaluated_policy_head_digest(head: EvaluatedPolicyHead) -> str:
    return _body_digest(head, "head_digest", "authority_receipt")


def _haldir_policy_domain_digest() -> str:
    return _digest(
        {
            "consumer": "haldir",
            "domain": "assessment-policy",
            "session": SESSION,
        }
    )


def _seal_evaluated_policy_head(
    head: EvaluatedPolicyHead,
    *,
    event_time: int,
) -> EvaluatedPolicyHead:
    head = replace(head, head_digest=_evaluated_policy_head_digest(head))
    return replace(
        head,
        authority_receipt=_seal_authority(
            receipt_id=head.authority_receipt.receipt_id,
            domain="haldir-evaluated-policy-head",
            subject_digest=head.head_digest,
            issuer=HALDIR_AUTHORITY,
            subject="haldir-assessor",
            clock_domain="policy-monotonic",
            clock_incarnation=head.policy_lineage_incarnation,
            event_time=event_time,
        ),
    )


