def _validate_policy_genesis(
    uninitialized: EvaluatedPolicySelector,
    installed_head: EvaluatedPolicyHead,
    commit: EvaluatedPolicyCommitReceipt,
    installed_selector: EvaluatedPolicySelector,
) -> None:
    _require(
        uninitialized.policy_domain_digest == _haldir_policy_domain_digest()
        and uninitialized.state == "UNINITIALIZED"
        and not uninitialized.ever_used
        and uninitialized.selector_version == 0
        and uninitialized.current_head_digest is None
        and uninitialized.prior_selector_digest is None
        and uninitialized.last_commit_digest is None
        and uninitialized.selector_digest == _policy_selector_digest(uninitialized)
        and installed_head.policy_domain_digest == uninitialized.policy_domain_digest
        and installed_head.policy_lineage_incarnation
        == uninitialized.policy_lineage_incarnation
        and installed_head.state_version == 1
        and installed_head.prior_head_digest is None
        and not installed_head.retained_head_digests
        and installed_head.deny_state == "ALLOW"
        and installed_head.head_digest == _evaluated_policy_head_digest(installed_head)
        and commit.operation == "GENESIS_FROM_UNINITIALIZED"
        and commit.policy_domain_digest == uninitialized.policy_domain_digest
        and commit.policy_lineage_incarnation
        == uninitialized.policy_lineage_incarnation
        and commit.prior_selector_digest == uninitialized.selector_digest
        and commit.prior_head_digest is None
        and commit.installed_head_digest == installed_head.head_digest
        and commit.installed_selector_version == 1
        and commit.commit_digest == _evaluated_policy_commit_digest(commit)
        and installed_selector.state == "INITIALIZED"
        and installed_selector.ever_used
        and installed_selector.selector_version == 1
        and installed_selector.current_head_digest == installed_head.head_digest
        and installed_selector.prior_selector_digest == uninitialized.selector_digest
        and installed_selector.last_commit_digest == commit.commit_digest
        and installed_selector.selector_digest
        == _policy_selector_digest(installed_selector),
        "policy genesis did not prove a never-used authority selector",
        CaptureError,
    )
    for receipt, domain, subject_digest in (
        (
            uninitialized.authority_receipt,
            "haldir-evaluated-policy-selector",
            uninitialized.selector_digest,
        ),
        (
            installed_head.authority_receipt,
            "haldir-evaluated-policy-head",
            installed_head.head_digest,
        ),
        (
            commit.authority_receipt,
            "haldir-evaluated-policy-commit",
            commit.commit_digest,
        ),
        (
            installed_selector.authority_receipt,
            "haldir-evaluated-policy-selector",
            installed_selector.selector_digest,
        ),
    ):
        _validate_authority(
            receipt,
            domain=domain,
            subject_digest=subject_digest,
            issuer=HALDIR_AUTHORITY,
            subject="haldir-assessor",
        )


@dataclass(frozen=True, slots=True)
class HaldirAssessmentDisposition:
    disposition_id: str
    assessment_digest: str
    eligibility_state: str
    outcome: str
    policy_effect: str
    evaluated_prior_head: EvaluatedPolicyHead | None
    evaluated_successor_head: EvaluatedPolicyHead | None
    policy_mutation_commit: EvaluatedPolicyCommitReceipt | None
    installed_selector: EvaluatedPolicySelector | None
    current_evaluated_head: EvaluatedPolicyHead | None
    disposition_digest: str
    authority_receipt: AuthorityReceipt


def _haldir_disposition_digest(
    disposition: HaldirAssessmentDisposition,
) -> str:
    return _body_digest(disposition, "disposition_digest", "authority_receipt")


def _seal_haldir_disposition(
    disposition: HaldirAssessmentDisposition,
    *,
    event_time: int,
) -> HaldirAssessmentDisposition:
    disposition = replace(
        disposition,
        disposition_digest=_haldir_disposition_digest(disposition),
    )
    return replace(
        disposition,
        authority_receipt=_seal_authority(
            receipt_id=disposition.authority_receipt.receipt_id,
            domain="haldir-assessment-disposition",
            subject_digest=disposition.disposition_digest,
            issuer=HALDIR_AUTHORITY,
            subject="haldir-assessor",
            clock_domain="policy-monotonic",
            clock_incarnation=GENERATION,
            event_time=event_time,
        ),
    )


def _validate_haldir_disposition(
    disposition: HaldirAssessmentDisposition,
) -> None:
    no_mutation = disposition.policy_effect == "NO_POLICY_MUTATION"
    committed = disposition.policy_effect == "POLICY_MUTATION_COMMITTED"
    if no_mutation:
        valid = (
            (
                disposition.eligibility_state,
                disposition.outcome,
            )
            in {
                ("INELIGIBLE", "INELIGIBLE"),
                ("REJECTED", "REJECTED"),
                ("ELIGIBLE", "RECORDED"),
            }
            and disposition.evaluated_prior_head is None
            and disposition.evaluated_successor_head is None
            and disposition.policy_mutation_commit is None
            and disposition.installed_selector is None
            and disposition.current_evaluated_head is None
        )
    elif committed:
        prior = disposition.evaluated_prior_head
        successor = disposition.evaluated_successor_head
        commit = disposition.policy_mutation_commit
        selector = disposition.installed_selector
        current = disposition.current_evaluated_head
        valid = (
            disposition.outcome == "APPLIED_DENY"
            and disposition.eligibility_state == "ELIGIBLE"
            and prior is not None
            and successor is not None
            and commit is not None
            and selector is not None
            and current is not None
            and prior.deny_state == "ALLOW"
            and successor.deny_state == "DENY"
            and successor.policy_domain_digest == prior.policy_domain_digest
            and successor.policy_lineage_incarnation == prior.policy_lineage_incarnation
            and successor.state_version == prior.state_version + 1
            and successor.prior_head_digest == prior.head_digest
            and prior.head_digest in successor.retained_head_digests
            and successor.head_digest == _evaluated_policy_head_digest(successor)
            and commit.operation == "POLICY_MUTATION_COMMITTED"
            and commit.policy_domain_digest == prior.policy_domain_digest
            and commit.policy_lineage_incarnation == prior.policy_lineage_incarnation
            and commit.prior_selector_digest == selector.prior_selector_digest
            and commit.prior_head_digest == prior.head_digest
            and commit.installed_head_digest == successor.head_digest
            and commit.installed_selector_version == selector.selector_version
            and commit.commit_digest == _evaluated_policy_commit_digest(commit)
            and selector.state == "INITIALIZED"
            and selector.ever_used
            and selector.current_head_digest == successor.head_digest
            and selector.last_commit_digest == commit.commit_digest
            and selector.selector_digest == _policy_selector_digest(selector)
            and current.head_digest == successor.head_digest
            and current.head_digest == _evaluated_policy_head_digest(current)
        )
    else:
        valid = False
    _require(
        _is_uuid4(disposition.disposition_id)
        and HEX64.fullmatch(disposition.assessment_digest) is not None
        and disposition.eligibility_state in {"ELIGIBLE", "INELIGIBLE", "REJECTED"}
        and valid
        and disposition.disposition_digest == _haldir_disposition_digest(disposition),
        "Haldir assessment disposition has a candidate, losing, or ambiguous effect",
        CaptureError,
    )
    _validate_authority(
        disposition.authority_receipt,
        domain="haldir-assessment-disposition",
        subject_digest=disposition.disposition_digest,
        issuer=HALDIR_AUTHORITY,
        subject="haldir-assessor",
    )
    if committed:
        prior = disposition.evaluated_prior_head
        successor = disposition.evaluated_successor_head
        mutation_commit = disposition.policy_mutation_commit
        selector = disposition.installed_selector
        current = disposition.current_evaluated_head
        _require(
            prior is not None
            and successor is not None
            and mutation_commit is not None
            and selector is not None
            and current is not None,
            "committed Haldir disposition lacks its validated effect members",
            CaptureError,
        )
        if (
            prior is None
            or successor is None
            or mutation_commit is None
            or selector is None
            or current is None
        ):
            raise CaptureError("validated Haldir effect member is absent")
        for receipt, domain, subject_digest in (
            (
                prior.authority_receipt,
                "haldir-evaluated-policy-head",
                prior.head_digest,
            ),
            (
                successor.authority_receipt,
                "haldir-evaluated-policy-head",
                successor.head_digest,
            ),
            (
                mutation_commit.authority_receipt,
                "haldir-evaluated-policy-commit",
                mutation_commit.commit_digest,
            ),
            (
                selector.authority_receipt,
                "haldir-evaluated-policy-selector",
                selector.selector_digest,
            ),
            (
                current.authority_receipt,
                "haldir-evaluated-policy-head",
                current.head_digest,
            ),
        ):
            _validate_authority(
                receipt,
                domain=domain,
                subject_digest=subject_digest,
                issuer=HALDIR_AUTHORITY,
                subject="haldir-assessor",
            )


