def _haldir_owned_digest(value: Any, digest_field: str) -> str:
    return _body_digest(value, digest_field, "authority_receipt")


def _seal_haldir_owned(
    value: Any,
    *,
    digest_field: str,
    domain: str,
    subject: str,
    issuer: str = HALDIR_AUTHORITY,
    clock_domain: str,
    clock_incarnation: str,
    event_time: int,
) -> Any:
    digest = _haldir_owned_digest(value, digest_field)
    value = replace(value, **{digest_field: digest})
    return replace(
        value,
        authority_receipt=_seal_authority(
            receipt_id=value.authority_receipt.receipt_id,
            domain=domain,
            subject_digest=digest,
            issuer=issuer,
            subject=subject,
            clock_domain=clock_domain,
            clock_incarnation=clock_incarnation,
            event_time=event_time,
        ),
    )


@dataclass(frozen=True, slots=True)
class GaladrielReleaseSuiteIdentity:
    algorithm: str
    domain: str
    encoding: str
    config_digest: bytes
    human_name: str
    identity_digest: str


def _galadriel_suite_identity_digest(
    identity: GaladrielReleaseSuiteIdentity,
) -> str:
    return _digest(
        {
            "algorithm": identity.algorithm,
            "config_digest_hex": identity.config_digest.hex(),
            "domain": identity.domain,
            "encoding": identity.encoding,
        }
    )


def _adapt_galadriel_suite_identity(
    config_digest_hex: str,
    *,
    human_name: str,
) -> GaladrielReleaseSuiteIdentity:
    _require(
        HEX64.fullmatch(config_digest_hex) is not None,
        "Galadriel ConfigDigest is not exact lowercase SHA-256 hex",
        CaptureError,
    )
    raw = bytes.fromhex(config_digest_hex)
    _require(
        len(raw) == 32,
        "Galadriel ConfigDigest does not encode exactly 32 bytes",
        CaptureError,
    )
    identity = GaladrielReleaseSuiteIdentity(
        "sha256",
        "galadriel-release-suite-v1",
        "lowercase-hex",
        raw,
        human_name,
        "",
    )
    return replace(
        identity,
        identity_digest=_galadriel_suite_identity_digest(identity),
    )


def _validate_galadriel_suite_identity(
    identity: GaladrielReleaseSuiteIdentity,
    *,
    expected_config_digest_hex: str,
) -> None:
    _require(
        identity.algorithm == "sha256"
        and identity.domain == "galadriel-release-suite-v1"
        and identity.encoding == "lowercase-hex"
        and len(identity.config_digest) == 32
        and identity.config_digest.hex() == expected_config_digest_hex
        and HEX64.fullmatch(expected_config_digest_hex) is not None
        and identity.identity_digest == _galadriel_suite_identity_digest(identity),
        "Galadriel suite identity changed digest/domain/encoding/length",
        CaptureError,
    )


