def _galadriel_lp(value: bytes) -> bytes:
    _require(
        len(value) < 1 << 128,
        "Galadriel length prefix exceeds u128",
        CaptureError,
    )
    return len(value).to_bytes(16, "big") + value


def _galadriel_optional_digest(value: str | None) -> bytes:
    if value is None:
        return b"\x00"
    _require(
        HEX64.fullmatch(value) is not None,
        "Galadriel optional digest is not exact SHA-256 hex",
        CaptureError,
    )
    return b"\x01" + bytes.fromhex(value)


def _galadriel_assessment_digest(
    *,
    suite_config_digest_hex: str,
    raw_assessment_vector: bytes,
) -> str:
    _require(
        HEX64.fullmatch(suite_config_digest_hex) is not None
        and len(raw_assessment_vector) <= MAX_CONTENT_BYTES,
        "Galadriel assessment digest input is malformed or oversize",
        CaptureError,
    )
    preimage = (
        b"galadriel-ncp/lifecycle-assessment/v0.9"
        + b"\x00"
        + bytes.fromhex(suite_config_digest_hex)
        + _galadriel_lp(raw_assessment_vector)
    )
    return hashlib.sha256(preimage).hexdigest()


def _galadriel_receipt_digest(
    receipt: GaladrielLifecycleReceipt,
    *,
    store: ContentStore,
) -> str:
    _require(
        _safe_int(receipt.index) and receipt.index < 1 << 64,
        "Galadriel lifecycle receipt index exceeds u64",
        CaptureError,
    )
    position = store.get(receipt.canonical_stream_position)
    transition = store.get(receipt.canonical_lifecycle_transition)
    _require(
        HEX64.fullmatch(receipt.previous_receipt_digest) is not None,
        "Galadriel previous receipt digest is malformed",
        CaptureError,
    )
    preimage = (
        b"galadriel-ncp/lifecycle-receipt/v0.9"
        + b"\x00"
        + struct.pack(">Q", receipt.index)
        + bytes.fromhex(receipt.previous_receipt_digest)
        + _galadriel_lp(receipt.producer_id.encode("utf-8"))
        + _galadriel_lp(position)
        + _galadriel_lp(transition)
        + _galadriel_optional_digest(receipt.frame_digest)
        + _galadriel_optional_digest(receipt.assessment_digest)
    )
    return hashlib.sha256(preimage).hexdigest()


