def _seal_galadriel_lifecycle_commit(
    receipt: GaladrielLifecycleLineageCommitReceipt,
    *,
    event_time: int,
) -> GaladrielLifecycleLineageCommitReceipt:
    receipt = replace(
        receipt,
        commit_digest=_galadriel_lifecycle_commit_digest(receipt),
    )
    return replace(
        receipt,
        authority_receipt=_seal_authority(
            receipt_id=receipt.authority_receipt.receipt_id,
            domain="galadriel-lifecycle-lineage-commit",
            subject_digest=receipt.commit_digest,
            issuer=GALADRIEL_AUTHORITY,
            subject="galadriel-lifecycle-adapter",
            clock_domain="galadriel-lifecycle-monotonic",
            clock_incarnation=receipt.detector_lineage_id,
            event_time=event_time,
        ),
    )


