    def observer_architecture_attach(
        *,
        intent_changes: dict[str, Any] | None = None,
        context_changes: dict[str, Any] | None = None,
    ) -> None:
        model = ObserverAttachmentArchitectureModel(realm_authority=SESSION_AUTHORITY)
        context = _observer_architecture_context(
            source_session_kind="SIMULATION_SERVICE",
            source_logical_session_id=SESSION,
            source_generation=_u(82_100),
            predecessor_source_generation=None,
            generation_phase="GENERATION_LIVE",
            registry_index=82_110,
        )
        intent = _observer_attach_intent(
            requester_principal=OBSERVER_A,
            intent_index=82_120,
        )
        _attach_registered_observer_target(
            model,
            context=replace(context, **(context_changes or {})),
            intent=replace(intent, **(intent_changes or {})),
        )

