    def reject_source_finalization_without_live_lineage_transactionally() -> None:
        source_id = "observer-finalization-lineage-race"
        model = ObserverAttachmentArchitectureModel(realm_authority=SESSION_AUTHORITY)
        context = _observer_architecture_context(
            source_session_kind="SIMULATION_SERVICE",
            source_logical_session_id=source_id,
            source_generation=_u(82_105),
            predecessor_source_generation=None,
            generation_phase="GENERATION_LIVE",
            registry_index=82_115,
        )
        _attach_registered_observer_target(
            model,
            context=context,
            intent=_observer_attach_intent(
                requester_principal=OBSERVER_A,
                intent_index=82_130,
                source_logical_session_id=source_id,
            ),
        )
        source_namespace_key = _observer_source_namespace_key(source_id)
        live_parent = model.source_parent_selectors[source_namespace_key]
        model.source_parent_selectors[source_namespace_key] = (
            model._seal_source_parent_selector_head(
                replace(
                    live_parent,
                    phase="GENERATION_FINALIZED",
                    transition_evidence_digest=_digest(
                        "hostile-competing-finalization-lineage-winner"
                    ),
                    head_digest="",
                )
            )
        )
        snapshot = (
            dict(model.target_history),
            dict(model.pending_target_roots),
            {
                registry_id: dict(registry)
                for registry_id, registry in (
                    model.source_authorization_registries.items()
                )
            },
            dict(model.registry_scopes),
            model.target_history_selector_version,
            model.target_history_head_digest,
            dict(model.source_parent_selectors),
        )
        try:
            model.finalize_source_generation(
                replace(context, generation_phase="GENERATION_FINALIZED"),
                server_registry_cut_installed=True,
                complete_pending_target_root_installed=True,
            )
        except CaptureError as error:
            installed = (
                dict(model.target_history),
                dict(model.pending_target_roots),
                {
                    registry_id: dict(registry)
                    for registry_id, registry in (
                        model.source_authorization_registries.items()
                    )
                },
                dict(model.registry_scopes),
                model.target_history_selector_version,
                model.target_history_head_digest,
                dict(model.source_parent_selectors),
            )
            if installed != snapshot:
                raise AssertionError(
                    "rejected observer finalization published partial target, "
                    "registry, selector, or lineage state"
                ) from error
            raise

