    def retirement_race_fixture(
        *,
        source_id: str,
        index: int,
        publish_checkpoint: bool = True,
    ) -> tuple[
        ObserverAttachmentArchitectureModel,
        SourceGenerationObserverContext,
        ObserverSourceLogicalSessionKey,
        ObserverSourceParentSelectorHead,
    ]:
        model = ObserverAttachmentArchitectureModel(realm_authority=SESSION_AUTHORITY)
        context = _observer_architecture_context(
            source_session_kind="SIMULATION_SERVICE",
            source_logical_session_id=source_id,
            source_generation=_u(index),
            predecessor_source_generation=None,
            generation_phase="GENERATION_LIVE",
            registry_index=index + 1,
        )
        entry = _attach_registered_observer_target(
            model,
            context=context,
            intent=_observer_attach_intent(
                requester_principal=OBSERVER_A,
                intent_index=index + 2,
                source_logical_session_id=source_id,
            ),
        )
        if publish_checkpoint:
            _finalize_and_publish_observer_targets(model, context, (entry,))
        else:
            model.finalize_source_generation(
                replace(context, generation_phase="GENERATION_FINALIZED"),
                server_registry_cut_installed=True,
                complete_pending_target_root_installed=True,
            )
        source_key = _observer_source_namespace_key(source_id)
        parent = _install_observer_terminal_source_parent_selector(
            model,
            context,
        )
        return model, context, source_key, parent

