                subject_digest=admission.receipt_digest,
                issuer=INGRESS_AUTHORITY,
                subject=admission.key.receiver_principal,
                clock_domain="receiver-monotonic",
                clock_incarnation=RECEIVER_B_CLOCK,
                event_time=admission.admitted_at,
