    def reject_numeric_executor_terminal_root_change(field: str) -> None:
        receipt = neural_language.execution_receipt
        evidence = receipt.executor_evidence
        _require(
            evidence is not None,
            "fixture neural execution lacks executor evidence",
            CaptureError,
        )
        if evidence is None:
            raise ProbeError("validated neural executor evidence is absent")
        terminal = _seal_prisoma_numeric_executor_head(
            replace(
                evidence.state_heads[-1],
                **{field: _digest(("changed-at-terminal", field))},
                head_digest="",
                authority_receipt=_pending_authority(85_020),
            ),
            event_time=160,
        )
        _validate_prisoma_numeric_executor_evidence(
            replace(
                evidence,
                state_heads=(*evidence.state_heads[:-1], terminal),
            ),
            contract=neural_language,
            transform=_bounded_json_object(
                fixture.store.get(neural_language.transform_artifact)
            ),
            receipt=receipt,
        )

