    def reject_categorical_transform_body(**changes: Any) -> None:
        local_store = ContentStore()
        for reference in fixture.store.refs():
            local_store.put_bytes(
                fixture.store.get(reference),
                reference.media_type,
            )
        transform = dict(
            _bounded_json_object(
                fixture.store.get(categorical_language.transform_artifact)
            )
        )
        transform.update(changes)
        transform_artifact = local_store.put_json(
            transform,
            "application/vnd.prisoma.language-transform+json",
        )
        _validate_language_contract(
            _seal_language_contract(
                replace(
                    categorical_language,
                    transform_artifact=transform_artifact,
                    contract_digest="",
                )
            ),
            store=local_store,
        )

    def reject_language_execution(
        contract: FrozenLanguageEmbeddingContract,
        *,
        environment_changes: Mapping[str, Any] | None = None,
        output_bytes_value: bytes | None = None,
        receipt_changes: Mapping[str, Any] | None = None,
    ) -> None:
        local_store = ContentStore()
        for reference in fixture.store.refs():
            local_store.put_bytes(
                fixture.store.get(reference),
                reference.media_type,
            )
        receipt = contract.execution_receipt
        environment_body = dict(
            _bounded_json_object(fixture.store.get(receipt.environment_artifact))
        )
        environment_body.update(dict(environment_changes or {}))
        environment = local_store.put_json(
            environment_body,
            "application/vnd.prisoma.language-execution-environment+json",
        )
        output_bytes = local_store.put_bytes(
            (
                fixture.store.get(receipt.output_bytes)
                if output_bytes_value is None
                else output_bytes_value
            ),
            "application/vnd.prisoma.language-output.binary64",
        )
        changed_receipt = replace(
            receipt,
            environment_artifact=environment,
            environment_digest=environment.sha256,
            execution_profile_digest=_language_execution_profile_digest(
                contract,
                environment_digest=environment.sha256,
            ),
            output_bytes=output_bytes,
            output_bytes_digest=output_bytes.sha256,
            **dict(receipt_changes or {}),
            receipt_digest="",
            authority_receipt=_pending_authority(83_090),
        )
        _validate_language_contract(
            _seal_language_contract(
                replace(
                    contract,
                    execution_receipt=_seal_language_execution_receipt(
                        changed_receipt,
                        event_time=160,
                    ),
                    contract_digest="",
                )
            ),
            store=local_store,
        )

