    def recomputed_numeric_sample_without_retained_bytes() -> MemberSample:
        sample = current_d.samples[0]
        forged_value = 987_654_321.0
        forged_bytes = struct.pack(">d", forged_value)
        forged_ref = ContentRef(
            hashlib.sha256(forged_bytes).hexdigest(),
            len(forged_bytes),
            sample.extraction_receipt.canonical_output.media_type,
        )
        forged_receipt = replace(
            sample.extraction_receipt,
            canonical_output=forged_ref,
            canonical_output_digest=forged_ref.sha256,
            replay_digest=_digest(
                {
                    "forged_output": forged_ref,
                    "retained_capsule": (
                        sample.delivered_admission_capsule.capsule_digest
                    ),
                }
            ),
            receipt_digest="",
        )
        forged_receipt = replace(
            forged_receipt,
            receipt_digest=_extraction_receipt_digest(forged_receipt),
        )
        return replace(
            sample,
            value=forged_value,
            extraction_receipt=forged_receipt,
            canonical_output_digest=forged_ref.sha256,
            sample_digest="",
        )

