    def seal_disposition_genesis_commit(
        receipt: BodySessionControlStateCommitReceipt,
    ) -> BodySessionControlStateCommitReceipt:
        return _seal_body_session_control_commit(
            receipt,
            event_time=0,
            clock_incarnation=fixture.disposition_head.journal_incarnation,
        )

    def disposition_genesis_variant(
        *,
        uninitialized_changes: Mapping[str, Any] | None = None,
        head_changes: Mapping[str, Any] | None = None,
        commit_changes: Mapping[str, Any] | None = None,
        installed_changes: Mapping[str, Any] | None = None,
    ) -> BodySessionControlGenesisEvidence:
        base = fixture.disposition_head.genesis_evidence
        uninitialized = _seal_body_session_control_selector(
            replace(
                base.uninitialized_selector,
                **dict(uninitialized_changes or {}),
                selector_digest="",
                authority_receipt=_pending_authority(82_000),
            ),
            event_time=0,
        )
        genesis_head = _seal_body_session_control_head(
            replace(
                base.genesis_head,
                **dict(head_changes or {}),
                head_digest="",
                authority_receipt=_pending_authority(82_001),
            ),
            event_time=0,
            clock_incarnation=fixture.disposition_head.journal_incarnation,
        )
        genesis_anchor = _digest(
            {
                "control_lineage_incarnation": (
                    fixture.disposition_head.journal_incarnation
                ),
                "domain": "body-session-control-state-genesis-v1",
                "session_creation_digest": _session_creation_digest(),
                "selector_digest": uninitialized.selector_digest,
            }
        )
        commit_members: dict[str, Any] = {
            "prior_head_digest": genesis_anchor,
            "installed_head_digest": genesis_head.head_digest,
            **dict(commit_changes or {}),
            "commit_digest": "",
            "authority_receipt": _pending_authority(82_002),
        }
        commit = seal_disposition_genesis_commit(
            replace(base.commit_receipt, **commit_members)
        )
        installed_members: dict[str, Any] = {
            "prior_selector_digest": uninitialized.selector_digest,
            "current_head_digest": genesis_head.head_digest,
            "last_commit_digest": commit.commit_digest,
            **dict(installed_changes or {}),
            "selector_digest": "",
            "authority_receipt": _pending_authority(82_003),
        }
        installed = _seal_body_session_control_selector(
            replace(base.installed_selector, **installed_members),
            event_time=0,
        )
        return BodySessionControlGenesisEvidence(
            uninitialized,
            base.security_authority_head,
            base.security_authority_commit,
            base.security_authority_selector,
            base.plant_authority_genesis_head,
            base.action_command_declaration_genesis_head,
            genesis_head,
            installed,
            commit,
        )

