    def replay_journal(
        *,
        include_rebind: bool,
    ) -> tuple[
        DispositionJournalBuilder,
        tuple[SealedDisposition, ...],
        SealedBodyClockRestartBridge,
        SealedSecurityRebindJournalRecord,
        ContentStore,
    ]:
        local_store = ContentStore()
        applied_value = fixture.applied_record.semantic_record.applied_value
        if applied_value is not None:
            local_store.put_bytes(
                fixture.store.get(applied_value),
                applied_value.media_type,
            )
        records = tuple(
            _seal_disposition(
                replace(item.semantic_record, record_digest=""),
                store=local_store,
            )
            for item in fixture.sealed_dispositions
        )
        bridge = _seal_restart_bridge(
            replace(fixture.sealed_bridge.semantic_bridge, bridge_digest=""),
            store=local_store,
        )
        rebind = _seal_security_rebind(
            replace(
                fixture.sealed_security_rebind.semantic_record,
                rebind_digest="",
            ),
            store=local_store,
        )
        builder = DispositionJournalBuilder(
            fixture.disposition_head.journal_incarnation,
            fixture.security_context_1,
            fixture.security_authority_head,
            fixture.security_authority_commit,
            fixture.security_installed,
            session_creation_digest=(
                fixture.disposition_head.genesis_evidence.commit_receipt.session_creation_digest
            ),
            security_retirement_expectation=security_retirement_expectation,
        )
        for item in records[:3]:
            builder.append(item, store=local_store)
        builder.append_bridge(bridge, store=local_store, index=1)
        for item in records[3:]:
            builder.append(item, store=local_store)
        if include_rebind:
            cutover_transition = next(
                item
                for item in fixture.disposition_head.transitions
                if item.transition_kind == "security_cutover_prepare"
            )
            builder.prepare_planned_security_cutover(
                global_event_sequence=cutover_transition.global_event_sequence,
                body_local_time=cutover_transition.body_local_time,
            )
            builder.observe_installed_security_authority_state(
                fixture.security_authority_transition
            )
            builder.append_security_rebind(rebind, store=local_store, index=1)
        return builder, records, bridge, rebind, local_store

    def closure_variant(
        closure: SecurityStateTransitionAuthorization,
        **changes: Any,
    ) -> SecurityStateTransitionAuthorization:
        changed = replace(
            closure,
            **changes,
            closure_digest="",
            authority_receipt=_pending_authority(81_000),
        )
        return _seal_security_transition_authorization(changed)

