    def rebind_against_active_tip(*, mode: str) -> None:
        local_store = ContentStore()
        received = _seal_disposition(
            replace(
                fixture.sealed_dispositions[0].semantic_record,
                record_digest="",
            ),
            store=local_store,
        )
        builder = DispositionJournalBuilder(
            fixture.disposition_head.journal_incarnation,
            fixture.security_context_1,
            fixture.security_authority_head,
            fixture.security_authority_commit,
            fixture.security_installed,
            session_creation_digest=(
                fixture.disposition_head.genesis_evidence.commit_receipt.session_creation_digest
            ),
            security_retirement_expectation=security_retirement_expectation,
        )
        builder.append(received, store=local_store)
        base_record = fixture.sealed_security_rebind.semantic_record
        base_closure = base_record.transition_authorization
        if mode == "PLANNED":
            closure = closure_variant(
                base_closure,
                prior_disposition_head_digest=builder.prior_head,
                closed_at=101,
            )
            successor = fixture.security_context_2
        else:
            closure = closure_variant(
                base_closure,
                transition_mode="AMBIGUOUS",
                ambiguity_state="AMBIGUOUS",
                generation_disposition="RETIRE_GENERATION",
                hold_state="ACTIVE",
                new_admission_state="BLOCKED",
                prior_disposition_head_digest=builder.prior_head,
                retired_stream_declaration_digests=(),
                retired_grant_digests=(),
                retired_lease_digests=(),
                closed_at=101,
            )
            successor = fixture.security_context_2
        rebind = _seal_security_rebind(
            replace(
                base_record,
                rebind_id=_u(81_002),
                rebind_nonce=_u(81_003),
                rebind_mode=mode,
                prior_installed_head_digest=builder.prior_head,
                successor_security_context=successor,
                transition_authorization=closure,
                global_event_sequence=1,
                body_local_time=101,
                session_event_time=101,
                rebind_digest="",
            ),
            store=local_store,
        )
        builder.observe_installed_security_authority_state(
            fixture.security_authority_transition
        )
        builder.append_security_rebind(rebind, store=local_store, index=2)

    def emergency_hold_fixture(
        *,
        terminal_state: str | None,
    ) -> tuple[
        DispositionJournalBuilder,
        tuple[SealedDisposition, ...],
        SealedSecurityRebindJournalRecord,
        ContentStore,
    ]:
        local_store = ContentStore()
        received = _seal_disposition(
            replace(
                fixture.sealed_dispositions[0].semantic_record,
                record_digest="",
            ),
            store=local_store,
        )
        admitted = _seal_disposition(
            replace(
                fixture.sealed_dispositions[2].semantic_record,
                global_event_sequence=1,
                body_local_time=101,
                prior_command_record_digest=received.semantic_record.record_digest,
                record_digest="",
            ),
            store=local_store,
        )
        builder = DispositionJournalBuilder(
            fixture.disposition_head.journal_incarnation,
            fixture.security_context_1,
            fixture.security_authority_head,
            fixture.security_authority_commit,
            fixture.security_installed,
            session_creation_digest=(
                fixture.disposition_head.genesis_evidence.commit_receipt.session_creation_digest
            ),
            security_retirement_expectation=security_retirement_expectation,
        )
        builder.append(received, store=local_store)
        builder.append(admitted, store=local_store)
        base_record = fixture.sealed_security_rebind.semantic_record
        closure = closure_variant(
            base_record.transition_authorization,
            transition_mode="EMERGENCY",
            ambiguity_state="RESOLVED",
            generation_disposition="CONTINUE_SAME_GENERATION",
            hold_state="ACTIVE",
            new_admission_state="BLOCKED",
            prior_disposition_head_digest=builder.prior_head,
            closed_at=102,
        )
        rebind = _seal_security_rebind(
            replace(
                base_record,
                rebind_id=_u(81_004),
                rebind_nonce=_u(81_005),
                rebind_mode="EMERGENCY",
                prior_installed_head_digest=builder.prior_head,
                transition_authorization=closure,
                global_event_sequence=2,
                body_local_time=102,
                session_event_time=102,
                rebind_digest="",
            ),
            store=local_store,
        )
        builder.observe_installed_security_authority_state(
            fixture.security_authority_transition
        )
        builder.append_security_rebind(rebind, store=local_store, index=3)
        records = [received, admitted]
        if terminal_state is not None:
            source = fixture.sealed_dispositions[4].semantic_record
            terminal = _seal_disposition(
                replace(
                    source,
                    record_id=_u(81_006),
                    security_context_digest=fixture.security_context_2.context_digest,
                    global_event_sequence=3,
                    state=terminal_state,
                    prior_command_record_digest=admitted.semantic_record.record_digest,
                    admitted_record_digest=(
                        admitted.semantic_record.record_digest
                        if terminal_state == "applied"
                        else None
                    ),
                    body_clock_incarnation=BODY_CLOCK_1,
                    body_local_time=103,
                    boundary_name=(
                        "body-command-boundary" if terminal_state == "applied" else None
                    ),
                    body_axis_contract_digest=(
                        source.body_axis_contract_digest
                        if terminal_state == "applied"
                        else None
                    ),
                    applied_value=(
                        source.applied_value if terminal_state == "applied" else None
                    ),
                    record_digest="",
                ),
                store=local_store,
            )
            records.append(terminal)
            builder.append(terminal, store=local_store)
        return builder, tuple(records), rebind, local_store

