    def suite_variant(
        **changes: Any,
    ) -> GaladrielReleaseSuiteIdentity:
        identity = replace(
            fixture.galadriel_suite_identity,
            **changes,
            identity_digest="",
        )
        return replace(
            identity,
            identity_digest=_galadriel_suite_identity_digest(identity),
        )

    def report_variant(
        **changes: Any,
    ) -> GaladrielSealedDefaultReportEvidence:
        return _seal_galadriel_report_evidence(
            replace(
                fixture.galadriel_report,
                **changes,
                evidence_digest="",
                authority_receipt=_pending_authority(84_008),
            ),
            event_time=193,
        )

    def fully_sealed_report_variant(
        **changes: Any,
    ) -> tuple[GaladrielSealedDefaultReportEvidence, ContentStore]:
        local_store = ContentStore()
        for reference in fixture.store.refs():
            local_store.put_bytes(
                fixture.store.get(reference),
                reference.media_type,
            )
        provisional = replace(
            fixture.galadriel_report,
            **changes,
            sealed_default_report=_empty_protected(84_009),
            sealed_default_report_digest="",
            evidence_digest="",
            authority_receipt=_pending_authority(84_009),
        )
        protected = _protect_body(
            _galadriel_default_report_body(provisional),
            store=local_store,
            media_type="application/vnd.galadriel.default-report+json",
            domain="galadriel-sealed-default-report",
            issuer=GALADRIEL_AUTHORITY,
            subject="galadriel-release-suite",
            event_time=193,
            clock_domain=provisional.clock_domain,
            clock_incarnation=GENERATION,
        )
        joined = replace(
            provisional,
            sealed_default_report=protected,
            sealed_default_report_digest=protected.body_digest,
        )
        joined = replace(
            joined,
            ncp_report_binding_digest=_galadriel_ncp_report_binding_digest(joined),
        )
        report = _seal_galadriel_report_evidence(
            joined,
            event_time=193,
        )
        return report, local_store

    expected_galadriel_config = _digest("galadriel-release-suite-config")

    def validate_galadriel_report(
        report: GaladrielSealedDefaultReportEvidence,
        *,
        store: ContentStore = fixture.store,
    ) -> None:
        _validate_galadriel_report_evidence(
            report,
            expected_suite_identity_digest=expected_galadriel_config,
            expected_channel_mapping=fixture.galadriel_mapping_receipt,
            expected_lineage_binding=fixture.galadriel_lineage_binding,
            store=store,
        )

    def reject_fully_sealed_galadriel_report(**changes: Any) -> None:
        report, local_store = fully_sealed_report_variant(**changes)
        validate_galadriel_report(report, store=local_store)

    def reject_galadriel_lineage_substitution(**changes: Any) -> None:
        lineage = _seal_galadriel_ncp_lineage_binding(
            replace(
                fixture.galadriel_lineage_binding,
                **changes,
                binding_digest="",
            )
        )
        report, local_store = fully_sealed_report_variant(
            ncp_lineage_binding=lineage,
        )
        validate_galadriel_report(report, store=local_store)

    def reject_galadriel_mapping_substitution() -> None:
        mapping = _seal_galadriel_mapping(
            replace(
                fixture.galadriel_mapping_receipt,
                stream_declaration_digest="0" * 64,
                mapping_digest="",
                authority_receipt=_pending_authority(84_010),
            ),
            event_time=193,
        )
        lineage = _seal_galadriel_ncp_lineage_binding(
            replace(
                fixture.galadriel_lineage_binding,
                stream_declaration_digest=mapping.stream_declaration_digest,
                mapping_receipt_digest=mapping.mapping_digest,
                binding_digest="",
            )
        )
        report, local_store = fully_sealed_report_variant(
            channel_mapping_receipt=mapping,
            ncp_lineage_binding=lineage,
        )
        validate_galadriel_report(report, store=local_store)

    galadriel_handoff = fixture.galadriel_report.observer_assessor_handoff
    galadriel_lifecycle = fixture.galadriel_report.lifecycle_evidence
    _require(
        galadriel_handoff is not None and galadriel_lifecycle is not None,
        "Galadriel hostile matrix lacks its validated lifecycle/handoff fixture",
        CaptureError,
    )
    if galadriel_handoff is None or galadriel_lifecycle is None:
        raise CaptureError("validated Galadriel hostile fixture is absent")

