def build_result() -> dict[str, Any]:
    validate_bridge_canonical_type_system()
    commitment_suite = bridge_commitment_suite()
    commitment_suite_digest = bridge_commitment_suite_digest()
    commitment_suite_digest_domain = bridge_commitment_suite_digest_domain()
    commitment_mutations = bridge_commitment_suite_mutation_report()
    bridge_profile = observer_read_capture_bridge_profile()
    validate_observer_read_capture_bridge_profile(bridge_profile)
    profile_mutations = observer_read_capture_bridge_profile_mutation_report()
    _require(
        bridge_profile["canonical_commitment"]
        == {
            "suite": commitment_suite,
            "suite_digest": commitment_suite_digest,
            "suite_digest_domain": commitment_suite_digest_domain,
        }
        and profile_mutations["total_mutations_executed"]
        == profile_mutations["total_mutations_rejected"],
        "shared bridge profile or its commitment triple differs",
        CaptureError,
    )
    lifecycle = build_grant_lifecycle_result()
    capture = build_capture_action_result()
    logic_mutants = [
        *lifecycle.get("logic_mutants", ()),
        *capture.get("logic_mutants", ()),
    ]
    targeted_case_components = {
        "grant_lifecycle_decision_cases": lifecycle["case_count"],
        "capture_action_decision_cases": capture["targeted_action_case_count"],
    }
    return {
        "schema": "ncp.b01-observer-capture-probe-result.v7",
        "scope": "bounded-pre-ratification-counterexample-discovery",
        "claim_boundary": (
            "These synthetic finite observer and capture fixtures are "
            "non-normative. They do not prove a live transport, interoperability, "
            "physical effect, scientific calibration, plant safety, certification, "
            "or release readiness. The legacy Galadriel, Haldir, and Prisoma "
            "shapes are not selector-closure evidence. Semantic contrasts are "
            "non-vacuity witnesses. The registered target-history mutants are "
            "synthetic single-defect checks, not implementation mutation evidence. "
            "The observer read-decision HMAC is deterministic fixture evidence "
            "only; it is not cryptographic qualification or an installed issuer. "
            "Authority-receipt HMACs likewise provide source-visible fixture "
            "tamper detection, not issuer authenticity. The same-process content "
            "store does not provide filesystem durability, fsync, or restart "
            "recovery evidence."
        ),
        "shared_bridge_commitment": {
            "profile": bridge_profile,
            "profile_digest": observer_read_capture_bridge_profile_digest(),
            "profile_digest_domain": (
                observer_read_capture_bridge_profile_digest_domain()
            ),
            "profile_mutation_report": profile_mutations,
            "suite": commitment_suite,
            "suite_digest": commitment_suite_digest,
            "suite_digest_domain": commitment_suite_digest_domain,
            "mutation_report": commitment_mutations,
        },
        "grant_lifecycle": lifecycle,
        "capture_action": capture,
        "counts": {
            "targeted_cases": sum(targeted_case_components.values()),
            "targeted_case_components": targeted_case_components,
            "logic_mutants_executed": len(logic_mutants),
            "logic_mutants_killed": sum(
                mutant.get("killed") is True for mutant in logic_mutants
            ),
            "logic_mutants_survived": sum(
                mutant.get("killed") is not True for mutant in logic_mutants
            ),
            "semantic_contrasts_reached": (
                len(lifecycle["semantic_contrasts"])
                + len(capture["semantic_contrasts"])
            ),
            "hostile_inputs_rejected": (
                len(lifecycle["hostile_inputs"]) + len(capture["hostile_inputs"])
            ),
            "bridge_commitment_mutations_executed": (
                commitment_mutations["total_mutations_executed"]
            ),
            "bridge_commitment_mutations_rejected": (
                commitment_mutations["total_mutations_rejected"]
            ),
            "invariant_witnesses_reached": (
                len(lifecycle["invariant_witnesses"])
                + len(capture["invariant_witnesses"])
            ),
        },
    }


def validate_result(value: Any) -> None:
    _require(
        isinstance(value, dict)
        and json.dumps(value, separators=(",", ":"), sort_keys=True)
        == json.dumps(build_result(), separators=(",", ":"), sort_keys=True),
        "observer/capture result differs from deterministic semantic replay",
    )


def _self_test_content_store_hardening() -> None:
    class BytesAlias(bytes):
        pass

    class TextAlias(str):
        pass

    exact_vector_bytes = _bounded_binary64_vector_bytes(
        [0.0] * MAX_LANGUAGE_OUTPUT_DIMENSION,
        expected_dimension=MAX_LANGUAGE_OUTPUT_DIMENSION,
    )
    _require(
        len(exact_vector_bytes) == MAX_LANGUAGE_OUTPUT_DIMENSION * 8,
        "exact maximum binary64 vector did not encode to its proven byte length",
        CaptureError,
    )
    try:
        _bounded_binary64_vector_bytes(
            [0.0] * (MAX_LANGUAGE_OUTPUT_DIMENSION + 1),
            expected_dimension=MAX_LANGUAGE_OUTPUT_DIMENSION + 1,
        )
    except CaptureError:
        pass
    else:
        raise CaptureError("binary64 vector accepted its dimension cap plus one")

    try:
        ContentStore.stage_bytes(BytesAlias(b"x"), "application/octet-stream")
    except CaptureError:
        pass
    else:
        raise CaptureError("content staging accepted a bytes subclass")
    for invalid_media_type in ("/", " / ", "text/plain\x00", "💣/💣"):
        try:
            ContentStore.stage_bytes(b"x", invalid_media_type)
        except CaptureError:
            pass
        else:
            raise CaptureError("content staging accepted invalid media syntax")
    for reference in (
        ContentRef(hashlib.sha256(b"x").hexdigest(), True, "text/plain"),
        ContentRef(
            TextAlias(hashlib.sha256(b"x").hexdigest()),
            1,
            "text/plain",
        ),
    ):
        try:
            ContentStore().commit_atomic(
                namespace="bad-reference",
                staged_writes=(StagedContentWrite(reference, b"x"),),
                visible_references=(reference,),
            )
        except CaptureError:
            pass
        else:
            raise CaptureError("content store accepted subclassed reference fields")

    aggregate_store = ContentStore()
    exact_chunks = tuple(
        bytes([index]) + bytes(MAX_CONTENT_BYTES - 1) for index in range(4)
    )
    for chunk in exact_chunks:
        aggregate_store.put_bytes(chunk, "application/octet-stream")
    _require(
        sum(reference.byte_length for reference in aggregate_store.refs())
        == MAX_CONTENT_STORE_AGGREGATE_BYTES,
        "content store exact aggregate cap did not remain visible",
        CaptureError,
    )
    exact_snapshot = aggregate_store._snapshot
    try:
        aggregate_store.put_bytes(b"x", "application/octet-stream")
    except CaptureError:
        pass
    else:
        raise CaptureError("content store accepted aggregate cap plus one")
    _require(
        aggregate_store._snapshot == exact_snapshot,
        "rejected aggregate-cap write changed the immutable snapshot",
        CaptureError,
    )

    atomic_capacity_store = ContentStore()
    for index in range(3):
        atomic_capacity_store.put_bytes(
            bytes([index]) + bytes(MAX_CONTENT_BYTES - 1),
            "application/octet-stream",
        )
    atomic_capacity_store.put_bytes(
        b"z" * (MAX_CONTENT_BYTES - 5),
        "application/octet-stream",
    )
    capacity_a = atomic_capacity_store.stage_bytes(
        b"abc",
        "application/vnd.ncp.extracted-source-value",
    )
    capacity_b = atomic_capacity_store.stage_bytes(
        b"def",
        "application/vnd.ncp.canonical-binary64-output",
    )
    capacity_snapshot = atomic_capacity_store._snapshot
    try:
        atomic_capacity_store.commit_atomic(
            namespace="extraction-capacity-test",
            staged_writes=(capacity_a, capacity_b),
            visible_references=tuple(
                sorted(
                    (capacity_a.reference, capacity_b.reference),
                    key=lambda reference: (
                        reference.sha256,
                        reference.media_type,
                        reference.byte_length,
                    ),
                )
            ),
        )
    except CaptureError:
        pass
    else:
        raise CaptureError("atomic extraction publication exceeded store capacity")
    _require(
        atomic_capacity_store._snapshot == capacity_snapshot,
        "failed extraction publication left partial source or output content",
        CaptureError,
    )

    atomic_store = ContentStore()
    staged_a = atomic_store.stage_bytes(b"a", "application/octet-stream")
    staged_b = atomic_store.stage_bytes(b"b", "application/octet-stream")
    before = atomic_store._snapshot
    for writes, visible in (
        (
            (staged_a,),
            (
                ContentRef(
                    hashlib.sha256(b"absent").hexdigest(),
                    len(b"absent"),
                    "application/octet-stream",
                ),
            ),
        ),
        ((staged_a, staged_a), (staged_a.reference,)),
    ):
        try:
            atomic_store.commit_atomic(
                namespace="atomic-test",
                staged_writes=writes,
                visible_references=visible,
            )
        except CaptureError:
            pass
        else:
            raise CaptureError("atomic store accepted an open or duplicate write set")
        _require(
            atomic_store._snapshot == before,
            "rejected atomic publication changed the snapshot",
            CaptureError,
        )
    atomic_store.commit_atomic(
        namespace="atomic-test",
        staged_writes=(staged_a, staged_b),
        visible_references=tuple(
            sorted(
                (staged_a.reference, staged_b.reference),
                key=lambda reference: (
                    reference.sha256,
                    reference.media_type,
                    reference.byte_length,
                ),
            )
        ),
    )
    _require(
        atomic_store.atomic_visibility("atomic-test")
        == tuple(
            sorted(
                (staged_a.reference, staged_b.reference),
                key=lambda reference: (
                    reference.sha256,
                    reference.media_type,
                    reference.byte_length,
                ),
            )
        ),
        "atomic visibility does not resolve its complete staged content set",
        CaptureError,
    )
    exact_atomic_snapshot = atomic_store._snapshot
    atomic_store.commit_atomic(
        namespace="atomic-test",
        staged_writes=(staged_a, staged_b),
        visible_references=atomic_store.atomic_visibility("atomic-test"),
        allow_exact_retry=True,
    )
    _require(
        atomic_store._snapshot == exact_atomic_snapshot,
        "exact atomic publication retry changed the immutable snapshot",
        CaptureError,
    )
    try:
        atomic_store.commit_atomic(
            namespace="atomic-test",
            staged_writes=(staged_a,),
            visible_references=atomic_store.atomic_visibility("atomic-test"),
            allow_exact_retry=True,
        )
    except CaptureError:
        pass
    else:
        raise CaptureError(
            "exact atomic publication retry accepted a strict staged subset"
        )
    _require(
        atomic_store._snapshot == exact_atomic_snapshot,
        "rejected subset retry changed the immutable snapshot",
        CaptureError,
    )

    closure_store = ContentStore()
    existing = closure_store.put_bytes(b"existing", "application/octet-stream")
    omitted = closure_store.stage_bytes(b"omitted", "application/octet-stream")
    closure_snapshot = closure_store._snapshot
    try:
        closure_store.commit_atomic(
            namespace="closure-test",
            staged_writes=(omitted,),
            visible_references=(existing,),
        )
    except CaptureError:
        pass
    else:
        raise CaptureError("atomic publication admitted an omitted staged digest")
    _require(
        closure_store._snapshot == closure_snapshot,
        "rejected visibility-closure publication changed the snapshot",
        CaptureError,
    )

    concurrent_store = ContentStore()
    barrier = threading.Barrier(3)
    failures: list[BaseException] = []

    def put_concurrently(content: bytes) -> None:
        try:
            barrier.wait()
            concurrent_store.put_bytes(content, "application/octet-stream")
        except BaseException as exc:
            failures.append(exc)

    threads = tuple(
        threading.Thread(target=put_concurrently, args=(content,))
        for content in (b"sibling-a", b"sibling-b")
    )
    for thread in threads:
        thread.start()
    barrier.wait()
    for thread in threads:
        thread.join()
    _require(
        not failures
        and {concurrent_store.get(reference) for reference in concurrent_store.refs()}
        == {b"sibling-a", b"sibling-b"},
        "concurrent sibling content writes lost a committed update",
        CaptureError,
    )


def _self_test_authority_receipt_authentication() -> None:
    transactional_store = ContentStore()
    before = transactional_store._snapshot
    try:
        _protect_body(
            {"value": 1},
            store=transactional_store,
            media_type="application/json",
            domain="fixture-authority-authentication",
            issuer=object(),  # type: ignore[arg-type]
            subject="fixture-subject",
            event_time=1,
        )
    except CaptureError:
        pass
    else:
        raise CaptureError("protected body accepted a non-principal issuer")
    _require(
        transactional_store._snapshot == before,
        "failed protected-body sealing left partially installed content",
        CaptureError,
    )
    protected = tuple(
        _protect_body(
            {"value": value},
            store=transactional_store,
            media_type="application/json",
            domain="fixture-authority-authentication",
            issuer=BODY_AUTHORITY,
            subject="fixture-subject",
            event_time=value,
        )
        for value in (1, 1, 2)
    )
    _require(
        len({item.authority_receipt.receipt_id for item in protected}) == 3
        and len(transactional_store.refs()) == 2
        and transactional_store._snapshot.next_authority_receipt_sequence == 4,
        "deduplicated protected bodies reused a receipt identity",
        CaptureError,
    )

    concurrent_store = ContentStore()
    barrier = threading.Barrier(3)
    protected_concurrently: list[ProtectedBody] = []
    concurrent_failures: list[BaseException] = []

    def protect_concurrently(value: int) -> None:
        try:
            barrier.wait()
            protected_concurrently.append(
                _protect_body(
                    {"value": value},
                    store=concurrent_store,
                    media_type="application/json",
                    domain="fixture-authority-authentication",
                    issuer=BODY_AUTHORITY,
                    subject="fixture-subject",
                    event_time=value,
                )
            )
        except BaseException as exc:
            concurrent_failures.append(exc)

    threads = tuple(
        threading.Thread(target=protect_concurrently, args=(value,)) for value in (1, 2)
    )
    for thread in threads:
        thread.start()
    barrier.wait()
    for thread in threads:
        thread.join()
    _require(
        not concurrent_failures
        and len(protected_concurrently) == 2
        and len({item.authority_receipt.receipt_id for item in protected_concurrently})
        == 2,
        "concurrent protected bodies reused a receipt identity",
        CaptureError,
    )

    invalid_store = ContentStore()
    for overrides in (
        {"domain": ""},
        {"clock_domain": ""},
        {"clock_incarnation": "not-a-uuid"},
        {"event_time": -1},
    ):
        invalid_before = invalid_store._snapshot
        arguments: dict[str, Any] = {
            "media_type": "application/json",
            "domain": "fixture-authority-authentication",
            "issuer": BODY_AUTHORITY,
            "subject": "fixture-subject",
            "event_time": 1,
            "clock_domain": "issuer-utc",
            "clock_incarnation": GENERATION,
        }
        arguments.update(overrides)
        try:
            invalid_store.protect_body_atomic({"value": 1}, **arguments)
        except CaptureError:
            pass
        else:
            raise CaptureError("protected body accepted invalid authority fields")
        _require(
            invalid_store._snapshot == invalid_before,
            "failed protected-body claim changed content or receipt allocation",
            CaptureError,
        )

    receipt = _seal_authority(
        receipt_id=_u(90_001),
        domain="fixture-authority-authentication",
        subject_digest=hashlib.sha256(b"subject").hexdigest(),
        issuer=BODY_AUTHORITY,
        subject="fixture-subject",
        clock_domain="issuer-utc",
        clock_incarnation=GENERATION,
        event_time=1,
    )
    _validate_authority(
        receipt,
        domain=receipt.domain,
        subject_digest=receipt.subject_digest,
        issuer=BODY_AUTHORITY,
        subject=receipt.subject_principal,
    )
    for forged in (
        replace(receipt, issuer_principal=INGRESS_AUTHORITY),
        replace(receipt, issuer_key_id="attacker:key:1"),
        replace(receipt, issuer_security_epoch=2),
        replace(
            receipt,
            fixture_authentication_tag=hashlib.sha256(b"public-forgery").hexdigest(),
        ),
    ):
        try:
            _validate_authority(
                forged,
                domain=receipt.domain,
                subject_digest=receipt.subject_digest,
                issuer=forged.issuer_principal,
                subject=receipt.subject_principal,
            )
        except CaptureError:
            pass
        else:
            raise CaptureError("forged authority receipt passed fixture authentication")


def _validate_exact_count_baseline(result: dict[str, Any]) -> None:
    lifecycle = result["grant_lifecycle"]
    _require(
        result["counts"]
        == {
            "targeted_cases": 249,
            "targeted_case_components": {
                "grant_lifecycle_decision_cases": 186,
                "capture_action_decision_cases": 63,
            },
            "logic_mutants_executed": 10,
            "logic_mutants_killed": 10,
            "logic_mutants_survived": 0,
            "semantic_contrasts_reached": 22,
            "hostile_inputs_rejected": 444,
            "bridge_commitment_mutations_executed": 672,
            "bridge_commitment_mutations_rejected": 672,
            "invariant_witnesses_reached": 73,
        }
        and lifecycle["case_count"] == 186
        and lifecycle["admitted"] == 36
        and lifecycle["rejected"] == 150
        and lifecycle["hostile_input_count"] == 150,
        "observer/capture exact count baseline drifted",
    )


def self_test(result: dict[str, Any]) -> None:
    _self_test_content_store_hardening()
    _self_test_authority_receipt_authentication()
    validate_result(result)
    validate_result(
        json.loads(json.dumps(result, separators=(",", ":"), sort_keys=True))
    )
    for section_name in ("grant_lifecycle", "capture_action"):
        section = result[section_name]
        _require(
            all(item.get("reached") is True for item in section["semantic_contrasts"])
            and all(item.get("rejected") is True for item in section["hostile_inputs"])
            and all(
                item.get("reached") is True for item in section["invariant_witnesses"]
            ),
            f"{section_name} contains an unreached or surviving witness",
        )
    lifecycle = result["grant_lifecycle"]
    capture = result["capture_action"]
    _require(
        lifecycle["case_count"] == lifecycle["admitted"] + lifecycle["rejected"]
        and lifecycle["hostile_input_count"]
        == lifecycle["rejected"]
        == len(lifecycle["hostile_inputs"]),
        "grant lifecycle decision and hostile counts do not reconcile",
    )
    _require(
        capture["targeted_action_case_count"]
        == sum(capture["targeted_action_case_components"].values())
        and capture["fail_safe_targeted_case_count"]
        == capture["targeted_action_case_components"]["body_fail_safe_action_cases"]
        and capture["fail_safe_targeted_case_count"]
        == sum(capture["fail_safe_targeted_case_components"].values()),
        "capture targeted-action case arithmetic does not reconcile",
    )
    _validate_exact_count_baseline(result)
    _require(
        result["shared_bridge_commitment"]["profile_mutation_report"][
            "total_mutations_executed"
        ]
        == result["shared_bridge_commitment"]["profile_mutation_report"][
            "total_mutations_rejected"
        ]
        == 310,
        "observer/capture bridge profile mutation baseline drifted",
    )
    _require(
        len(_CAPTURE_ARTIFACT_TYPE_IDS) == len(_CAPTURE_ARTIFACT_TYPE_REGISTRY) == 262,
        "explicit capture artifact type registry count drifted",
    )
    _require(
        _canonical_bytes(result) == _canonical_bytes(build_result()),
        "observer/capture probe is not deterministic",
    )


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--self-test", action="store_true")
    arguments = parser.parse_args()
    result = build_result()
    # The selector-closure gate invokes the probe without --self-test. Keep the
    # exact coverage baseline on that normal output path as well, so adding or
    # removing a case cannot leave the focused runner as the only detector.
    _validate_exact_count_baseline(result)
    if arguments.self_test:
        self_test(result)
    print(json.dumps(result, sort_keys=True))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
